def iso_from_timestamp(timestamp):
    if not timestamp:
        return ""
    return dt.datetime.fromtimestamp(timestamp).strftime("%Y-%m-%d %H:%M:%S")


def normalize_legacy_texts(value):
    if isinstance(value, str):
        value = value.replace(LEGACY_ASPEN_BOUNDARY_TEXTS[0], CURRENT_C3_ASPEN_BOUNDARY)
        value = value.replace(LEGACY_ASPEN_BOUNDARY_TEXTS[1], NEW_SYSTEM_ASPEN_BOUNDARY)
        return value
    if isinstance(value, list):
        return [normalize_legacy_texts(item) for item in value]
    if isinstance(value, dict):
        return {key: normalize_legacy_texts(item) for key, item in value.items()}
    return value


def contains_legacy_text(value):
    if isinstance(value, str):
        return any(text in value for text in LEGACY_ASPEN_BOUNDARY_TEXTS)
    if isinstance(value, list):
        return any(contains_legacy_text(item) for item in value)
    if isinstance(value, dict):
        return any(contains_legacy_text(item) for item in value.values())
    return False


def escape_invalid_json_backslashes(text):
    """Repair legacy reports that contain raw Windows backslashes inside JSON strings."""
    text = str(text or "")
    out = []
    i = 0
    valid_simple_escapes = set('"\\/bfnrt')
    hex_digits = set("0123456789abcdefABCDEF")
    while i < len(text):
        if text[i] != "\\":
            out.append(text[i])
            i += 1
            continue
        j = i
        while j < len(text) and text[j] == "\\":
            j += 1
        run_len = j - i
        next_char = text[j] if j < len(text) else ""
        valid_escape = run_len % 2 == 0 or next_char in valid_simple_escapes
        if not valid_escape and next_char == "u":
            valid_escape = j + 4 < len(text) and all(ch in hex_digits for ch in text[j + 1:j + 5])
        out.append("\\" * (run_len if valid_escape else run_len + 1))
        i = j
    return "".join(out)


def read_json(path):
    text = Path(path).read_text(encoding="utf-8-sig")
    missing = object()
    parsed = json_loads_repaired(text, default=missing)
    if parsed is missing:
        raise json.JSONDecodeError("invalid JSON", text, 0)
    return parsed


def json_loads_repaired(text, default=None):
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        try:
            return json.loads(escape_invalid_json_backslashes(text))
        except Exception:
            return default
    except Exception:
        return default


def write_json_file(path, payload):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = normalize_legacy_texts(payload)
    text = json.dumps(payload, ensure_ascii=False, indent=2, default=str) + "\n"
    tmp_path = path.with_name(
        ".{}.{}.{}.tmp".format(path.name, os.getpid(), threading.get_ident())
    )
    last_error = None
    for attempt in range(20):
        try:
            tmp_path.write_text(text, encoding="utf-8")
            os.replace(str(tmp_path), str(path))
            return
        except PermissionError as exc:
            last_error = exc
            time.sleep(min(0.75, 0.05 * (attempt + 1)))
        except OSError as exc:
            last_error = exc
            if getattr(exc, "winerror", None) != 5:
                raise
            time.sleep(min(0.75, 0.05 * (attempt + 1)))
    try:
        if tmp_path.exists():
            tmp_path.unlink()
    except Exception:
        pass
    if last_error:
        raise last_error


def normalize_relative_volatility_retry_paths(report):
    report = dict(report or {})
    retry = report.get("property_strategy_retry") or {}
    output_csv = str(retry.get("output_csv") or "").strip()
    work_dir = str(retry.get("work_dir") or "").strip()
    if not output_csv and not work_dir:
        return report
    paths = dict(report.get("research_task_package_paths") or {})
    if output_csv:
        previous = paths.get("relative_volatility_kvalue_results_csv") or ""
        if previous and previous != output_csv:
            paths.setdefault("relative_volatility_kvalue_results_previous_csv", previous)
        paths["relative_volatility_kvalue_results_csv"] = output_csv
    if work_dir:
        paths["relative_volatility_flash_work_dir"] = work_dir
    report["research_task_package_paths"] = paths
    return report


def write_csv_file(path, rows, fieldnames=None):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    rows = rows or []
    if fieldnames is None:
        fieldnames = []
        for row in rows:
            for key in row.keys():
                if key not in fieldnames:
                    fieldnames.append(key)
    with path.open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames, extrasaction="ignore")
        writer.writeheader()
        for row in rows:
            writer.writerow({key: normalize_legacy_texts(row.get(key, "")) for key in fieldnames})
    return path


def read_csv_rows(path, encodings=("utf-8-sig", "utf-8", "gbk", "cp936")):
    path = Path(path)
    if not path.exists():
        return []
    last_error = None
    for encoding in encodings:
        try:
            with path.open("r", encoding=encoding, newline="") as handle:
                return list(csv.DictReader(handle))
        except UnicodeDecodeError as exc:
            last_error = exc
    if last_error:
        raise last_error
    return []


def read_json_default(path, default):
    try:
        return read_json(path)
    except Exception:
        return default


def normalized_path_key(value):
    value = str(value or "").strip()
    if not value:
        return ""
    try:
        path = Path(value)
        if not path.is_absolute():
            path = (BASE_DIR / path)
        return str(path.resolve()).replace("/", "\\").lower()
    except Exception:
        return value.replace("/", "\\").lower()


def same_path_value(left, right):
    left_key = normalized_path_key(left)
    right_key = normalized_path_key(right)
    return bool(left_key and right_key and (left_key == right_key or left_key.endswith(right_key) or right_key.endswith(left_key)))


def path_is_within_root(path, root):
    path_text = str(Path(path).resolve()).casefold()
    root_text = str(Path(root).resolve()).casefold().rstrip("\\/")
    return path_text == root_text or path_text.startswith(root_text + os.sep)


def run_state_report_path(run_state=None):
    run_state = run_state or RUN_STATE
    report_path = str(run_state.get("report_path") or "").strip()
    if report_path:
        return report_path
    output_dir = str(run_state.get("output_dir") or "").strip()
    if output_dir:
        return str((Path(output_dir) / "full_agent_decision_report.json").resolve())
    return ""


def run_state_matches_report(run_state, report_path):
    return same_path_value(run_state_report_path(run_state), report_path)


def system_frontend_current(paths):
    paths = paths or {}
    html_path = paths.get("system_frontend_html")
    manifest_path = paths.get("system_frontend_manifest_json")
    if not html_path or not manifest_path:
        return False
    if not Path(html_path).exists() or not Path(manifest_path).exists():
        return False
    manifest = read_json_default(manifest_path, {})
    return int(manifest.get("frontend_template_version") or 0) >= SYSTEM_FRONTEND_TEMPLATE_VERSION


def file_meta(path, label=None):
    item = {
        "path": str(path),
        "label": label or Path(path).name,
        "exists": False,
        "mtime": 0,
        "mtime_iso": "",
        "size": 0,
    }
    try:
        resolved = Path(path)
        if resolved.exists():
            stat = resolved.stat()
            item.update({
                "exists": True,
                "mtime": stat.st_mtime,
                "mtime_iso": iso_from_timestamp(stat.st_mtime),
                "size": stat.st_size,
            })
    except OSError:
        pass
    return item


