def preferred_gromacs_interaction_summary_path():
    candidates = (
        GROMACS_MASTER_DIR / "GROMACS_equilibrated_interaction_summary.csv",
        GROMACS_MASTER_DIR / "GROMACS_auto_interaction_summary.csv",
    )
    for path in candidates:
        if path.exists():
            return path
    return candidates[0]


def compact_alias_text(value):
    return re.sub(r"[\s\-_/,，、（）()]+", "", str(value or "").upper())


def canonical_gromacs_code(value):
    token = re.sub(r"[^A-Z0-9]+", "", str(value or "").upper())
    if token.endswith("WG") and len(token) > 2:
        token = token[:-2]
    return GROMACS_TOKEN_ALIASES.get(token, token)


def load_gromacs_project_aliases():
    global GROMACS_PROJECT_ALIAS_CACHE
    if GROMACS_PROJECT_ALIAS_CACHE is not None:
        return GROMACS_PROJECT_ALIAS_CACHE
    aliases = {}
    for label, code in GROMACS_TEXT_ALIASES.items():
        key = compact_alias_text(label)
        if key:
            aliases[key] = code
    for path in [
        preferred_gromacs_interaction_summary_path(),
        GROMACS_MASTER_DIR / "GROMACS_auto_interaction_summary.csv",
        GROMACS_MASTER_DIR / "GROMACS_RDF_effect_summary_带名称和判断.csv",
        GROMACS_MASTER_DIR / "Gaussian_auto_BSSE_summary.csv",
    ]:
        for row in read_csv_rows(path):
            code = canonical_gromacs_code(row.get("ExtractantCode") or row.get("萃取剂代号"))
            if not code:
                continue
            for name in [
                row.get("ExtractantName"),
                row.get("萃取剂名称"),
                row.get("类型"),
            ]:
                key = compact_alias_text(name)
                if key:
                    aliases.setdefault(key, code)
    GROMACS_PROJECT_ALIAS_CACHE = aliases
    return aliases


def gromacs_token(value):
    text_key = compact_alias_text(value)
    aliases = load_gromacs_project_aliases()
    if text_key in aliases:
        return aliases[text_key]
    return canonical_gromacs_code(value)


def gromacs_token_candidates(*values):
    tokens = []
    for value in values:
        text = str(value or "")
        if not text:
            continue
        raw = re.sub(r"[^A-Z0-9]+", "", text.upper())
        for candidate in {raw, gromacs_token(raw), gromacs_token(text)}:
            if candidate and candidate not in tokens:
                tokens.append(candidate)
        text_key = compact_alias_text(text)
        for marker, alias in load_gromacs_project_aliases().items():
            if marker and marker == text_key and alias not in tokens:
                tokens.append(alias)
    return tokens


def gromacs_asset_search_dirs(token):
    dirs = []
    for item in [
        GROMACS_GENERATED_ASSET_LIBRARY / token,
        GROMACS_MASTER_DIR,
        GROMACS_PROJECT_ROOT / token,
        GROMACS_SOBTOP_DIR,
    ]:
        if item and item.exists() and item not in dirs:
            dirs.append(item)
    return dirs


