def build_next_action_plan(report):
    task = report.get("separation_task") or {}
    gaps = report.get("transfer_gap_report") or []
    full_flow = task_is_full_flow_verified(report)
    if full_flow:
        return [
            {
                "priority": 1,
                "action": "复核该任务的全流程验证结果",
                "rationale": "该二元任务已经走到分子证据、Aspen 验证、多目标优化和可信度审计终点，可作为总控 Agent 的验证结果展示。",
                "owner": "agent/auditor",
            },
            {
                "priority": 2,
                "action": "生成汇报摘要",
                "rationale": "将这次二元任务整理为任务输入、体系诊断、候选生成、分子证据、流程优化和审计结论的完整叙述。",
                "owner": "manuscript",
            },
        ]
    plan = []
    gap_items = {row.get("item") for row in gaps if row.get("status") == "missing"}
    if "thermo_basis" in gap_items:
        plan.append({
            "priority": len(plan) + 1,
            "action": "检索并确认热力学/VLE 基础",
            "rationale": "该二元任务尚未完成物性方法确认，需要先确定可用于流程模拟的 VLE 或物性模型依据。",
            "owner": "agent + human check",
        })
    if "candidate_seed_rules" in gap_items:
        plan.append({
            "priority": len(plan) + 1,
            "action": "生成候选溶剂种子规则",
            "rationale": "根据目标产物、组分极性/挥发性和分离边界，建立该二元任务自己的候选池，而不是套用其他任务排序。",
            "owner": "agent",
        })
    if "molecular_snapshot" in gap_items:
        plan.append({
            "priority": len(plan) + 1,
            "action": "排队低成本分子证据计算",
            "rationale": "先生成 Gaussian/ESP/BSSE 和 MD/RDF 任务清单，用于判断候选溶剂是否具有体系特异选择性。",
            "owner": "molecular workflow",
        })
    if "aspen_template" in gap_items:
        plan.append({
            "priority": len(plan) + 1,
            "action": "建立 Aspen 初始流程模板",
            "rationale": "只有在热力学基础和候选溶剂边界明确后，才生成该体系的流程模板或 BKP。",
            "owner": "process agent",
        })
    if "process_evidence" in gap_items:
        plan.append({
            "priority": len(plan) + 1,
            "action": "启动流程验证/优化队列",
            "rationale": "有兼容模板后再进入 Aspen 验证、NSGA-II 和 TOPSIS 排序，保证每个二元任务使用自己的证据链。",
            "owner": "process optimizer",
        })
    if not plan:
        plan.append({
            "priority": 1,
            "action": "人工复核审计状态",
            "rationale": "当前报告未检测到明确缺口，但也未进入已验证边界。",
            "owner": "human check",
        })
    return plan


def build_lookup_confidence_note(lookup_rows):
    if not lookup_rows:
        return "未执行在线组分识别。"
    found = [row for row in lookup_rows if row.get("status") == "found"]
    missing = [row for row in lookup_rows if row.get("status") != "found"]
    cas_pending = [row.get("input") for row in found if not row.get("cas")]
    parts = [
        "PubChem PUG-REST was used for CID, molecular identity and synonym lookup.",
        "CAS numbers are extracted from PubChem synonyms and checksum-filtered; final regulatory use still needs manual confirmation.",
    ]
    if found:
        parts.append("Resolved: {}.".format(", ".join("{}(CID {})".format(row.get("input"), row.get("cid")) for row in found)))
    if cas_pending:
        parts.append("CAS pending: {}.".format(", ".join(cas_pending)))
    if missing:
        parts.append("Lookup unresolved/offline: {}.".format(", ".join(row.get("input", "-") for row in missing)))
    return " ".join(parts)


def web_search_url(query):
    return "https://www.google.com/search?q={}".format(urllib.parse.quote_plus(query))


def scholar_search_url(query):
    return "https://scholar.google.com/scholar?q={}".format(urllib.parse.quote_plus(query))


def nist_webbook_url(name):
    return "https://webbook.nist.gov/cgi/cbook.cgi?Name={}&Units=SI".format(urllib.parse.quote_plus(name or ""))


def seed_strategy_for_system(components, target_product, compatible):
    component_set = {component_token(item) for item in components}
    task = {
        "component_a": components[0] if len(components) > 0 else "",
        "component_b": components[1] if len(components) > 1 else "",
        "target_product": target_product,
    }
    classification = classify_binary_system(task)
    if compatible:
        return [
            {
                "family": "verified fluorocarbon ED solvents",
                "examples": "NMP, sulfolane, GBL, PC, ADPN",
                "reason": "Current verified evidence already links molecular selectivity with extractive-distillation validation for C3F8/C3F6.",
                "status": "verified_case",
            }
        ]
    if classification["solvent_strategy"] in {
        "hydrogen_bonding_high_boiling_entrainers",
        "hydrogen_bonding_or_polar_high_boiling_seeds",
    }:
        return [
            {
                "family": "high-boiling hydrogen-bonding entrainer seeds",
                "examples": "glycerol, diethylene glycol, triethylene glycol, propanediols, lactams, phosphate esters",
                "reason": "The Agent classified this as {} with {}; first screen high-boiling hydrogen-bonding candidates and exclude feed components themselves.".format(
                    classification["family"],
                    classification["nonideality"],
                ),
                "status": "needs_gaussian_gromacs_screening",
            },
            {
                "family": "configured polar benchmark solvents",
                "examples": "DMSO, sulfolane, NMP, ethylene carbonate, DMPU",
                "reason": "These are already represented in the project/Aspen mapping and can serve as molecular controls, but final use requires system-specific VLE, miscibility and parameter checks.",
                "status": "benchmark_controls",
            },
            {
                "family": "no-third-solvent process baseline",
                "examples": "ordinary/vacuum/pressure-swing distillation baseline",
                "reason": "The Agent should compare whether a solvent is needed at all before claiming extractive distillation is superior.",
                "status": "route_baseline_required",
            },
        ]
    if "CO2" in component_set:
        return [
            {
                "family": "physical CO2-affinity solvents",
                "examples": "propylene carbonate, sulfolane, NMP, polyethylene-glycol dimethyl ethers",
                "reason": "CO2-containing systems should first test high-boiling physical solvents with known CO2 affinity before process validation.",
                "status": "hypothesis",
            },
            {
                "family": "polar aprotic ED seeds",
                "examples": "NMP, DMF/DMAC controls, lactones, carbonates",
                "reason": "Use polar aprotic families as a transferable seed pool, but require new molecular evidence for this binary system.",
                "status": "needs_molecular_screening",
            },
            {
                "family": "reactive-solvent controls",
                "examples": "amines as caution/control only",
                "reason": "Reactive CO2 absorption may violate the current extractive-distillation boundary and should be separated from physical-solvent screening.",
                "status": "boundary_check",
            },
        ]
    return [
        {
            "family": "high-boiling polar aprotic seeds",
            "examples": "NMP, sulfolane, lactones, carbonates, nitriles",
            "reason": "Start from solvents that can be represented in Aspen and molecular workflows, then rank by system-specific interaction evidence.",
            "status": "hypothesis",
        }
    ]


def build_literature_vle_summary(component_a, component_b, web_queries):
    literature_rows = []
    for query in web_queries[:3]:
        records = crossref_get_works(query.get("query", ""), rows=4)
        for record in records:
            row = dict(record)
            row["topic"] = query.get("topic")
            row["query"] = query.get("query")
            row["use_in_agent"] = (
                "candidate thermo/VLE lead; metadata only, inspect source before claiming data"
                if row.get("status") != "lookup_failed"
                else "lookup failed; use manual search link"
            )
            literature_rows.append(row)
    nist_rows = [
        {
            "component": component_a,
            "nist_url": nist_webbook_url(component_a),
            "purpose": "Check component identity, critical constants and phase-change data where available.",
            "status": "link_generated",
        },
        {
            "component": component_b,
            "nist_url": nist_webbook_url(component_b),
            "purpose": "Check component identity, critical constants and phase-change data where available.",
            "status": "link_generated",
        },
    ]
    return {
        "summary_status": "metadata_leads_generated",
        "method": "Crossref metadata search + NIST WebBook component links",
        "caution": "The rows below are literature leads, not extracted VLE numerical data. Use DOI/NIST links for manual verification before Aspen model selection.",
        "crossref_records": literature_rows[:10],
        "nist_component_links": nist_rows,
    }


def candidate_aspen_status(candidate):
    token = component_token(candidate.get("code") or candidate.get("name") or candidate.get("aspen_component_id"))
    alias = ASPEN_COMPONENT_ALIASES.get(token) or ASPEN_COMPONENT_ALIASES.get(component_token(candidate.get("name")))
    aspen_id = str(candidate.get("aspen_component_id") or (alias or {}).get("aspen_component_id") or "").strip()
    if aspen_id:
        confidence = str((alias or {}).get("confidence") or "").strip()
        if confidence in {"needs_aspen_probe", "unverified_aspen_alias"}:
            return "needs_aspen_identity_check"
        return "configured_current_project"
    return "needs_aspen_identity_check"


