def build_candidate_molecular_task_queue(report, solvent_pool):
    task = report.get("separation_task") or {}
    compatible = bool(task.get("compatible_verified_case"))
    component_a = task.get("component_a", "")
    component_b = task.get("component_b", "")
    target_product = task.get("target_product", "")
    rows = []
    active_solvents = molecular_automation_solvent_items(report, solvent_pool, default_limit=1)
    active_codes = {component_token(row.get("code")) for row in active_solvents}
    for solvent in (solvent_pool.get("items") or [])[:12]:
        legacy_ready = solvent.get("legacy_molecular_evidence_status") == "legacy_c3f6_c3f8_evidence_available"
        approved_for_execution = component_token(solvent.get("code")) in active_codes
        base = {
            "system": "{}/{}".format(component_a, component_b),
            "target_product": target_product,
            "solvent_code": solvent.get("code"),
            "solvent_name": solvent.get("name"),
            "solvent_cid": solvent.get("cid"),
            "solvent_cas": solvent.get("cas"),
            "priority": solvent.get("rank"),
            "prescreen_score": solvent.get("prescreen_score"),
            "recommendation_status": solvent.get("recommendation_status"),
            "relative_volatility_gate": solvent.get("relative_volatility_gate"),
            "alpha_definition": solvent.get("alpha_definition"),
            "alpha_0": solvent.get("alpha_0"),
            "alpha_s_best": solvent.get("alpha_s_best"),
            "alpha_improvement_best": solvent.get("alpha_improvement_best"),
            "alpha_best_sf_ratio": solvent.get("alpha_best_sf_ratio"),
            "alpha_integrated_score": solvent.get("alpha_integrated_score"),
            "alpha_system_fit_reason": solvent.get("alpha_system_fit_reason"),
            "alpha_integrated_decision": solvent.get("alpha_integrated_decision"),
            "ed_preferential_binding_component": solvent.get("ed_preferential_binding_component"),
            "learning_status": solvent.get("learning_status"),
            "execution_policy": "approved_current_recommendation" if approved_for_execution else "prescreen_only_waiting_user_confirmation",
            "aspen_component_id": solvent.get("aspen_component_id"),
        }
        rows.append(dict(base, **{
            "task_type": "gaussian_bsse_or_esp",
            "objective": "Compare whether solvent preferentially stabilizes the alpha bottom-key component before process validation.",
            "input_needed": "component structures + solvent structure + initial conformers",
            "expected_output": "Delta interaction energy and directionality flag",
            "status": (
                "imported_from_legacy_gaussian_bsse"
                if legacy_ready
                else (
                    "done_for_verified_case"
                    if compatible and solvent.get("screening_status") == "verified_seed"
                    else ("queued" if approved_for_execution else "prescreen_only_waiting_user_confirmation")
                )
            ),
            "legacy_evidence_policy": solvent.get("legacy_molecular_evidence_policy", ""),
        }))
        rows.append(dict(base, **{
            "task_type": "md_rdf_msd_check",
            "objective": "Check RDF/coordination/diffusion consistency for top molecular candidates.",
            "input_needed": "force-field parameters + mixture box + solvent candidate",
            "expected_output": "RDF peaks, coordination numbers, MSD/diffusion and MD interaction-energy trend",
            "status": (
                "imported_from_legacy_gromacs_rdf_msd"
                if legacy_ready
                else (
                    "done_for_verified_case"
                    if compatible and solvent.get("screening_status") == "verified_seed"
                    else ("blocked_until_gaussian_pass" if approved_for_execution else "prescreen_only_waiting_user_confirmation")
                )
            ),
            "legacy_evidence_policy": solvent.get("legacy_molecular_evidence_policy", ""),
        }))
        rows.append(dict(base, **{
            "task_type": "aspen_component_check",
            "objective": "Confirm component availability and aliases before process template generation.",
            "input_needed": "CAS/CID/Aspen component ID and property-method basis",
            "expected_output": "Aspen component mapping status",
            "status": "ready" if solvent.get("aspen_component_id") else "needs_identity_mapping",
        }))
    return rows


def molecular_automation_solvent_items(report, solvent_pool, default_limit=1):
    task = report.get("separation_task") or {}
    pool_items = solvent_pool.get("items") or []
    if not pool_items:
        return []
    if not task.get("compatible_verified_case"):
        try:
            screen = build_screening_state(report)
            alpha = ((screen.get("progress") or {}).get("alpha") or {})
            if int(alpha.get("pending") or 0) > 0:
                return []
        except Exception:
            pass
    requested_limit = (
        task.get("molecular_approved_solvent_count")
        or task.get("approved_molecular_solvent_count")
        or task.get("molecular_batch_size")
    )
    limit = clean_int_arg(
        requested_limit,
        default_limit,
        min_value=1,
        max_value=max(1, len(pool_items)),
    )
    auto_selected = [] if molecular_selection_is_manual(report) else post_alpha_top_candidates(pool_items, limit=limit)
    if auto_selected:
        return auto_selected
    requested_token = normalize_agent_token(
        task.get("molecular_selected_solvent_code")
        or task.get("selected_solvent_code")
        or report.get("selected_molecular_solvent_code")
    )
    if requested_token:
        for row in pool_items:
            row_tokens = {
                normalize_agent_token(row.get("code")),
                normalize_agent_token(row.get("aspen_component_id")),
                normalize_agent_token(row.get("name")),
            }
            row_tokens.discard("")
            if requested_token in row_tokens:
                selected = dict(row)
                if not relative_volatility_gate_allows_execution(selected):
                    selected["relative_volatility_gate"] = "manual_alpha_override"
                    selected["alpha_manual_override_reason"] = "User selected this solvent for molecular exploration after alpha prescreen."
                return [selected]
        return []
    status_order = {
        "current_recommended_for_confirmation": 0,
        "recommend_next_if_current_fails": 1,
        "learned_good_reference": 2,
        "learned_neutral_reference": 3,
        "reserve_prescreen_candidate": 4,
        "learned_bad_hold": 8,
    }
    executable_items = sorted(
        [row for row in pool_items if relative_volatility_gate_allows_execution(row)],
        key=lambda row: (
            status_order.get(row.get("recommendation_status") or "", 5),
            -safe_float(row.get("alpha_integrated_score"), 0.0),
            int(row.get("rank") or 999),
            -safe_float(row.get("prescreen_score"), 0.0),
        ),
    )
    selected_items = list(executable_items[:limit])
    return selected_items


def build_molecular_automation_summary(report, solvent_pool):
    task = report.get("separation_task") or {}
    compatible = bool(task.get("compatible_verified_case"))
    lookup_rows = report.get("online_component_info") or []
    imported = report.get("molecular_evidence_import") or {}
    imported_count = int(imported.get("evidence_record_count") or 0)
    solvent_items = molecular_automation_solvent_items(report, solvent_pool)
    current_solvent = solvent_items[0] if solvent_items else {}
    lookup_ready = bool(lookup_rows) and all(row.get("status") == "found" for row in lookup_rows)
    solvent_ready = [row for row in solvent_items if row.get("cid")]
    status = "existing_evidence_available" if compatible else "input_generation_ready"
    if imported_count:
        status = "imported_results_available"
    if not lookup_ready:
        status = "blocked_component_identity"
    elif not solvent_items and not compatible:
        status = "blocked_relative_volatility_prescreen"
    elif not solvent_ready:
        status = "blocked_solvent_identity"
    return {
        "status": status,
        "scope": "Gaussian/BSSE single-point input generation plus GROMACS queue scaffolding",
        "recommendation_mode": "relative_volatility_gate_then_user_confirmed_molecular_simulation",
        "current_recommended_solvent": current_solvent,
        "relative_volatility_prescreen": solvent_pool.get("relative_volatility_prescreen") or {},
        "learning_memory_path": str(SOLVENT_LEARNING_MEMORY_PATH.resolve()),
        "top_candidate_limit": len(solvent_items),
        "component_identity_ready": lookup_ready,
        "solvent_identity_ready_count": len(solvent_ready),
        "imported_evidence_record_count": imported_count,
        "imported_evidence_status": imported.get("status", ""),
        "gaussian_route": "B3LYP/6-311G(d,p) EmpiricalDispersion=GD3BJ; Counterpoise=2 for dimers",
        "md_scope": "GROMACS command queue and MDP files are generated; force-field/topology generation remains an explicit prerequisite",
        "automation_boundary": (
            "For new systems the Agent generates runnable-looking input decks and command queues, "
            "but parsed Gaussian/MD evidence is not claimed until the logs and trajectories are imported."
        ),
        "job_types": [
            {"job_type": "pubchem_structure_fetch", "status": "ready" if lookup_ready else "blocked"},
            {"job_type": "gaussian_monomer_inputs", "status": "ready" if lookup_ready else "blocked"},
            {"job_type": "gaussian_counterpoise_dimers", "status": "ready" if lookup_ready and solvent_ready else "blocked"},
            {"job_type": "gaussian_log_parser", "status": "imported_or_ready" if imported_count else "generated_by_export"},
            {"job_type": "gromacs_mdp_and_command_queue", "status": "imported_or_ready" if imported_count else "generated_by_export"},
            {"job_type": "gromacs_topology_parameterization", "status": "external_prerequisite"},
        ],
        "generated_files": {},
    }


def solvent_match_token(value):
    return re.sub(r"[^A-Z0-9]+", "", str(value or "").upper())


def process_solvent_items_for_report(report, solvent_pool):
    task = report.get("separation_task") or {}
    pool_items = (solvent_pool.get("items") or [])[:6]
    selected = report.get("selected_flow_candidates") or []
    selected_keys = {
        solvent_match_token(row.get("code") or row.get("aspen_component_id") or row.get("name") or row.get("solvent_name"))
        for row in selected
        if row
    }
    matched = []
    for solvent in pool_items:
        keys = {
            solvent_match_token(solvent.get("code")),
            solvent_match_token(solvent.get("aspen_component_id")),
            solvent_match_token(solvent.get("name")),
        }
        if selected_keys.intersection(keys):
            matched.append(solvent)
    if not matched and selected:
        for index, candidate in enumerate(selected, start=1):
            code = candidate.get("code") or candidate.get("aspen_component_id") or "SOLVENT_{}".format(index)
            matched.append({
                "rank": index,
                "code": code,
                "name": candidate.get("name") or candidate.get("solvent_name") or code,
                "aspen_component_id": candidate.get("aspen_component_id") or "",
                "aspen_status": "available_current_template" if candidate.get("aspen_component_id") else "needs_identity_mapping",
            })
    if matched:
        return matched
    limit = clean_int_arg(task.get("flow_validation_count"), 4, min_value=1, max_value=max(1, len(pool_items)))
    return pool_items[:limit]


def solvent_process_rejected(solvent):
    return str(solvent.get("distillation_gate") or "").startswith("reject_")


