def lookup_formula_for_code(report, code):
    token = component_token(code)
    for row in report.get("online_component_info") or []:
        row_tokens = {
            component_token(row.get("input")),
            component_token(row.get("normalized_identifier")),
            component_token(row.get("title")),
            component_token(row.get("query")),
        }
        if token and token in row_tokens:
            return row.get("molecular_formula") or ""
    candidate_rows = []
    brief_pool = ((report.get("system_research_brief") or {}).get("candidate_solvent_pool") or {}).get("items") or []
    candidate_rows.extend(brief_pool)
    external = report.get("external_candidate_library") or {}
    for key in ("items", "ready_for_aspen_alpha_items", "identity_mapping_queue"):
        candidate_rows.extend(external.get(key) or [])
    preflight = report.get("external_candidate_identity_preflight") or {}
    candidate_rows.extend(preflight.get("checked_items") or [])
    for row in candidate_rows:
        row_tokens = {
            component_token(row.get("code")),
            component_token(row.get("name")),
            component_token(row.get("pubchem_name")),
            component_token(row.get("aspen_component_id")),
        }
        if token and token in row_tokens:
            return row.get("molecular_formula") or row.get("formula") or ""
    return ""


def local_aspen_probe_component_id(code, name="", fallback="CMP"):
    raw = code or name or fallback
    token = re.sub(r"[^A-Z0-9]+", "", str(raw or "").upper())
    if not token:
        token = fallback
    if not token[0].isalpha():
        token = "C" + token
    return token[:8]


def aspen_identity_for_item(report, code, name="", explicit_aspen_id="", role="component"):
    token = component_token(code or name)
    alias = ASPEN_COMPONENT_ALIASES.get(token) or ASPEN_COMPONENT_ALIASES.get(component_token(name))
    aspen_id = str(explicit_aspen_id or (alias or {}).get("aspen_component_id") or "").strip()
    lookup = lookup_row_for_component((report or {}).get("online_component_info") or [], code or name)
    formula = str((alias or {}).get("formula") or lookup_formula_for_code(report, code or name) or token or aspen_id).strip()
    confidence = (alias or {}).get("confidence", "")
    if explicit_aspen_id and not confidence:
        confidence = "provided_by_candidate_library"
    if not aspen_id and role == "feed_component" and lookup.get("status") == "found" and formula:
        aspen_id = local_aspen_probe_component_id(code, name=name, fallback="CMP")
        confidence = "pubchem_formula_preflight_needs_aspen_probe"
    if aspen_id:
        status = "mapped_by_agent"
        if confidence in {"needs_aspen_probe", "pubchem_formula_preflight_needs_aspen_probe"}:
            status = "mapped_needs_aspen_probe"
    else:
        status = "needs_aspen_component_check"
    return {
        "role": role,
        "name": name or code,
        "code": code,
        "aspen_component_id": aspen_id,
        "formula": formula,
        "status": status,
        "mapping_confidence": confidence or "unmapped",
    }


def parse_feed_fraction_pair(task):
    text = str(task.get("feed_molar_ratio") or "")
    numbers = re.findall(r"\d+(?:\.\d+)?", text)
    if len(numbers) >= 2:
        first = safe_float(numbers[0], 90.0)
        second = safe_float(numbers[1], 10.0)
    else:
        first, second = 90.0, 10.0
    total = max(first + second, 1.0e-12)
    return first / total, second / total


def build_zero_build_aspen_spec(task, classification, property_method, component_mapping, selected_solvent):
    feed_components = [row for row in component_mapping if row.get("role") == "feed_component"]
    components = []
    seen = set()
    for row in feed_components + [selected_solvent]:
        cid = row.get("aspen_component_id")
        if not cid or cid in seen:
            continue
        seen.add(cid)
        formula = row.get("formula") or cid
        mapping_confidence = str(row.get("mapping_confidence") or "")
        role = str(row.get("role") or "")
        db_name = row.get("db_name") or row.get("aspen_databank_id") or row.get("databank_id") or cid
        if role == "candidate_solvent" and formula and formula != cid:
            db_name = formula
        elif mapping_confidence in {"needs_aspen_probe", "unverified_aspen_alias", "pubchem_formula_preflight_needs_aspen_probe"} and formula and formula != cid:
            db_name = formula
        components.append({
            "id": cid,
            "formula": formula,
            "db_name": db_name,
            "role": role,
            "mapping_confidence": mapping_confidence,
        })
    if len(feed_components) < 2 or not selected_solvent.get("aspen_component_id"):
        return {}
    a, b = feed_components[:2]
    solvent_id = selected_solvent["aspen_component_id"]
    frac_a, frac_b = parse_feed_fraction_pair(task)
    feed_total = 10.0
    sf_initial = safe_float(selected_solvent.get("alpha_best_sf_ratio"))
    if sf_initial is None or sf_initial <= 0:
        sf_initial = 1.5
    solvent_flow = feed_total * sf_initial
    makeup_flow = max(0.02, feed_total * 0.02)
    pressure_bar = max(0.001, float(task.get("feed_pressure_mpa") or 0.1) * 10.0)
    feed_temperature_c = float(task.get("feed_temperature_c") or 50.0)
    n1 = 50 if classification.get("family") in {"aqueous_associating_oxygenate", "polar_associating_liquid"} else 60
    nf1 = max(2, int(round(n1 * 0.70)))
    ns1 = max(2, int(round(n1 * 0.42)))
    n2 = 8
    condenser_mode = "PARTIAL-V"
    distillate_phase = "L" if condenser_mode == "TOTAL" else "V"
    target_purity = safe_float(task.get("target_purity"), 0.99) or 0.99
    target_purity_basis = str(task.get("target_purity_basis") or "mole_fraction").strip().lower()
    target_recovery = safe_float(task.get("target_recovery"))
    if target_recovery is not None and not 0.0 < target_recovery <= 1.0:
        target_recovery = None
    design_recovery_guess = target_recovery if target_recovery is not None else 0.99
    target_index = 0 if component_token(task.get("target_product")) == component_token(a.get("code") or a.get("name")) else 1
    target_feed = feed_total * (frac_a if target_index == 0 else frac_b)
    other_feed = max(0.05, feed_total - target_feed)
    d1_guess = max(0.05, min(feed_total * 0.98, target_feed * design_recovery_guess))
    d2_guess = max(0.05, min(feed_total * 0.98, other_feed * design_recovery_guess))
    return {
        "name": "agent_generated_{}_{}_{}".format(
            safe_file_token(task.get("component_a") or "A"),
            safe_file_token(task.get("component_b") or "B"),
            safe_file_token(solvent_id),
        ),
        "target_product": task.get("target_product") or "",
        "target_aspen_component_id": feed_components[target_index].get("aspen_component_id") if feed_components else "",
        "target_purity": target_purity,
        "target_purity_basis": target_purity_basis,
        "target_recovery": target_recovery,
        "target_recovery_mode": "hard_constraint" if target_recovery is not None else "maximize_only",
        "design_recovery_guess": design_recovery_guess,
        "feed_component_mapping": feed_components,
        "process_topology_mode": "closed_loop_calculator_inventory_recycle",
        "recycle_control_mode": "calculator_inventory_control",
        "closed_loop_completion_policy": {
            "requires_closed_loop_optimization_pass": True,
            "open_loop_allowed_for_initialization_only": True,
            "reject_open_loop_as_full_flow": True,
            "failure_policy": "block_and_require_recycle_repair_after_repeated_closed_loop_failures",
        },
        "property_method": property_method,
        "property_keyword": property_method,
        "components": components,
        "streams": {
            "C1": {"temperature_c": 25.0, "pressure_bar": pressure_bar, "mole_flow": {solvent_id: solvent_flow}},
            "C2": {"temperature_c": feed_temperature_c, "pressure_bar": pressure_bar, "mole_flow": {solvent_id: solvent_flow}},
            "F": {
                "temperature_c": feed_temperature_c,
                "pressure_bar": pressure_bar,
                "mole_flow": {
                    a["aspen_component_id"]: feed_total * frac_a,
                    b["aspen_component_id"]: feed_total * frac_b,
                },
            },
        },
        "blocks": [
            {"id": "B1", "type": "RADFRAC", "in": ["C2", "S2"], "out": ["D", "W"]},
            {"id": "B2", "type": "RADFRAC", "in": ["W"], "out": ["S1", "S3"]},
            {"id": "B3", "type": "MIXER", "in": ["C1", "S3"], "out": ["C2"]},
            {"id": "B4", "type": "HEATER", "in": ["F"], "out": ["S2"]},
        ],
        "mixer_max_iterations": 200,
        "heater": {"B4": {"pressure_bar": pressure_bar, "vapor_fraction": 0.0}},
        "calculator": {
            "id": "C-1",
            "solvent_component": solvent_id,
            "target_flow": solvent_flow,
            "recycle_stream": "S3",
            "makeup_stream": "C1",
        },
        "radfrac": {
            "B1": {
                "nstage": n1,
                "init_option": "STANDARD",
                "max_iterations": 200,
                "condenser": condenser_mode,
                "feeds": {"C2": ns1, "S2": nf1},
                "products": {"D": [1, distillate_phase], "W": [n1, "L"]},
                "pressure_bar": pressure_bar,
                "distillate_mole_flow": d1_guess,
                "reflux_ratio": 4.0,
                "internal_sections": [[1, 2, max(2, ns1 - 1)], [2, ns1, max(ns1, nf1 - 1)], [3, nf1, n1 - 1]],
            },
            "B2": {
                "nstage": n2,
                "max_iterations": 200,
                "condenser": condenser_mode,
                "feeds": {"W": 2},
                "products": {"S1": [1, distillate_phase], "S3": [n2, "L"]},
                "pressure_bar": pressure_bar,
                "distillate_mole_flow": max(0.1, feed_total - d1_guess),
                "reflux_ratio": 1.5,
                "internal_sections": [[1, 2, n2 - 1]],
            },
        },
        "validation_role": "generic Aspen ED zero-build archive for real optimization",
        "validation_source": "full_agent_dashboard.build_zero_build_aspen_spec",
        "validation_case": {
            "case_id": "GENERIC_{}_{}_{}".format(
                safe_file_token(task.get("component_a") or "A"),
                safe_file_token(task.get("component_b") or "B"),
                safe_file_token(solvent_id),
            ),
            "solvent_name": selected_solvent.get("name") or solvent_id,
            "aspen_component_id": solvent_id,
            "target_product": task.get("target_product") or "",
            "target_aspen_component_id": feed_components[target_index].get("aspen_component_id") if feed_components else "",
            "target_purity": target_purity,
            "target_purity_basis": target_purity_basis,
            "target_recovery": target_recovery,
            "target_recovery_mode": "hard_constraint" if target_recovery is not None else "maximize_only",
            "SF": sf_initial,
            "makeup_flow": makeup_flow,
            "recycle_control_mode": "calculator_inventory_control",
            "RR1": 4.0,
            "D1": d1_guess,
            "RR2": 1.5,
            "D2": max(0.1, feed_total - d1_guess),
            "N1": n1,
            "NF1": nf1,
            "NS1": ns1,
            "N2": n2,
            "NF2": 2,
            "condenser_mode": condenser_mode,
            "distillate_phase": distillate_phase,
            "max_iterations": 200,
        },
    }


def build_aspen_from_zero_plan(report, thermo_confirmation, solvent_pool):
    task = report.get("separation_task") or {}
    compatible = bool(task.get("compatible_verified_case"))
    classification = classify_binary_system(task)
    associating_liquid = classification["family"] in {"aqueous_associating_oxygenate", "polar_associating_liquid"}
    pair = "{}/{}".format(task.get("component_a", ""), task.get("component_b", ""))
    target_product = task.get("target_product", "")
    selected_method = thermo_confirmation.get("selected_method") or task.get("property_method") or "to_be_selected"
    execution_method = thermo_confirmation.get("execution_method_candidate") or (
        "PRWS" if compatible else ""
    )
    solvent_items = process_solvent_items_for_report(report, solvent_pool)
    locked_solvent_code = locked_molecular_solvent_code(report)
    if locked_solvent_code:
        locked_token = normalize_agent_token(locked_solvent_code)
        locked_item = None
        for item in (solvent_pool.get("items") or []):
            item_tokens = {
                normalize_agent_token(item.get("code")),
                normalize_agent_token(item.get("aspen_component_id")),
                normalize_agent_token(item.get("name")),
            }
            item_tokens.discard("")
            if locked_token in item_tokens:
                locked_item = item
                break
        if locked_item:
            solvent_items = [locked_item]
    pool_items = (solvent_pool.get("items") or [])[:6]
    if (
        not locked_solvent_code
        and not any((item.get("aspen_component_id") or "").strip() and not solvent_process_rejected(item) for item in solvent_items)
    ):
        seen_codes = {str(item.get("code") or "") for item in solvent_items}
        for candidate in sorted(pool_items, key=lambda row: (int(row.get("process_gate_rank") or 999), int(row.get("rank") or 999))):
            if str(candidate.get("code") or "") in seen_codes:
                continue
            if solvent_process_rejected(candidate):
                continue
            identity = aspen_identity_for_item(
                report,
                candidate.get("code"),
                name=candidate.get("name"),
                explicit_aspen_id=candidate.get("aspen_component_id") or "",
                role="candidate_solvent",
            )
            if identity.get("aspen_component_id") and identity.get("mapping_confidence") != "needs_aspen_probe":
                solvent_items.append(candidate)
                break
    component_mapping = [
        aspen_identity_for_item(report, task.get("component_a", ""), role="feed_component"),
        aspen_identity_for_item(report, task.get("component_b", ""), role="feed_component"),
    ]
    for solvent in solvent_items:
        item = aspen_identity_for_item(
            report,
            solvent.get("code"),
            name=solvent.get("name"),
            explicit_aspen_id=solvent.get("aspen_component_id") or "",
            role="candidate_solvent",
        )
        item["candidate_rank"] = solvent.get("rank")
        item["candidate_aspen_status"] = solvent.get("aspen_status")
        item["candidate_distillation_gate"] = solvent.get("distillation_gate")
        item["candidate_process_gate_rank"] = solvent.get("process_gate_rank")
        item["candidate_process_gate_reason"] = solvent.get("process_gate_reason")
        item["relative_volatility_gate"] = solvent.get("relative_volatility_gate")
        item["alpha_definition"] = solvent.get("alpha_definition")
        item["alpha_improvement_best"] = solvent.get("alpha_improvement_best")
        item["alpha_integrated_score"] = solvent.get("alpha_integrated_score")
        item["alpha_system_fit_reason"] = solvent.get("alpha_system_fit_reason")
        item["alpha_best_sf_ratio"] = solvent.get("alpha_best_sf_ratio")
        item["ed_preferential_binding_component"] = solvent.get("ed_preferential_binding_component")
        component_mapping.append(item)

    initial_cases = []
    for index, solvent in enumerate(solvent_items, start=1):
        solvent_identity = aspen_identity_for_item(
            report,
            solvent.get("code"),
            name=solvent.get("name"),
            explicit_aspen_id=solvent.get("aspen_component_id") or "",
            role="candidate_solvent",
        )
        case_thermo_gate = thermo_evidence_gate.evaluate_candidate(
            report,
            candidate=solvent,
            selected_method=execution_method,
        )
        case_status = (
            "ready_for_existing_template"
            if compatible and solvent_identity.get("aspen_component_id")
            else (
                "spec_ready_waiting_molecular_gate"
                if solvent_identity.get("aspen_component_id") and execution_method and case_thermo_gate.get("aspen_run_authorized")
                else (
                    "blocked_thermo_evidence_incomplete"
                    if not case_thermo_gate.get("aspen_run_authorized")
                    else "dry_plan_needs_component_method_confirmation"
                )
            )
        )
        initial_sf = safe_float(solvent.get("alpha_best_sf_ratio"))
        if initial_sf is None or initial_sf <= 0:
            initial_sf = 1.5
        initial_cases.append({
            "case_id": "AUTO_{}_{}".format(index, solvent.get("code")),
            "solvent_code": solvent.get("code"),
            "solvent_name": solvent.get("name"),
            "aspen_component_id": solvent_identity.get("aspen_component_id") or "",
            "distillation_gate": solvent.get("distillation_gate"),
            "process_gate_reason": solvent.get("process_gate_reason"),
            "relative_volatility_gate": solvent.get("relative_volatility_gate"),
            "alpha_improvement_best": solvent.get("alpha_improvement_best"),
            "alpha_definition": solvent.get("alpha_definition"),
            "SF": initial_sf,
            "RR1": 4.0,
            "D1_policy": "estimate from target recovery and feed composition",
            "RR2": 1.5,
            "D2_policy": "solvent-recovery overhead adjusted during repair",
            "N1": 60,
            "NF1": 45,
            "NS1": 25,
            "N2": 8,
            "NF2": 2,
            "status": case_status,
            "thermo_claim_level": case_thermo_gate.get("claim_level") or "blocked",
            "thermo_aspen_execution_mode": case_thermo_gate.get("aspen_execution_mode") or "blocked",
            "thermodynamic_evidence_gate": case_thermo_gate,
        })

    repair_strategy = [
        {
            "failure_mode": "Aspen component missing",
            "detection": "component ID cannot be inserted or Aspen databank lookup fails",
            "repair_action": "try CAS/name alias, then block BKP generation until the component is added manually or via databank import",
        },
        {
            "failure_mode": "property method unavailable or no BIP",
            "detection": "property package cannot initialize or binary parameters are absent/untracked",
            "repair_action": "search the original VLE/phase-equilibrium article and audited Aspen/DECHEMA/DDB records; regress and validate missing parameters before another Aspen run",
        },
        {
            "failure_mode": "RadFrac non-convergence",
            "detection": "Aspen run status is failed or product constraints are unreadable",
            "repair_action": "reduce purity target temporarily, relax RR/D, perturb feed stages, then rerun bounded repair grid",
        },
        {
            "failure_mode": "false feasible solution",
            "detection": "converged flag is true but purity/recovery/TAC/energy or solvent loss is physically inconsistent",
            "repair_action": "run result trust audit and keep the case out of TOPSIS until constraints and units pass",
        },
    ]

    topology = [
        "feed conditioning block",
        "extractive distillation column",
        "solvent recovery column",
        "fresh solvent makeup plus recycle tear stream",
    ]
    if associating_liquid:
        topology = [
            "feed conditioning for classified associating liquid binary",
            "ordinary/vacuum/pressure-swing distillation baseline",
            "candidate entrainer/extractive-distillation branch gated by molecular screening",
            "solvent recovery plus impurity-rich stream audit if an entrainer is retained",
        ]

    solvent_mappings = [
        row for row in component_mapping
        if row.get("role") == "candidate_solvent" and row.get("aspen_component_id")
    ]
    solvent_mappings.sort(key=lambda row: (
        0 if relative_volatility_gate_allows_execution(row) else 1,
        -safe_float(row.get("alpha_integrated_score"), 0.0),
        -safe_float(row.get("alpha_improvement_best"), 0.0),
        1 if str(row.get("candidate_distillation_gate") or "").startswith("reject_") else 0,
        int(row.get("candidate_process_gate_rank") or 999),
        1 if row.get("mapping_confidence") == "needs_aspen_probe" else 0,
        1 if str(row.get("candidate_aspen_status") or "").startswith("needs") else 0,
        int(row.get("candidate_rank") or 999),
        row.get("aspen_component_id") or "",
    ))
    selected_solvent = {}
    if locked_solvent_code:
        locked_token = normalize_agent_token(locked_solvent_code)
        for row in solvent_mappings:
            row_tokens = {
                normalize_agent_token(row.get("code")),
                normalize_agent_token(row.get("aspen_component_id")),
                normalize_agent_token(row.get("name")),
            }
            row_tokens.discard("")
            if locked_token in row_tokens:
                selected_solvent = row
                break
    if not selected_solvent:
        selected_solvent = solvent_mappings[0] if solvent_mappings else {}
    selected_thermo_gate = thermo_evidence_gate.evaluate_candidate(
        report,
        candidate=selected_solvent if selected_solvent else None,
        selected_method=execution_method,
    )
    candidate_molecular_rows = []
    paths = report.get("research_task_package_paths") or {}
    candidate_csv = paths.get("candidate_molecular_evidence_import_csv")
    if not candidate_csv and paths.get("molecular_inputs_dir"):
        candidate_csv = str(Path(paths.get("molecular_inputs_dir")) / "candidate_molecular_evidence_import.csv")
    if candidate_csv:
        candidate_molecular_rows = read_csv_rows(candidate_csv)
    selected_tokens = {
        normalize_agent_token(selected_solvent.get("code")),
        normalize_agent_token(selected_solvent.get("aspen_component_id")),
    }
    selected_tokens.discard("")
    candidate_summary_ready = any(
        row.get("molecular_evidence_status") in {
            "gaussian_bsse_nci_and_gromacs_pair_imported",
            "gaussian_bsse_and_gromacs_pair_imported",
            "gaussian_and_gromacs_pair_imported",
        }
        and (
            not selected_tokens
            or normalize_agent_token(row.get("solvent_code")) in selected_tokens
            or normalize_agent_token(row.get("solvent_asset_code")) in selected_tokens
        )
        for row in candidate_molecular_rows
    )
    strict_selected_gromacs_rows = [
        row for row in strict_gromacs_evidence_rows(paths)
        if (
            not selected_tokens
            or normalize_agent_token(row.get("solvent_code")) in selected_tokens
            or normalize_agent_token(row.get("solvent_asset_code")) in selected_tokens
        )
    ]
    molecular_selection_ready = bool(candidate_summary_ready and len(strict_selected_gromacs_rows) >= 2)
    if compatible:
        molecular_selection_ready = True
    feed_mapping_ready = all(
        row.get("aspen_component_id")
        for row in component_mapping
        if row.get("role") == "feed_component"
    )
    thermo_execution_ready = bool(compatible or selected_thermo_gate.get("aspen_run_authorized"))
    spec_ready = bool(
        feed_mapping_ready
        and selected_solvent.get("aspen_component_id")
        and execution_method
        and thermo_execution_ready
    )
    zero_build_spec = (
        build_zero_build_aspen_spec(task, classification, execution_method, component_mapping, selected_solvent)
        if spec_ready
        else {}
    )
    if zero_build_spec:
        evidence_component_map = {
            row.get("code") or row.get("name") or row.get("formula"): row.get("aspen_component_id")
            for row in component_mapping
            if row.get("aspen_component_id")
        }
        nrtl_pairs = thermo_evidence_gate.nrtl_pairs_for_candidate(
            report,
            candidate=selected_solvent,
            selected_method=execution_method,
            component_id_map=evidence_component_map,
        )
        zero_build_spec["nrtl_pairs"] = nrtl_pairs
        zero_build_spec["thermodynamic_evidence_gate"] = selected_thermo_gate
        zero_build_spec["thermodynamic_parameter_injection"] = {
            "source": selected_thermo_gate.get("evidence_source") or "",
            "method": selected_thermo_gate.get("selected_method") or execution_method,
            "directed_nrtl_row_count": len(nrtl_pairs),
            "aspen_run_authorized": selected_thermo_gate.get("aspen_run_authorized"),
            "publication_ready": selected_thermo_gate.get("publication_ready"),
            "screening_ready": selected_thermo_gate.get("screening_ready"),
            "claim_level": selected_thermo_gate.get("claim_level") or "blocked",
            "aspen_execution_mode": selected_thermo_gate.get("aspen_execution_mode") or "blocked",
            "requires_uncertainty_campaign": selected_thermo_gate.get("requires_uncertainty_campaign"),
        }
    can_generate_bkp = bool(compatible or (spec_ready and molecular_selection_ready))

    flowsheet_spec = {
        "name": "agent_generated_extract_distillation_{}_to_{}".format(pair.replace("/", "_"), target_product),
        "system": pair,
        "target_product": target_product,
        "target_purity": task.get("target_purity"),
        "target_purity_basis": task.get("target_purity_basis") or "mole_fraction",
        "system_classification": classification,
        "property_method": selected_method,
        "execution_property_method": execution_method,
        "process_boundary": task.get("process_boundary"),
        "topology": topology,
        "components": component_mapping,
        "initial_cases": initial_cases,
        "thermodynamic_evidence_gate": selected_thermo_gate,
        "nrtl_parameter_row_count": len((zero_build_spec or {}).get("nrtl_pairs") or []),
        "status": (
            "template_compatible_current_case"
            if compatible
            else ("spec_ready_waiting_molecular_gate" if spec_ready else "spec_generated_bkp_blocked_until_checks_pass")
        ),
    }

    boundary = NEW_SYSTEM_ASPEN_BOUNDARY
    if associating_liquid:
        boundary = (
            "The Agent classified this system as {} and generated an Aspen flowsheet specification plus candidate case table. "
            "BKP generation remains blocked until Gaussian/NCI/GROMACS screening, activity-model parameter confirmation, "
            "and Aspen component mapping are complete."
        ).format(
            classification["family"]
        )
    if spec_ready and not molecular_selection_ready:
        boundary = (
            "The Agent has component aliases, an executable property-method candidate and a generic ED Aspen spec, "
            "but it is waiting for same-task Gaussian + NCI/VMD + GROMACS solvent evidence before starting BKP generation."
        )
    elif spec_ready and molecular_selection_ready:
        boundary = (
            "The Agent has passed the component/property/spec gate and imported same-task molecular evidence; "
            "BKP generation is allowed as an exploratory process validation for this binary system."
        )
    elif not compatible and not thermo_execution_ready:
        missing_pairs = ", ".join(
            "/".join(row.get("pair") or [])
            for row in (selected_thermo_gate.get("missing_pairs") or [])
        )
        boundary = (
            "Aspen generation is blocked by the thermodynamic evidence gate. "
            "Missing or incomplete model-compatible binary evidence: {}."
        ).format(missing_pairs or "no structured evidence package")

    return {
        "status": (
            "bkp_available_or_generatable_current_case"
            if compatible
            else ("from_zero_spec_ready_waiting_molecular_gate" if spec_ready and not molecular_selection_ready else ("from_zero_spec_bkp_ready" if can_generate_bkp else "from_zero_spec_generated_bkp_blocked"))
        ),
        "can_generate_bkp_now": can_generate_bkp,
        "spec_ready": spec_ready,
        "molecular_selection_ready": molecular_selection_ready,
        "strict_gromacs_pair_ready": bool(len(strict_selected_gromacs_rows) >= 2),
        "strict_gromacs_ready_count": len(strict_selected_gromacs_rows),
        "candidate_summary_ready": candidate_summary_ready,
        "thermodynamic_evidence_ready": thermo_execution_ready,
        "thermodynamic_evidence_gate": selected_thermo_gate,
        "bkp_generation_boundary": (
            CURRENT_C3_ASPEN_BOUNDARY
            if compatible
            else boundary
        ),
        "selected_property_method": selected_method,
        "execution_property_method": execution_method,
        "selected_process_solvent": selected_solvent,
        "component_mapping": component_mapping,
        "flowsheet_spec": flowsheet_spec,
        "zero_build_spec": zero_build_spec,
        "initial_cases": initial_cases,
        "repair_strategy": repair_strategy,
        "aspen_commands": [
            {
                "purpose": "write this task's generic zero-build Aspen spec",
                "command": "python zero_build_aspen_agent.py --spec <task_zero_build_spec.json> --output-bkp <task>.bkp --no-seed-run; then run generic_aspen_once_optimizer.py for real Aspen evidence",
                "status": "ready_after_molecular_gate" if spec_ready else "blocked_until_component_method_mapping",
            },
            {
                "purpose": "build verified C3F8/C3F6 zero BKP",
                "command": "python zero_build_aspen_agent.py --output-bkp generated/zero_agent_generated_ed_template.bkp",
                "status": "available_current_case" if compatible else "blocked_new_system",
            },
        ],
        "exported_files": {},
    }


def primary_validation_solvent_identity(report, preferred_solvent_code=""):
    """Return the solvent the Agent should use for the first end-to-end validation pass."""
    brief = report.get("system_research_brief") or {}
    task = report.get("separation_task") or {}
    pool_items = ((brief.get("candidate_solvent_pool") or {}).get("items") or [])
    paths = report.get("research_task_package_paths") or {}
    if not pool_items:
        candidate_csv = paths.get("candidate_solvent_pool_csv")
        if candidate_csv:
            pool_items = read_csv_rows(candidate_csv)
    explicit_token = normalize_agent_token(preferred_solvent_code)
    locked_token = normalize_agent_token(locked_molecular_solvent_code(report)) if molecular_selection_is_manual(report) else ""
    requested_token = explicit_token or locked_token
    def with_tokens(row, user_selected=False, relock_reason=""):
        selected = dict(row or {})
        selected["tokens"] = [
            token for token in [
                normalize_agent_token(selected.get("code")),
                normalize_agent_token(selected.get("solvent_code")),
                normalize_agent_token(selected.get("aspen_component_id")),
                normalize_agent_token(selected.get("name")),
            ]
            if token
        ]
        selected["user_selected"] = bool(user_selected)
        if relock_reason:
            selected["agent_relocked_reason"] = relock_reason
        return selected

    if requested_token and pool_items:
        for row in pool_items:
            tokens = {
                normalize_agent_token(row.get("code")),
                normalize_agent_token(row.get("solvent_code")),
                normalize_agent_token(row.get("aspen_component_id")),
                normalize_agent_token(row.get("name")),
            }
            tokens.discard("")
            if requested_token in tokens:
                selected = with_tokens(row, user_selected=True)
                if not relative_volatility_gate_allows_execution(selected):
                    selected["relative_volatility_gate"] = "manual_alpha_override"
                    selected["alpha_manual_override_reason"] = "User selected this solvent despite the relative-volatility prescreen."
                return selected
        return {
            "selection_error": "requested_solvent_not_in_current_candidate_pool",
            "requested_code": preferred_solvent_code,
            "tokens": [requested_token],
        }
    auto_selected = post_alpha_top_candidates(pool_items, limit=1)
    if auto_selected and not task.get("compatible_verified_case"):
        return with_tokens(auto_selected[0], user_selected=False)
    if pool_items and not task.get("compatible_verified_case"):
        ranked_pool = sorted(
            pool_items,
            key=lambda row: (
                0 if relative_volatility_gate_allows_execution(row) else 1,
                0 if row.get("recommendation_status") == "current_recommended_for_confirmation" else 1,
                -safe_float(row.get("alpha_integrated_score"), 0),
                -safe_float(row.get("prescreen_score"), 0),
                int(row.get("rank") or 999),
            ),
        )
        return with_tokens(ranked_pool[0])

    plan = brief.get("aspen_from_zero_plan") or {}
    selected_from_plan = dict(plan.get("selected_process_solvent") or {})
    plan_path = paths.get("aspen_build_plan_json")
    if not selected_from_plan and plan_path:
        try:
            selected_from_plan = dict((read_json(plan_path).get("selected_process_solvent") or {}))
        except Exception:
            selected_from_plan = {}
    if selected_from_plan.get("code") or selected_from_plan.get("aspen_component_id"):
        return with_tokens(selected_from_plan)

    ranked = sorted(
        pool_items,
        key=lambda row: (
            0 if (row.get("aspen_component_id") or "").strip() else 1,
            0 if row.get("aspen_status") == "configured_current_project" else 1,
            int(row.get("rank") or 999),
        ),
    )
    if not ranked:
        return {}
    return with_tokens(ranked[0])


def primary_validation_solvent_code(report):
    selected = primary_validation_solvent_identity(report)
    return selected.get("code") or selected.get("aspen_component_id") or ""


def row_matches_primary_validation_solvent(row, selected):
    tokens = set(selected.get("tokens") or [])
    if not tokens:
        return True
    row_tokens = {
        normalize_agent_token(row.get("solvent_code")),
        normalize_agent_token(row.get("solvent_asset_code")),
        normalize_agent_token(row.get("aspen_component_id")),
        normalize_agent_token(row.get("code")),
    }
    row_tokens.discard("")
    return bool(tokens.intersection(row_tokens))


def build_result_trust_audit(report, thermo_confirmation, molecular_automation, aspen_plan):
    task = report.get("separation_task") or {}
    compatible = bool(task.get("compatible_verified_case"))
    counts = report.get("counts") or {}
    lookup_rows = report.get("online_component_info") or []
    lookup_ok = bool(lookup_rows) and all(row.get("status") == "found" for row in lookup_rows)
    process_records = int(counts.get("process_evidence_records") or 0)
    molecular_records = int(counts.get("molecular_candidates") or 0)
    imported_molecular_records = int(counts.get("imported_molecular_evidence_records") or 0)
    imported_process_records = int(counts.get("imported_process_result_records") or 0)
    imported_closed_loop = imported_molecular_records > 0 and imported_process_records > 0
    molecular_gate_status = "pass" if compatible and molecular_records else "queued_inputs_only"
    molecular_claim = "molecular ranking can be used" if compatible else "only input generation/queue can be claimed"
    if imported_molecular_records:
        molecular_gate_status = "imported_results_available"
        molecular_claim = "imported molecular evidence can be used for the current task after consistency/provenance review"
    alpha_summary = (molecular_automation or {}).get("relative_volatility_prescreen") or {}
    alpha_pass_count = int(alpha_summary.get("pass_count") or 0)
    alpha_status = alpha_summary.get("status") or "missing"
    property_scientifically_valid = thermo_confirmation.get("status") in {
        "publication_property_validated",
        "experimentally_validated_property_method",
    }
    candidate_thermo_gate = aspen_plan.get("thermodynamic_evidence_gate") or {}
    if candidate_thermo_gate:
        property_scientifically_valid = bool(candidate_thermo_gate.get("publication_ready"))
    execution_evidence_available = bool(process_records or imported_process_records)
    audit_rows = [
        {
            "gate": "component identity",
            "status": "pass" if lookup_ok else ("partial" if lookup_rows else "missing"),
            "basis": "PubChem lookup rows: {}".format(len(lookup_rows)),
            "claim_allowed": "component names/CID/CAS can be reported with manual CAS caveat" if lookup_ok else "do not build Aspen automatically",
        },
        {
            "gate": "VLE/property method",
            "status": "pass" if property_scientifically_valid else (
                "execution_method_recorded_validation_pending"
                if compatible
                else (
                    "screening_only_predictive"
                    if candidate_thermo_gate.get("screening_ready")
                    else (
                        "blocked_thermo_evidence_incomplete"
                        if candidate_thermo_gate
                        else "evidence_leads_only"
                    )
                )
            ),
            "basis": (
                "{}; publication pairs {}; screening-ready pairs {}/{}; source {}".format(
                    thermo_confirmation.get("selected_method", ""),
                    candidate_thermo_gate.get("publication_ready_pair_count") or 0,
                    candidate_thermo_gate.get("screening_ready_pair_count") or 0,
                    candidate_thermo_gate.get("required_pair_count") or 0,
                    candidate_thermo_gate.get("evidence_source") or "not supplied",
                )
                if candidate_thermo_gate
                else thermo_confirmation.get("selected_method", "")
            ),
            "claim_allowed": (
                "property validation can be reported"
                if property_scientifically_valid
                else (
                    "screening and ranking may be reported with predictive uncertainty; fitted/holdout/experimental validation cannot be claimed"
                    if candidate_thermo_gate.get("screening_ready")
                    else "the recorded execution method may be stated, but fitted/holdout/experimental validation cannot be claimed"
                )
            ),
        },
        {
            "gate": "relative volatility solvent prescreen",
            "status": "pass" if alpha_pass_count else alpha_status,
            "basis": "{} pass candidates; threshold Ialpha >= {}".format(
                alpha_pass_count,
                alpha_summary.get("i_alpha_pass_threshold") or RELATIVE_VOLATILITY_I_ALPHA_PASS_THRESHOLD,
            ),
            "claim_allowed": "molecular simulation may start only for strict pass_alpha_gate, integrated_screening_selected, or explicit manual override candidates",
        },
        {
            "gate": "Gaussian/MD molecular evidence",
            "status": molecular_gate_status,
            "basis": "molecular rows: {}; imported evidence rows: {}; automation status: {}".format(
                molecular_records,
                imported_molecular_records,
                molecular_automation.get("status"),
            ),
            "claim_allowed": molecular_claim,
        },
        {
            "gate": "Aspen BKP generation",
            "status": "pass" if aspen_plan.get("can_generate_bkp_now") else "blocked",
            "basis": aspen_plan.get("bkp_generation_boundary", ""),
            "claim_allowed": "BKP generation is inside verified current template" if compatible else "flowsheet spec only; no new-system BKP claim",
        },
        {
            "gate": "Aspen convergence and output parsing",
            "status": "pass" if compatible and (process_records or imported_process_records) else ("imported_results_available" if imported_process_records else "missing"),
            "basis": "process evidence records: {}; imported process rows: {}".format(process_records, imported_process_records),
            "claim_allowed": (
                "process validation/optimization can be cited"
                if compatible and (process_records or imported_process_records)
                else ("imported process outputs can be audited for this task" if imported_process_records else "do not use as process result")
            ),
        },
        {
            "gate": "unit and variable provenance",
            "status": "mapped_current_template_needs_case_unit_audit" if compatible else ("imported_output_schema_present" if imported_process_records else "needs_variable_map"),
            "basis": "variable_map.py is available; selected-case unit and equipment-basis audit remains required" if compatible else (
                "imported Aspen optimization schema was parsed" if imported_process_records else "new system needs a variable map before output parsing"
            ),
            "claim_allowed": "execution outputs may be read conditionally; final TAC/optimum claims require case-level unit and equipment review" if compatible else (
                "completion can be audited from imported process rows; optimized TAC/TOPSIS claims still need variable/unit review"
                if imported_process_records
                else "do not compute TAC/TOPSIS until variables and units are mapped"
            ),
        },
        {
            "gate": "final result claim",
            "status": (
                "execution_evidence_available_publication_validation_pending"
                if compatible and execution_evidence_available
                else ("closed_loop_outputs_imported" if imported_closed_loop else "research_task_package_only")
            ),
            "basis": task.get("validation_scope", ""),
            "claim_allowed": (
                "C3F8/C3F6 execution-level evidence may be reported conditionally; property, unit, economics and uncertainty blockers must remain explicit."
                if compatible and execution_evidence_available
                else (
                    "The Agent can claim the current task reached imported molecular and process outputs; final separation optimum still needs property and unit audit."
                    if imported_closed_loop
                    else "The Agent can claim task instantiation, evidence gating and package generation; it cannot claim optimized separation results yet."
                )
            ),
        },
    ]
    partial_or_blocked_statuses = {
        "blocked",
        "missing",
        "research_task_package_only",
        "evidence_leads_only",
        "queued_inputs_only",
        "needs_variable_map",
        "execution_method_recorded_validation_pending",
        "blocked_thermo_evidence_incomplete",
        "mapped_current_template_needs_case_unit_audit",
        "execution_evidence_available_publication_validation_pending",
        "imported_output_schema_present",
    }
    blocked = [row for row in audit_rows if row.get("status") in partial_or_blocked_statuses]
    return {
        "overall_status": (
            "execution_evidence_available_needs_publication_audit"
            if compatible and execution_evidence_available
            else ("closed_loop_outputs_imported_needs_property_review" if imported_closed_loop else "not_trusted_for_new_process_claim")
        ),
        "blocked_or_partial_gates": len(blocked),
        "audit_rows": audit_rows,
        "decision": (
            "allow_execution_level_claims_only"
            if compatible and execution_evidence_available
            else ("allow_audited_completion_claims_only" if imported_closed_loop else "allow_agent_capability_claims_only")
        ),
    }


def build_system_research_brief(report):
    task = report.get("separation_task") or {}
    lookup_rows = report.get("online_component_info") or []
    compatible = bool(task.get("compatible_verified_case"))
    component_a = task.get("component_a", "")
    component_b = task.get("component_b", "")
    target_product = task.get("target_product", "")
    pair = "{}/{}".format(component_a, component_b)
    classification = classify_binary_system(task)
    titles = {
        row.get("input"): row.get("title") or row.get("query") or row.get("input")
        for row in lookup_rows
    }
    query_pair = "{} {} vapor liquid equilibrium binary interaction parameters".format(component_a, component_b)
    thermo_query = "{} {} thermodynamic model VLE PR PC-SAFT NRTL".format(component_a, component_b)
    solvent_query = "{} {} solvent screening extractive distillation separation".format(component_a, component_b)
    identity_links = []
    for row in lookup_rows:
        title = row.get("title") or row.get("query") or row.get("input")
        identity_links.append({
            "component": row.get("input"),
            "title": title,
            "pubchem": row.get("source_url"),
            "nist": nist_webbook_url(title),
            "cas": ", ".join(row.get("cas") or []),
            "status": row.get("status"),
        })
    web_queries = [
        {
            "topic": "VLE / binary interaction",
            "query": query_pair,
            "purpose": "Find phase-equilibrium data or binary-interaction parameters before Aspen template generation.",
            "search_url": web_search_url(query_pair),
            "scholar_url": scholar_search_url(query_pair),
        },
        {
            "topic": "Thermodynamic model",
            "query": thermo_query,
            "purpose": "Compare EOS/activity-coefficient models and decide whether PR/PRWS/PC-SAFT/NRTL variants are appropriate.",
            "search_url": web_search_url(thermo_query),
            "scholar_url": scholar_search_url(thermo_query),
        },
        {
            "topic": "Solvent-screening precedent",
            "query": solvent_query,
            "purpose": "Collect candidate solvent families and process-boundary precedents for the new binary system.",
            "search_url": web_search_url(solvent_query),
            "scholar_url": scholar_search_url(solvent_query),
        },
    ]
    molecular_jobs = [
        {
            "job": "component identity package",
            "input": pair,
            "output": "component structures, charges and Aspen/PubChem identifiers",
            "status": "done" if lookup_rows else "queued",
        },
        {
            "job": "low-cost interaction scan",
            "input": "{} with seed solvent families".format(pair),
            "output": "Gaussian/ESP/BSSE interaction-energy direction for target vs impurity",
            "status": "done" if compatible else "queued",
        },
        {
            "job": "MD selectivity check",
            "input": "top molecular candidates",
            "output": "RDF peaks, coordination numbers, diffusion/MSD and interaction-energy consistency",
            "status": "done" if compatible else "blocked_until_candidates_exist",
        },
        {
            "job": "screening snapshot export",
            "input": "completed molecular rows",
            "output": "system-specific screening_api_snapshot.json for process Agent",
            "status": "done" if compatible else "blocked_until_molecular_jobs_finish",
        },
    ]
    process_requirements = [
        {
            "requirement": "property-method basis",
            "detail": "Document VLE/property-model choice for {} before running Aspen.".format(pair),
            "status": "available" if compatible else "missing",
        },
        {
            "requirement": "Aspen component identity",
            "detail": "Map PubChem/CAS identity to Aspen components and check missing aliases.",
            "status": "available" if compatible else "needs_check",
        },
        {
            "requirement": "flowsheet boundary",
            "detail": "Confirm whether the task remains physical-solvent extractive distillation or requires another process class.",
            "status": "available" if compatible else "needs_decision",
        },
        {
            "requirement": "optimization objectives",
            "detail": "Set purity/recovery, reboiler duty and TAC objectives for the target product {}.".format(target_product),
            "status": "available" if compatible else "queued",
        },
    ]
    literature_summary = build_literature_vle_summary(component_a, component_b, web_queries)
    candidate_pool = build_candidate_solvent_pool(report)
    thermo_confirmation = build_thermo_method_confirmation(report, literature_summary)
    molecular_automation = build_molecular_automation_summary(report, candidate_pool)
    aspen_plan = build_aspen_from_zero_plan(report, thermo_confirmation, candidate_pool)
    trust_audit = build_result_trust_audit(report, thermo_confirmation, molecular_automation, aspen_plan)
    return {
        "system": pair,
        "target_product": target_product,
        "system_classification": classification,
        "identity_links": identity_links,
        "web_queries": web_queries,
        "separation_diagnosis": build_separation_diagnosis(report),
        "route_decision": build_route_decision(report),
        "literature_vle_summary": literature_summary,
        "thermo_method_confirmation": thermo_confirmation,
        "thermodynamic_evidence_summary": thermo_confirmation.get("thermodynamic_evidence_gate") or {},
        "candidate_seed_strategy": seed_strategy_for_system([component_a, component_b], target_product, compatible),
        "candidate_campaign": candidate_pool.get("candidate_campaign") or build_candidate_screening_campaign(report, candidate_pool.get("items") or []),
        "candidate_solvent_pool": candidate_pool,
        "relative_volatility_prescreen": candidate_pool.get("relative_volatility_prescreen") or {},
        "candidate_molecular_task_queue": build_candidate_molecular_task_queue(report, candidate_pool),
        "molecular_automation_package": molecular_automation,
        "molecular_job_queue": molecular_jobs,
        "process_template_requirements": process_requirements,
        "aspen_from_zero_plan": aspen_plan,
        "result_trust_audit": trust_audit,
        "brief_status": "full_flow_verified_task" if compatible else "task_flow_package_generated",
        "note": (
            "This package is one task-flow record of the binary-separation Agent. "
            "Completed stages can be cited; queued stages remain execution tasks."
        ),
    }


def count_csv_rows_if_available(path):
    if not path:
        return 0
    try:
        return len(read_csv_rows(path))
    except Exception:
        return 0


def apply_task_flow_counts(report):
    report = dict(report)
    counts = dict(report.get("counts") or {})
    brief = report.get("system_research_brief") or {}
    paths = report.get("research_task_package_paths") or {}
    pool_items = (brief.get("candidate_solvent_pool") or {}).get("items") or []
    molecular_queue = brief.get("candidate_molecular_task_queue") or []
    candidate_pool_count = max(
        int(counts.get("candidate_solvent_pool_items") or 0),
        len(pool_items),
        count_csv_rows_if_available(paths.get("candidate_solvent_pool_csv")),
    )
    molecular_task_count = max(
        int(counts.get("molecular_task_queue_rows") or 0),
        len(molecular_queue),
        count_csv_rows_if_available(paths.get("molecular_task_queue_csv")),
    )
    gaussian_job_count = max(
        int(counts.get("gaussian_job_rows") or 0),
        count_csv_rows_if_available(paths.get("gaussian_jobs_csv")),
    )
    gromacs_job_count = max(
        int(counts.get("gromacs_job_rows") or 0),
        count_csv_rows_if_available(paths.get("gromacs_jobs_csv")),
    )
    if candidate_pool_count:
        counts["candidate_solvent_pool_items"] = candidate_pool_count
    alpha_summary = (brief.get("candidate_solvent_pool") or {}).get("relative_volatility_prescreen") or brief.get("relative_volatility_prescreen") or {}
    counts["relative_volatility_pass_candidates"] = int(alpha_summary.get("pass_count") or 0)
    if molecular_task_count:
        counts["molecular_task_queue_rows"] = molecular_task_count
    if gaussian_job_count:
        counts["gaussian_job_rows"] = gaussian_job_count
    if gromacs_job_count:
        counts["gromacs_job_rows"] = gromacs_job_count
    report["counts"] = counts
    return report


def enrich_trial_report_payload(report):
    report = normalize_relative_volatility_retry_paths(report)
    task = dict(report.get("separation_task") or {})
    if task:
        task["validation_role"] = task_validation_role(task)
        task["publication_validation_eligible"] = task_publication_eligible(task)
        report["separation_task"] = task
        report["component_identity_gate"] = component_identity_gate(
            task.get("component_a", ""),
            task.get("component_b", ""),
            task.get("target_product", ""),
            report.get("online_component_info") or [],
        )
    report["separation_diagnosis"] = report.get("separation_diagnosis") or build_separation_diagnosis(report)
    report["route_decision"] = report.get("route_decision") or build_route_decision(report, report["separation_diagnosis"])
    existing_brief = report.get("system_research_brief") or {}
    existing_aspen_plan = existing_brief.get("aspen_from_zero_plan") or {}
    existing_thermo = existing_brief.get("thermo_method_confirmation") or {}
    existing_thermo_evidence = existing_thermo.get("thermodynamic_evidence_gate") or {}
    current_evidence_payload, current_evidence_source, current_evidence_status = thermo_evidence_gate.load_evidence_payload(report)
    current_evidence_records = current_evidence_payload.get("records") or []
    stale_thermo_evidence = (
        not existing_thermo_evidence
        or str(existing_thermo_evidence.get("evidence_source") or "") != str(current_evidence_source or "")
        or int(existing_thermo_evidence.get("record_count") or 0) != len(current_evidence_records if isinstance(current_evidence_records, list) else [])
        or str(existing_thermo_evidence.get("status") or "") != str(current_evidence_status or "")
    )
    existing_pool = (existing_brief.get("candidate_solvent_pool") or {}).get("items") or []
    existing_alpha = (
        existing_brief.get("relative_volatility_prescreen")
        or (existing_brief.get("candidate_solvent_pool") or {}).get("relative_volatility_prescreen")
        or {}
    )
    measured_alpha_rows = relative_volatility_kvalue_result_rows(report)
    measured_alpha_trust_statuses = [
        row_property_trust(row)[0]
        for row in measured_alpha_rows
    ]
    alpha_trust_blocked = any(str(status or "").startswith("blocked_") for status in measured_alpha_trust_statuses)
    alpha_has_trusted_result = any(
        row_property_trust(row)[0] == "trusted"
        and str(row.get("status") or "").strip().lower() in {"imported", "base_binary_imported", "base_vle_scan_imported"}
        for row in measured_alpha_rows
    )
    existing_pool_trust_blocked = any(
        str(item.get("property_trust_status") or item.get("relative_volatility_gate") or "").startswith("blocked_")
        for item in existing_pool
    )
    stale_alpha_results = bool(measured_alpha_rows) and (
        int(existing_alpha.get("imported_kvalue_result_count") or 0) != len(measured_alpha_rows)
        or not existing_alpha.get("base_binary_status")
        or (
            alpha_trust_blocked
            and (
                str(existing_alpha.get("status") or "") not in set(measured_alpha_trust_statuses)
                or not existing_pool_trust_blocked
            )
        )
        or (
            alpha_has_trusted_result
            and str(existing_alpha.get("status") or "").strip().lower().startswith("blocked_")
        )
    )
    stale_candidate_pool = bool(existing_brief) and (
        not (existing_brief.get("candidate_solvent_pool") or {}).get("recommendation_policy")
        or int((existing_brief.get("candidate_solvent_pool") or {}).get("one_pass_screening_version") or 0) < ONE_PASS_SCREENING_VERSION
        or not existing_brief.get("candidate_campaign")
        or not (existing_brief.get("candidate_solvent_pool") or {}).get("candidate_campaign")
        or any("prescreen_score" not in item for item in existing_pool[:1])
        or not (existing_brief.get("candidate_solvent_pool") or {}).get("relative_volatility_prescreen")
        or any("relative_volatility_gate" not in item for item in existing_pool[:1])
        or len(existing_pool) < min(candidate_pool_limit(report), len(candidate_base_rows_for_task(report)))
    )
    imported_molecular_count = int((report.get("counts") or {}).get("imported_molecular_evidence_records") or 0)
    stale_molecular_gate = (
        imported_molecular_count > 0
        and existing_aspen_plan.get("spec_ready")
        and not existing_aspen_plan.get("can_generate_bkp_now")
        and not existing_aspen_plan.get("molecular_selection_ready")
    )
    previous_molecular_selection = locked_molecular_solvent_code(report)
    report["system_research_brief"] = (
        build_system_research_brief(report)
        if (not existing_brief or stale_molecular_gate or stale_candidate_pool or stale_alpha_results or stale_thermo_evidence)
        else existing_brief
    )
    brief = dict(report.get("system_research_brief") or {})
    pool_block = dict(brief.get("candidate_solvent_pool") or {})
    pool_items = pool_block.get("items") or []
    if pool_items:
        candidate_campaign = build_candidate_screening_campaign(report, pool_items)
        pool_block["candidate_campaign"] = candidate_campaign
        brief["candidate_campaign"] = candidate_campaign
        brief["candidate_solvent_pool"] = pool_block
        report["system_research_brief"] = brief
    report = sync_auto_molecular_selection(report)
    current_molecular_selection = locked_molecular_solvent_code(report)
    if (
        current_molecular_selection
        and normalize_agent_token(current_molecular_selection) != normalize_agent_token(previous_molecular_selection)
    ):
        report["system_research_brief"] = build_system_research_brief(report)
        report = sync_auto_molecular_selection(report)
    report = apply_task_flow_counts(report)
    report["agent_stage_trace"] = build_agent_stage_trace(report)
    report["next_action_plan"] = report.get("next_action_plan") or build_next_action_plan(report)
    report["lookup_confidence_note"] = report.get("lookup_confidence_note") or build_lookup_confidence_note(report.get("online_component_info") or [])
    report["aspen_progress"] = aspen_progress_summary(report)
    report["screening_state"] = build_screening_state(report)
    return normalize_relative_volatility_retry_paths(report)


def safe_file_token(value, default="item"):
    value = str(value or "").strip()
    value = re.sub(r"[^A-Za-z0-9_.-]+", "_", value)
    value = value.strip("_.-").lower()
    return value or default


def fetch_pubchem_sdf(cid, record_type="3d", timeout=10):
    url = "https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/cid/{}/SDF?record_type={}".format(
        int(cid),
        urllib.parse.quote(record_type),
    )
    request = urllib.request.Request(url, headers={"User-Agent": "SESC-PSE-screening-agent/1.0"})
    with urllib.request.urlopen(request, timeout=timeout) as response:
        return response.read().decode("utf-8", "replace")


def parse_sdf_atoms(text):
    lines = (text or "").splitlines()
    if len(lines) < 4:
        return []
    count_line = lines[3]
    try:
        atom_count = int(count_line[:3])
    except Exception:
        parts = count_line.split()
        atom_count = int(parts[0]) if parts else 0
    atoms = []
    for line in lines[4:4 + atom_count]:
        parts = line.split()
        if len(parts) < 4:
            continue
        try:
            x, y, z = float(parts[0]), float(parts[1]), float(parts[2])
        except Exception:
            continue
        symbol = parts[3]
        if re.match(r"^[A-Z][a-z]?$", symbol):
            atoms.append({"symbol": symbol, "x": x, "y": y, "z": z})
    return atoms


def parse_sdf_bonds(text):
    lines = (text or "").splitlines()
    if len(lines) < 4:
        return []
    count_line = lines[3]
    try:
        atom_count = int(count_line[:3])
        bond_count = int(count_line[3:6])
    except Exception:
        parts = count_line.split()
        atom_count = int(parts[0]) if len(parts) > 0 else 0
        bond_count = int(parts[1]) if len(parts) > 1 else 0
    bonds = []
    start = 4 + atom_count
    for index, line in enumerate(lines[start:start + bond_count], start=1):
        parts = line.split()
        if len(parts) < 3:
            continue
        try:
            a1, a2, order = int(parts[0]), int(parts[1]), int(parts[2])
        except Exception:
            continue
        bonds.append({"id": index, "a1": a1, "a2": a2, "order": max(1, order)})
    return bonds


def mol2_atom_type(symbol):
    symbol = str(symbol or "").strip()
    mapping = {
        "C": "C.3",
        "H": "H",
        "O": "O.3",
        "N": "N.3",
        "S": "S.3",
        "F": "F",
        "Cl": "Cl",
        "Br": "Br",
        "I": "I",
    }
    return mapping.get(symbol, symbol or "Du")


def write_mol2_file(path, label, atoms, bonds):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    token = safe_file_token(label, "molecule").upper()
    lines = [
        "@<TRIPOS>MOLECULE",
        token,
        "{} {} 0 0 0".format(len(atoms), len(bonds)),
        "SMALL",
        "USER_CHARGES",
        "",
        "@<TRIPOS>ATOM",
    ]
    for index, atom in enumerate(atoms, start=1):
        symbol = atom.get("symbol") or "C"
        lines.append(
            "{:>7d} {:<8s} {:>12.6f} {:>12.6f} {:>12.6f} {:<6s} {:>3d} {:<8s} {:>10.6f}".format(
                index,
                "{}{}".format(symbol, index),
                float(atom.get("x") or 0.0),
                float(atom.get("y") or 0.0),
                float(atom.get("z") or 0.0),
                mol2_atom_type(symbol),
                1,
                token,
                0.0,
            )
        )
    lines.append("@<TRIPOS>BOND")
    for bond in bonds:
        order = "ar" if int(bond.get("order") or 1) == 4 else str(min(3, int(bond.get("order") or 1)))
        lines.append(
            "{:>6d} {:>5d} {:>5d} {}".format(
                int(bond.get("id") or 0),
                int(bond.get("a1") or 0),
                int(bond.get("a2") or 0),
                order,
            )
        )
    path.write_text("\n".join(lines) + "\n", encoding="ascii")
    return str(path.resolve())


def geometry_from_pubchem(cid, label, structure_dir):
    structure_dir = Path(structure_dir)
    structure_dir.mkdir(parents=True, exist_ok=True)
    token = safe_file_token("{}_{}".format(label, cid), "compound")
    for record_type in ("3d", "2d"):
        sdf_path = structure_dir / "{}_{}.sdf".format(token, record_type)
        try:
            if sdf_path.exists():
                text = sdf_path.read_text(encoding="utf-8", errors="replace")
            else:
                text = fetch_pubchem_sdf(cid, record_type=record_type)
                sdf_path.write_text(text, encoding="utf-8")
            atoms = parse_sdf_atoms(text)
            if atoms:
                bonds = parse_sdf_bonds(text)
                mol2_path = sdf_path.with_suffix(".mol2")
                write_mol2_file(mol2_path, label, atoms, bonds)
                alias_mol2 = structure_dir / "{}.mol2".format(safe_file_token(label, "molecule"))
                if alias_mol2 != mol2_path:
                    write_mol2_file(alias_mol2, label, atoms, bonds)
                return {
                    "status": "geometry_loaded",
                    "cid": cid,
                    "label": label,
                    "record_type": record_type,
                    "sdf_path": str(sdf_path.resolve()),
                    "mol2_path": str(mol2_path.resolve()),
                    "bonds": bonds,
                    "atoms": atoms,
                }
        except Exception as exc:
            last_error = str(exc)
            continue
    return {
        "status": "geometry_lookup_failed",
        "cid": cid,
        "label": label,
        "record_type": "",
        "sdf_path": "",
        "atoms": [],
        "error": locals().get("last_error", ""),
    }


def gaussian_atom_line(atom, fragment=None, shift_x=0.0, shift_y=0.0, shift_z=0.0):
    symbol = atom.get("symbol", "C")
    if fragment is not None:
        symbol = "{}(Fragment={})".format(symbol, fragment)
    return "{:<18s} {:>14.6f} {:>14.6f} {:>14.6f}".format(
        symbol,
        float(atom.get("x") or 0.0) + shift_x,
        float(atom.get("y") or 0.0) + shift_y,
        float(atom.get("z") or 0.0) + shift_z,
    )


def atom_symbol(atom):
    return re.sub(r"[^A-Za-z]", "", str(atom.get("symbol") or "C")).upper()


def atom_xyz(atom):
    return (
        float(atom.get("x") or 0.0),
        float(atom.get("y") or 0.0),
        float(atom.get("z") or 0.0),
    )


def vec_add(a, b):
    return (a[0] + b[0], a[1] + b[1], a[2] + b[2])


def vec_sub(a, b):
    return (a[0] - b[0], a[1] - b[1], a[2] - b[2])


def vec_scale(a, value):
    return (a[0] * value, a[1] * value, a[2] * value)


def vec_norm(a):
    length = math.sqrt(a[0] * a[0] + a[1] * a[1] + a[2] * a[2])
    if length <= 1e-9:
        return (1.0, 0.0, 0.0)
    return (a[0] / length, a[1] / length, a[2] / length)


def vec_distance(a, b):
    return math.sqrt((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2 + (a[2] - b[2]) ** 2)


def atom_distance(a, b):
    ax, ay, az = atom_xyz(a)
    bx, by, bz = atom_xyz(b)
    return math.sqrt((ax - bx) ** 2 + (ay - by) ** 2 + (az - bz) ** 2)


def shifted_atoms(atoms, shift):
    out = []
    for atom in atoms:
        item = dict(atom)
        item["x"] = float(item.get("x") or 0.0) + shift[0]
        item["y"] = float(item.get("y") or 0.0) + shift[1]
        item["z"] = float(item.get("z") or 0.0) + shift[2]
        out.append(item)
    return out


def rotate_atoms(atoms, angles_deg):
    ax, ay, az = [math.radians(float(value or 0.0)) for value in angles_deg]
    cx, sx = math.cos(ax), math.sin(ax)
    cy, sy = math.cos(ay), math.sin(ay)
    cz, sz = math.cos(az), math.sin(az)
    center = fragment_center(atoms)
    out = []
    for atom in atoms:
        x, y, z = vec_sub(atom_xyz(atom), center)
        y, z = y * cx - z * sx, y * sx + z * cx
        x, z = x * cy + z * sy, -x * sy + z * cy
        x, y = x * cz - y * sz, x * sz + y * cz
        item = dict(atom)
        item["x"], item["y"], item["z"] = vec_add((x, y, z), center)
        out.append(item)
    return out


def fragment_center(atoms):
    if not atoms:
        return (0.0, 0.0, 0.0)
    return (
        sum(float(atom.get("x") or 0.0) for atom in atoms) / len(atoms),
        sum(float(atom.get("y") or 0.0) for atom in atoms) / len(atoms),
        sum(float(atom.get("z") or 0.0) for atom in atoms) / len(atoms),
    )


def acceptor_atoms(atoms):
    acceptor_symbols = {"O", "N", "F", "S", "CL", "BR", "I"}
    return [atom for atom in atoms if atom_symbol(atom) in acceptor_symbols]


def donor_sites(atoms):
    donor_symbols = {"O", "N", "S"}
    hydrogens = [atom for atom in atoms if atom_symbol(atom) == "H"]
    heavy = [atom for atom in atoms if atom_symbol(atom) != "H"]
    sites = []
    for hydrogen in hydrogens:
        nearest = min(heavy, key=lambda atom: atom_distance(hydrogen, atom), default=None)
        if not nearest or atom_symbol(nearest) not in donor_symbols:
            continue
        cutoff = 1.25 if atom_symbol(nearest) in {"O", "N"} else 1.45
        if atom_distance(hydrogen, nearest) <= cutoff:
            sites.append({"hydrogen": hydrogen, "heavy": nearest})
    return sites


def min_heavy_distance(fragment_a, fragment_b):
    heavy_a = [atom for atom in fragment_a if atom_symbol(atom) != "H"]
    heavy_b = [atom for atom in fragment_b if atom_symbol(atom) != "H"]
    values = [atom_distance(a, b) for a in heavy_a for b in heavy_b]
    return min(values) if values else 99.0


def closest_atom_pair(fragment_a, fragment_b):
    best = None
    for atom_a in fragment_a:
        for atom_b in fragment_b:
            distance = atom_distance(atom_a, atom_b)
            if best is None or distance < best[0]:
                best = (distance, atom_a, atom_b)
    return best or (99.0, {}, {})


def relax_interfragment_clashes(component_atoms, solvent_atoms, min_distance=1.55, max_steps=30):
    posed = [dict(atom) for atom in solvent_atoms]
    total_shift = (0.0, 0.0, 0.0)
    for _ in range(max_steps):
        distance, atom_a, atom_b = closest_atom_pair(component_atoms, posed)
        if distance >= min_distance:
            break
        direction = vec_norm(vec_sub(atom_xyz(atom_b), atom_xyz(atom_a)))
        if direction == (1.0, 0.0, 0.0):
            direction = vec_norm(vec_sub(fragment_center(posed), fragment_center(component_atoms)))
        step = vec_scale(direction, (min_distance - distance) + 0.08)
        total_shift = vec_add(total_shift, step)
        posed = shifted_atoms(posed, step)
    return posed, total_shift, closest_atom_pair(component_atoms, posed)[0]


def fallback_separated_pose(component_atoms, solvent_atoms):
    max_x = max((float(atom.get("x") or 0.0) for atom in component_atoms), default=0.0)
    min_x = min((float(atom.get("x") or 0.0) for atom in solvent_atoms), default=0.0)
    shift = (max_x - min_x + 3.0, 0.0, 0.0)
    return shifted_atoms(solvent_atoms, shift), {
        "strategy": "fallback_vdw_contact_x_axis",
        "shift_x": shift[0],
        "target_contact_distance_angstrom": 3.0,
    }


def contact_pose_solvent_atoms(component_atoms, solvent_atoms):
    if not component_atoms or not solvent_atoms:
        return fallback_separated_pose(component_atoms, solvent_atoms)
    candidates = []
    component_center = fragment_center(component_atoms)
    solvent_center = fragment_center(solvent_atoms)

    def add_candidate(strategy, shift, contact_distance, target_distance):
        posed = shifted_atoms(solvent_atoms, shift)
        posed, clash_shift, any_min = relax_interfragment_clashes(component_atoms, posed)
        shift = vec_add(shift, clash_shift)
        heavy_min = min_heavy_distance(component_atoms, posed)
        clash_penalty = 30.0 if any_min < 1.45 else (20.0 if heavy_min < 1.25 else 0.0)
        center_distance = vec_distance(component_center, vec_add(solvent_center, shift))
        candidates.append({
            "strategy": strategy,
            "shift": shift,
            "posed": posed,
            "contact_distance": contact_distance,
            "target_distance": target_distance,
            "heavy_min": heavy_min,
            "any_min": any_min,
            "score": abs(contact_distance - target_distance) + clash_penalty + max(0.0, 2.0 - heavy_min) * 5.0 + center_distance * 0.01,
        })

    for donor in donor_sites(component_atoms):
        donor_heavy = atom_xyz(donor["heavy"])
        donor_h = atom_xyz(donor["hydrogen"])
        direction = vec_norm(vec_sub(donor_h, donor_heavy))
        target = vec_add(donor_h, vec_scale(direction, 1.85))
        for acceptor in acceptor_atoms(solvent_atoms):
            shift = vec_sub(target, atom_xyz(acceptor))
            add_candidate("component_donor_to_solvent_acceptor_hbond", shift, vec_distance(target, donor_h), 1.85)

    for donor in donor_sites(solvent_atoms):
        donor_heavy = atom_xyz(donor["heavy"])
        donor_h = atom_xyz(donor["hydrogen"])
        direction = vec_norm(vec_sub(donor_h, donor_heavy))
        for acceptor in acceptor_atoms(component_atoms):
            target_h = vec_sub(atom_xyz(acceptor), vec_scale(direction, 1.85))
            shift = vec_sub(target_h, donor_h)
            add_candidate("solvent_donor_to_component_acceptor_hbond", shift, 1.85, 1.85)

    if not candidates:
        comp_heavy = [atom for atom in component_atoms if atom_symbol(atom) != "H"] or component_atoms
        solv_heavy = [atom for atom in solvent_atoms if atom_symbol(atom) != "H"] or solvent_atoms
        comp_atom = max(comp_heavy, key=lambda atom: float(atom.get("x") or 0.0))
        solv_atom = min(solv_heavy, key=lambda atom: float(atom.get("x") or 0.0))
        target = vec_add(atom_xyz(comp_atom), (3.0, 0.0, 0.0))
        shift = vec_sub(target, atom_xyz(solv_atom))
        add_candidate("heavy_atom_vdw_contact", shift, 3.0, 3.0)

    best = min(candidates, key=lambda item: item["score"], default=None)
    if not best:
        return fallback_separated_pose(component_atoms, solvent_atoms)
    return best["posed"], {
        "strategy": best["strategy"],
        "shift_x": best["shift"][0],
        "shift_y": best["shift"][1],
        "shift_z": best["shift"][2],
        "target_contact_distance_angstrom": best["target_distance"],
        "min_heavy_distance_angstrom": best["heavy_min"],
        "min_atom_distance_angstrom": best["any_min"],
    }


def dimer_pose_variants(component_atoms, solvent_atoms, max_variants=4):
    rotations = [
        (0, 0, 0),
        (0, 0, 90),
        (0, 0, 180),
        (0, 90, 0),
        (90, 0, 0),
        (0, 180, 90),
    ]
    variants = []
    seen = set()
    for rotation in rotations:
        rotated = rotate_atoms(solvent_atoms, rotation)
        posed, pose = contact_pose_solvent_atoms(component_atoms, rotated)
        key = tuple(
            round(float(atom.get(axis) or 0.0), 2)
            for atom in posed[: min(6, len(posed))]
            for axis in ("x", "y", "z")
        )
        if key in seen:
            continue
        seen.add(key)
        pose = dict(pose)
        pose["rotation_x_deg"] = rotation[0]
        pose["rotation_y_deg"] = rotation[1]
        pose["rotation_z_deg"] = rotation[2]
        pose["pose_index"] = len(variants) + 1
        variants.append((posed, pose))
        if len(variants) >= int(max_variants or 4):
            break
    if not variants:
        posed, pose = contact_pose_solvent_atoms(component_atoms, solvent_atoms)
        pose = dict(pose)
        pose["pose_index"] = 1
        variants.append((posed, pose))
    return variants


def write_gaussian_monomer(path, title, atoms):
    path = Path(path)
    lines = [
        "%chk={}.chk".format(path.stem),
        "%nprocshared={}".format(GAUSSIAN_DEFAULT_NPROC),
        "%mem={}".format(GAUSSIAN_DEFAULT_MEM),
        "#p B3LYP/6-311G(d,p) EmpiricalDispersion=GD3BJ Opt SCF=Tight",
        "",
        title,
        "",
        "0 1",
    ]
    lines.extend(gaussian_atom_line(atom) for atom in atoms)
    lines.extend(["", ""])
    write_text_if_changed(path, "\n".join(lines))


def write_gaussian_counterpoise_pose(path, title, component_atoms, posed_solvent_atoms, pose=None):
    path = Path(path)
    pose = pose or {}
    lines = [
        "%chk={}.chk".format(path.stem),
        "%nprocshared={}".format(GAUSSIAN_DEFAULT_NPROC),
        "%mem={}".format(GAUSSIAN_DEFAULT_MEM),
        "#p B3LYP/6-311G(d,p) EmpiricalDispersion=GD3BJ Counterpoise=2 Opt=(Loose,MaxCycles={}) IOp(1/152={}) SCF=Tight NoSymm".format(GAUSSIAN_DIMER_OPT_MAX_CYCLES, GAUSSIAN_DIMER_OPT_MAX_CYCLES),
        "",
        "{} | agent_pose={}".format(title, pose.get("strategy", "contact_pose")),
        "",
        "0 1 0 1 0 1",
    ]
    lines.extend(gaussian_atom_line(atom, fragment=1) for atom in component_atoms)
    lines.extend(gaussian_atom_line(atom, fragment=2) for atom in posed_solvent_atoms)
    lines.extend(["", ""])
    write_text_if_changed(path, "\n".join(lines))
    return pose


def write_gaussian_counterpoise(path, title, component_atoms, solvent_atoms):
    posed_solvent_atoms, pose = contact_pose_solvent_atoms(component_atoms, solvent_atoms)
    return write_gaussian_counterpoise_pose(path, title, component_atoms, posed_solvent_atoms, pose)


def write_text_if_changed(path, text, encoding="utf-8"):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        try:
            if path.read_text(encoding=encoding) == text:
                return str(path.resolve())
        except Exception:
            pass
    path.write_text(text, encoding=encoding)
    return str(path.resolve())


def write_text_file(path, text):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")
    return str(path.resolve())


def read_csv_rows(path, limit=None):
    path = Path(path)
    if not path.exists():
        return []
    rows = []
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        reader = csv.DictReader(handle)
        for row in reader:
            rows.append(row)
            if limit and len(rows) >= limit:
                break
    return rows


def csv_status_summary(path, status_field="status"):
    rows = read_csv_rows(path)
    counts = {}
    for row in rows:
        status = row.get(status_field) or "unknown"
        counts[status] = counts.get(status, 0) + 1
    return {"path": str(Path(path).resolve()), "rows": len(rows), "status_counts": counts}


def parse_xvg_numeric(path):
    path = Path(path)
    if not path.exists():
        return []
    rows = []
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        text = line.strip()
        if not text or text.startswith(("#", "@")):
            continue
        parts = text.split()
        try:
            rows.append([float(part) for part in parts])
        except Exception:
            continue
    return rows


def numeric_column_means(rows, tail_fraction=0.5):
    if not rows:
        return []
    start = max(0, int(len(rows) * (1.0 - float(tail_fraction or 0.5))))
    tail = rows[start:] or rows
    width = max(len(row) for row in tail)
    means = []
    for index in range(width):
        values = [row[index] for row in tail if len(row) > index and math.isfinite(row[index])]
        means.append(sum(values) / len(values) if values else None)
    return means


def summarize_xvg(path):
    rows = parse_xvg_numeric(path)
    means = numeric_column_means(rows)
    value_means = [value for value in means[1:] if value is not None]
    times = [row[0] for row in rows if row and math.isfinite(row[0])]
    return {
        "path": str(Path(path).resolve()) if path else "",
        "point_count": len(rows),
        "first_time_ps": times[0] if times else None,
        "last_time_ps": times[-1] if times else None,
        "time_span_ps": (times[-1] - times[0]) if len(times) >= 2 else 0,
        "column_means_tail": ";".join("" if value is None else "{:.8g}".format(value) for value in means),
        "value_column_count": len(value_means),
        "value_sum_mean_tail": sum(value_means) if value_means else None,
    }


def parse_gromacs_setting(text, key):
    if not text:
        return None
    pattern = r"(?im)^\s*{}\s*(?:=\s*)?([-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)".format(re.escape(key))
    matches = re.findall(pattern, text)
    if not matches:
        return None
    try:
        value = float(matches[-1])
    except Exception:
        return None
    return value


def gromacs_md_quality(case_dir, energy=None, msd=None, rdf=None):
    case_dir = Path(case_dir) if case_dir else None
    energy = energy or {}
    msd = msd or {}
    rdf = rdf or {}
    text_parts = []
    log_path = None
    mdp_path = None
    if case_dir and case_dir.exists():
        log_path = case_dir / "md.log"
        mdp_path = case_dir / "md.mdp"
        for path in (log_path, mdp_path):
            if path.exists():
                text_parts.append(path.read_text(encoding="utf-8", errors="replace"))
    text = "\n".join(text_parts)
    nsteps = parse_gromacs_setting(text, "nsteps")
    dt_ps = parse_gromacs_setting(text, "dt")
    production_ps = (nsteps * dt_ps) if nsteps is not None and dt_ps is not None else None
    frame_count = 0
    if text:
        frames = re.findall(r"Statistics over\s+\d+\s+steps\s+using\s+(\d+)\s+frames", text, flags=re.I)
        if frames:
            try:
                frame_count = int(frames[-1])
            except Exception:
                frame_count = 0
    energy_points = int(energy.get("point_count") or 0)
    msd_points = int(msd.get("point_count") or 0)
    rdf_points = int(rdf.get("point_count") or 0)
    analysis_complete = bool(energy_points and msd_points and rdf_points)
    strict = bool(
        analysis_complete
        and production_ps is not None
        and production_ps >= GROMACS_STRICT_MIN_PRODUCTION_PS
        and energy_points >= GROMACS_STRICT_MIN_ENERGY_POINTS
        and msd_points >= GROMACS_STRICT_MIN_MSD_POINTS
        and rdf_points >= GROMACS_STRICT_MIN_RDF_POINTS
    )
    if strict:
        status = "strict_md_complete"
        reason = "production MD and analysis meet the strict floor"
    elif analysis_complete:
        status = "smoke_md_too_short"
        reason = "analysis files exist but production MD is below the strict floor"
    elif energy_points or msd_points or rdf_points:
        status = "analysis_incomplete"
        reason = "some GROMACS analysis files exist, but energy/MSD/RDF are not all complete"
    else:
        status = "no_analysis"
        reason = "no completed GROMACS analysis files found"
    return {
        "status": status,
        "reason": reason,
        "strict_md_complete": strict,
        "analysis_complete": analysis_complete,
        "production_ps": production_ps,
        "nsteps": int(nsteps) if nsteps is not None else "",
        "dt_ps": dt_ps,
        "frame_count": frame_count,
        "energy_point_count": energy_points,
        "msd_point_count": msd_points,
        "rdf_point_count": rdf_points,
        "strict_min_production_ps": GROMACS_STRICT_MIN_PRODUCTION_PS,
        "strict_min_energy_points": GROMACS_STRICT_MIN_ENERGY_POINTS,
        "strict_min_msd_points": GROMACS_STRICT_MIN_MSD_POINTS,
        "strict_min_rdf_points": GROMACS_STRICT_MIN_RDF_POINTS,
        "md_log": str(log_path.resolve()) if log_path and log_path.exists() else "",
        "md_mdp": str(mdp_path.resolve()) if mdp_path and mdp_path.exists() else "",
    }


def gromacs_live_log_progress(case_dir):
    case_dir = Path(case_dir) if case_dir else None
    if not case_dir or not case_dir.exists():
        return {}
    stage_order = [
        ("md", case_dir / "md.log"),
        ("npt", case_dir / "npt.log"),
        ("nvt", case_dir / "nvt.log"),
        ("em", case_dir / "em.log"),
    ]
    for stage, log_path in stage_order:
        if not log_path.exists():
            continue
        text = log_path.read_text(encoding="utf-8", errors="replace")
        nsteps = parse_gromacs_setting(text, "nsteps")
        dt_ps = parse_gromacs_setting(text, "dt")
        if nsteps is None and stage == "em":
            nsteps = parse_gromacs_setting((case_dir / "em.mdp").read_text(encoding="utf-8", errors="replace") if (case_dir / "em.mdp").exists() else "", "nsteps")
        if dt_ps is None:
            dt_ps = 0.001 if stage in {"md", "nvt", "npt"} else 1.0
        target_ps = (nsteps * dt_ps) if nsteps is not None and dt_ps is not None else None
        pairs = re.findall(r"(?m)^\s*(\d+)\s+(\d+(?:\.\d+)?)\s*$", text)
        current_step = None
        current_ps = None
        if pairs:
            try:
                current_step = int(pairs[-1][0])
                current_ps = float(pairs[-1][1])
            except Exception:
                current_step = None
                current_ps = None
        finished = bool(re.search(r"Finished mdrun", text, flags=re.I))
        fraction = None
        if target_ps and current_ps is not None:
            fraction = max(0.0, min(1.0, current_ps / target_ps))
        return {
            "stage": stage,
            "log_file": str(log_path.resolve()),
            "current_step": current_step,
            "current_ps": current_ps,
            "target_ps": target_ps,
            "nsteps": int(nsteps) if nsteps is not None else "",
            "dt_ps": dt_ps,
            "finished": finished,
            "stage_progress_fraction": fraction,
            "stage_progress_percent": (fraction * 100.0) if fraction is not None else None,
            "latest_update_ts": log_path.stat().st_mtime,
            "latest_update": iso_from_timestamp(log_path.stat().st_mtime),
        }
    return {}


def truthy_flag(value):
    return str(value or "").strip().lower() in {"1", "true", "yes", "y", "pass", "passed"}


def strict_gromacs_evidence_rows(paths):
    paths = paths or {}
    evidence_csv = paths.get("molecular_evidence_import_csv") or ""
    if not evidence_csv and paths.get("molecular_inputs_dir"):
        evidence_csv = str(Path(paths.get("molecular_inputs_dir")) / "molecular_evidence_import.csv")
    rows = []
    for row in read_csv_rows(evidence_csv) if evidence_csv else []:
        if row.get("evidence_type") != "gromacs":
            continue
        if row.get("status") == "historical_result_available":
            rows.append(row)
        elif row.get("status") == "imported" and truthy_flag(row.get("gromacs_strict_md_complete")):
            rows.append(row)
    return rows


def gaussian_log_summary(path, input_file=None, enforce_input_mtime=False):
    path = Path(path)
    input_path = Path(input_file) if input_file else None
    path = resolve_gaussian_output_path(path, input_path)
    if not path:
        return {}
    if enforce_input_mtime and input_path and input_path.exists() and path.stat().st_mtime < input_path.stat().st_mtime:
        return {
            "log_file": str(path.resolve()),
            "status": "stale_log_input_newer",
            "normal_termination": False,
        }
    text = path.read_text(encoding="utf-8", errors="replace")
    scf = re.findall(r"SCF Done:\s+E\([^)]*\)\s+=\s+(-?\d+\.\d+)", text)
    cp = re.findall(r"Counterpoise corrected energy\s+=\s+(-?\d+\.\d+)", text, flags=re.I)
    normal = "Normal termination" in text
    return {
        "log_file": str(path.resolve()),
        "scf_energy_hartree": scf[-1] if scf else "",
        "counterpoise_corrected_hartree": cp[-1] if cp else "",
        "normal_termination": normal,
        "status": "parsed" if (scf or cp) else "no_energy_found",
    }


def resolve_gaussian_output_path(expected_log, input_file=None):
    expected = Path(expected_log) if expected_log else None
    input_path = Path(input_file) if input_file else None
    direct = []
    if expected:
        direct.extend([expected, expected.with_suffix(".out")])
    if input_path:
        direct.extend([input_path.with_suffix(".log"), input_path.with_suffix(".out")])
    seen = set()
    for candidate in direct:
        key = str(candidate)
        if key in seen:
            continue
        seen.add(key)
        if candidate.exists():
            return candidate
    if not input_path or not input_path.exists():
        return None
    base = input_path.stem.lower()
    skip_suffixes = {".gjf", ".com", ".chk", ".fch", ".rwf", ".int", ".d2e", ".scr"}
    matches = []
    for candidate in input_path.parent.iterdir():
        if not candidate.is_file() or candidate == input_path:
            continue
        if candidate.suffix.lower() in skip_suffixes:
            continue
        stem = candidate.stem.lower()
        name = candidate.name.lower()
        if base.startswith(stem) or stem.startswith(base) or name.startswith(base):
            matches.append(candidate)
    for candidate in sorted(matches, key=lambda item: item.stat().st_mtime, reverse=True):
        text = candidate.read_text(encoding="utf-8", errors="replace")
        if "Normal termination of Gaussian" in text or "Error termination" in text or "SCF Done" in text:
            return candidate
    return None


def molecular_evidence_import_rows(report, paths):
    rows = []
    gaussian_jobs_path = paths.get("gaussian_jobs_csv")
    if gaussian_jobs_path and Path(gaussian_jobs_path).exists():
        for job in read_csv_rows(gaussian_jobs_path):
            log_path = job.get("expected_log") or ""
            parsed = gaussian_log_summary(
                log_path,
                input_file=job.get("input_file"),
                enforce_input_mtime=job.get("job_type") in {"counterpoise_dimer_single_point", "counterpoise_dimer_optimization"},
            )
            if not parsed:
                rows.append({
                    "evidence_type": "gaussian",
                    "job_id": job.get("job_id"),
                    "job_type": job.get("job_type"),
                    "component": job.get("component"),
                    "solvent_code": job.get("solvent_code"),
                    "solvent_name": job.get("solvent_name"),
                    "source_file": log_path,
                    "status": "pending_log",
                })
                continue
            rows.append({
                "evidence_type": "gaussian",
                "job_id": job.get("job_id"),
                "job_type": job.get("job_type"),
                "component": job.get("component"),
                "solvent_code": job.get("solvent_code"),
                "solvent_name": job.get("solvent_name"),
                "source_file": parsed.get("log_file"),
                "status": "imported" if parsed.get("status") == "parsed" else parsed.get("status"),
                "normal_termination": parsed.get("normal_termination"),
                "scf_energy_hartree": parsed.get("scf_energy_hartree"),
                "counterpoise_corrected_hartree": parsed.get("counterpoise_corrected_hartree"),
            })

    nci_rows_path = paths.get("nci_vmd_results_csv") or ""
    nci_jobs_path = paths.get("nci_vmd_jobs_csv") or ""
    nci_source_path = nci_rows_path if nci_rows_path and Path(nci_rows_path).exists() else nci_jobs_path
    nci_job_by_id = {
        row.get("job_id"): row
        for row in (read_csv_rows(nci_jobs_path) if nci_jobs_path and Path(nci_jobs_path).exists() else [])
        if row.get("job_id")
    }
    if nci_source_path and Path(nci_source_path).exists():
        for job in read_csv_rows(nci_source_path):
            queue_job = nci_job_by_id.get(job.get("job_id")) or {}
            png_path = job.get("render_png") or job.get("image_file") or ""
            tga_path = job.get("render_tga") or ""
            func1_path = job.get("func1_cube") or ""
            func2_path = job.get("func2_cube") or ""
            source_fch = job.get("source_fch") or ""
            source_input = job.get("source_input_file") or queue_job.get("source_input_file") or ""
            png_ready = bool(png_path and Path(png_path).exists() and Path(png_path).stat().st_size > 0)
            tga_ready = bool(tga_path and Path(tga_path).exists() and Path(tga_path).stat().st_size > 0)
            cube_ready = bool(
                func1_path and func2_path
                and Path(func1_path).exists()
                and Path(func2_path).exists()
            )
            stale_fch = bool(
                source_input
                and source_fch
                and Path(source_input).exists()
                and Path(source_fch).exists()
                and Path(source_fch).stat().st_mtime < Path(source_input).stat().st_mtime
            )
            stale_image = bool(
                source_input
                and png_path
                and Path(source_input).exists()
                and Path(png_path).exists()
                and Path(png_path).stat().st_mtime < Path(source_input).stat().st_mtime
            )
            if stale_fch:
                status_value = "stale_fch_input_newer"
            elif stale_image:
                status_value = "stale_nci_image_input_newer"
            elif png_ready:
                status_value = "imported"
            elif tga_ready:
                status_value = "rendered_tga"
            elif cube_ready:
                status_value = "cubes_generated"
            elif source_fch and Path(source_fch).exists():
                status_value = "ready_for_nci"
            else:
                status_value = "pending_fch"
            rows.append({
                "evidence_type": "nci_vmd",
                "job_id": job.get("job_id"),
                "component": job.get("component"),
                "solvent_code": job.get("solvent_code"),
                "solvent_name": job.get("solvent_name"),
                "source_file": png_path if png_ready else (tga_path if tga_ready else source_fch),
                "source_input_file": source_input,
                "image_file": png_path,
                "tga_file": tga_path,
                "func1_cube": func1_path,
                "func2_cube": func2_path,
                "vmd_script": job.get("vmd_script") or "",
                "multiwfn_log": job.get("multiwfn_log") or "",
                "vmd_log": job.get("vmd_log") or "",
                "grid_quality": job.get("grid_quality") or "",
                "status": status_value,
                "source_status": job.get("status") or queue_job.get("status") or "",
                "error": job.get("error") or "",
                "work_dir": job.get("work_dir") or "",
            })

    gromacs_jobs_path = paths.get("gromacs_jobs_csv")
    if gromacs_jobs_path and Path(gromacs_jobs_path).exists():
        for job in read_csv_rows(gromacs_jobs_path):
            energy_path = job.get("interaction_energy_xvg") or ""
            if not energy_path and job.get("case_dir"):
                candidate = Path(job.get("case_dir")) / "interaction_energy.xvg"
                energy_path = str(candidate) if candidate.exists() else ""
            msd_path = job.get("msd_xvg") or ""
            if not msd_path and job.get("case_dir"):
                candidate = Path(job.get("case_dir")) / "msd_{}.xvg".format(job.get("component_asset_code") or job.get("target_component") or "")
                msd_path = str(candidate) if candidate.exists() else ""
            rdf_path = job.get("rdf_xvg") or ""
            if not rdf_path and job.get("case_dir"):
                candidate = Path(job.get("case_dir")) / "rdf_{}_{}.xvg".format(
                    job.get("component_asset_code") or job.get("target_component") or "",
                    job.get("solvent_asset_code") or job.get("solvent_code") or "",
                )
                rdf_path = str(candidate) if candidate.exists() else ""
            energy = summarize_xvg(energy_path) if energy_path and Path(energy_path).exists() else {}
            msd = summarize_xvg(msd_path) if msd_path and Path(msd_path).exists() else {}
            rdf = summarize_xvg(rdf_path) if rdf_path and Path(rdf_path).exists() else {}
            case_dir_value = job.get("case_dir") or job.get("existing_run_dir") or (str(Path(energy_path).parent) if energy_path else "")
            md_quality = gromacs_md_quality(case_dir_value, energy=energy, msd=msd, rdf=rdf)
            if job.get("status") == "historical_gromacs_result_available":
                gromacs_status = "historical_result_available"
            elif energy.get("point_count"):
                gromacs_status = "imported" if md_quality.get("strict_md_complete") else md_quality.get("status")
            else:
                gromacs_status = "pending_xvg"
            rows.append({
                "evidence_type": "gromacs",
                "job_id": job.get("job_id"),
                "component": job.get("target_component"),
                "component_asset_code": job.get("component_asset_code"),
                "solvent_code": job.get("solvent_code"),
                "solvent_asset_code": job.get("solvent_asset_code"),
                "source_file": energy.get("path") or energy_path,
                "msd_file": msd.get("path") or msd_path,
                "rdf_file": rdf.get("path") or rdf_path,
                "status": gromacs_status,
                "source_status": job.get("status"),
                "energy_point_count": energy.get("point_count", 0),
                "energy_value_column_count": energy.get("value_column_count", 0),
                "energy_first_time_ps": energy.get("first_time_ps"),
                "energy_last_time_ps": energy.get("last_time_ps"),
                "energy_time_span_ps": energy.get("time_span_ps"),
                "interaction_energy_sum_mean_tail": energy.get("value_sum_mean_tail"),
                "energy_column_means_tail": energy.get("column_means_tail", ""),
                "msd_point_count": msd.get("point_count", 0),
                "msd_first_time_ps": msd.get("first_time_ps"),
                "msd_last_time_ps": msd.get("last_time_ps"),
                "msd_column_means_tail": msd.get("column_means_tail", ""),
                "rdf_point_count": rdf.get("point_count", 0),
                "rdf_column_means_tail": rdf.get("column_means_tail", ""),
                "gromacs_quality_status": md_quality.get("status"),
                "gromacs_quality_reason": md_quality.get("reason"),
                "gromacs_strict_md_complete": md_quality.get("strict_md_complete"),
                "gromacs_analysis_complete": md_quality.get("analysis_complete"),
                "gromacs_production_ps": md_quality.get("production_ps"),
                "gromacs_nsteps": md_quality.get("nsteps"),
                "gromacs_dt_ps": md_quality.get("dt_ps"),
                "gromacs_frame_count": md_quality.get("frame_count"),
                "gromacs_strict_min_production_ps": md_quality.get("strict_min_production_ps"),
                "gromacs_strict_min_energy_points": md_quality.get("strict_min_energy_points"),
                "gromacs_strict_min_msd_points": md_quality.get("strict_min_msd_points"),
                "gromacs_strict_min_rdf_points": md_quality.get("strict_min_rdf_points"),
                "existing_run_dir": job.get("existing_run_dir"),
                "case_dir": case_dir_value,
            })
    return rows


def candidate_molecular_import_summary(report, rows):
    task = report.get("separation_task") or {}
    target = str(task.get("target_product") or "").upper()
    target_token = component_token(target)
    alpha_roles = relative_volatility_role_summary(task, lookup_rows=report.get("online_component_info") or [])
    alpha_overhead_token = component_token(alpha_roles.get("alpha_overhead_token") or alpha_roles.get("alpha_overhead_component"))
    alpha_bottom_token = component_token(alpha_roles.get("alpha_bottom_token") or alpha_roles.get("alpha_bottom_component"))
    other_components = [
        str(item or "").upper()
        for item in [task.get("component_a"), task.get("component_b")]
        if component_token(item) != target_token
    ]
    other_component_tokens = {component_token(item) for item in other_components}
    solvent_meta = {
        str(item.get("code") or item.get("solvent_code") or "").upper(): item
        for item in (((report.get("system_research_brief") or {}).get("candidate_solvent_pool") or {}).get("items") or [])
    }
    component_monomer_energy = {}
    solvent_monomer_energy = {}
    for row in rows:
        if row.get("evidence_type") != "gaussian" or row.get("status") not in {"imported", "historical_result_available"}:
            continue
        if row.get("job_type") not in {"component_monomer_opt", "solvent_monomer_opt"}:
            continue
        energy = safe_float(row.get("scf_energy_hartree"))
        if energy is None:
            continue
        component = str(row.get("component") or "").upper()
        solvent = str(row.get("solvent_code") or "").upper()
        if component:
            component_monomer_energy[component] = energy
        if solvent:
            solvent_monomer_energy[solvent] = energy
    by_solvent = {}
    for row in rows:
        if row.get("status") not in {"imported", "historical_result_available", "smoke_md_too_short", "analysis_incomplete"}:
            continue
        solvent = str(row.get("solvent_code") or row.get("solvent_asset_code") or "").upper()
        if not solvent:
            continue
        meta = solvent_meta.get(solvent) or {}
        item = by_solvent.setdefault(solvent, {
            "solvent_code": solvent,
            "solvent_name": meta.get("name") or row.get("solvent_name") or "",
            "gaussian_imported": 0,
            "gaussian_bsse_imported": 0,
            "nci_vmd_images_imported": 0,
            "gromacs_imported": 0,
            "gromacs_smoke_records": 0,
            "target_component": target,
            "alpha_definition": alpha_roles.get("alpha_definition") or "",
            "alpha_overhead_component": alpha_roles.get("alpha_overhead_component") or "",
            "alpha_bottom_component": alpha_roles.get("alpha_bottom_component") or "",
            "ed_preferential_binding_component": alpha_roles.get("ed_preferential_binding_component") or "",
            "molecular_score_basis": "relative_volatility_bottom_key_preference" if alpha_roles.get("status") == "roles_identified" else "legacy_target_component_preference",
            "target_gromacs_energy_mean": None,
            "other_gromacs_energy_mean": None,
            "alpha_overhead_gromacs_energy_mean": None,
            "alpha_bottom_gromacs_energy_mean": None,
            "target_gaussian_bsse_binding_kjmol": None,
            "other_gaussian_bsse_binding_kjmol": None,
            "alpha_overhead_gaussian_bsse_binding_kjmol": None,
            "alpha_bottom_gaussian_bsse_binding_kjmol": None,
            "process_gate_rank": meta.get("process_gate_rank") or "",
            "process_gate_reason": meta.get("process_gate_reason") or "",
            "relative_volatility_gate": meta.get("relative_volatility_gate") or "",
            "alpha_improvement_best": meta.get("alpha_improvement_best") or "",
            "alpha_best_sf_ratio": meta.get("alpha_best_sf_ratio") or "",
            "molecular_evidence_status": "partial",
        })
        if not item.get("solvent_name") and row.get("solvent_name"):
            item["solvent_name"] = row.get("solvent_name")
        if row.get("evidence_type") == "gaussian":
            item["gaussian_imported"] += 1
            if row.get("job_type") in {"counterpoise_dimer_single_point", "counterpoise_dimer_optimization"} or str(row.get("job_id") or "").lower().endswith("_cp"):
                item["gaussian_bsse_imported"] += 1
                component = str(row.get("component") or "").upper()
                cp_energy = safe_float(row.get("counterpoise_corrected_hartree"))
                component_energy = component_monomer_energy.get(component)
                solvent_energy = solvent_monomer_energy.get(solvent)
                if cp_energy is not None and component_energy is not None and solvent_energy is not None:
                    binding_kjmol = (cp_energy - component_energy - solvent_energy) * 2625.49962
                    component_key = component_token(component)
                    if component_key == target_token:
                        item["target_gaussian_bsse_binding_kjmol"] = binding_kjmol
                    elif component_key in other_component_tokens or item.get("other_gaussian_bsse_binding_kjmol") is None:
                        item["other_gaussian_bsse_binding_kjmol"] = binding_kjmol
                    if alpha_overhead_token and component_key == alpha_overhead_token:
                        item["alpha_overhead_gaussian_bsse_binding_kjmol"] = binding_kjmol
                    if alpha_bottom_token and component_key == alpha_bottom_token:
                        item["alpha_bottom_gaussian_bsse_binding_kjmol"] = binding_kjmol
        if row.get("evidence_type") == "gromacs" and row.get("status") in {"smoke_md_too_short", "analysis_incomplete"}:
            item["gromacs_smoke_records"] += 1
            continue
        if row.get("evidence_type") == "gromacs":
            item["gromacs_imported"] += 1
            component = str(row.get("component") or "").upper()
            component_key = component_token(component)
            energy = safe_float(row.get("interaction_energy_sum_mean_tail"))
            if component_key == target_token:
                item["target_gromacs_energy_mean"] = energy
            elif component_key in other_component_tokens or item.get("other_gromacs_energy_mean") is None:
                item["other_gromacs_energy_mean"] = energy
            if alpha_overhead_token and component_key == alpha_overhead_token:
                item["alpha_overhead_gromacs_energy_mean"] = energy
            if alpha_bottom_token and component_key == alpha_bottom_token:
                item["alpha_bottom_gromacs_energy_mean"] = energy
        if row.get("evidence_type") == "nci_vmd":
            item["nci_vmd_images_imported"] += 1
    for item in by_solvent.values():
        target_energy = safe_float(item.get("target_gromacs_energy_mean"))
        other_energy = safe_float(item.get("other_gromacs_energy_mean"))
        if target_energy is not None and other_energy is not None:
            item["gromacs_delta_target_minus_other"] = target_energy - other_energy
            item["gromacs_target_preference_kjmol"] = other_energy - target_energy
        overhead_energy = safe_float(item.get("alpha_overhead_gromacs_energy_mean"))
        bottom_energy = safe_float(item.get("alpha_bottom_gromacs_energy_mean"))
        if overhead_energy is not None and bottom_energy is not None:
            item["gromacs_bottom_key_preference_kjmol"] = overhead_energy - bottom_energy
        target_binding = safe_float(item.get("target_gaussian_bsse_binding_kjmol"))
        other_binding = safe_float(item.get("other_gaussian_bsse_binding_kjmol"))
        if target_binding is not None and other_binding is not None:
            item["gaussian_bsse_target_preference_kjmol"] = other_binding - target_binding
        overhead_binding = safe_float(item.get("alpha_overhead_gaussian_bsse_binding_kjmol"))
        bottom_binding = safe_float(item.get("alpha_bottom_gaussian_bsse_binding_kjmol"))
        if overhead_binding is not None and bottom_binding is not None:
            item["gaussian_bsse_bottom_key_preference_kjmol"] = overhead_binding - bottom_binding
        selectivity_score = None
        if alpha_roles.get("status") == "roles_identified":
            selectivity_score = safe_float(item.get("gromacs_bottom_key_preference_kjmol"))
            if selectivity_score is None:
                selectivity_score = safe_float(item.get("gaussian_bsse_bottom_key_preference_kjmol"))
        if selectivity_score is None:
            selectivity_score = safe_float(item.get("gromacs_target_preference_kjmol"))
        if selectivity_score is None:
            selectivity_score = safe_float(item.get("gaussian_bsse_target_preference_kjmol"))
        if selectivity_score is not None:
            item["molecular_selectivity_score"] = selectivity_score
            if alpha_roles.get("status") == "roles_identified":
                if selectivity_score > 0:
                    item["molecular_preference"] = "alpha_bottom_key_preferred"
                elif selectivity_score < 0:
                    item["molecular_preference"] = "alpha_overhead_key_preferred"
                else:
                    item["molecular_preference"] = "neutral"
            elif selectivity_score > 0:
                item["molecular_preference"] = "target_component_preferred"
            elif selectivity_score < 0:
                item["molecular_preference"] = "other_component_preferred"
            else:
                item["molecular_preference"] = "neutral"
        if item.get("gaussian_bsse_imported", 0) >= 2 and item.get("nci_vmd_images_imported", 0) >= 2 and item.get("gromacs_imported") >= 2:
            item["molecular_evidence_status"] = "gaussian_bsse_nci_and_gromacs_pair_imported"
        elif item.get("gaussian_bsse_imported", 0) >= 2 and item.get("gromacs_imported") >= 2:
            item["molecular_evidence_status"] = "gaussian_bsse_and_gromacs_pair_imported"
        elif item.get("gaussian_bsse_imported", 0) >= 2 and item.get("nci_vmd_images_imported", 0) >= 2:
            item["molecular_evidence_status"] = "gaussian_bsse_and_nci_pair_imported"
        elif item.get("gaussian_imported") and item.get("gromacs_imported") >= 2:
            item["molecular_evidence_status"] = "gaussian_and_gromacs_pair_imported"
        elif item.get("gromacs_imported") >= 2:
            item["molecular_evidence_status"] = "gromacs_pair_imported"
        elif item.get("gromacs_smoke_records") >= 2:
            item["molecular_evidence_status"] = "gromacs_smoke_pair_not_strict"
        elif item.get("nci_vmd_images_imported"):
            item["molecular_evidence_status"] = "nci_vmd_image_imported"
        elif item.get("gaussian_imported"):
            item["molecular_evidence_status"] = "gaussian_imported"
        elif item.get("gromacs_imported"):
            item["molecular_evidence_status"] = "gromacs_single_imported"
    ranked = sorted(
        by_solvent.values(),
        key=lambda item: (
            safe_float(item.get("molecular_selectivity_score")) is not None,
            safe_float(item.get("molecular_selectivity_score")) if safe_float(item.get("molecular_selectivity_score")) is not None else float("-inf"),
            -safe_float(item.get("process_gate_rank")) if safe_float(item.get("process_gate_rank")) is not None else float("-inf"),
        ),
        reverse=True,
    )
    for index, item in enumerate(ranked, start=1):
        item["molecular_rank"] = index if safe_float(item.get("molecular_selectivity_score")) is not None else ""
        score = safe_float(item.get("molecular_selectivity_score"))
        if score is None:
            item["molecular_recommendation"] = "insufficient_quantitative_evidence"
        elif score > 0:
            item["molecular_recommendation"] = "advance_for_process_gate_check"
        else:
            item["molecular_recommendation"] = "retain_as_lower_priority_or_alpha_direction_failed"
    return ranked


def gaussian_job_completed_map(rows):
    completed = {}
    for row in rows or []:
        if row.get("evidence_type") != "gaussian":
            continue
        job_id = row.get("job_id")
        if not job_id:
            continue
        completed[job_id] = row.get("status") == "imported" and bool(row.get("normal_termination"))
    return completed


def count_completed_gaussian_jobs(jobs, completed_map, job_types):
    selected = [row for row in jobs if row.get("job_type") in set(job_types)]
    done = [row for row in selected if completed_map.get(row.get("job_id"))]
    return len(done), len(selected)


def fch_count_for_jobs(jobs, job_types=None):
    types = set(job_types or [])
    count = 0
    total = 0
    for job in jobs:
        if types and job.get("job_type") not in types:
            continue
        input_file = job.get("input_file")
        if not input_file:
            continue
        total += 1
        if Path(input_file).with_suffix(".fch").exists():
            count += 1
    return count, total


def build_agent_execution_step_plan(report, paths, molecular_rows=None):
    task = report.get("separation_task") or {}
    counts = report.get("counts") or {}
    paths = paths or report.get("research_task_package_paths") or {}
    molecular_rows = molecular_rows if molecular_rows is not None else molecular_evidence_import_rows(report, paths)
    gaussian_jobs = read_csv_rows(paths.get("gaussian_jobs_csv")) if paths.get("gaussian_jobs_csv") else []
    nci_vmd_jobs = read_csv_rows(paths.get("nci_vmd_jobs_csv")) if paths.get("nci_vmd_jobs_csv") else []
    gromacs_jobs = read_csv_rows(paths.get("gromacs_jobs_csv")) if paths.get("gromacs_jobs_csv") else []
    completed_gaussian = gaussian_job_completed_map(molecular_rows)

    monomer_done, monomer_total = count_completed_gaussian_jobs(
        gaussian_jobs,
        completed_gaussian,
        {"component_monomer_opt", "solvent_monomer_opt"},
    )
    dimer_done, dimer_total = count_completed_gaussian_jobs(
        gaussian_jobs,
        completed_gaussian,
        {"counterpoise_dimer_single_point", "counterpoise_dimer_optimization"},
    )
    fch_done, fch_total = fch_count_for_jobs(
        gaussian_jobs,
        {"component_monomer_opt", "solvent_monomer_opt"},
    )
    nci_done = sum(
        1 for row in molecular_rows
        if row.get("evidence_type") == "nci_vmd" and row.get("status") in {"imported", "rendered_tga"}
    )
    nci_total = len(nci_vmd_jobs)
    gromacs_done = sum(
        1 for row in molecular_rows
        if row.get("evidence_type") == "gromacs" and row.get("status") in {"imported", "historical_result_available"}
    )
    gromacs_smoke = sum(
        1 for row in molecular_rows
        if row.get("evidence_type") == "gromacs" and row.get("status") in {"smoke_md_too_short", "analysis_incomplete"}
    )
    gromacs_total = len(gromacs_jobs)
    process_count = int(counts.get("imported_process_result_records") or 0) + int(counts.get("process_evidence_records") or 0)
    process_import = report.get("process_result_import") or {}
    optimization_cases = int(process_import.get("optimization_case_count") or 0)
    optimization_pass_cases = int(process_import.get("closed_loop_optimization_pass_case_count") or 0)
    closed_loop_diag = process_import.get("closed_loop_recycle_diagnosis") or {}
    aspen_repair_required = bool(closed_loop_diag.get("agent_should_stop_before_more_optimization"))
    aspen_repair_strategy_ready = closed_loop_diag.get("status") == "closed_loop_recycle_repair_strategy_ready"
    aspen_plan = ((report.get("system_research_brief") or {}).get("aspen_from_zero_plan") or {})
    aspen_ready = bool(task.get("compatible_verified_case") or aspen_plan.get("can_generate_bkp_now"))
    aspen_spec_ready = bool(aspen_plan.get("spec_ready"))

    def status(done, total, waiting=False, blocked=False):
        if blocked:
            return "blocked"
        if waiting:
            return "waiting_previous_stage"
        if total and done >= total:
            return "done"
        if done:
            return "partial"
        return "queued" if total else "missing"

    steps = [
        {
            "order": 1,
            "stage": "gaussian_monomers",
            "label": "Gaussian 单组分优化",
            "status": status(monomer_done, monomer_total),
            "done": monomer_done,
            "total": monomer_total,
            "next_action": "run_gaussian_queue with budgeted MaxJobs until all component/solvent monomers terminate normally",
        },
        {
            "order": 2,
            "stage": "gaussian_bsse_dimers",
            "label": "Gaussian 双组分/BSSE",
            "status": status(dimer_done, dimer_total, waiting=monomer_done < monomer_total),
            "done": dimer_done,
            "total": dimer_total,
            "next_action": "run counterpoise dimer jobs for target/other component against each candidate solvent",
        },
        {
            "order": 3,
            "stage": "multiwfn_nci_vmd_images",
            "label": "Multiwfn/VMD NCI图",
            "status": status(nci_done, nci_total, waiting=dimer_done < dimer_total),
            "done": nci_done,
            "total": nci_total,
            "next_action": "run Multiwfn NCI cube export and VMD rendering for each counterpoise dimer .fch",
        },
        {
            "order": 4,
            "stage": "multiwfn_sobtop_topology",
            "label": "Multiwfn/Sobtop 拓扑",
            "status": status(fch_done, fch_total, waiting=monomer_done < monomer_total),
            "done": fch_done,
            "total": fch_total,
            "next_action": "generate charges/topologies from .fch and import .gro/.itp assets",
        },
        {
            "order": 5,
            "stage": "gromacs_md_rdf",
            "label": "GROMACS MD/RDF/相互作用能",
            "status": status(gromacs_done, gromacs_total, waiting=fch_done < fch_total or dimer_done < dimer_total),
            "done": gromacs_done,
            "total": gromacs_total,
            "next_action": (
                "rerun GROMACS with the strict legacy MD floor before Aspen gating"
                if gromacs_smoke and gromacs_done < gromacs_total
                else "run GROMACS queue after topology assets are ready, then import XVG/RDF/energy evidence"
            ),
            "smoke_done": gromacs_smoke,
        },
        {
            "order": 6,
            "stage": "molecular_selection_gate",
            "label": "萃取剂分子证据筛选",
            "status": "done" if gromacs_total and gromacs_done >= gromacs_total and dimer_total and dimer_done >= dimer_total and (not nci_total or nci_done >= nci_total) else "waiting_molecular_evidence",
            "done": min(gromacs_done, gromacs_total) + min(dimer_done, dimer_total) + min(nci_done, nci_total),
            "total": gromacs_total + dimer_total + nci_total,
            "next_action": "rank candidate solvents from Gaussian selectivity and GROMACS interaction/RDF evidence",
        },
        {
            "order": 7,
            "stage": "aspen_template_variable_map",
            "label": "Aspen 物性/模板/变量映射",
            "status": "ready" if aspen_ready else ("waiting_molecular_gate" if aspen_spec_ready else "blocked_new_system_template"),
            "done": 1 if aspen_ready else 0,
            "total": 1,
            "next_action": (
                "run Aspen zero-build archive generation, then real optimization"
                if aspen_ready
                else (
                    "finish same-task Gaussian/GROMACS molecular gate before Aspen BKP generation"
                    if aspen_spec_ready
                    else "build Aspen component/property/spec mapping before optimization"
                )
            ),
        },
        {
            "order": 8,
            "stage": "aspen_validation_optimization",
            "label": "Aspen 验证与优化",
            "status": (
                "done"
                if optimization_pass_cases
                else (
                    "blocked_recycle_repair_required"
                    if aspen_repair_required
                    else (
                        "repair_strategy_ready"
                        if aspen_repair_strategy_ready
                        else ("partial_needs_repair" if optimization_cases else ("ready" if aspen_ready and process_count else "blocked_until_aspen_boundary"))
                    )
                )
            ),
            "done": optimization_pass_cases,
            "total": max(1, optimization_cases or process_count or 1),
            "next_action": (
                "repair closed-loop recycle/convergence strategy before any larger Aspen campaign"
                if aspen_repair_required
                else (
                    "run calculator-inventory closed-loop Aspen repair campaign"
                    if aspen_repair_strategy_ready
                    else "run Aspen validation and one optimization campaign for this same binary task"
                )
            ),
            "diagnosis": closed_loop_diag,
        },
    ]
    next_step = next((row for row in steps if row.get("status") not in {"done"}), steps[-1] if steps else {})
    return {
        "task_id": task.get("task_id"),
        "validation_role": task_validation_role(task),
        "generated_at": iso_from_timestamp(time.time()),
        "overall_status": "complete" if all(row.get("status") == "done" for row in steps) else "in_progress",
        "next_stage": next_step.get("stage"),
        "next_action": next_step.get("next_action"),
        "steps": steps,
    }


def write_agent_execution_step_plan(report, paths, molecular_rows=None):
    paths = paths or report.get("research_task_package_paths") or {}
    mol_dir_value = paths.get("molecular_inputs_dir")
    if not mol_dir_value:
        return report, {}
    mol_dir = generated_path(mol_dir_value, "molecular_inputs_dir")
    plan = build_agent_execution_step_plan(report, paths, molecular_rows=molecular_rows)
    json_path = mol_dir.parent / "agent_execution_step_plan.json"
    csv_path = mol_dir.parent / "agent_execution_step_plan.csv"
    write_json_file(json_path, plan)
    write_csv_file(csv_path, plan.get("steps") or [])
    paths["agent_execution_step_plan_json"] = str(json_path.resolve())
    paths["agent_execution_step_plan_csv"] = str(csv_path.resolve())
    report["research_task_package_paths"] = paths
    report["agent_execution_step_plan"] = plan
    return report, plan


def import_molecular_results(report, report_path):
    paths = report.get("research_task_package_paths") or {}
    preserved_runtime_paths = {
        key: value for key, value in paths.items()
        if key in {"full_flow_autopilot_status_json"}
    }
    mol_dir = generated_path(paths.get("molecular_inputs_dir"), "molecular_inputs_dir")
    rows = molecular_evidence_import_rows(report, paths)
    summary_rows = candidate_molecular_import_summary(report, rows)
    learning_summary = update_solvent_learning_memory(report, summary_rows)
    evidence_csv = mol_dir / "molecular_evidence_import.csv"
    candidate_csv = mol_dir / "candidate_molecular_evidence_import.csv"
    summary_json = mol_dir / "molecular_evidence_import_summary.json"
    write_csv_file(evidence_csv, rows)
    write_csv_file(candidate_csv, summary_rows)
    imported_count = sum(1 for row in rows if row.get("status") in {"imported", "historical_result_available"})
    strict_gromacs_count = sum(
        1 for row in rows
        if row.get("evidence_type") == "gromacs"
        and row.get("status") in {"imported", "historical_result_available"}
    )
    smoke_gromacs_count = sum(
        1 for row in rows
        if row.get("evidence_type") == "gromacs"
        and row.get("status") in {"smoke_md_too_short", "analysis_incomplete"}
    )
    nci_image_count = sum(1 for row in rows if row.get("evidence_type") == "nci_vmd" and row.get("status") in {"imported", "rendered_tga"})
    status_counts = {}
    for row in rows:
        status = row.get("status") or "unknown"
        status_counts[status] = status_counts.get(status, 0) + 1
    summary = {
        "status": "imported_results_available" if imported_count else "no_completed_results_found",
        "evidence_record_count": imported_count,
        "row_count": len(rows),
        "candidate_count": len(summary_rows),
        "strict_gromacs_record_count": strict_gromacs_count,
        "smoke_gromacs_record_count": smoke_gromacs_count,
        "nci_vmd_image_count": nci_image_count,
        "status_counts": status_counts,
        "evidence_csv": str(evidence_csv.resolve()),
        "candidate_evidence_csv": str(candidate_csv.resolve()),
        "learning_summary": learning_summary,
        "generated_at": iso_from_timestamp(time.time()),
    }
    write_json_file(summary_json, summary)
    paths["molecular_evidence_import_csv"] = str(evidence_csv.resolve())
    paths["candidate_molecular_evidence_import_csv"] = str(candidate_csv.resolve())
    paths["molecular_evidence_import_summary_json"] = str(summary_json.resolve())
    report["research_task_package_paths"] = paths
    report["molecular_evidence_import"] = summary
    counts = dict(report.get("counts") or {})
    counts["imported_molecular_evidence_records"] = imported_count
    counts["imported_strict_gromacs_records"] = strict_gromacs_count
    counts["smoke_gromacs_records"] = smoke_gromacs_count
    counts["imported_molecular_evidence_candidates"] = len(summary_rows)
    counts["imported_nci_vmd_image_records"] = nci_image_count
    report["counts"] = counts
    report, step_plan = write_agent_execution_step_plan(report, paths, molecular_rows=rows)
    report.pop("system_research_brief", None)
    report.pop("agent_stage_trace", None)
    report.pop("next_action_plan", None)
    report = enrich_trial_report_payload(report)
    output_dir = Path(report.get("output_dir") or Path(report_path).parent)
    paths = export_research_task_package(report, output_dir)
    paths.update({
        "molecular_evidence_import_csv": str(evidence_csv.resolve()),
        "candidate_molecular_evidence_import_csv": str(candidate_csv.resolve()),
        "molecular_evidence_import_summary_json": str(summary_json.resolve()),
    })
    paths.update({key: value for key, value in preserved_runtime_paths.items() if value})
    report["research_task_package_paths"] = paths
    report = enrich_trial_report_payload(report)
    refresh_system_frontend_artifacts(report, report_path)
    write_json_file(report_path, report)
    return report, summary


def read_jsonl_records(path, limit=10000):
    records = []
    path = Path(path)
    if not path.exists():
        return records
    with path.open("r", encoding="utf-8-sig") as handle:
        for index, line in enumerate(handle):
            if index >= limit:
                break
            text = line.strip()
            if not text:
                continue
            try:
                payload = json.loads(text)
            except Exception:
                continue
            if isinstance(payload, dict):
                records.append(payload)
    return records


def aspen_optimization_search_roots(report, package_path):
    roots = []
    candidates = []
    if package_path:
        candidates.append(Path(package_path).parent)
    if report.get("output_dir"):
        candidates.append(report.get("output_dir"))
    for candidate in candidates:
        try:
            path = generated_path(candidate, "optimization_search_root")
        except Exception:
            continue
        if path.exists() and path.is_dir() and str(path.resolve()) not in roots:
            roots.append(str(path.resolve()))
    return [Path(path) for path in roots]


def aspen_spec_topology_metadata(spec):
    spec = spec or {}
    blocks = {str(block.get("id") or ""): block for block in spec.get("blocks", []) if isinstance(block, dict)}
    calculator = spec.get("calculator") or {}
    mode = str(spec.get("process_topology_mode") or "").strip()
    b3 = blocks.get("B3") or {}
    b3_inputs = {str(item).upper() for item in (b3.get("in") or [])}
    b3_outputs = {str(item).upper() for item in (b3.get("out") or [])}
    has_recycle_mixer = "B3" in blocks and "S3" in b3_inputs and "C2" in b3_outputs
    recycle_stream = str(calculator.get("recycle_stream") or "")
    makeup_stream = str(calculator.get("makeup_stream") or "")
    closed_loop = bool(
        "closed" in mode.lower()
        or (
            has_recycle_mixer
            and (not calculator or recycle_stream.upper() == "S3")
        )
    )
    if not mode:
        mode = "closed_loop_solvent_recycle" if closed_loop else "open_loop_or_unclassified"
    recycle_control_mode = str(spec.get("recycle_control_mode") or "").strip()
    if not recycle_control_mode:
        if calculator:
            recycle_control_mode = (
                "bounded_nonnegative_makeup_control"
                if calculator.get("formula_mode") == "bounded_nonnegative_makeup"
                else "calculator_inventory_control"
            )
        elif "fixed_makeup" in mode.lower():
            recycle_control_mode = "fixed_fresh_makeup_diagnostic"
    return {
        "process_topology_mode": mode,
        "recycle_control_mode": recycle_control_mode,
        "closed_loop_recycle": closed_loop,
        "has_recycle_mixer": has_recycle_mixer,
        "has_recycle_calculator": bool(calculator),
        "recycle_stream": recycle_stream or ("S3" if has_recycle_mixer else ""),
        "makeup_stream": makeup_stream or ("C1" if has_recycle_mixer else ""),
    }


def truthy_cell(value):
    if isinstance(value, bool):
        return value
    return str(value or "").strip().lower() in {"1", "true", "yes", "y", "pass"}


def short_cell(value, limit=220):
    text = str(value or "").replace("\r", " ").replace("\n", " ").strip()
    if len(text) <= limit:
        return text
    return text[: max(0, limit - 3)] + "..."


def recycle_control_mode_from_result_row(row):
    mode = str(row.get("recycle_control_mode") or "").strip()
    if mode:
        return mode
    source = str(row.get("source") or "").lower()
    if "bounded" in source:
        return "bounded_nonnegative_makeup_control"
    if "fixed_makeup" in source:
        return "fixed_fresh_makeup_diagnostic"
    if truthy_cell(row.get("has_recycle_calculator")):
        return "calculator_inventory_control"
    return "unknown_or_fixed_makeup"


def _positive_numeric_cell(value, eps=1e-12):
    number = safe_float(value)
    return number is not None and abs(number) > eps


def _any_positive_numeric_mapping(mapping):
    if not isinstance(mapping, dict):
        return False
    return any(_positive_numeric_cell(value) for value in mapping.values())


def process_case_has_required_outputs(case):
    case = case or {}
    explicit = case.get("required_outputs_complete")
    if explicit not in (None, ""):
        return truthy_cell(explicit)

    has_probe_flags = (
        case.get("duty_signal_available") not in (None, "")
        or case.get("stream_signal_available") not in (None, "")
    )
    if has_probe_flags:
        return truthy_cell(case.get("duty_signal_available")) and truthy_cell(case.get("stream_signal_available"))

    duty_probe = case.get("duty_probe_values")
    stream_probe = case.get("stream_probe_values")
    if isinstance(duty_probe, dict) or isinstance(stream_probe, dict):
        return _any_positive_numeric_mapping(duty_probe) and _any_positive_numeric_mapping(stream_probe)

    duty_signal = any(
        _positive_numeric_cell(case.get(key))
        for key in (
            "Qreb_1",
            "Qreb_2",
            "total_reboiler_duty",
            "total_reboiler_duty_kW",
            "objective_energy",
        )
    )
    economic_signal = _positive_numeric_cell(case.get("TAC")) or _positive_numeric_cell(case.get("decision_score"))
    product_signal = any(
        key.startswith("x_") or key.startswith("recovery_")
        for key, value in case.items()
        if _positive_numeric_cell(value)
    )
    return bool(duty_signal and (economic_signal or product_signal))


def process_case_required_outputs_missing(case):
    case = case or {}
    explicit = case.get("required_outputs_complete")
    if explicit not in (None, ""):
        return not truthy_cell(explicit)

    text = " ".join(str(case.get(key) or "") for key in (
        "error_message",
        "status",
        "convergence_status",
    )).lower()
    if "required_outputs_missing" in text:
        return True

    pass_like = (
        str(case.get("pass_or_fail") or "").upper() == "PASS"
        or truthy_cell(case.get("feasible"))
        or truthy_cell(case.get("converged"))
        or case.get("status") in {"optimization_case_pass", "optimization_case_feasible", "optimization_case_converged"}
    )
    return bool(pass_like and not process_case_has_required_outputs(case))


def result_row_required_outputs_missing(row):
    row = row or {}
    if truthy_cell(row.get("legacy_required_outputs_missing")):
        return True
    return process_case_required_outputs_missing(row)


def result_row_aspen_run_pass(row):
    row = row or {}
    for key in ("aspen_run_pass_or_fail", "aspen_status", "run_status", "pass_or_fail"):
        value = str(row.get(key) or "").strip().upper()
        if value:
            return value == "PASS"
    return False


def result_row_is_pass(row):
    if result_row_required_outputs_missing(row):
        return False
    return (
        result_row_aspen_run_pass(row)
        or row.get("status") == "optimization_case_pass"
    )


def result_row_is_exact_c1_closed_loop_pass(row):
    trusted_value = row.get("trusted_as_optimization_pass")
    trusted = True if trusted_value in (None, "") else truthy_cell(trusted_value)
    return (
        trusted
        and truthy_cell(row.get("closed_loop_recycle"))
        and recycle_control_mode_from_result_row(row) == "calculator_inventory_control"
        and result_row_is_pass(row)
    )


def aspen_closed_loop_recycle_diagnosis(rows, min_failed_cases=6):
    rows = rows or []
    case_rows = [row for row in rows if row.get("source_type") == "aspen_nsga2_checkpoint_case"]
    closed_loop_rows = [row for row in case_rows if truthy_cell(row.get("closed_loop_recycle"))]
    pass_like_rows = [
        row for row in closed_loop_rows
        if result_row_is_pass(row)
    ]
    pass_rows = [
        row for row in closed_loop_rows
        if result_row_is_exact_c1_closed_loop_pass(row)
    ]
    diagnostic_pass_rows = [
        row for row in pass_like_rows
        if row not in pass_rows
    ]
    open_loop_pass_rows = [
        row for row in case_rows
        if not truthy_cell(row.get("closed_loop_recycle"))
        and (
            str(row.get("pass_or_fail") or "").upper() == "PASS"
            or row.get("status") == "optimization_case_pass"
        )
    ]
    zero_build_rows = [row for row in rows if row.get("source_type") == "zero_build_aspen_report"]
    closed_loop_zero_build_rows = [row for row in zero_build_rows if truthy_cell(row.get("closed_loop_recycle"))]
    closed_loop_zero_build_validation_rows = [
        row for row in closed_loop_zero_build_rows
        if str(row.get("pass_or_fail") or "").upper() == "PASS"
    ]

    failed_rows = [row for row in closed_loop_rows if row not in pass_like_rows]
    required_outputs_missing_rows = [
        row for row in closed_loop_rows
        if result_row_required_outputs_missing(row)
    ]
    def error_text(row):
        return " ".join(str(row.get(key) or "") for key in (
            "error_message",
            "convergence_status",
            "status",
            "pass_or_fail",
            "constraint_violation",
            "stdout_tail",
            "stderr_tail",
        )).upper()

    max_iter_rows = [
        row for row in failed_rows
        if (
            "EXCEEDED MAXIMUM NUMBER OF ITERATIONS" in error_text(row)
            or "EXCEEDED_MAXIMUM_ITERATIONS" in error_text(row)
            or "MAXIMUM NUMBER OF ITERATIONS" in error_text(row)
        )
    ]
    crash_rows = [
        row for row in failed_rows
        if truthy_cell(row.get("aspen_crash_dump")) or bool(str(row.get("dump_files") or "").strip())
    ]
    timeout_rows = [row for row in failed_rows if truthy_cell(row.get("timed_out"))]
    rpc_failure_rows = [
        row for row in failed_rows
        if (
            "-2147023170" in error_text(row)
            or "REMOTE PROCEDURE CALL" in error_text(row)
            or "远程过程调用失败" in str(row.get("error_message") or "")
            or "PYWINTYPES.COM_ERROR" in error_text(row)
        )
    ]
    nonconverged_rows = [
        row for row in failed_rows
        if not truthy_cell(row.get("converged")) or "NOT CONVERGED" in error_text(row)
    ]
    control_mode_counts = {}
    for row in closed_loop_rows:
        mode = recycle_control_mode_from_result_row(row)
        control_mode_counts[mode] = control_mode_counts.get(mode, 0) + 1
    calculator_rows = [
        row for row in closed_loop_rows
        if recycle_control_mode_from_result_row(row) == "calculator_inventory_control"
    ]
    bounded_rows = [
        row for row in closed_loop_rows
        if recycle_control_mode_from_result_row(row) == "bounded_nonnegative_makeup_control"
    ]
    untested_repair_strategies = []
    if closed_loop_rows and not calculator_rows:
        untested_repair_strategies.append("calculator_inventory_control")
    if closed_loop_rows and calculator_rows and not bounded_rows:
        untested_repair_strategies.append("bounded_nonnegative_makeup_control")

    if pass_rows:
        status = "closed_loop_pass_available"
        severity = "ok"
        dominant_failure = ""
        recommended_action = "continue_to_ranking_and_reporting"
        stop_before_more = False
        blocker = ""
    elif not closed_loop_rows:
        status = "closed_loop_not_attempted"
        severity = "pending"
        dominant_failure = ""
        recommended_action = "run_zero_build_and_first_closed_loop_optimization_campaign"
        stop_before_more = False
        blocker = "No closed-loop Aspen optimization case has been imported."
    elif required_outputs_missing_rows:
        status = "closed_loop_required_outputs_missing"
        severity = "blocked"
        dominant_failure = "required_outputs_missing"
        recommended_action = "repair_aspen_model_outputs_before_more_optimization"
        stop_before_more = True
        blocker = (
            "Aspen Run2 returned no hard error, but required duty/stream outputs were missing or zero. "
            "These cases are not trusted for process optimization."
        )
    else:
        if rpc_failure_rows and len(rpc_failure_rows) >= max(len(crash_rows), len(max_iter_rows), len(timeout_rows), 1):
            dominant_failure = "aspen_com_rpc_failure"
        elif crash_rows and len(crash_rows) >= max(len(max_iter_rows), len(timeout_rows)):
            dominant_failure = "aspen_fatal_dump"
        elif timeout_rows and len(timeout_rows) >= len(max_iter_rows):
            dominant_failure = "case_timeout"
        elif max_iter_rows:
            dominant_failure = "recycle_convergence_max_iterations"
        elif nonconverged_rows:
            dominant_failure = "closed_loop_not_converged"
        else:
            dominant_failure = "closed_loop_no_pass"
        if untested_repair_strategies:
            status = "closed_loop_recycle_repair_strategy_ready"
            severity = "repair_ready"
            stop_before_more = False
            recommended_action = "run_calculator_inventory_repair_campaign"
            blocker = (
                "Closed-loop Aspen cases failed with the current recycle control. "
                "The Agent still has an untried repair strategy: {}."
            ).format(", ".join(untested_repair_strategies))
        elif diagnostic_pass_rows:
            status = "closed_loop_diagnostic_pass_only"
            severity = "blocked"
            stop_before_more = True
            recommended_action = "convert_diagnostic_case_to_exact_c1_calculator_closed_loop"
            blocker = (
                "A diagnostic closed-loop case passed, but no exact C-1 calculator inventory-control "
                "case passed. Full-flow completion still requires FLOW=target-recycle."
            )
        elif dominant_failure == "aspen_com_rpc_failure":
            status = "closed_loop_aspen_rpc_failure"
            severity = "blocked"
            stop_before_more = True
            recommended_action = "retry_aspen_repair_probe_without_fast_inplace"
            blocker = (
                "Aspen COM/RPC failed while opening or controlling Aspen. "
                "Retry the repair probe with isolated case archives instead of a reused fast-inplace session."
            )
        else:
            repeated_failure = len(closed_loop_rows) >= int(min_failed_cases or 1)
            stop_before_more = bool(repeated_failure and (max_iter_rows or crash_rows or timeout_rows or nonconverged_rows))
            status = "closed_loop_recycle_repair_required" if stop_before_more else "closed_loop_trials_no_pass"
            severity = "blocked" if stop_before_more else "needs_more_evidence"
            recommended_action = (
                "repair_closed_loop_recycle_solver_before_more_optimization"
                if stop_before_more
                else "run_limited_closed_loop_repair_campaign"
            )
            blocker = (
                "Closed-loop Aspen cases were generated, but none passed. Dominant failure: {}."
                .format(dominant_failure)
            )

    sample_rows = closed_loop_rows[-5:]
    return {
        "status": status,
        "severity": severity,
        "full_flow_completion_allowed": bool(pass_rows),
        "agent_should_stop_before_more_optimization": bool(stop_before_more),
        "dominant_failure": dominant_failure,
        "recommended_agent_action": recommended_action,
        "blocker": blocker,
        "minimum_failed_cases_before_block": int(min_failed_cases or 1),
        "closed_loop_case_count": len(closed_loop_rows),
        "closed_loop_pass_case_count": len(pass_rows),
        "diagnostic_closed_loop_pass_case_count": len(diagnostic_pass_rows),
        "closed_loop_failed_case_count": len(failed_rows),
        "closed_loop_zero_build_case_count": len(closed_loop_zero_build_rows),
        "closed_loop_zero_build_validation_case_count": len(closed_loop_zero_build_validation_rows),
        "open_loop_pass_case_count": len(open_loop_pass_rows),
        "required_outputs_missing_count": len(required_outputs_missing_rows),
        "max_iteration_failure_count": len(max_iter_rows),
        "aspen_crash_dump_count": len(crash_rows),
        "aspen_rpc_failure_count": len(rpc_failure_rows),
        "timeout_case_count": len(timeout_rows),
        "nonconverged_case_count": len(nonconverged_rows),
        "recycle_control_mode_counts": control_mode_counts,
        "calculator_inventory_case_count": len(calculator_rows),
        "bounded_nonnegative_makeup_case_count": len(bounded_rows),
        "untested_repair_strategies": untested_repair_strategies,
        "failure_policy": {
            "requires_closed_loop_optimization_pass": True,
            "open_loop_allowed_for_initialization_only": True,
            "reject_open_loop_as_full_flow": True,
        },
        "last_closed_loop_case_id": (closed_loop_rows[-1].get("case_id") if closed_loop_rows else ""),
        "sample_failed_cases": [
            {
                "case_id": row.get("case_id", ""),
                "source": row.get("source", ""),
                "pass_or_fail": row.get("pass_or_fail", ""),
                "converged": row.get("converged", ""),
                "aspen_crash_dump": row.get("aspen_crash_dump", ""),
                "timed_out": row.get("timed_out", ""),
                "convergence_status": row.get("convergence_status", ""),
                "error_message": short_cell(row.get("error_message")),
            }
            for row in sample_rows
            if str(row.get("pass_or_fail") or "").upper() != "PASS"
        ],
    }


def aspen_spec_topology_from_path(path):
    try:
        value = str(path or "").strip()
        if not value:
            return aspen_spec_topology_metadata({})
        return aspen_spec_topology_metadata(read_json_default(generated_path(value, "aspen_case_spec"), {}))
    except Exception:
        return aspen_spec_topology_metadata({})


def aspen_input_deck_topology_from_path(path):
    try:
        value = str(path or "").strip()
        if not value:
            return aspen_spec_topology_metadata({})
        text = generated_path(value, "aspen_input_deck").read_text(encoding="utf-8", errors="ignore").upper()
    except Exception:
        return aspen_spec_topology_metadata({})
    has_recycle_mixer = "BLOCK B3 IN=C1 S3 OUT=C2" in text or (
        "BLOCK B3" in text and "IN=C1 S3" in text and "OUT=C2" in text
    )
    closed_loop = has_recycle_mixer
    return {
        "process_topology_mode": "closed_loop_solvent_recycle" if closed_loop else "open_loop_or_unclassified",
        "recycle_control_mode": "calculator_inventory_control" if "CALCULATOR" in text else ("fixed_fresh_makeup_diagnostic" if has_recycle_mixer else ""),
        "closed_loop_recycle": closed_loop,
        "has_recycle_mixer": has_recycle_mixer,
        "has_recycle_calculator": "CALCULATOR" in text,
        "recycle_stream": "S3" if has_recycle_mixer or "STREAM=S3" in text else "",
        "makeup_stream": "C1" if has_recycle_mixer or "STREAM=C1" in text else "",
        "topology_source": "input_deck",
        "topology_source_readable": True,
    }


def topology_from_result_payload(payload):
    payload = payload or {}
    explicit = payload.get("topology") or {}
    direct_topology_keys = {
        "process_topology_mode",
        "recycle_control_mode",
        "closed_loop_recycle",
        "has_recycle_mixer",
        "has_recycle_calculator",
        "recycle_stream",
        "makeup_stream",
    }
    if any(key in payload for key in direct_topology_keys):
        return {
            "process_topology_mode": payload.get("process_topology_mode") or ("closed_loop_solvent_recycle" if truthy_cell(payload.get("closed_loop_recycle")) else "open_loop_or_unclassified"),
            "recycle_control_mode": payload.get("recycle_control_mode") or (
                "calculator_inventory_control"
                if truthy_cell(payload.get("has_recycle_calculator"))
                else ("fixed_fresh_makeup_diagnostic" if "fixed_makeup" in str(payload.get("process_topology_mode") or "").lower() else "")
            ),
            "closed_loop_recycle": truthy_cell(payload.get("closed_loop_recycle")),
            "has_recycle_mixer": truthy_cell(payload.get("has_recycle_mixer")),
            "has_recycle_calculator": truthy_cell(payload.get("has_recycle_calculator")),
            "recycle_stream": payload.get("recycle_stream") or "",
            "makeup_stream": payload.get("makeup_stream") or "",
        }
    if explicit:
        return aspen_spec_topology_metadata({
            "process_topology_mode": explicit.get("process_topology_mode"),
            "recycle_control_mode": explicit.get("recycle_control_mode"),
            "blocks": [{"id": "B3"}] if truthy_cell(explicit.get("has_recycle_mixer")) else [],
            "calculator": {
                "recycle_stream": explicit.get("recycle_stream") or "",
                "makeup_stream": explicit.get("makeup_stream") or "",
            } if truthy_cell(explicit.get("has_recycle_calculator")) else {},
        })
    if payload.get("source") == "zero_build_pass_seed_checkpoint":
        return aspen_spec_topology_metadata({})
    deck_topology = aspen_input_deck_topology_from_path(payload.get("input_deck"))
    if deck_topology.get("topology_source_readable"):
        return deck_topology
    return aspen_spec_topology_from_path(payload.get("spec"))


def serializable_optimizer_bounds(bounds):
    payload = {}
    if not isinstance(bounds, dict):
        return payload
    for key in ASPEN_OPTIMIZER_BOUND_KEYS:
        value = bounds.get(key)
        if value is None:
            continue
        if isinstance(value, tuple):
            payload[key] = list(value)
        elif isinstance(value, list):
            payload[key] = value
        else:
            payload[key] = value
    profile = bounds.get("profile") or bounds.get("bounds_profile")
    if profile:
        payload["profile"] = profile
    return payload


def optimizer_bounds_for_dashboard_profile(profile, current_bounds=None):
    profile_key = str(profile or "publication_safe").strip().lower()
    template = ASPEN_OPTIMIZER_BOUNDS_PROFILES.get(profile_key) or ASPEN_OPTIMIZER_BOUNDS_PROFILES["publication_safe"]
    bounds = serializable_optimizer_bounds(template)
    current = serializable_optimizer_bounds(current_bounds or {})
    for key in ("D1", "D2"):
        current_value = current.get(key)
        if isinstance(current_value, list) and len(current_value) >= 2:
            bounds[key] = current_value
    bounds["profile"] = profile_key
    return bounds


def optimizer_bounds_delta_rows(current_bounds, recommended_bounds):
    current = serializable_optimizer_bounds(current_bounds or {})
    recommended = serializable_optimizer_bounds(recommended_bounds or {})
    rows = []
    for key in ASPEN_OPTIMIZER_BOUND_KEYS:
        before = current.get(key)
        after = recommended.get(key)
        if before is None and after is None:
            continue
        rows.append({
            "variable": key,
            "current": before,
            "recommended": after,
            "changed": before != after,
        })
    return rows


def collect_aspen_optimization_rows(search_roots):
    rows = []
    seen_dirs = set()
    for root in search_roots:
        if not root.exists():
            continue
        run_dirs = []
        for pattern in (
            "aspen_optimization_once*",
            "aspen_optimization_bounds_adjustment*",
            "aspen_repair_probe_autopilot_*",
            "aspen_db_identity_fix_test*",
        ):
            run_dirs.extend(sorted(root.glob(pattern)))
        for run_dir in run_dirs:
            if not run_dir.is_dir():
                continue
            resolved_run_dir = str(run_dir.resolve())
            if resolved_run_dir in seen_dirs:
                continue
            seen_dirs.add(resolved_run_dir)
            run_report = run_dir / "full_agent_decision_report.json"
            if run_report.exists():
                payload = read_json_default(run_report, {})
                for index, run in enumerate(payload.get("optimization_runs") or []):
                    returncode = run.get("returncode")
                    rows.append({
                        "source_type": "aspen_nsga2_run_report",
                        "source_file": str(run_report.resolve()),
                        "optimization_dir": resolved_run_dir,
                        "run_index": index + 1,
                        "aspen_component_id": run.get("aspen_component_id", ""),
                        "returncode": returncode,
                        "status": "optimization_run_success" if returncode == 0 else "optimization_run_failed",
                        "stdout_tail": (run.get("stdout_tail") or "")[-1000:],
                        "stderr_tail": (run.get("stderr_tail") or "")[-1000:],
                        "generated_at": iso_from_timestamp(run_report.stat().st_mtime),
                    })
            optimization_dir = run_dir / "optimization"
            optimizer_report_path = run_dir / "generic_aspen_once_optimizer.report.json"
            optimizer_report = read_json_default(optimizer_report_path, {}) if optimizer_report_path.exists() else {}
            multi_objective_report = optimizer_report.get("multi_objective_optimization") or {}
            convergence_report = optimizer_report.get("convergence") or {}
            boundary_report = optimizer_report.get("boundary_diagnosis") or {}
            range_policy_report = optimizer_report.get("range_policy") or {}
            current_bounds_report = serializable_optimizer_bounds(
                boundary_report.get("bounds") or range_policy_report.get("bounds") or {}
            )
            recommended_profile_report = str(boundary_report.get("recommended_bounds_profile") or "").strip()
            recommended_bounds_report = optimizer_bounds_for_dashboard_profile(
                recommended_profile_report or "publication_safe",
                current_bounds_report,
            ) if recommended_profile_report or boundary_report.get("agent_should_adjust_bounds") else {}
            bounds_delta_report = optimizer_bounds_delta_rows(current_bounds_report, recommended_bounds_report)
            for checkpoint_path in sorted(optimization_dir.glob("*.checkpoint.jsonl")):
                case_rows = read_jsonl_records(checkpoint_path)
                workbook_path = checkpoint_path.with_name(checkpoint_path.name.replace(".checkpoint.jsonl", ".xlsx"))
                pareto_csv_path = checkpoint_path.with_name(checkpoint_path.name.replace(".checkpoint.jsonl", ".pareto_front.csv"))
                topsis_csv_path = checkpoint_path.with_name(checkpoint_path.name.replace(".checkpoint.jsonl", ".topsis_ranking.csv"))
                trusted_case_rows = [
                    row for row in case_rows
                    if not process_case_required_outputs_missing(row)
                ]
                passed = [
                    row for row in trusted_case_rows
                    if str(row.get("pass_or_fail") or "").upper() == "PASS"
                ]
                feasible = [
                    row for row in trusted_case_rows
                    if truthy_cell(row.get("feasible"))
                ]
                required_missing_count = len(case_rows) - len(trusted_case_rows)
                best_tac_case = min(
                    (row for row in trusted_case_rows if safe_float(row.get("TAC")) is not None),
                    key=lambda row: safe_float(row.get("TAC"), math.inf),
                    default={},
                )
                rows.append({
                    "source_type": "aspen_nsga2_checkpoint",
                    "source_file": str(checkpoint_path.resolve()),
                    "workbook": str(workbook_path.resolve()) if workbook_path.exists() else "",
                    "optimization_dir": resolved_run_dir,
                    "status": (
                        "optimization_checkpoint_pass"
                        if passed
                        else (
                            "optimization_checkpoint_required_outputs_missing"
                            if required_missing_count
                            else "optimization_checkpoint_available"
                        )
                    ),
                    "case_count": len(case_rows),
                    "feasible_case_count": len(feasible),
                    "pass_case_count": len(passed),
                    "required_outputs_missing_count": required_missing_count,
                    "best_case_id": best_tac_case.get("case_id", ""),
                    "best_TAC": best_tac_case.get("TAC", ""),
                    "multi_objective_status": multi_objective_report.get("status", ""),
                    "multi_objective_feasible_case_count": multi_objective_report.get("feasible_case_count", ""),
                    "multi_objective_converged": convergence_report.get("converged", multi_objective_report.get("converged", "")),
                    "multi_objective_convergence_status": convergence_report.get("status", multi_objective_report.get("convergence_status", "")),
                    "multi_objective_convergence_stop_reason": convergence_report.get("stop_reason", multi_objective_report.get("convergence_stop_reason", "")),
                    "multi_objective_convergence_stagnant_generations": convergence_report.get("stagnant_generations", ""),
                    "optimization_bounds_profile": range_policy_report.get("bounds_profile", boundary_report.get("bounds_profile", "")),
                    "optimization_current_bounds": current_bounds_report,
                    "optimization_boundary_status": boundary_report.get("status", ""),
                    "optimization_boundary_recommended_action": boundary_report.get("recommended_action", ""),
                    "optimization_boundary_recommended_bounds_profile": boundary_report.get("recommended_bounds_profile", ""),
                    "optimization_recommended_bounds": recommended_bounds_report,
                    "optimization_bounds_delta_rows": bounds_delta_report,
                    "optimization_boundary_hits": boundary_report.get("selected_boundary_hits", []),
                    "optimization_pareto_boundary_hit_counts": boundary_report.get("pareto_boundary_hit_counts", {}),
                    "optimization_agent_should_adjust_bounds": boundary_report.get("agent_should_adjust_bounds", ""),
                    "pareto_front_case_count": multi_objective_report.get("pareto_front_case_count", ""),
                    "topsis_best_case_id": multi_objective_report.get("topsis_best_case_id", ""),
                    "topsis_best_score": multi_objective_report.get("topsis_best_score", ""),
                    "pareto_front_csv": str(pareto_csv_path.resolve()) if pareto_csv_path.exists() else "",
                    "topsis_ranking_csv": str(topsis_csv_path.resolve()) if topsis_csv_path.exists() else "",
                    "generated_at": iso_from_timestamp(checkpoint_path.stat().st_mtime),
                })
                if workbook_path.exists():
                    rows.append({
                        "source_type": "aspen_nsga2_workbook",
                        "source_file": str(workbook_path.resolve()),
                        "checkpoint": str(checkpoint_path.resolve()),
                        "optimization_dir": resolved_run_dir,
                        "status": "optimization_workbook_available",
                        "case_count": len(case_rows),
                        "generated_at": iso_from_timestamp(workbook_path.stat().st_mtime),
                    })
                for case in case_rows:
                    topology = topology_from_result_payload(case)
                    pass_or_fail = str(case.get("pass_or_fail") or "").upper()
                    aspen_run_pass = (
                        str(case.get("aspen_run_pass_or_fail") or "").upper() == "PASS"
                        or pass_or_fail == "PASS"
                    )
                    formal_multi_objective_pass = (
                        truthy_cell(case.get("multi_objective_feasible"))
                        or (
                            truthy_cell(case.get("feasible"))
                            and all(
                                safe_float(case.get(name)) is not None
                                for name in (
                                    "objective_carbon_emission",
                                    "objective_TAC",
                                    "objective_recovery_loss",
                                )
                            )
                        )
                    )
                    required_outputs_complete = process_case_has_required_outputs(case)
                    required_outputs_missing = process_case_required_outputs_missing(case)
                    recycle_control_mode = (
                        topology.get("recycle_control_mode", case.get("recycle_control_mode", ""))
                        or ""
                    )
                    final_closed_loop_pass = (
                        aspen_run_pass
                        and not required_outputs_missing
                        and truthy_cell(topology.get("closed_loop_recycle"))
                        and str(recycle_control_mode).strip() == "calculator_inventory_control"
                    )
                    untrusted_seed = (
                        case.get("source") == "zero_build_pass_seed_checkpoint"
                        and not truthy_cell(topology.get("closed_loop_recycle"))
                    )
                    if untrusted_seed:
                        status = "optimization_case_untrusted_seed"
                        pass_or_fail = "UNTRUSTED"
                        final_closed_loop_pass = False
                    elif required_outputs_missing:
                        status = "optimization_case_required_outputs_missing"
                        pass_or_fail = "FAIL"
                        final_closed_loop_pass = False
                    elif final_closed_loop_pass and formal_multi_objective_pass:
                        status = "optimization_case_pass"
                    elif final_closed_loop_pass or aspen_run_pass:
                        status = "optimization_case_diagnostic_pass"
                    elif truthy_cell(case.get("feasible")):
                        status = "optimization_case_feasible"
                    elif truthy_cell(case.get("converged")):
                        status = "optimization_case_converged"
                    else:
                        status = "optimization_case_result"
                    error_message = case.get("error_message", "")
                    if required_outputs_missing and "required_outputs_missing" not in str(error_message).lower():
                        error_message = short_cell(
                            "{}; required_outputs_missing_legacy_import: old checkpoint PASS lacks required duty/stream outputs.".format(
                                str(error_message or "").strip()
                            ).strip("; "),
                            500,
                        )
                    row = {
                        "source_type": "aspen_nsga2_checkpoint_case",
                        "source_file": str(checkpoint_path.resolve()),
                        "workbook": str(workbook_path.resolve()) if workbook_path.exists() else "",
                        "optimization_dir": resolved_run_dir,
                        "status": status,
                        "case_id": case.get("case_id", ""),
                        "generation": case.get("generation", ""),
                        "source": case.get("source", ""),
                        "process_topology_mode": topology.get("process_topology_mode", ""),
                        "recycle_control_mode": recycle_control_mode,
                        "closed_loop_recycle": topology.get("closed_loop_recycle", False),
                        "has_recycle_mixer": topology.get("has_recycle_mixer", False),
                        "has_recycle_calculator": topology.get("has_recycle_calculator", False),
                        "recycle_stream": topology.get("recycle_stream", ""),
                        "makeup_stream": topology.get("makeup_stream", ""),
                        "solvent_name": case.get("solvent_name", ""),
                        "aspen_component_id": case.get("aspen_component_id", ""),
                        "converged": False if required_outputs_missing else case.get("converged", ""),
                        "feasible": False if required_outputs_missing else case.get("feasible", ""),
                        "pass_or_fail": pass_or_fail,
                        "aspen_run_pass": bool(aspen_run_pass),
                        "formal_multi_objective_pass": bool(formal_multi_objective_pass),
                        "trusted_as_optimization_pass": bool(final_closed_loop_pass),
                        "final_closed_loop_pass": bool(final_closed_loop_pass),
                        "diagnostic_only_pass": bool((final_closed_loop_pass or aspen_run_pass) and not formal_multi_objective_pass),
                        "required_outputs_complete": bool(required_outputs_complete),
                        "legacy_required_outputs_missing": bool(
                            required_outputs_missing and case.get("required_outputs_complete") in (None, "")
                        ),
                        "duty_signal_available": case.get("duty_signal_available", ""),
                        "stream_signal_available": case.get("stream_signal_available", ""),
                        "constraint_violation": case.get("constraint_violation", ""),
                        "aspen_crash_dump": case.get("aspen_crash_dump", ""),
                        "dump_files": case.get("dump_files", ""),
                        "timed_out": case.get("timed_out", ""),
                        "timeout_seconds": case.get("timeout_seconds", ""),
                        "Qreb_1": case.get("Qreb_1", ""),
                        "Qreb_2": case.get("Qreb_2", ""),
                        "TAC": "" if required_outputs_missing else case.get("TAC", ""),
                        "total_reboiler_duty": case.get("total_reboiler_duty", ""),
                        "total_reboiler_duty_kW": case.get("total_reboiler_duty_kW", ""),
                        "energy_cost": case.get("energy_cost", ""),
                        "reboiler_steam_duty_gj_per_year": case.get("reboiler_steam_duty_gj_per_year", ""),
                        "carbon_emission_kg_per_year": case.get("carbon_emission_kg_per_year", ""),
                        "carbon_emission_ton_per_year": case.get("carbon_emission_ton_per_year", ""),
                        "carbon_emission_basis": case.get("carbon_emission_basis", ""),
                        "solvent_loss_total": case.get("solvent_loss_total", ""),
                        "decision_score": "" if required_outputs_missing else case.get("decision_score", ""),
                        "multi_objective_feasible": False if required_outputs_missing else case.get("multi_objective_feasible", ""),
                        "objective_carbon_emission": "" if required_outputs_missing else case.get("objective_carbon_emission", ""),
                        "objective_recovery_loss": "" if required_outputs_missing else case.get("objective_recovery_loss", ""),
                        "objective_TAC": "" if required_outputs_missing else case.get("objective_TAC", ""),
                        "objective_energy_cost": "" if required_outputs_missing else case.get("objective_energy_cost", ""),
                        "objective_solvent_loss": "" if required_outputs_missing else case.get("objective_solvent_loss", ""),
                        "objective_energy": "" if required_outputs_missing else case.get("objective_energy", ""),
                        "objective_solvent_circulation": case.get("objective_solvent_circulation", ""),
                        "objective_column_stages": case.get("objective_column_stages", ""),
                        "objective_makeup": case.get("objective_makeup", ""),
                        "solvent_flow_kmol_hr": case.get("solvent_flow_kmol_hr", ""),
                        "solvent_to_feed_ratio": case.get("solvent_to_feed_ratio", ""),
                        "column_stage_total": case.get("column_stage_total", ""),
                        "reflux_ratio_sum": case.get("reflux_ratio_sum", ""),
                        "pareto_front": case.get("pareto_front", ""),
                        "pareto_rank": case.get("pareto_rank", ""),
                        "topsis_score": case.get("topsis_score", ""),
                        "topsis_rank": case.get("topsis_rank", ""),
                        "error_message": error_message,
                        "convergence_status": case.get("convergence_status", ""),
                        "generated_at": iso_from_timestamp(checkpoint_path.stat().st_mtime),
                    }
                    for key, value in case.items():
                        if key.startswith("x_") or key.startswith("recovery_") or key in {"SF", "makeup_flow", "RR1", "D1", "RR2", "D2", "N1", "NF1", "NS1", "N2", "NF2"}:
                            row[key] = value
                    rows.append(row)
    return rows


def process_result_rows(report, paths):
    rows = []
    plan_path = paths.get("aspen_build_plan_json")
    package_path = None
    if plan_path:
        package_path = Path(plan_path).parent
        aspen_dir = package_path / "aspen_generated"
        if aspen_dir.exists():
            for path in sorted(aspen_dir.glob("*.autoverify.json")) + sorted(aspen_dir.glob("*report.json")):
                payload = read_json_default(path, {})
                smoke = payload.get("smoke_result") or {}
                static = payload.get("static_verification") or {}
                topology = topology_from_result_payload(payload)
                row = {
                    "source_type": "zero_build_aspen_report",
                    "source_file": str(path.resolve()),
                    "generated_at": payload.get("generated_at"),
                    "generated_bkp": payload.get("generated_bkp", ""),
                    "input_deck": payload.get("input_deck", ""),
                    "process_topology_mode": topology.get("process_topology_mode", ""),
                    "recycle_control_mode": topology.get("recycle_control_mode", ""),
                    "closed_loop_recycle": topology.get("closed_loop_recycle", False),
                    "has_recycle_mixer": topology.get("has_recycle_mixer", False),
                    "has_recycle_calculator": topology.get("has_recycle_calculator", False),
                    "recycle_stream": topology.get("recycle_stream", ""),
                    "makeup_stream": topology.get("makeup_stream", ""),
                    "static_verification_passed": static.get("passed"),
                    "status": "static_verified" if static.get("passed") else "generated_or_failed",
                }
                if smoke:
                    row.update({
                        "case_id": smoke.get("case_id"),
                        "solvent_name": smoke.get("solvent_name"),
                        "converged": smoke.get("converged"),
                        "pass_or_fail": smoke.get("pass_or_fail"),
                        "TAC": smoke.get("TAC"),
                        "total_reboiler_duty": smoke.get("total_reboiler_duty"),
                        "decision_score": smoke.get("decision_score"),
                        "error_message": smoke.get("error_message"),
                    })
                    row["status"] = "zero_build_validation_pass" if str(smoke.get("pass_or_fail") or "").upper() == "PASS" else "zero_build_validation_result_available"
                rows.append(row)
    rows.extend(collect_aspen_optimization_rows(aspen_optimization_search_roots(report, package_path)))
    return rows


def import_process_results(report, report_path):
    paths = report.get("research_task_package_paths") or {}
    package_path = generated_path(paths.get("aspen_build_plan_json"), "aspen_build_plan_json").parent
    rows = process_result_rows(report, paths)
    process_csv = package_path / "process_result_import.csv"
    summary_json = package_path / "process_result_import_summary.json"
    write_csv_file(process_csv, rows)
    imported_statuses = {
        "optimization_case_pass",
        "optimization_case_diagnostic_pass",
        "optimization_case_feasible",
        "optimization_case_converged",
        "optimization_case_result",
        "optimization_case_required_outputs_missing",
    }
    imported_count = sum(1 for row in rows if row.get("status") in imported_statuses)
    optimization_checkpoint_rows = [row for row in rows if row.get("source_type") == "aspen_nsga2_checkpoint"]
    optimization_case_rows = [row for row in rows if row.get("source_type") == "aspen_nsga2_checkpoint_case"]
    optimization_pass_rows = [row for row in optimization_case_rows if row.get("status") == "optimization_case_pass"]
    diagnostic_pass_rows = [row for row in optimization_case_rows if row.get("status") == "optimization_case_diagnostic_pass"]
    closed_loop_case_rows = [row for row in optimization_case_rows if truthy_cell(row.get("closed_loop_recycle"))]
    closed_loop_pass_rows = [
        row for row in closed_loop_case_rows
        if result_row_is_exact_c1_closed_loop_pass(row)
    ]
    multi_objective_rows = [row for row in optimization_case_rows if truthy_cell(row.get("multi_objective_feasible"))]
    pareto_rows = [row for row in multi_objective_rows if truthy_cell(row.get("pareto_front"))]
    topsis_ranked_rows = [
        row for row in multi_objective_rows
        if safe_float(row.get("topsis_rank")) is not None
    ]
    topsis_best_row = min(
        topsis_ranked_rows,
        key=lambda row: safe_float(row.get("topsis_rank"), math.inf),
        default={},
    )
    max_optimization_generation = max(
        [int(safe_float(row.get("generation"), 0) or 0) for row in optimization_case_rows] + [0]
    )
    multi_objective_complete = bool(
        len(multi_objective_rows) >= 2
        and len(pareto_rows) >= 1
        and topsis_best_row
        and max_optimization_generation >= 1
    )
    multi_objective_converged = any(
        truthy_cell(row.get("multi_objective_converged"))
        for row in optimization_checkpoint_rows
    )
    convergence_statuses = sorted(set(
        str(row.get("multi_objective_convergence_status") or "").strip()
        for row in optimization_checkpoint_rows
        if str(row.get("multi_objective_convergence_status") or "").strip()
    ))
    convergence_stop_reasons = sorted(set(
        str(row.get("multi_objective_convergence_stop_reason") or "").strip()
        for row in optimization_checkpoint_rows
        if str(row.get("multi_objective_convergence_stop_reason") or "").strip()
    ))
    latest_boundary_row = next(
        (
            row for row in reversed(optimization_checkpoint_rows)
            if str(row.get("optimization_boundary_status") or "").strip()
            or str(row.get("optimization_bounds_profile") or "").strip()
        ),
        {},
    )
    campaign = optimization_campaign_defaults(report.get("separation_task") or {})
    publication_budget_complete = bool(
        multi_objective_complete
        and multi_objective_converged
        and len(optimization_case_rows) >= int(campaign.get("minimum_case_count") or 0)
        and len(multi_objective_rows) >= int(campaign.get("minimum_feasible_case_count") or 0)
        and max_optimization_generation >= int(campaign.get("minimum_generations") or 0)
    )
    best_pass_row = min(
        (row for row in optimization_pass_rows if safe_float(row.get("TAC")) is not None),
        key=lambda row: safe_float(row.get("TAC"), math.inf),
        default={},
    )
    best_closed_loop_pass_row = min(
        (row for row in closed_loop_pass_rows if safe_float(row.get("TAC")) is not None),
        key=lambda row: safe_float(row.get("TAC"), math.inf),
        default={},
    )
    best_tac_row = min(
        (row for row in optimization_case_rows if safe_float(row.get("TAC")) is not None),
        key=lambda row: safe_float(row.get("TAC"), math.inf),
        default={},
    )
    best_display_row = best_pass_row or best_tac_row
    status_counts = {}
    for row in rows:
        status = row.get("status") or "unknown"
        status_counts[status] = status_counts.get(status, 0) + 1
    closed_loop_diagnosis = aspen_closed_loop_recycle_diagnosis(rows)
    summary = {
        "status": "imported_process_results_available" if imported_count else "no_completed_process_results_found",
        "process_result_count": imported_count,
        "row_count": len(rows),
        "optimization_case_count": len(optimization_case_rows),
        "optimization_pass_case_count": len(optimization_pass_rows),
        "diagnostic_optimization_pass_case_count": len(diagnostic_pass_rows),
        "closed_loop_optimization_case_count": len(closed_loop_case_rows),
        "closed_loop_optimization_pass_case_count": len(closed_loop_pass_rows),
        "multi_objective_optimization_complete": multi_objective_complete,
        "multi_objective_converged": multi_objective_converged,
        "multi_objective_convergence_statuses": convergence_statuses,
        "multi_objective_convergence_stop_reasons": convergence_stop_reasons,
        "optimization_campaign_mode": campaign.get("mode", ""),
        "optimization_campaign_population_size": campaign.get("population_size", ""),
        "optimization_campaign_max_generations": campaign.get("max_generations", campaign.get("generations", "")),
        "optimization_campaign_minimum_generations": campaign.get("minimum_generations", ""),
        "optimization_campaign_convergence_patience": campaign.get("convergence_patience", ""),
        "optimization_campaign_required_case_count": campaign.get("minimum_case_count", ""),
        "optimization_campaign_required_feasible_case_count": campaign.get("minimum_feasible_case_count", ""),
        "optimization_bounds_profile": latest_boundary_row.get("optimization_bounds_profile", ""),
        "optimization_current_bounds": latest_boundary_row.get("optimization_current_bounds", {}),
        "optimization_boundary_status": latest_boundary_row.get("optimization_boundary_status", ""),
        "optimization_boundary_recommended_action": latest_boundary_row.get("optimization_boundary_recommended_action", ""),
        "optimization_boundary_recommended_bounds_profile": latest_boundary_row.get("optimization_boundary_recommended_bounds_profile", ""),
        "optimization_recommended_bounds": latest_boundary_row.get("optimization_recommended_bounds", {}),
        "optimization_bounds_delta_rows": latest_boundary_row.get("optimization_bounds_delta_rows", []),
        "optimization_boundary_hits": latest_boundary_row.get("optimization_boundary_hits", []),
        "optimization_pareto_boundary_hit_counts": latest_boundary_row.get("optimization_pareto_boundary_hit_counts", {}),
        "optimization_agent_should_adjust_bounds": latest_boundary_row.get("optimization_agent_should_adjust_bounds", ""),
        "publication_optimization_budget_complete": publication_budget_complete,
        "multi_objective_feasible_case_count": len(multi_objective_rows),
        "pareto_front_case_count": len(pareto_rows),
        "max_optimization_generation": max_optimization_generation,
        "topsis_best_case_id": topsis_best_row.get("case_id", ""),
        "topsis_best_score": topsis_best_row.get("topsis_score", ""),
        "topsis_best_carbon_emission": topsis_best_row.get("carbon_emission_ton_per_year", ""),
        "topsis_best_TAC": topsis_best_row.get("TAC", ""),
        "topsis_best_recovery_loss": topsis_best_row.get("objective_recovery_loss", ""),
        "topsis_best_recovery": topsis_best_row.get("target_recovery", ""),
        "topsis_best_solvent_flow_kmol_hr": topsis_best_row.get("solvent_flow_kmol_hr", ""),
        "topsis_best_column_stage_total": topsis_best_row.get("column_stage_total", ""),
        "best_optimization_case_id": best_display_row.get("case_id", ""),
        "best_optimization_TAC": best_display_row.get("TAC", ""),
        "best_pass_optimization_case_id": best_pass_row.get("case_id", ""),
        "best_pass_optimization_TAC": best_pass_row.get("TAC", ""),
        "best_closed_loop_optimization_case_id": best_closed_loop_pass_row.get("case_id", ""),
        "best_closed_loop_optimization_TAC": best_closed_loop_pass_row.get("TAC", ""),
        "best_available_case_passed": bool(best_pass_row),
        "best_closed_loop_case_passed": bool(best_closed_loop_pass_row),
        "closed_loop_recycle_diagnosis": closed_loop_diagnosis,
        "closed_loop_completion_allowed": bool(closed_loop_diagnosis.get("full_flow_completion_allowed")),
        "closed_loop_repair_required": bool(closed_loop_diagnosis.get("agent_should_stop_before_more_optimization")),
        "closed_loop_dominant_failure": closed_loop_diagnosis.get("dominant_failure", ""),
        "status_counts": status_counts,
        "process_result_import_csv": str(process_csv.resolve()),
        "generated_at": iso_from_timestamp(time.time()),
    }
    try:
        progress_report = dict(report)
        progress_report["research_task_package_paths"] = paths
        progress_report["process_result_import"] = summary
        progress = aspen_progress_summary(progress_report)
        for key in (
            "optimization_solvent_alignment_status",
            "optimization_solvent_alignment_message",
            "mainline_multi_objective_converged",
            "mainline_aspen_optimization_required",
            "optimization_evidence_scope",
            "selected_molecular_solvent_code",
            "selected_molecular_solvent_label",
            "topsis_best_solvent_name",
            "topsis_best_aspen_component_id",
        ):
            if key in progress:
                summary[key] = progress.get(key)
    except Exception:
        pass
    write_json_file(summary_json, summary)
    paths["process_result_import_csv"] = str(process_csv.resolve())
    paths["process_result_import_summary_json"] = str(summary_json.resolve())
    report["research_task_package_paths"] = paths
    report["process_result_import"] = summary
    counts = dict(report.get("counts") or {})
    counts["imported_process_result_records"] = imported_count
    report["counts"] = counts
    report.pop("system_research_brief", None)
    report.pop("agent_stage_trace", None)
    report.pop("next_action_plan", None)
    report = enrich_trial_report_payload(report)
    refresh_system_frontend_artifacts(report, report_path)
    write_json_file(report_path, report)
    return report, summary


def import_generated_gromacs_assets(report, report_path):
    paths = report.get("research_task_package_paths") or {}
    mol_dir_value = paths.get("molecular_inputs_dir")
    if not mol_dir_value:
        return report, {"status": "no_molecular_inputs_dir", "imported_asset_count": 0}
    mol_dir = generated_path(mol_dir_value, "molecular_inputs_dir")
    generated_dir = mol_dir / "gromacs_assets_generated"
    if not generated_dir.exists():
        return report, {"status": "no_generated_assets_dir", "imported_asset_count": 0}
    asset_codes = set()
    for path in generated_dir.glob("*.*"):
        if path.suffix.lower() in {".gro", ".itp", ".top", ".chg", ".mol2", ".fch"}:
            asset_codes.add(path.stem)
    imported = []
    for asset_code in sorted(asset_codes):
        gro = generated_dir / "{}.gro".format(asset_code)
        itp = generated_dir / "{}.itp".format(asset_code)
        if not gro.exists() or not itp.exists():
            continue
        target_dir = GROMACS_GENERATED_ASSET_LIBRARY / asset_code
        target_dir.mkdir(parents=True, exist_ok=True)
        copied = []
        for ext in (".gro", ".itp", ".top", ".chg", ".mol2", ".fch"):
            src = generated_dir / "{}{}".format(asset_code, ext)
            if src.exists():
                dst = target_dir / src.name
                shutil.copy2(src, dst)
                copied.append(str(dst.resolve()))
        imported.append({
            "asset_code": asset_code,
            "asset_dir": str(target_dir.resolve()),
            "copied_files": copied,
        })
    if imported:
        report.pop("system_research_brief", None)
        report.pop("agent_stage_trace", None)
        report.pop("next_action_plan", None)
        output_dir = Path(report.get("output_dir") or Path(report_path).parent)
        report["research_task_package_paths"] = export_research_task_package(report, output_dir)
        report = enrich_trial_report_payload(report)
        write_json_file(report_path, report)
    summary = {
        "status": "generated_assets_imported" if imported else "no_complete_generated_assets",
        "imported_asset_count": len(imported),
        "assets": imported,
        "asset_library": str(GROMACS_GENERATED_ASSET_LIBRARY.resolve()),
        "generated_at": iso_from_timestamp(time.time()),
    }
    return report, summary


def build_system_frontend_manifest(report, paths, output_dir):
    task = report.get("separation_task") or {}
    task_id = task.get("task_id") or trial_slug(
        task.get("component_a", "A"),
        task.get("component_b", "B"),
        task.get("target_product", "B"),
    )
    report_path = report.get("json_report") or str((Path(output_dir) / "full_agent_decision_report.json").resolve())
    return {
        "manifest_version": 1,
        "frontend_template_version": SYSTEM_FRONTEND_TEMPLATE_VERSION,
        "generated_at": iso_from_timestamp(time.time()),
        "created_by": "binary-separation-agent",
        "task_id": task_id,
        "report_path": str(Path(report_path).resolve()),
        "task": task,
        "counts": report.get("counts") or {},
        "diagnosis": report.get("separation_diagnosis") or {},
        "route_decision": report.get("route_decision") or {},
        "agent_stage_trace": report.get("agent_stage_trace") or [],
        "next_action_plan": report.get("next_action_plan") or [],
        "molecular_evidence_import": report.get("molecular_evidence_import") or {},
        "process_result_import": report.get("process_result_import") or {},
        "aspen_progress": aspen_progress_summary(report),
        "agent_execution_step_plan": report.get("agent_execution_step_plan") or {},
        "paths": paths,
        "frontend_policy": {
            "mode": "agent_generated_per_system_frontend",
            "note": "The central dashboard only embeds this generated frontend; it does not hand-code per-system workbench logic.",
            "linked_molecular_dashboard": MOLECULAR_DASHBOARD_URL if task.get("compatible_verified_case") else "",
        },
    }


