def system_workbench_status_payload(report, report_path):
    report = enrich_trial_report_payload(report)
    task = report.get("separation_task") or {}
    paths = report.get("research_task_package_paths") or {}
    if (
        not paths
        or not system_frontend_current(paths)
    ):
        output_dir = Path(report.get("output_dir") or Path(report_path).parent)
        paths = export_research_task_package(report, output_dir)
        report["research_task_package_paths"] = paths
        write_json_file(report_path, report)
    aspen_plan = {}
    if paths.get("aspen_build_plan_json") and Path(paths["aspen_build_plan_json"]).exists():
        try:
            plan = read_json(paths["aspen_build_plan_json"])
            aspen_plan = {
                "status": plan.get("status"),
                "can_generate_bkp_now": bool(plan.get("can_generate_bkp_now")),
                "boundary": friendly_aspen_boundary(plan, task),
                "selected_property_method": plan.get("selected_property_method"),
            }
        except Exception as exc:
            aspen_plan = {"status": "read_failed", "boundary": str(exc), "can_generate_bkp_now": False}
    try:
        figure_manifest = build_figure_manifest(report_path, report=report, force=False)
    except Exception as exc:
        figure_manifest = {"figure_count": 0, "figures": [], "errors": [{"error": str(exc)}]}
    execution = orchestrator_execution_status(report_path)
    aspen_progress_payload = execution.get("aspen_progress") or report.get("aspen_progress") or aspen_progress_summary(report)
    if str(execution.get("status") or "").strip().lower() == "stale_after_reboot" and not execution.get("running"):
        aspen_progress_payload = dict(aspen_progress_payload or {})
        aspen_progress_payload.update({
            "status": "stale_after_reboot",
            "stage_status": "stale",
            "headline": execution.get("message") or aspen_progress_payload.get("headline") or "",
            "aspen_process_active": False,
            "stale_running_state": True,
        })
    return {
        "generated_at": iso_from_timestamp(time.time()),
        "task": report.get("separation_task") or {},
        "counts": report.get("counts") or {},
        "molecular_dashboard_online": molecular_dashboard_online(),
        "molecular_dashboard_url": MOLECULAR_DASHBOARD_URL,
        "queues": {
            "gaussian_jobs": csv_status_summary(paths.get("gaussian_jobs_csv")) if paths.get("gaussian_jobs_csv") else {},
            "nci_vmd_jobs": csv_status_summary(paths.get("nci_vmd_jobs_csv")) if paths.get("nci_vmd_jobs_csv") else {},
            "nci_vmd_results": csv_status_summary(paths.get("nci_vmd_results_csv")) if paths.get("nci_vmd_results_csv") else {},
            "gromacs_jobs": csv_status_summary(paths.get("gromacs_jobs_csv")) if paths.get("gromacs_jobs_csv") else {},
            "molecular_evidence_import": csv_status_summary(paths.get("molecular_evidence_import_csv")) if paths.get("molecular_evidence_import_csv") else {},
            "molecular_task_queue": csv_status_summary(paths.get("molecular_task_queue_csv")) if paths.get("molecular_task_queue_csv") else {},
            "aspen_initial_cases": csv_status_summary(paths.get("aspen_initial_cases_csv"), "case_status") if paths.get("aspen_initial_cases_csv") else {},
            "process_result_import": csv_status_summary(paths.get("process_result_import_csv")) if paths.get("process_result_import_csv") else {},
        },
        "molecular_evidence_import": report.get("molecular_evidence_import") or {},
        "nci_vmd_images": nci_vmd_image_gallery(paths),
        "process_result_import": report.get("process_result_import") or {},
        "aspen_progress": aspen_progress_payload,
        "agent_execution_step_plan": report.get("agent_execution_step_plan") or {},
        "queue_progress": molecular_queue_progress(paths),
        "figures": figure_manifest,
        "aspen_plan": aspen_plan,
        "execution": execution,
        "live_progress": execution.get("live_progress") or {},
        "paths": paths,
    }


def serve_system_workbench_html(report_path):
    report, path = load_action_report(report_path)
    paths = report.get("research_task_package_paths") or {}
    html_path = paths.get("system_frontend_html")
    if not html_path or not system_frontend_current(paths):
        output_dir = Path(report.get("output_dir") or path.parent)
        report["research_task_package_paths"] = export_research_task_package(report, output_dir)
        write_json_file(path, report)
        html_path = report["research_task_package_paths"].get("system_frontend_html")
    if not html_path or not Path(html_path).exists():
        raise FileNotFoundError("system frontend was not generated")
    return Path(html_path).read_text(encoding="utf-8")


def tail_text_file(path, limit=4000):
    if not path:
        return ""
    path = Path(path)
    if not path.exists() or not path.is_file():
        return ""
    data = path.read_bytes()
    if len(data) > limit:
        data = data[-limit:]
    return decode_subprocess_output(data)


def generated_path(value, label):
    if not value:
        raise ValueError("{} path is missing".format(label))
    path = Path(value).resolve()
    root = (BASE_DIR / "generated").resolve()
    if not str(path).lower().startswith(str(root).lower()):
        raise ValueError("{} path is outside generated workspace: {}".format(label, path))
    return path


def executable_path(name):
    name = clean_text_arg(name, "", max_len=260)
    if not name:
        return ""
    candidate = Path(name)
    if candidate.exists():
        return str(candidate.resolve())
    return shutil.which(name) or ""


def first_existing_path(candidates):
    for candidate in candidates:
        if not candidate:
            continue
        try:
            path = Path(candidate)
            if path.exists():
                return str(path.resolve())
        except Exception:
            continue
    return ""


def discover_gaussian_executable():
    explicit = (
        os.environ.get("GAUSSIAN_EXE")
        or os.environ.get("G16_EXE")
        or os.environ.get("G09_EXE")
        or ""
    )
    found = executable_path(explicit) if explicit else ""
    if found:
        return found
    found = executable_path("g16") or executable_path("g09")
    if found:
        return found
    return first_existing_path([
        r"C:\G16W\g16.exe",
        r"C:\G16W\G16W.exe",
        r"D:\g16w\g16.exe",
        r"D:\G16W\g16.exe",
        r"D:\g09w\g09.exe",
        r"C:\g09w\g09.exe",
    ])


def discover_formchk_executable(gaussian_exe=""):
    explicit = os.environ.get("FORMCHK_EXE") or ""
    found = executable_path(explicit) if explicit else ""
