def powershell_path():
    return shutil.which("powershell.exe") or shutil.which("powershell") or shutil.which("pwsh.exe") or shutil.which("pwsh") or ""


def process_pid_is_live(pid):
    try:
        pid = int(pid or 0)
    except Exception:
        pid = 0
    if pid <= 0:
        return False
    if pid == os.getpid():
        return True
    if os.name != "nt":
        try:
            os.kill(pid, 0)
            return True
        except Exception:
            return False
    ps = powershell_path()
    if not ps:
        return False
    try:
        result = subprocess.run(
            [
                ps,
                "-NoProfile",
                "-Command",
                "if (Get-CimInstance Win32_Process -Filter \"ProcessId={}\" -ErrorAction SilentlyContinue) {{ '1' }} else {{ '0' }}".format(pid),
            ],
            cwd=str(BASE_DIR),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=5,
            check=False,
        )
        return decode_subprocess_output(result.stdout or b"").strip() == "1"
    except Exception:
        return False


def kill_process_tree(pid):
    try:
        pid = int(pid)
    except Exception:
        return {"pid": pid, "status": "invalid_pid"}
    if pid <= 0 or pid == os.getpid():
        return {"pid": pid, "status": "skipped_self_or_invalid"}
    command = ["taskkill", "/PID", str(pid), "/T", "/F"] if os.name == "nt" else ["kill", "-TERM", str(pid)]
    try:
        result = subprocess.run(
            command,
            cwd=str(BASE_DIR),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=10,
            check=False,
        )
        cim_result = None
        if os.name == "nt":
            ps = powershell_path()
            if ps:
                try:
                    cim_result = subprocess.run(
                        [
                            ps,
                            "-NoProfile",
                            "-Command",
                            (
                                "$p=Get-CimInstance Win32_Process -Filter \"ProcessId={}\" "
                                "-ErrorAction SilentlyContinue; "
                                "if($p){{ (Invoke-CimMethod -InputObject $p -MethodName Terminate "
                                "-Arguments @{{Reason=0}}).ReturnValue }} else {{ 0 }}"
                            ).format(pid),
                        ],
                        cwd=str(BASE_DIR),
                        stdout=subprocess.PIPE,
                        stderr=subprocess.PIPE,
                        timeout=10,
                        check=False,
                    )
                except Exception:
                    cim_result = None
        cim_stdout = decode_subprocess_output((cim_result.stdout if cim_result else b"") or b"") if cim_result else ""
        cim_stderr = decode_subprocess_output((cim_result.stderr if cim_result else b"") or b"") if cim_result else ""
        cim_ok = bool(cim_result and cim_result.returncode == 0 and re.search(r"\b0\b", cim_stdout or "0"))
        return {
            "pid": pid,
            "status": "stopped" if result.returncode == 0 or cim_ok else "stop_failed",
            "returncode": result.returncode,
            "stdout": decode_subprocess_output(result.stdout or b"")[-800:],
            "stderr": decode_subprocess_output(result.stderr or b"")[-800:],
            "cim_returncode": cim_result.returncode if cim_result else "",
            "cim_stdout": cim_stdout[-800:],
            "cim_stderr": cim_stderr[-800:],
        }
    except Exception as exc:
        return {"pid": pid, "status": "stop_failed", "error": str(exc)}


def process_snapshot_with_command_lines():
    ps = powershell_path()
    if not ps:
        return []
    script = (
        "$procs = Get-CimInstance Win32_Process | "
        "Where-Object { "
        "$_.Name -match '^(python|pythonw|g16|g09|formchk|gmx|gmx_mpi|mdrun|multiwfn|sobtop|vmd|AspenPlus|apmain|apwn|AspenProperties|l\\d+)\\.exe$' "
        "-or $_.CommandLine -match 'agent_full_flow_runner.py|generic_aspen_once_optimizer.py|agent_screening_autopilot_runner.py|full_agent_dashboard.py' "
        "} | "
        "ForEach-Object { $_ | Select-Object ProcessId,ParentProcessId,Name,CommandLine }; "
        "$procs | ConvertTo-Json -Compress -Depth 3"
    )
    try:
        result = subprocess.run(
            [ps, "-NoProfile", "-Command", script],
            cwd=str(BASE_DIR),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=6,
            check=False,
        )
        if result.returncode != 0:
            return []
        raw = decode_subprocess_output(result.stdout or b"").strip()
        if not raw:
            return []
        data = json.loads(raw)
        if isinstance(data, dict):
            return [data]
        if isinstance(data, list):
            return data
    except Exception:
        return []
    return []


def report_process_needles(report=None, report_path=None):
    needles = {str(BASE_DIR.resolve()).lower()}
    if report_path:
        try:
            path = Path(report_path).resolve()
            needles.add(str(path).lower())
            needles.add(str(path.parent).lower())
        except Exception:
            pass
    paths = (report or {}).get("research_task_package_paths") or {}
    for value in paths.values():
        if not isinstance(value, str) or not value.strip():
            continue
        try:
            path = Path(value).resolve()
        except Exception:
            continue
        needles.add(str(path).lower())
        try:
            needles.add(str(path.parent).lower())
        except Exception:
            pass
    return {needle for needle in needles if needle}


def report_owned_active_processes(report=None, report_path=None):
    base_token = str(BASE_DIR.resolve()).replace("/", "\\").lower()
    needles = {
        needle.replace("/", "\\").lower()
        for needle in report_process_needles(report, report_path)
        if needle and needle.replace("/", "\\").lower() != base_token
    }
    if not needles:
        return []
    script_markers = (
        "run_gaussian_jobs.ps1",
        "run_nci_vmd_queue.ps1",
        "run_sobtop_parameterization.ps1",
        "run_gromacs_queue.ps1",
        "agent_screening_autopilot_runner.py",
        "agent_full_flow_runner.py",
        "zero_build_aspen_agent.py",
        "aspen_relative_volatility_flash.py",
        "generic_aspen_once_optimizer.py",
        "full_screening_agent.py",
        "aspen_case_worker.py",
    )
    likely_names = {
        "powershell.exe", "pwsh.exe", "python.exe", "py.exe",
        "g16.exe", "g09.exe", "formchk.exe",
        "multiwfn.exe", "sobtop.exe", "vmd.exe",
        "gmx.exe", "gmx_mpi.exe", "mdrun.exe",
        "apwn.exe", "apmain.exe", "aspenplus.exe", "aspenhysys.exe",
        "hysys.exe", "aspenproperties.exe", "aspenplusgui.exe",
    }
    rows = []
    self_pid = os.getpid()
    for row in process_snapshot_with_command_lines():
        try:
            pid = int(row.get("ProcessId") or 0)
        except Exception:
            continue
        if pid <= 0 or pid == self_pid:
            continue
        name = str(row.get("Name") or "").lower()
        command_line = str(row.get("CommandLine") or "")
        command_norm = command_line.replace("/", "\\").lower()
        if not command_norm:
            continue
        path_match = any(needle and needle in command_norm for needle in needles)
        if not path_match:
            continue
        script_match = any(marker in command_norm for marker in script_markers)
        link_match = bool(re.match(r"^l\d+\.exe$", name))
        if not (script_match or name in likely_names or link_match):
            continue
        rows.append({
            "pid": pid,
            "name": row.get("Name") or "",
            "command_line": command_line[:320],
        })
    return rows


def stop_agent_compute_processes(report=None, report_path=None, include_global_quantum=False, include_global_aspen=False):
    needles = report_process_needles(report, report_path)
    script_markers = (
        "run_gaussian_jobs.ps1",
        "run_nci_vmd_queue.ps1",
        "run_sobtop_parameterization.ps1",
        "run_gromacs_queue.ps1",
        "agent_screening_autopilot_runner.py",
        "agent_full_flow_runner.py",
        "zero_build_aspen_agent.py",
        "aspen_relative_volatility_flash.py",
        "generic_aspen_once_optimizer.py",
        "full_screening_agent.py",
        "aspen_case_worker.py",
    )
    likely_names = {
        "powershell.exe", "pwsh.exe", "python.exe", "py.exe",
        "g16.exe", "g09.exe", "formchk.exe",
        "multiwfn.exe", "sobtop.exe", "vmd.exe",
        "gmx.exe", "gmx_mpi.exe", "mdrun.exe",
    }
    quantum_names = {"g16.exe", "g09.exe", "formchk.exe", "multiwfn.exe", "sobtop.exe", "vmd.exe"}
    aspen_names = {"apwn.exe", "apmain.exe", "aspenplus.exe", "aspenhysys.exe", "hysys.exe", "aspenproperties.exe", "aspenplusgui.exe"}
    killed = []
    seen = set()
    self_pid = os.getpid()
    for row in process_snapshot_with_command_lines():
        try:
            pid = int(row.get("ProcessId") or 0)
        except Exception:
            continue
        if pid <= 0 or pid == self_pid or pid in seen:
            continue
        name = str(row.get("Name") or "").lower()
        cmd = str(row.get("CommandLine") or "").lower()
        if not name and not cmd:
            continue
        path_match = any(needle and needle in cmd for needle in needles)
        script_match = any(marker in cmd for marker in script_markers)
        link_match = bool(re.match(r"^l\d+\.exe$", name))
        should_stop = False
        if script_match and path_match:
            should_stop = True
        elif path_match and (name in likely_names or link_match or name in aspen_names):
            should_stop = True
        elif include_global_quantum and (name in quantum_names or link_match or name in {"gmx.exe", "gmx_mpi.exe", "mdrun.exe"}):
            should_stop = True
        elif include_global_aspen and name in aspen_names:
            should_stop = True
        if not should_stop:
            continue
        seen.add(pid)
        result = kill_process_tree(pid)
        result.update({"name": row.get("Name") or "", "command_line": row.get("CommandLine") or ""})
        killed.append(result)
    PROCESS_SNAPSHOT_CACHE["timestamp"] = 0.0
    return killed


def cancel_orchestrator_execution(report=None, report_path=None):
    global ORCH_EXEC_PROCESS
    task = (report or {}).get("separation_task") or {}
    with ORCH_EXEC_LOCK:
        process = ORCH_EXEC_PROCESS
        state = dict(ORCH_EXEC_STATE)
        running = bool(process is not None and process.poll() is None)
        ORCH_EXEC_PROCESS = None
        if running:
            ORCH_EXEC_STATE.update({
                "running": False,
                "finished_at": iso_from_timestamp(time.time()),
                "returncode": -15,
                "stdout_tail": tail_text_file(ORCH_EXEC_STATE.get("stdout_log")),
                "stderr_tail": tail_text_file(ORCH_EXEC_STATE.get("stderr_log")),
                "message": "用户已停止当前 Agent 后台执行；已有输出文件保留。",
            })
    stopped = []
    if running:
        stopped.append(kill_process_tree(process.pid))
    active_molecular = False
    if report:
        try:
            active_molecular = report_has_active_molecular_job(report)
        except Exception:
            active_molecular = False
    action_name = str(state.get("action") or "").lower()
    aspen_context = False
    try:
        status_payload = autopilot_status_payload_for_report(report_path) if report_path else {}
        aspen_progress = aspen_progress_summary(report) if report else {}
        stage_text = " ".join([
            str(action_name or ""),
            str(state.get("current_stage") or ""),
            str(status_payload.get("current_stage") or ""),
            str(status_payload.get("status") or ""),
            str(aspen_progress.get("status") or ""),
        ]).lower()
        aspen_context = (
            "aspen" in stage_text
            or bool(aspen_progress.get("aspen_process_active"))
            or bool(aspen_progress.get("aspen_optimizer_active"))
        )
    except Exception:
        aspen_context = "aspen" in action_name or "relative_volatility" in action_name
    stopped.extend(stop_agent_compute_processes(
        report=report,
        report_path=report_path,
        include_global_quantum=bool(running or active_molecular),
        include_global_aspen=bool(aspen_context or (running and ("aspen" in action_name or "relative_volatility" in action_name))),
    ))
    stopped_ok = sum(1 for item in stopped if item.get("status") == "stopped")
    if stopped_ok or running:
        message = "已停止当前 Agent 后台执行和匹配到的外部计算进程；已有 Gaussian/GROMACS/Aspen 输出文件都保留。"
    elif active_molecular:
        message = "已收到停止请求；当前没有检测到仍存活的外部计算进程，近期输出文件会保留为已停止/待诊断状态。"
    else:
        message = "当前没有检测到需要停止的 Agent 后台长计算。"
    with ORCH_EXEC_LOCK:
        if not ORCH_EXEC_STATE.get("running"):
            ORCH_EXEC_STATE.update({
                "running": False,
                "action": "stop_current_execution",
                "task_id": task.get("task_id") or state.get("task_id") or "",
                "finished_at": iso_from_timestamp(time.time()),
                "returncode": -15 if stopped_ok or running else 0,
                "pid": None,
                "stdout_tail": tail_text_file(ORCH_EXEC_STATE.get("stdout_log")),
                "stderr_tail": tail_text_file(ORCH_EXEC_STATE.get("stderr_log")),
                "message": message,
            })
    return {
        "returncode": 0,
        "status": "cancelled" if stopped_ok or running or active_molecular else "idle",
        "action": "stop_current_execution",
        "task_id": task.get("task_id") or state.get("task_id") or "",
        "message": message,
        "stopped_processes": stopped,
        "stopped_process_count": stopped_ok,
        "report_path": str(report_path or ""),
    }


def set_orchestrator_blocked(action, task_id, message, extra=None):
    payload = {
        "returncode": 0,
        "status": "blocked",
        "action": action,
        "task_id": task_id,
        "message": message,
    }
    if extra:
        payload.update(extra)
    with ORCH_EXEC_LOCK:
        ORCH_EXEC_STATE.update({
            "running": False,
            "action": action,
            "task_id": task_id or "",
            "started_at": iso_from_timestamp(time.time()),
            "finished_at": iso_from_timestamp(time.time()),
            "returncode": None,
            "pid": None,
            "command": [],
            "cwd": "",
            "stdout_log": "",
            "stderr_log": "",
            "stdout_tail": "",
            "stderr_tail": "",
            "message": message,
        })
    return payload


def monitor_orchestrator_process(process, stdout_log, stderr_log, message):
    global ORCH_EXEC_PROCESS
    returncode = process.wait()
    with ORCH_EXEC_LOCK:
        if ORCH_EXEC_PROCESS is process:
            ORCH_EXEC_STATE.update({
                "running": False,
                "finished_at": iso_from_timestamp(time.time()),
                "returncode": returncode,
                "stdout_tail": tail_text_file(stdout_log),
                "stderr_tail": tail_text_file(stderr_log),
                "message": "{}；进程已结束，returncode={}".format(message, returncode),
            })
            ORCH_EXEC_PROCESS = None


def current_aspen_processes():
    if os.name != "nt":
        return []
    command = [
        "powershell",
        "-NoProfile",
        "-Command",
        (
            "$ErrorActionPreference='SilentlyContinue'; "
            "Get-CimInstance Win32_Process | "
            "Where-Object { $_.Name -match '^(Apwn|APMain|AspenPlus|AspenProperties|AspenPlusGUI)\\.exe$' } | "
            "ForEach-Object { "
            "$gp=Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue; "
            "[pscustomobject]@{ProcessId=$_.ProcessId;Name=$_.Name;CommandLine=$_.CommandLine;"
            "CreationDate=$_.CreationDate;MainWindowTitle=$gp.MainWindowTitle} } | "
            "ConvertTo-Json -Compress"
        ),
    ]
    try:
        output = subprocess.check_output(command, stderr=subprocess.STDOUT, timeout=5)
        text = output.decode("utf-8", "replace").strip()
    except Exception as exc:
        return [{"probe_error": "{}: {}".format(exc.__class__.__name__, exc)}]
    if not text:
        return []
    try:
        data = json.loads(text)
    except Exception:
        return [{"probe_error": "invalid_process_json", "raw": text[:500]}]
    if isinstance(data, dict):
        data = [data]
    rows = []
    for row in data or []:
        name = str(row.get("Name") or "")
        command_line = str(row.get("CommandLine") or "")
        if ASPEN_PROCESS_NAME_PATTERN.search(name) or ASPEN_PROCESS_NAME_PATTERN.search(command_line):
            is_automation = bool(re.search(r"-(Automation|Embedding)\b", command_line, re.I))
            creation_date = str(row.get("CreationDate") or "")
            age_seconds = None
            match = re.match(r"^(\d{14})", creation_date)
            if match:
                try:
                    started = dt.datetime.strptime(match.group(1), "%Y%m%d%H%M%S").timestamp()
                    age_seconds = max(0.0, time.time() - started)
                except Exception:
                    age_seconds = None
            else:
                match = re.search(r"/Date\((\d+)\)/", creation_date)
                if match:
                    try:
                        raw_started = float(match.group(1))
                        if raw_started > 100000000000:
                            raw_started /= 1000.0
                        age_seconds = max(0.0, time.time() - raw_started)
                    except Exception:
                        age_seconds = None
            rows.append({
                "pid": row.get("ProcessId"),
                "name": name,
                "command_line": command_line[:260],
                "creation_date": creation_date,
                "main_window_title": str(row.get("MainWindowTitle") or ""),
                "is_automation": is_automation,
                "age_seconds": age_seconds,
            })
    return rows


def cleanup_safe_aspen_automation_orphans(process_limit=1, min_age_seconds=90, protect_pids=None, reason=""):
    protect = {int(pid) for pid in (protect_pids or []) if pid}
    rows = current_aspen_processes()
    automation = []
    for row in rows:
        try:
            pid = int(row.get("pid") or 0)
        except Exception:
            continue
        if pid <= 0 or pid in protect:
            continue
        name = str(row.get("name") or "").strip().lower()
        if name != "aspenplus.exe":
            continue
        if not row.get("is_automation"):
            continue
        if str(row.get("main_window_title") or "").strip():
            continue
        age_seconds = row.get("age_seconds")
        if age_seconds is not None and float(age_seconds) < float(min_age_seconds or 0):
            continue
        automation.append(row)

    active_automation = [
        row for row in rows
        if str(row.get("name") or "").strip().lower() == "aspenplus.exe" and row.get("is_automation")
    ]
    over_by = max(0, len(active_automation) - max(0, int(process_limit or 0)))
    candidates = sorted(
        automation,
        key=lambda row: (row.get("creation_date") or "", int(row.get("pid") or 0)),
    )
    to_stop = candidates[:over_by] if over_by else []
    stopped = []
    for row in to_stop:
        try:
            pid = int(row.get("pid") or 0)
        except Exception:
            continue
        if pid > 0:
            result = kill_process_tree(pid)
            result.update({
                "name": row.get("name") or "",
                "command_line": row.get("command_line") or "",
                "reason": reason or "aspen_automation_over_limit",
            })
            stopped.append(result)
    PROCESS_SNAPSHOT_CACHE["timestamp"] = 0.0
    remaining = current_aspen_processes()
    remaining_automation = [
        row for row in remaining
        if str(row.get("name") or "").strip().lower() == "aspenplus.exe" and row.get("is_automation")
    ]
    return {
        "timestamp": iso_from_timestamp(time.time()),
        "process_limit": int(process_limit or 0),
        "min_age_seconds": int(min_age_seconds or 0),
        "before_automation_count": len(active_automation),
        "candidate_count": len(candidates),
        "stopped_count": sum(1 for item in stopped if item.get("status") == "stopped"),
        "stopped": stopped,
        "after_automation_count": len(remaining_automation),
        "after_processes": remaining,
    }


def aspen_execution_guard(action, task_id):
    if action not in ASPEN_LONG_ACTIONS:
        return None
    rows = current_aspen_processes()
    probe_errors = [row for row in rows if row.get("probe_error")]
    if probe_errors:
        return set_orchestrator_blocked(
            action,
            task_id,
            "Aspen 后台监管失败，已阻止启动新的 Aspen 长计算，避免电脑卡死：{}".format(probe_errors[0].get("probe_error")),
            {"aspen_process_probe": rows},
        )
    active = [row for row in rows if row.get("pid")]
    active_instances = [
        row for row in active
        if str(row.get("name") or "").strip().lower() in ASPEN_INSTANCE_PROCESS_NAMES
    ]
    active_count = len(active_instances) or (1 if active else 0)
    if active_count >= ASPEN_MAX_PARALLEL_PROCESSES:
        cleanup_event = cleanup_safe_aspen_automation_orphans(
            process_limit=max(0, ASPEN_MAX_PARALLEL_PROCESSES - 1),
            min_age_seconds=90,
            reason="pre_aspen_launch_guard",
        )
        rows = current_aspen_processes()
        active = [row for row in rows if row.get("pid")]
        active_instances = [
            row for row in active
            if str(row.get("name") or "").strip().lower() in ASPEN_INSTANCE_PROCESS_NAMES
        ]
        active_count = len(active_instances) or (1 if active else 0)
        if active_count < ASPEN_MAX_PARALLEL_PROCESSES:
            return None
        return set_orchestrator_blocked(
            action,
            task_id,
            "检测到已有 {} 个 Aspen 实例；智能体已尝试清理无窗口 Aspen 自动化残留，但仍超过安全上限，已阻止启动新的 Aspen 长计算。".format(active_count),
            {
                "aspen_process_count": len(active),
                "aspen_instance_count": active_count,
                "aspen_process_limit": ASPEN_MAX_PARALLEL_PROCESSES,
                "aspen_processes": active,
                "aspen_cleanup_event": cleanup_event,
            },
        )
    return None


def start_orchestrator_process(action, task_id, command, cwd, log_dir, message):
    global ORCH_EXEC_PROCESS
    guard = aspen_execution_guard(action, task_id)
    if guard:
        return guard
    with ORCH_EXEC_LOCK:
        if ORCH_EXEC_PROCESS is not None and ORCH_EXEC_PROCESS.poll() is None:
            payload = dict(ORCH_EXEC_STATE)
            payload.update({
                "returncode": 0,
                "status": "blocked",
                "message": "已有后台执行正在运行，先等当前任务结束或查看日志。",
            })
            return payload

        log_dir = Path(log_dir)
        log_dir.mkdir(parents=True, exist_ok=True)
        token = "{}_{}".format(action, dt.datetime.now().strftime("%Y%m%d_%H%M%S"))
        stdout_log = log_dir / "{}.out.log".format(token)
        stderr_log = log_dir / "{}.err.log".format(token)
        creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        stdout_handle = stdout_log.open("ab")
        stderr_handle = stderr_log.open("ab")
        try:
            process = subprocess.Popen(
                command,
                cwd=str(cwd),
                stdout=stdout_handle,
                stderr=stderr_handle,
                creationflags=creationflags,
            )
        finally:
            stdout_handle.close()
            stderr_handle.close()

        ORCH_EXEC_PROCESS = process
        ORCH_EXEC_STATE.update({
            "running": True,
            "action": action,
            "task_id": task_id or "",
            "started_at": iso_from_timestamp(time.time()),
            "finished_at": None,
            "returncode": None,
            "pid": process.pid,
            "command": command,
            "cwd": str(Path(cwd).resolve()),
            "stdout_log": str(stdout_log.resolve()),
            "stderr_log": str(stderr_log.resolve()),
            "stdout_tail": "",
            "stderr_tail": "",
            "message": message,
            "post_run_import_done": False,
            "post_run_import_error": "",
        })
        threading.Thread(
            target=monitor_orchestrator_process,
            args=(process, stdout_log, stderr_log, message),
            daemon=True,
        ).start()
        payload = dict(ORCH_EXEC_STATE)
        payload.update({"returncode": 0, "status": "started"})
        return payload


def command_arg_value(command, option):
    if isinstance(command, str):
        items = command.split()
    else:
        items = [str(item) for item in (command or [])]
    for index in range(len(items) - 1, -1, -1):
        item = items[index]
        if item == option and index + 1 < len(items):
            return items[index + 1]
    return ""


def command_arg_int(command, option, default=0):
    value = command_arg_value(command, option)
    try:
        return int(str(value).strip())
    except Exception:
        return default


def alpha_progress_case_id(row):
    row = row or {}
    case_id = str(row.get("case_id") or row.get("CaseID") or row.get("case") or "").strip()
    if case_id:
        return case_id
    status = str(row.get("status") or "").strip().lower()
    if status == "base_binary_imported":
        return "BASE_BINARY"
    code = str(row.get("solvent_code") or row.get("code") or row.get("aspen_component_id") or "").strip()
    sf_ratio = str(row.get("sf_ratio") or row.get("SF") or row.get("s_f_ratio") or "").strip()
    if not code or not sf_ratio:
        return ""
    x_spec = str(row.get("x_overhead_liquid_spec") or row.get("x_lk") or "").strip()
    suffix = "_x{}".format(x_spec.replace(".", "p")) if x_spec else ""
    return "{}_sf{}{}".format(code, sf_ratio.replace(".", "p"), suffix)


def alpha_progress_case_key(row):
    row = row or {}
    case_id = alpha_progress_case_id(row)
    if case_id.upper().startswith("BASE"):
        return ("BASE", case_id.upper())
    token = alpha_progress_candidate_token(row)
    if not token:
        return ("CASE", case_id.upper()) if case_id else ("", "")
    sf_value = safe_float(row.get("sf_ratio") or row.get("SF") or row.get("s_f_ratio"))
    x_value = safe_float(
        row.get("x_overhead_liquid_spec")
        or row.get("x_lk")
        or row.get("x_overhead")
    )
    if sf_value is None or x_value is None:
        return ("CASE", case_id.upper()) if case_id else ("TOKEN", token)
    return ("POINT", token, round(float(sf_value), 6), round(float(x_value), 6))


def alpha_progress_number(value, digits=4):
    number = safe_float(value)
    if number is None:
        return ""
    return round(number, digits)


def alpha_progress_bool(value):
    return str(value).strip().lower() in {"1", "true", "yes", "y", "pass", "passed"}


def alpha_progress_candidate_token(row):
    return component_token((row or {}).get("solvent_code") or (row or {}).get("code") or (row or {}).get("aspen_component_id"))


def alpha_progress_candidate_tokens(rows, limit=0):
    tokens = []
    seen = set()
    for row in rows or []:
        token = alpha_progress_candidate_token(row)
        if not token or token in seen:
            continue
        seen.add(token)
        tokens.append(token)
        if limit and len(tokens) >= limit:
            break
    return tokens


def alpha_progress_filter_rows_by_tokens(rows, tokens, keep_without_token=False):
    token_set = {component_token(token) for token in (tokens or []) if component_token(token)}
    if not token_set:
        return list(rows or [])
    filtered = []
    for row in rows or []:
        token = alpha_progress_candidate_token(row)
        if token in token_set or (keep_without_token and not token):
            filtered.append(row)
    return filtered


def alpha_progress_dynamic_key_grid_count(report):
    task = (report or {}).get("separation_task") or {}
    roles = relative_volatility_role_summary(task, lookup_rows=(report or {}).get("online_component_info") or [])
    if roles.get("status") != "roles_identified":
        return 0
    paths = (report or {}).get("research_task_package_paths") or {}
    summary = (report or {}).get("relative_volatility_base_vle_scan_summary") or read_json_default(
        paths.get("relative_volatility_base_vle_scan_summary_json") or "",
        {},
    )
    if not summary or str(summary.get("status") or "").strip() == "base_vle_scan_missing":
        return 0

    frac_a, frac_b = parse_feed_fraction_pair(task)
    overhead_token = component_token(roles.get("alpha_overhead_component") or roles.get("alpha_overhead_token"))
    feed_x = frac_a if overhead_token == component_token(task.get("component_a")) else frac_b
    target_purity = safe_float(task.get("target_purity"), 0.99) or 0.99
    points = {}

    def add(value, zone):
        value = safe_float(value)
        if value is None:
            return
        value = max(0.001, min(0.999, float(value)))
        key = round(value, 4)
        if key not in points:
            points[key] = {"x": key, "composition_zone": zone}
        elif zone not in str(points[key].get("composition_zone") or ""):
            points[key]["composition_zone"] = "{}+{}".format(points[key].get("composition_zone"), zone)

    for delta in [0.0, -0.10, -0.05, 0.05, 0.10]:
        add((feed_x or 0.5) + delta, "feed_neighborhood")
    azeotrope_x = safe_float(summary.get("azeotrope_x_overhead_liquid"))
    hard_x = safe_float(summary.get("hardest_x_overhead_liquid"))
    if azeotrope_x is not None:
        for delta in [0.0, -0.10, -0.05, -0.02, 0.02, 0.05, 0.10]:
            add(azeotrope_x + delta, "azeotrope_neighborhood")
    elif hard_x is not None:
        for delta in [0.0, -0.10, -0.05, -0.02, 0.02, 0.05, 0.10]:
            add(hard_x + delta, "alpha_hard_neighborhood")
    if roles.get("target_product_position") == "overhead":
        for value in [0.90, 0.95, 0.99, target_purity]:
            add(value, "overhead_product_end")
    elif roles.get("target_product_position") == "bottom":
        for value in [0.001, 0.005, 0.01, 0.03, 0.05, max(0.001, 1.0 - target_purity)]:
            add(value, "bottom_product_end")
    ordered = [points[key] for key in sorted(points)]
    if len(ordered) > 14:
        critical = [
            point for point in ordered
            if any(token in point.get("composition_zone", "") for token in ["feed", "azeotrope", "alpha_hard"])
        ]
        ends = [point for point in ordered if "product_end" in point.get("composition_zone", "")]
        ordered = (critical + ends)[:14]
        ordered = sorted({round(point["x"], 4): point for point in ordered}.values(), key=lambda point: point["x"])
    return len(ordered)


def alpha_progress_expected_case_count(report, request_rows, completed_cases):
    grid_count = alpha_progress_dynamic_key_grid_count(report)
    if not grid_count:
        return 0
    sf_by_token = {}
    for row in request_rows or []:
        token = alpha_progress_candidate_token(row)
        sf = str(row.get("sf_ratio") or row.get("SF") or row.get("s_f_ratio") or "").strip()
        if token and sf:
            sf_by_token.setdefault(token, set()).add(sf)
    total = sum(len(values) * grid_count for values in sf_by_token.values())
    return max(total, len(completed_cases or []))


def alpha_progress_candidate(row, pool_by_code=None):
    if not row:
        return {}
    pool_by_code = pool_by_code or {}
    code = str(row.get("solvent_code") or row.get("code") or row.get("aspen_component_id") or "").strip()
    meta = pool_by_code.get(code.upper()) or {}
    name = str(row.get("solvent_name") or meta.get("name") or row.get("name") or "").strip()
    label = code
    if name:
        label = "{} / {}".format(code, name) if code else name
    status = str(row.get("status") or "").strip()
    pass_gate = row.get("pass_alpha_gate")
    trust_status, trust_reason = row_property_trust(row)
    return {
        "case_id": alpha_progress_case_id(row),
        "solvent_code": code,
        "solvent_name": name,
        "label": label,
        "sf_ratio": row.get("sf_ratio") or row.get("SF") or row.get("s_f_ratio") or "",
        "x_overhead_liquid_spec": alpha_progress_number(row.get("x_overhead_liquid_spec") or row.get("x_lk")),
        "x_overhead_liquid_actual": alpha_progress_number(row.get("alpha_match_x_overhead") or row.get("x_overhead")),
        "composition_zone": row.get("composition_zone") or "",
        "vle_scan_kind": row.get("vle_scan_kind") or "",
        "property_trust_status": trust_status,
        "property_trust_reason": trust_reason,
        "base_alpha_match_method": row.get("base_alpha_match_method") or "",
        "status": status,
        "property_method": row.get("property_method") or "",
        "alpha_definition": row.get("alpha_definition") or "",
        "alpha_0": alpha_progress_number(row.get("alpha_0") or row.get("alpha_0_proxy")),
        "alpha_s": alpha_progress_number(row.get("alpha_s") or row.get("alpha")),
        "i_alpha": alpha_progress_number(row.get("alpha_improvement") or row.get("i_alpha") or row.get("Ialpha")),
        "k_overhead": alpha_progress_number(row.get("k_overhead") or row.get("K_overhead")),
        "k_bottom": alpha_progress_number(row.get("k_bottom") or row.get("K_bottom")),
        "run_seconds": alpha_progress_number(row.get("run_seconds"), 2),
        "pass_alpha_gate": alpha_progress_bool(pass_gate),
        "pass_alpha_gate_raw": str(pass_gate if pass_gate is not None else "").strip(),
        "error_message": str(row.get("error_message") or "").strip(),
    }


def live_alpha_candidate_gate_summary(candidate_rows, scan_complete=False):
    valid = []
    for row in candidate_rows or []:
        i_alpha = safe_float(row.get("alpha_improvement") or row.get("i_alpha") or row.get("Ialpha"))
        if i_alpha is None:
            continue
        valid.append({
            "i_alpha": i_alpha,
            "sf_ratio": safe_float(row.get("sf_ratio") or row.get("SF")),
            "x_overhead_liquid_spec": safe_float(row.get("x_overhead_liquid_spec") or row.get("x_lk")),
            "x_overhead_liquid_actual": safe_float(row.get("alpha_match_x_overhead") or row.get("x_overhead")),
            "composition_zone": row.get("composition_zone") or "",
            "case_id": row.get("case_id") or "",
        })
    if not valid:
        return {
            "candidate_gate": "pending_alpha_scan",
            "candidate_gate_passed": False,
            "candidate_gate_note": "No Aspen alpha points have been imported for this candidate yet.",
            "candidate_best_i_alpha": "",
            "candidate_key_region_mean": "",
            "candidate_key_region_min": "",
            "candidate_key_region_pass_fraction": "",
        }
    threshold = RELATIVE_VOLATILITY_I_ALPHA_PASS_THRESHOLD
    best = max(valid, key=lambda point: safe_float(point.get("i_alpha"), float("-inf")))
    best_i = safe_float(best.get("i_alpha"))
    key_points = [
        point for point in valid
        if any(token in str(point.get("composition_zone") or "") for token in ["feed", "azeotrope", "alpha_hard"])
    ] or valid
    key_values = [safe_float(point.get("i_alpha")) for point in key_points if safe_float(point.get("i_alpha")) is not None]
    key_mean = (sum(key_values) / len(key_values)) if key_values else None
    key_min = min(key_values) if key_values else None
    key_pass_count = sum(1 for value in key_values if value >= threshold)
    key_fraction = (key_pass_count / len(key_values)) if key_values else 0.0
    row_pass_count = sum(1 for point in valid if safe_float(point.get("i_alpha"), 0.0) >= threshold)
    scan_mode = any(point.get("x_overhead_liquid_spec") is not None for point in valid)
    if scan_mode:
        candidate_pass = bool(
            scan_complete
            and best_i is not None
            and best_i >= threshold
            and key_mean is not None
            and key_mean >= threshold
            and key_min is not None
            and key_min >= 1.0
            and key_fraction >= 0.5
        )
    else:
        candidate_pass = bool(best_i is not None and best_i >= threshold)
    if candidate_pass:
        gate = "pass_alpha_gate"
    elif not scan_complete and row_pass_count:
        gate = "borderline_row_pass_candidate_pending"
    elif scan_complete:
        gate = "fail_alpha_gate"
    else:
        gate = "pending_alpha_scan"
    note = (
        "Candidate gate uses key-region scan, not a single best point. "
        "row_pass={}/{}, key_pass={}/{}, key_mean={}, key_min={}, best_i_alpha={}."
    ).format(
        row_pass_count,
        len(valid),
        key_pass_count,
        len(key_values),
        round(key_mean, 5) if key_mean is not None else "",
        round(key_min, 5) if key_min is not None else "",
        round(best_i, 5) if best_i is not None else "",
    )
    return {
        "candidate_gate": gate,
        "candidate_gate_passed": candidate_pass,
        "candidate_gate_note": note,
        "candidate_best_i_alpha": round(best_i, 5) if best_i is not None else "",
        "candidate_key_region_mean": round(key_mean, 5) if key_mean is not None else "",
        "candidate_key_region_min": round(key_min, 5) if key_min is not None else "",
        "candidate_key_region_pass_fraction": round(key_fraction, 3) if key_values else "",
    }


def live_relative_volatility_progress(payload):
    action_name = str((payload or {}).get("action") or "")
    if action_name not in {"restart_relative_volatility_flash", "run_relative_volatility_flash", "run_next_relative_volatility_candidate", "retry_alpha_with_predictive_property_method"}:
        return None
    command = (payload or {}).get("command") or []
    report_path = (
        str((payload or {}).get("report_path") or "").strip()
        or command_arg_value(command, "--report")
    )
    if not report_path:
        return None
    report = read_json_default(report_path, {})
    if not report:
        return None
    active_alpha_commands = []
    try:
        report_token = str(Path(report_path).resolve()).replace("/", "\\").lower()
    except Exception:
        report_token = str(report_path or "").replace("/", "\\").lower()
    if report_token:
        for process_row in active_agent_runtime_processes():
            command_line = str(process_row.get("command_line") or "")
            command_norm = command_line.replace("/", "\\").lower()
            if report_token in command_norm and "aspen_relative_volatility_flash.py" in command_norm:
                active_alpha_commands.append(command_line)
    active_alpha_runtime = bool(active_alpha_commands)
    if active_alpha_runtime and not command:
        command = active_alpha_commands[0].split()
    task = report.get("separation_task") or {}
    property_retry = report.get("property_strategy_retry") or {}
    brief = report.get("system_research_brief") or {}
    pool_items = ((brief.get("candidate_solvent_pool") or {}).get("items") or [])
    pool_by_code = {
        str(item.get("code") or item.get("solvent_code") or item.get("aspen_component_id") or "").upper(): item
        for item in pool_items
        if item.get("code") or item.get("solvent_code") or item.get("aspen_component_id")
    }
    paths = report.get("research_task_package_paths") or {}
    trial_dir = Path(report_path).resolve().parent
    request_csv = (
        paths.get("relative_volatility_kvalue_request_csv")
        or paths.get("relative_volatility_prescreen_request_csv")
        or str(trial_dir / "research_task_package" / "relative_volatility_kvalue_request.csv")
    )
    results_csv = (
        paths.get("relative_volatility_kvalue_results_csv")
        or paths.get("relative_volatility_prescreen_results_csv")
        or str(trial_dir / "research_task_package" / "relative_volatility_kvalue_results.csv")
    )
    try:
        request_rows = read_csv_rows(request_csv) if request_csv else []
    except Exception:
        request_rows = []
    scoped_candidate_code = (
        command_arg_value(command, "--candidate-code")
        or (property_retry.get("candidate_code") if action_name == "retry_alpha_with_predictive_property_method" else "")
        or ""
    )
    scoped_token = component_token(scoped_candidate_code)
    if scoped_candidate_code:
        request_rows = [
            row for row in request_rows
            if scoped_token in {
                component_token(row.get("solvent_code")),
                component_token(row.get("code")),
                component_token(row.get("aspen_component_id")),
            }
        ]
    scoped_method = command_arg_value(command, "--property-method") or property_retry.get("property_method") or ""
    if scoped_method:
        for row in request_rows:
            row["property_method"] = scoped_method
    try:
        result_rows = read_csv_rows(results_csv) if results_csv else []
    except Exception:
        result_rows = []
    if scoped_token:
        result_rows = [
            row for row in result_rows
            if not component_token(row.get("solvent_code") or row.get("code"))
            or component_token(row.get("solvent_code") or row.get("code")) == scoped_token
        ]
    batch_limit = command_arg_int(command, "--max-candidates", 0)
    if batch_limit > 0 and not scoped_token:
        result_candidate_rows = [
            row for row in result_rows
            if alpha_progress_candidate_token(row)
            and not alpha_progress_case_id(row).upper().startswith("BASE")
        ]
        batch_tokens = alpha_progress_candidate_tokens(result_candidate_rows, batch_limit)
        if not batch_tokens:
            batch_tokens = alpha_progress_candidate_tokens(request_rows, batch_limit)
        if batch_tokens:
            request_rows = alpha_progress_filter_rows_by_tokens(request_rows, batch_tokens)
            result_rows = alpha_progress_filter_rows_by_tokens(result_rows, batch_tokens, keep_without_token=True)

    request_cases = [alpha_progress_case_key(row) for row in request_rows]
    request_cases = [case for case in request_cases if case and case != ("", "")]
    completed_cases = {
        alpha_progress_case_key(row)
        for row in result_rows
        if alpha_progress_case_id(row)
        and not alpha_progress_case_id(row).upper().startswith("BASE")
        and str(row.get("solvent_code") or "").strip()
    }
    pending_rows = [row for row in request_rows if alpha_progress_case_key(row) not in completed_cases]
    candidate_rows = [
        row for row in result_rows
        if not alpha_progress_case_id(row).upper().startswith("BASE")
        and str(row.get("solvent_code") or "").strip()
    ]
    base_rows = [
        row for row in result_rows
        if alpha_progress_case_id(row).upper().startswith("BASE")
        or str(row.get("status") or "").strip().lower() in {"base_binary_imported", "base_vle_scan_imported"}
    ]
    result_status_counts = {}
    for row in result_rows:
        key = str(row.get("status") or row.get("property_trust_status") or "unknown").strip() or "unknown"
        result_status_counts[key] = result_status_counts.get(key, 0) + 1
    try:
        results_updated_at = iso_from_timestamp(Path(results_csv).stat().st_mtime) if results_csv and Path(results_csv).exists() else ""
    except Exception:
        results_updated_at = ""
    latest_row = candidate_rows[-1] if candidate_rows else (result_rows[-1] if result_rows else {})
    expected_cases = alpha_progress_expected_case_count(report, request_rows, completed_cases)
    total_cases = expected_cases or len(request_cases) or len(completed_cases)
    total_cases = max(total_cases, len(completed_cases))
    completed_count = len(completed_cases)
    percent = round((completed_count / total_cases) * 100, 1) if total_cases else 0.0
    running = bool((payload or {}).get("running") or active_alpha_runtime)
    if running:
        state_note = "正在逐个候选萃取剂和 S/F 点计算 K 值与 Iα；尚未进入 Gaussian/GROMACS。"
    elif candidate_rows or base_rows:
        state_note = "本轮 Aspen α 快算已结束；这里显示最近完成的萃取剂和 S/F 点。"
    else:
        state_note = "该体系已有 Aspen α 快算队列，但尚未看到结果；启动后会逐个显示萃取剂和 S/F 点。"
    if action_name == "retry_alpha_with_predictive_property_method":
        if running:
            state_note = "正在用 {} 复算 {} 的 Aspen α；本轮仍由总控限制为 1 支候选，尚未进入 Gaussian/GROMACS。".format(
                property_retry.get("property_method") or task.get("property_method") or "-",
                property_retry.get("candidate_code") or "-",
            )
        elif candidate_rows or base_rows:
            state_note = "物性方法复算已结束；这里显示该方法的新 α 结果，只有可信通过项才会解锁 Gaussian/GROMACS。"
        else:
            state_note = "物性方法复算队列已准备；启动后会单支候选显示 Aspen α 进度。"
    current_row = pending_rows[0] if running and pending_rows else (candidate_rows[-1] if candidate_rows else None)
    last_row = candidate_rows[-1] if candidate_rows else None
    next_row = pending_rows[0] if pending_rows else None
    recent = [alpha_progress_candidate(row, pool_by_code) for row in candidate_rows[-8:]]
    pass_count = sum(1 for row in candidate_rows if alpha_progress_bool(row.get("pass_alpha_gate")))
    failed_count = sum(1 for row in candidate_rows if str(row.get("error_message") or "").strip())
    scan_complete = bool(total_cases and completed_count >= total_cases)
    progress_status = "running" if running else ("complete" if scan_complete else "waiting")
    progress_stage_status = "running" if running else ("done" if scan_complete else "waiting")
    candidate_gate = live_alpha_candidate_gate_summary(candidate_rows, scan_complete=scan_complete)
    task_label = "{} / {} -> {}".format(
        task.get("component_a") or "-",
        task.get("component_b") or "-",
        task.get("target_product") or "-",
    )
    try:
        screening_state = compact_autopilot_screening_state(build_screening_state(report))
    except Exception:
        screening_state = {}
    if ((screening_state.get("blocker") or {}).get("status") == "blocked_aspen_property_license"):
        deck_open_failed_count = int(result_status_counts.pop("blocked_aspen_input_deck_open_failed", 0) or 0)
        if deck_open_failed_count:
            result_status_counts["blocked_aspen_property_license"] = (
                int(result_status_counts.get("blocked_aspen_property_license") or 0)
                + deck_open_failed_count
            )
    return {
        "kind": "relative_volatility_flash",
        "title": "Aspen α / Iα 相对挥发度预筛",
        "actor": "总控智能体后台",
        "executor": "Aspen Plus property flash / K-value",
        "driver": Path(((payload or {}).get("command") or ["", "aspen_relative_volatility_flash.py"])[1]).name
        if len((payload or {}).get("command") or []) > 1 else "aspen_relative_volatility_flash.py",
        "task_label": task_label,
        "property_method": property_retry.get("property_method") or task.get("property_method") or "",
        "report_path": str(Path(report_path).resolve()),
        "status": progress_status,
        "stage_status": progress_stage_status,
        "execution_state": "running" if running else ("complete" if scan_complete else "waiting"),
        "current_stage": "alpha_queue",
        "request_csv": str(Path(request_csv).resolve()) if request_csv else "",
        "results_csv": str(Path(results_csv).resolve()) if results_csv else "",
        "state_note": state_note,
        "has_results": bool(result_rows),
        "request_row_count": len(request_rows),
        "result_row_count": len(result_rows),
        "candidate_result_row_count": len(candidate_rows),
        "base_result_row_count": len(base_rows),
        "status_counts": result_status_counts,
        "result_status_counts": result_status_counts,
        "results_updated_at": results_updated_at,
        "latest_status": latest_row.get("status") or latest_row.get("property_trust_status") or "",
        "latest_error_message": latest_row.get("error_message") or latest_row.get("property_trust_reason") or "",
        "base_done": bool(base_rows),
        "base_alpha": alpha_progress_number((base_rows[-1] if base_rows else {}).get("alpha_0") or (base_rows[-1] if base_rows else {}).get("alpha")),
        "total_cases": total_cases,
        "completed_cases": completed_count,
        "pending_cases": max(0, total_cases - completed_count),
        "percent": percent,
        "pass_count": pass_count,
        "row_pass_count": pass_count,
        "failed_count": failed_count,
        "candidate_gate": candidate_gate.get("candidate_gate"),
        "candidate_gate_passed": candidate_gate.get("candidate_gate_passed"),
        "candidate_gate_note": candidate_gate.get("candidate_gate_note"),
        "candidate_best_i_alpha": candidate_gate.get("candidate_best_i_alpha"),
        "candidate_key_region_mean": candidate_gate.get("candidate_key_region_mean"),
        "candidate_key_region_min": candidate_gate.get("candidate_key_region_min"),
        "candidate_key_region_pass_fraction": candidate_gate.get("candidate_key_region_pass_fraction"),
        "current_candidate": alpha_progress_candidate(current_row, pool_by_code),
        "last_completed": alpha_progress_candidate(last_row, pool_by_code),
        "next_candidate": alpha_progress_candidate(next_row, pool_by_code),
        "recent_results": recent,
        "screening_state": screening_state,
    }


FULL_FLOW_STAGE_ORDER = {
    "component_monomer_opt": 0,
    "solvent_monomer_opt": 1,
    "counterpoise_dimer_optimization": 2,
    "counterpoise_dimer_single_point": 2,
}


def full_flow_gaussian_row_complete(row):
    if row.get("status") != "input_generated":
        return False
    parsed = gaussian_log_summary(
        row.get("expected_log") or "",
        input_file=row.get("input_file"),
        enforce_input_mtime=row.get("job_type") in {"counterpoise_dimer_single_point", "counterpoise_dimer_optimization"},
    )
    return bool(parsed.get("normal_termination"))


def full_flow_row_in_primary_scope(row, primary_solvent):
    if not primary_solvent:
        return True
    if row.get("job_type") == "component_monomer_opt":
        return True
    return row_matches_primary_validation_solvent(row, primary_solvent)


def full_flow_gaussian_status(paths, primary_solvent):
    rows = [
        row for row in read_csv_rows(paths.get("gaussian_jobs_csv") or "")
        if row.get("status") == "input_generated"
        and full_flow_row_in_primary_scope(row, primary_solvent)
    ]
    rows = sorted(
        rows,
        key=lambda row: (
            FULL_FLOW_STAGE_ORDER.get(row.get("job_type"), 9),
            row.get("component") or "",
            row.get("solvent_code") or "",
            row.get("job_id") or "",
        ),
    )
    completed = [row for row in rows if full_flow_gaussian_row_complete(row)]
    pending = [row for row in rows if not full_flow_gaussian_row_complete(row)]
    next_job = pending[0] if pending else {}
    return {
        "label": "Gaussian",
        "total": len(rows),
        "completed": len(completed),
        "pending": len(pending),
        "next": next_job.get("job_id") or next_job.get("input_file") or "",
        "status": "done" if rows and not pending else ("waiting" if pending else "missing"),
    }


def full_flow_nci_status(paths, primary_solvent):
    rows = read_csv_rows(paths.get("nci_vmd_jobs_csv") or "")
    if primary_solvent:
        rows = [row for row in rows if row_matches_primary_validation_solvent(row, primary_solvent)]
    evidence_csv = paths.get("molecular_evidence_import_csv") or ""
    if not evidence_csv and paths.get("molecular_inputs_dir"):
        evidence_csv = str(Path(paths.get("molecular_inputs_dir")) / "molecular_evidence_import.csv")
    evidence = [
        row for row in read_csv_rows(evidence_csv)
        if row.get("evidence_type") == "nci_vmd"
        and row.get("status") in {"imported", "rendered_tga"}
    ]
    if primary_solvent:
        evidence = [row for row in evidence if row_matches_primary_validation_solvent(row, primary_solvent)]
    completed_job_ids = {row.get("job_id") for row in evidence if row.get("job_id")}
    ready_rows = [row for row in rows if row.get("source_fch") and Path(row.get("source_fch")).exists()]
    pending = max(0, len(rows) - len(completed_job_ids))
    next_job = next((row.get("job_id") for row in rows if row.get("job_id") not in completed_job_ids), "")
    return {
        "label": "NCI/VMD",
        "total": len(rows),
        "completed": len(completed_job_ids),
        "pending": pending,
        "ready": len(ready_rows),
        "next": next_job,
        "status": "done" if rows and pending <= 0 else ("ready" if ready_rows else ("waiting" if rows else "missing")),
    }


def full_flow_gromacs_status(paths, primary_solvent):
    if not paths.get("gromacs_jobs_csv"):
        return {"label": "GROMACS", "total": 0, "completed": 0, "pending": 0, "status": "missing"}
    job_rows = read_csv_rows(paths.get("gromacs_jobs_csv") or "")
    if primary_solvent:
        job_rows = [row for row in job_rows if row_matches_primary_validation_solvent(row, primary_solvent)]
    total = len([row for row in job_rows if row.get("job_id")])
    job_ids = {row.get("job_id") for row in job_rows if row.get("job_id")}
    try:
        readiness = inspect_gromacs_queue_readiness(paths, primary_solvent=primary_solvent)
    except Exception as exc:
        return {"label": "GROMACS", "total": 0, "completed": 0, "pending": 0, "status": "error", "note": str(exc)}
    strict_rows = strict_gromacs_evidence_rows(paths)
    if primary_solvent:
        strict_rows = [row for row in strict_rows if row_matches_primary_validation_solvent(row, primary_solvent)]
    completed_ids = {row.get("job_id") for row in strict_rows if row.get("job_id") in job_ids}
    completed = len(completed_ids)
    pending = max(0, total - completed)
    if primary_solvent and readiness.get("primary_expected_job_count"):
        ready = int(readiness.get("primary_ready_job_count") or 0)
        ready_dirs = readiness.get("primary_ready_dirs") or []
    else:
        ready = int(readiness.get("ready_dir_count") or 0)
        ready_dirs = readiness.get("ready_dirs") or []
    ready = min(ready, total)
    return {
        "label": "GROMACS",
        "total": total,
        "completed": completed,
        "pending": pending,
        "ready": ready,
        "next": ready_dirs[0] if ready_dirs else "",
        "status": "done" if total and pending <= 0 else ("ready" if ready else ("waiting" if total else "missing")),
    }


def parse_gromacs_mdp_progress_basis(case_dir):
    basis = {}
    for name in ("mdout.mdp", "md.mdp"):
        path = Path(case_dir) / name
        if not path.exists():
            continue
        try:
            for line in path.read_text(encoding="utf-8", errors="ignore").splitlines():
                match = re.match(r"^\s*(nsteps|dt)\s*=\s*([0-9.eE+-]+)", line)
                if not match:
                    continue
                key = match.group(1)
                value = float(match.group(2))
                if key == "nsteps":
                    basis["total_steps"] = int(value)
                elif key == "dt":
                    basis["dt_ps"] = value
        except Exception:
            continue
        if basis.get("total_steps") and basis.get("dt_ps"):
            break
    if basis.get("total_steps") and basis.get("dt_ps"):
        basis["total_time_ps"] = basis["total_steps"] * basis["dt_ps"]
    return basis


def parse_gromacs_md_log_progress(case_dir):
    log_path = Path(case_dir) / "md.log"
    if not log_path.exists():
        return {}
    tail = read_file_tail(log_path, limit=220000)
    latest_step = None
    latest_time = None
    for line in tail.splitlines():
        match = re.match(r"^\s*(\d+)\s+([0-9]+(?:\.[0-9]+)?)\s*$", line)
        if match:
            latest_step = int(match.group(1))
            latest_time = float(match.group(2))
    if latest_step is None:
        return {}
    progress = {
        "current_step": latest_step,
        "current_time_ps": latest_time,
    }
    progress.update(parse_gromacs_mdp_progress_basis(case_dir))
    total_steps = int(progress.get("total_steps") or 0)
    if total_steps > 0:
        progress["percent"] = round(min(100.0, max(0.0, latest_step * 100.0 / total_steps)), 1)
        if progress.get("total_time_ps") is None and latest_time is not None:
            dt_ps = (progress.get("dt_ps") or 0)
            if dt_ps:
                progress["total_time_ps"] = total_steps * dt_ps
    return progress


def latest_aspen_optimizer_activity(optimization_output_dir="", optimizer_report_json="", stdout_log="", stderr_log="", extra=None):
    candidates = []

    def add_candidate(path_value):
        path_value = str(path_value or "").strip()
        if not path_value:
            return
        try:
            path = Path(path_value)
            if path.exists() and path.is_file():
                stat = path.stat()
                candidates.append({"path": path, "mtime": stat.st_mtime, "size": stat.st_size})
        except Exception:
            return

    output_dir = Path(str(optimization_output_dir or "").strip()) if str(optimization_output_dir or "").strip() else None
    if output_dir:
        add_candidate(output_dir / "generic_aspen_once_optimizer.report.json")
        add_candidate(output_dir / "optimization" / "generic_agent_nsga2.case_events.jsonl")
        add_candidate(output_dir / "optimization" / "generic_agent_nsga2.case_results.csv")
        add_candidate(output_dir / "logs" / "aspen_generic_optimization.out.log")
        add_candidate(output_dir / "logs" / "aspen_generic_optimization.err.log")
    add_candidate(optimizer_report_json)
    add_candidate(stdout_log)
    add_candidate(stderr_log)
    if not candidates:
        return {}
    latest = max(candidates, key=lambda item: item["mtime"])
    path = latest["path"]
    try:
        relative = str(path.relative_to(output_dir)) if output_dir else path.name
    except Exception:
        relative = path.name
    payload = {
        "path": str(path),
        "relative_path": relative,
        "name": path.name,
        "size": latest["size"],
        "mtime": latest["mtime"],
        "mtime_iso": iso_from_timestamp(latest["mtime"]),
        "activity_kind": "aspen_optimizer",
    }
    if isinstance(extra, dict):
        payload.update({k: v for k, v in extra.items() if v not in ("", None)})
    return payload


def latest_full_flow_activity(paths, current_stage, aspen_progress=None):
    stage = str(current_stage or "").lower()
    if "aspen" in stage or "optimization" in stage or "pareto" in stage or "topsis" in stage:
        aspen_progress = aspen_progress or {}
        activity = latest_aspen_optimizer_activity(
            aspen_progress.get("optimization_output_dir") or aspen_progress.get("optimization_bounds_adjustment_output_dir") or "",
            aspen_progress.get("optimizer_report_json") or "",
            aspen_progress.get("stdout_log") or "",
            aspen_progress.get("stderr_log") or "",
            {
                "case_id": aspen_progress.get("latest_optimization_case_id") or "",
                "generation": aspen_progress.get("latest_optimization_generation") or "",
            },
        )
        if activity:
            return activity
    mol_dir_raw = paths.get("molecular_inputs_dir") or ""
    if not mol_dir_raw:
        return {}
    mol_dir = Path(mol_dir_raw)
    if not mol_dir.exists():
        return {}
    if "gromacs" in stage:
        roots = [mol_dir / "gromacs"]
        suffixes = {".log", ".xvg", ".edr", ".xtc", ".gro", ".trr"}
    elif "gaussian" in stage:
        roots = [mol_dir / "gaussian"]
        suffixes = {".out", ".log", ".chk", ".fchk", ".fch"}
    elif "nci" in stage or "vmd" in stage:
        roots = [mol_dir / "nci_vmd"]
        suffixes = {".png", ".tga", ".cube", ".log", ".txt", ".csv"}
    else:
        roots = [mol_dir]
        suffixes = {".log", ".json", ".csv", ".xvg", ".out"}
    latest = None
    for root in roots:
        if not root.exists():
            continue
        try:
            iterator = root.rglob("*")
        except Exception:
            continue
        for path in iterator:
            try:
                if not path.is_file() or path.suffix.lower() not in suffixes:
                    continue
                if "previous_runs" in {part.lower() for part in path.parts}:
                    continue
                stat = path.stat()
            except Exception:
                continue
            if latest is None or stat.st_mtime > latest["mtime"]:
                latest = {"path": path, "mtime": stat.st_mtime, "size": stat.st_size}
    if not latest:
        return {}
    path = latest["path"]
    try:
        relative = str(path.relative_to(mol_dir))
    except Exception:
        relative = str(path)
    payload = {
        "path": str(path),
        "relative_path": relative,
        "name": path.name,
        "size": latest["size"],
        "mtime": latest["mtime"],
        "mtime_iso": iso_from_timestamp(latest["mtime"]),
    }
    if "gromacs" in stage:
        try:
            progress = parse_gromacs_md_log_progress(path.parent)
        except Exception:
            progress = {}
        if progress:
            payload["progress"] = progress
            payload["case_dir"] = path.parent.name
    return payload


def mark_stage_running(stage_rows, label, activity=None):
    for row in stage_rows:
        if str(row.get("label") or "").lower() != label.lower():
            continue
        total = int(row.get("total") or 0)
        completed = int(row.get("completed") or 0)
        pending = int(row.get("pending") or 0)
        if total <= 0:
            total = 1
        if pending <= 0:
            pending = 1
            completed = min(completed, max(0, total - 1))
        row.update({
            "total": total,
            "completed": completed,
            "pending": pending,
            "status": "running",
        })
        if activity and activity.get("relative_path"):
            row["next"] = activity.get("relative_path")
        return


def normalized_full_flow_stage(value):
    value = str(value or "").strip().lower()
    if not value:
        return ""
    if "gaussian" in value:
        return "gaussian"
    if "nci" in value or "vmd" in value:
        return "nci_vmd"
    if "gromacs" in value or "sobtop" in value or "topology" in value:
        return "gromacs"
    if "aspen" in value or "optimization" in value or "topsis" in value or "pareto" in value:
        return "aspen"
    if value == "full_flow_verified":
        return "complete"
    return value


def full_flow_stage_process_count(stage, compute_processes):
    stage = normalized_full_flow_stage(stage)
    compute_processes = compute_processes or {}
    if stage == "gaussian":
        return int(compute_processes.get("gaussian_count") or 0)
    if stage == "nci_vmd":
        return int(compute_processes.get("nci_vmd_count") or 0)
    if stage == "gromacs":
        return int(compute_processes.get("gromacs_count") or 0)
    if stage == "aspen":
        # AspenPlus COM children do not carry the case path in their command line.
        # Treat Aspen as current workflow activity only while an Agent/optimizer
        # process is alive; otherwise it is a machine-safety signal, not stage proof.
        runtime_processes = compute_processes.get("agent_runtime_processes") or []
        optimizer_active = any(
            "generic_aspen_once_optimizer.py" in str(row.get("command_line") or row.get("CommandLine") or "").lower()
            or "optimize_nmp_nsga2.py" in str(row.get("command_line") or row.get("CommandLine") or "").lower()
            or "aspen_case_worker.py" in str(row.get("command_line") or row.get("CommandLine") or "").lower()
            for row in runtime_processes
            if isinstance(row, dict)
        )
        if optimizer_active:
            return max(1, int(compute_processes.get("aspen_count") or 0))
        if int(compute_processes.get("agent_runtime_count") or 0) <= 0:
            return 0
        return int(compute_processes.get("aspen_count") or 0)
    return 0


def full_flow_effective_stage(stage_rows, reported_stage, compute_processes):
    """Resolve one authoritative stage from live processes, runner state, and evidence."""
    for stage in ("gromacs", "nci_vmd", "gaussian", "aspen"):
        if full_flow_stage_process_count(stage, compute_processes) > 0:
            return stage, "live_process"

    row_by_stage = {
        normalized_full_flow_stage(row.get("label")): row
        for row in (stage_rows or [])
        if isinstance(row, dict)
    }
    reported = normalized_full_flow_stage(reported_stage)
    reported_row = row_by_stage.get(reported) or {}
    if reported in {"gaussian", "nci_vmd", "gromacs"}:
        total = int(reported_row.get("total") or 0)
        completed = int(reported_row.get("completed") or 0)
        pending = int(reported_row.get("pending") or 0)
        if not reported_row or pending > 0 or completed < total:
            return reported, "runner_status"
    elif reported:
        return reported, "runner_status"

    for stage in ("gaussian", "nci_vmd", "gromacs"):
        row = row_by_stage.get(stage) or {}
        total = int(row.get("total") or 0)
        completed = int(row.get("completed") or 0)
        pending = int(row.get("pending") or 0)
        if not row or total <= 0 or pending > 0 or completed < total:
            return stage, "evidence_frontier"
    return "complete", "evidence_frontier"


def report_owned_runtime_processes(compute_processes, report_path):
    if not report_path:
        return []
    try:
        report_token = str(Path(report_path).resolve()).replace("/", "\\").lower()
    except Exception:
        report_token = str(report_path).replace("/", "\\").lower()
    return [
        row for row in ((compute_processes or {}).get("agent_runtime_processes") or [])
        if report_token and report_token in str(row.get("command_line") or "").replace("/", "\\").lower()
    ]


def live_full_flow_progress(report, status_payload, report_path=None):
    if not report:
        return None
    status_payload = status_payload or {}
    task = report.get("separation_task") or {}
    paths = report.get("research_task_package_paths") or {}
    solvent_code = (
        (status_payload.get("primary_validation_solvent") or {}).get("code")
        or status_payload.get("solvent_lock")
        or ((status_payload.get("molecular_scope") or {}).get("solvent_filter"))
        or ""
    )
    primary_solvent = primary_validation_solvent_identity(report, solvent_code) if solvent_code else {}
    solvent_label = " / ".join(
        item for item in [
            primary_solvent.get("code") or solvent_code,
            primary_solvent.get("name") or primary_solvent.get("solvent_name") or "",
        ]
        if item
    )
    alpha_summary = relative_volatility_summary(report)
    def _progress_int(value):
        try:
            return int(float(value or 0))
        except Exception:
            return 0
    def _progress_bool(value):
        if isinstance(value, str):
            return value.strip().lower() in {"1", "true", "yes", "y"}
        return bool(value)
    alpha_status = str(alpha_summary.get("status") or "").strip().lower()
    alpha_candidate_count = _progress_int(alpha_summary.get("candidate_count") or alpha_summary.get("total"))
    alpha_completed_count = _progress_int(alpha_summary.get("alpha_completed_count") or alpha_summary.get("completed_count"))
    alpha_pending_count = _progress_int(alpha_summary.get("alpha_pending_count") or alpha_summary.get("pending_count"))
    if alpha_candidate_count and not alpha_pending_count and not _progress_bool(alpha_summary.get("alpha_full_screen_complete")):
        alpha_pending_count = max(0, alpha_candidate_count - alpha_completed_count)
    alpha_pass_count = _progress_int(alpha_summary.get("pass_count"))
    alpha_full_complete = _progress_bool(alpha_summary.get("alpha_full_screen_complete"))
    alpha_frontier_pending = bool(
        alpha_candidate_count > 0
        and (
            alpha_pending_count > 0
            or not alpha_full_complete
            or alpha_status in {"alpha_queue_pass_candidates_pending", "alpha_queue_no_candidate_pass_yet"}
        )
    )
    alpha_gate_blocked = bool(
        alpha_candidate_count > 0
        and not alpha_frontier_pending
        and alpha_pass_count <= 0
        and alpha_status not in {"pass_candidates_available"}
    )
    alpha_gate_waiting = alpha_frontier_pending or alpha_gate_blocked
    alpha_stage_rows = []
    if alpha_candidate_count:
        alpha_stage_rows.append({
            "label": "Aspen alpha",
            "total": alpha_candidate_count,
            "completed": min(alpha_candidate_count, alpha_completed_count),
            "pending": alpha_pending_count if alpha_frontier_pending else 0,
            "next": (report.get("screening_state") or {}).get("next_action") or "",
            "status": "blocked" if alpha_gate_blocked else ("waiting" if alpha_frontier_pending else alpha_status or "waiting"),
        })
    stage_rows = alpha_stage_rows + [
        full_flow_gaussian_status(paths, primary_solvent),
        full_flow_nci_status(paths, primary_solvent),
        full_flow_gromacs_status(paths, primary_solvent),
    ]
    molecular_frontier_pending = any(
        normalized_full_flow_stage(row.get("label")) in {"gaussian", "nci_vmd", "gromacs"}
        and int(row.get("total") or 0) > 0
        and (
            int(row.get("pending") or 0) > 0
            or int(row.get("completed") or 0) < int(row.get("total") or 0)
        )
        for row in stage_rows
        if isinstance(row, dict)
    )
    reported_current_stage = str(status_payload.get("current_stage") or "").strip()
    process_import = (
        status_payload.get("process_import_after_optimization")
        or status_payload.get("process_import")
        or report.get("process_result_import")
        or {}
    )
    if not isinstance(process_import, dict):
        process_import = {}
    current_aspen_progress = aspen_progress_summary(report)
    optimization_alignment = str(
        process_import.get("optimization_solvent_alignment_status")
        or current_aspen_progress.get("optimization_solvent_alignment_status")
        or ""
    ).strip().lower()
    mainline_aspen_pending = bool(
        optimization_alignment in {"mismatch", "unknown"}
        or process_import.get("mainline_aspen_optimization_required")
        or current_aspen_progress.get("mainline_aspen_optimization_required")
    )
    compute_processes = active_compute_process_summary()
    aspen_optimizer_process_active = any(
        "generic_aspen_once_optimizer.py" in str(row.get("command_line") or row.get("CommandLine") or "").lower()
        for row in (compute_processes.get("agent_runtime_processes") or [])
        if isinstance(row, dict)
    )
    current_stage, current_stage_source = full_flow_effective_stage(
        stage_rows,
        reported_current_stage,
        compute_processes,
    )
    status_text = str(status_payload.get("status") or "").strip().lower()
    stage_status_text = str(status_payload.get("stage_status") or "").strip().lower()
    current_action_text = str(status_payload.get("current_action") or "").strip().lower()
    retryable_required_output_repair = bool(
        status_text == "blocked_required_outputs_missing_retryable"
        or reported_current_stage == "aspen_required_output_repair_probe"
        or current_action_text == "continue_required_output_repair_probe"
    )
    if alpha_gate_waiting:
        current_stage = "relative_volatility_flash"
        current_stage_source = "alpha_gate"
    elif retryable_required_output_repair:
        current_stage = reported_current_stage or "aspen_required_output_repair_probe"
        current_stage_source = "required_output_repair_probe"
    elif mainline_aspen_pending and not molecular_frontier_pending:
        current_stage = "aspen_mainline_optimization"
        current_stage_source = "mainline_aspen_gate"
    elif aspen_optimizer_process_active and not alpha_gate_waiting and not molecular_frontier_pending:
        current_stage = "aspen_mainline_optimization"
        current_stage_source = "live_aspen_optimizer_process"
    owned_runtime_processes = report_owned_runtime_processes(compute_processes, report_path)
    stage_process_active = full_flow_stage_process_count(current_stage, compute_processes) > 0
    runtime_active = bool(owned_runtime_processes or stage_process_active)
    stale_after_reboot = bool(
        not runtime_active
        and (
            status_text == "running"
            or stage_status_text in {"running", "planning", "started", "delegating"}
        )
    )
    latest_activity = latest_full_flow_activity(paths, current_stage, current_aspen_progress)
    current_stage_lower = current_stage.lower()
    if "gaussian" in current_stage_lower and compute_processes.get("gaussian_count", 0) > 0:
        mark_stage_running(stage_rows, "Gaussian", latest_activity)
    if ("nci" in current_stage_lower or "vmd" in current_stage_lower) and compute_processes.get("nci_vmd_count", 0) > 0:
        mark_stage_running(stage_rows, "NCI/VMD", latest_activity)
    if "gromacs" in current_stage_lower and compute_processes.get("gromacs_count", 0) > 0:
        mark_stage_running(stage_rows, "GROMACS", latest_activity)
    if current_stage.startswith("aspen") or "aspen" in current_stage:
        aspen_stage_runtime_active = full_flow_stage_process_count("aspen", compute_processes) > 0
        aspen_blocked = (
            not aspen_stage_runtime_active
            and (
                str(status_payload.get("stage_status") or "").lower() == "blocked"
                or str(status_payload.get("status") or "").lower().startswith("blocked")
                or mainline_aspen_pending
            )
        )
        aspen_complete = str(status_payload.get("status") or "").lower() == "complete" and not mainline_aspen_pending
        stage_rows.append({
            "label": "Aspen",
            "total": 1,
            "completed": 1 if aspen_complete and not aspen_stage_runtime_active else 0,
            "pending": 0 if (aspen_complete or aspen_blocked) and not aspen_stage_runtime_active else 1,
            "next": status_payload.get("aspen_optimization_output_dir") or "",
            "status": "running" if aspen_stage_runtime_active else (status_payload.get("stage_status") or status_payload.get("status") or "waiting"),
        })
    total_cases = sum(int(row.get("total") or 0) for row in stage_rows)
    completed_cases = sum(int(row.get("completed") or 0) for row in stage_rows)
    pending_cases = sum(int(row.get("pending") or 0) for row in stage_rows)
    total_cases = max(total_cases, completed_cases)
    percent = round(completed_cases * 100 / total_cases, 1) if total_cases else 0.0
    alpha_state_note = ""
    if alpha_gate_blocked:
        alpha_state_note = "当前体系的 Aspen α/K-value 相对挥发度筛选已闭合，但没有萃取剂通过；不能进入 Gaussian/GROMACS，需要扩展候选或复核物性方法。"
    elif alpha_frontier_pending:
        alpha_state_note = "当前体系还没有完成真实 Aspen α/K-value 相对挥发度筛选；不能锁定萃取剂或进入 Gaussian/GROMACS。"
    aspen_runtime_state_note = ""
    if aspen_optimizer_process_active and not alpha_gate_waiting and not molecular_frontier_pending:
        best_purity = current_aspen_progress.get("constraint_best_purity") or ""
        best_recovery = current_aspen_progress.get("constraint_best_recovery") or ""
        target_purity = current_aspen_progress.get("constraint_target_purity") or task.get("target_purity") or ""
        latest_case = current_aspen_progress.get("latest_optimization_case_id") or ""
        latest_purity = current_aspen_progress.get("latest_optimization_purity") or ""
        latest_recovery = current_aspen_progress.get("latest_optimization_recovery") or ""
        pieces = ["Aspen 主线多目标优化正在运行，当前保持单 Aspen 链逐案搜索。"]
        topsis_case = current_aspen_progress.get("current_run_topsis_best_case_id") or current_aspen_progress.get("topsis_best_case_id") or ""
        topsis_tac = current_aspen_progress.get("current_run_topsis_best_TAC") or current_aspen_progress.get("topsis_best_TAC") or ""
        topsis_purity = current_aspen_progress.get("current_run_topsis_best_purity") or ""
        topsis_recovery = (
            current_aspen_progress.get("current_run_topsis_best_case_recovery")
            or current_aspen_progress.get("current_run_topsis_best_recovery")
            or current_aspen_progress.get("topsis_best_recovery")
            or ""
        )
        if topsis_case:
            pieces.append("当前TOPSIS可行最优 {}：TAC {}，纯度 {}，回收率 {}。".format(topsis_case, topsis_tac or "-", topsis_purity or "-", topsis_recovery or "-"))
        if best_purity not in ("", None):
            pieces.append("最高纯度诊断 {} / 目标 {}，对应回收率 {}。".format(best_purity, target_purity, best_recovery))
        if latest_case and latest_purity not in ("", None) and latest_recovery not in ("", None):
            pieces.append("最新案例 {}：纯度 {}，回收率 {}。".format(latest_case, latest_purity, latest_recovery))
        else:
            latest_metric_case = current_aspen_progress.get("latest_metric_optimization_case_id") or ""
            latest_metric_purity = current_aspen_progress.get("latest_metric_optimization_purity") or ""
            latest_metric_recovery = current_aspen_progress.get("latest_metric_optimization_recovery") or ""
            if latest_metric_case:
                pieces.append("最新完整指标案例 {}：纯度 {}，回收率 {}。".format(latest_metric_case, latest_metric_purity, latest_metric_recovery))
            elif latest_case:
                pieces.append("最新案例 {} 已写入，正在等待 Aspen 指标回填。".format(latest_case))
        if not current_aspen_progress.get("topsis_best_case_id"):
            pieces.append("尚未出现满足硬约束的 Pareto/TOPSIS 可行点。")
        aspen_runtime_state_note = "".join(pieces)
    if mainline_aspen_pending and molecular_frontier_pending and not alpha_gate_waiting:
        mainline_state_note = (
            "当前体系的主线 Aspen 还未完成，但前置分子证据也没有补齐；应先按本体系文件夹继续 Gaussian/NCI/VMD/GROMACS，不能直接把流程判到 Aspen 优化完成。"
        )
    elif mainline_aspen_pending and not alpha_gate_waiting:
        selected = (
            process_import.get("selected_molecular_solvent_label")
            or current_aspen_progress.get("selected_molecular_solvent_label")
            or process_import.get("selected_molecular_solvent_code")
            or current_aspen_progress.get("selected_molecular_solvent_code")
            or solvent_label
            or "当前锁定萃取剂"
        )
        optimized = " / ".join(
            item for item in [
                process_import.get("topsis_best_aspen_component_id") or current_aspen_progress.get("topsis_best_aspen_component_id") or process_import.get("latest_optimization_aspen_component_id") or "",
                process_import.get("topsis_best_solvent_name") or current_aspen_progress.get("topsis_best_solvent_name") or process_import.get("latest_optimization_solvent_name") or "",
            ]
            if item
        ) or "旁支优化结果"
        mainline_state_note = (
            "当前主线 {} 的 Aspen 还没闭合；已有优化结果属于 {}，不能算当前体系完成。".format(
                selected,
                optimized,
            )
        )
    else:
        mainline_state_note = ""
    live_progress_override = {}
    if retryable_required_output_repair:
        live_progress_override = {
            "state_note": status_payload.get("message") or "",
            "status": status_payload.get("status") or "",
            "stage_status": status_payload.get("stage_status") or "",
            "current_stage": current_stage,
            "current_stage_source": current_stage_source,
        }
    return {
        "kind": "agent_full_flow",
        "title": "Agent full-flow supervision",
        "state_note": (
            alpha_state_note
            if alpha_gate_waiting else (
                aspen_runtime_state_note
                if aspen_runtime_state_note else (
                    mainline_state_note
                    if mainline_aspen_pending else (
                        "上次状态文件仍写着 running，但当前没有检测到本任务的长计算进程；这是中断后的待继续状态。"
                        if stale_after_reboot else (status_payload.get("message") or "")
                    )
                )
            )
        ),
        "status": (
            ("blocked_no_alpha_pass" if alpha_gate_blocked else "relative_volatility_pending")
            if alpha_gate_waiting
            else (
                "running"
                if aspen_runtime_state_note else (
                    "molecular_evidence_pending"
                    if (mainline_aspen_pending and molecular_frontier_pending)
                    else (
                        "blocked_aspen_mainline_not_optimized"
                        if mainline_aspen_pending
                        else ("stale_after_reboot" if stale_after_reboot else (status_payload.get("status") or ""))
                    )
                )
            )
        ),
        "stage_status": (
            ("blocked" if alpha_gate_blocked else "waiting")
            if alpha_gate_waiting
            else (
                "running"
                if aspen_runtime_state_note else (
                    "waiting"
                    if (mainline_aspen_pending and molecular_frontier_pending)
                    else (
                        "blocked"
                        if mainline_aspen_pending
                        else ("interrupted" if stale_after_reboot else (status_payload.get("stage_status") or ""))
                    )
                )
            )
        ),
        "current_stage": current_stage,
        "reported_current_stage": reported_current_stage,
        "current_stage_source": current_stage_source,
        "execution_state": "running" if runtime_active else ("interrupted" if stale_after_reboot else "waiting"),
        "task_label": "{} / {} -> {}".format(
            task.get("component_a") or "-",
            task.get("component_b") or "-",
            task.get("target_product") or "-",
        ),
        "solvent_label": solvent_label or "-",
        "total_cases": total_cases,
        "completed_cases": completed_cases,
        "pending_cases": pending_cases,
        "percent": percent,
        "stages": stage_rows,
        "compute_processes": compute_processes,
        "owned_runtime_processes": owned_runtime_processes,
        "latest_activity": latest_activity,
        **live_progress_override,
    }


def attach_orchestrator_live_progress(payload, report_path=None):
    payload = dict(payload or {})
    try:
        if report_path and not payload.get("report_path"):
            payload["report_path"] = str(report_path)
        action_name = str(payload.get("action") or "").strip()
        report_for_progress = {}
        status_payload_for_progress = {}
        if report_path:
            report_for_progress = read_json_default(report_path, {})
            status_payload_for_progress = autopilot_status_payload_for_report(report_path) or (report_for_progress.get("full_flow_autopilot_status") or {})
        status_mode = str((status_payload_for_progress or {}).get("mode") or "").strip()
        status_stage = str((status_payload_for_progress or {}).get("current_stage") or "").strip()
        alpha_actions = {"restart_relative_volatility_flash", "run_relative_volatility_flash", "run_next_relative_volatility_candidate", "retry_alpha_with_predictive_property_method"}
        nested_alpha_payload = {}
        if isinstance(status_payload_for_progress, dict):
            for key in ("nested_execution", "last_action_result"):
                candidate_payload = status_payload_for_progress.get(key)
                if not isinstance(candidate_payload, dict):
                    continue
                if str(candidate_payload.get("action") or "").strip() in alpha_actions:
                    nested_alpha_payload = dict(candidate_payload)
                    if nested_alpha_payload.get("finished_at") and nested_alpha_payload.get("running"):
                        nested_alpha_payload["running"] = False
                        if nested_alpha_payload.get("returncode") is None:
                            nested_alpha_payload["returncode"] = 0
                    if nested_alpha_payload.get("running") and nested_alpha_payload.get("pid") and not process_pid_is_live(nested_alpha_payload.get("pid")):
                        nested_alpha_payload.update({
                            "running": False,
                            "finished_at": nested_alpha_payload.get("finished_at") or iso_from_timestamp(time.time()),
                            "returncode": nested_alpha_payload.get("returncode") if nested_alpha_payload.get("returncode") is not None else 0,
                            "stdout_tail": nested_alpha_payload.get("stdout_tail") or tail_text_file(nested_alpha_payload.get("stdout_log")),
                            "stderr_tail": nested_alpha_payload.get("stderr_tail") or tail_text_file(nested_alpha_payload.get("stderr_log")),
                            "inferred_finished_from_missing_pid": True,
                        })
                    break
        if nested_alpha_payload and report_path and (
            status_stage in {"relative_volatility_flash", "alpha_queue"}
            or nested_alpha_payload.get("running")
        ):
            nested_alpha_payload["report_path"] = str(report_path)
            nested_progress = live_relative_volatility_progress(nested_alpha_payload)
            if nested_progress:
                nested_progress = dict(nested_progress)
                payload["live_progress"] = nested_progress
                if nested_alpha_payload.get("running"):
                    nested_progress.update({
                        "status": "running",
                        "stage_status": "running",
                        "execution_state": "running",
                    })
                    payload.update({
                        "running": True,
                        "status": "running",
                        "action": action_name or status_mode or "agent_screening_autopilot",
                        "returncode": None,
                        "finished_at": "",
                        "message": nested_progress.get("state_note") or status_payload_for_progress.get("message") or payload.get("message") or "",
                    })
                else:
                    payload.update({
                        "running": False,
                        "returncode": nested_alpha_payload.get("returncode") if nested_alpha_payload.get("returncode") is not None else payload.get("returncode"),
                        "message": nested_progress.get("state_note") or status_payload_for_progress.get("message") or payload.get("message") or "",
                    })
                return payload
        report_screen_stage = str((report_for_progress.get("screening_state") or {}).get("stage") or "").strip()
        alpha_stage_active = bool(
            status_stage in {"relative_volatility_flash", "alpha_queue", "property_strategy_review", "strategy_review"}
            or report_screen_stage in {"alpha_queue", "property_strategy_review", "strategy_review"}
        )
        if alpha_stage_active and report_path:
            alpha_probe = dict(payload)
            alpha_probe.update({
                "action": action_name if action_name in alpha_actions else "run_relative_volatility_flash",
                "report_path": str(report_path),
            })
            alpha_progress = live_relative_volatility_progress(alpha_probe)
            if alpha_progress:
                alpha_progress = dict(alpha_progress)
                status_text = str(status_payload_for_progress.get("status") or "").strip().lower()
                stage_status_text = str(status_payload_for_progress.get("stage_status") or "").strip().lower()
                progress_status_text = str(alpha_progress.get("status") or "").strip().lower()
                progress_execution_text = str(alpha_progress.get("execution_state") or "").strip().lower()
                recovered_running = bool(
                    status_text == "running"
                    or stage_status_text in {"running", "planning", "started", "delegating"}
                    or progress_status_text == "running"
                    or progress_execution_text == "running"
                )
                if recovered_running:
                    alpha_progress.update({
                        "status": "running",
                        "stage_status": "running",
                        "execution_state": "running",
                    })
                payload.update({
                    "running": recovered_running,
                    "status": "running" if recovered_running else payload.get("status"),
                    "action": alpha_probe["action"],
                    "returncode": None if recovered_running else payload.get("returncode"),
                    "finished_at": "" if recovered_running else payload.get("finished_at"),
                    "message": alpha_progress.get("state_note") or status_payload_for_progress.get("message") or payload.get("message") or "",
                    "live_progress": alpha_progress,
                })
                return payload
        has_full_flow_status = bool(
            status_mode in {"agent_screening_autopilot", "agent_full_flow_autopilot", "agent_publication_trial_autopilot"}
            and status_stage
            and status_stage not in {"relative_volatility_flash", "alpha_queue"}
        )
        report_steps = report_for_progress.get("agent_steps") or report_for_progress.get("agent_stage_trace") or []
        has_downstream_trial_evidence = bool(
            report_for_progress.get("process_result_import")
            or report_for_progress.get("aspen_progress")
            or ((report_for_progress.get("research_task_package_paths") or {}).get("aspen_build_plan_json"))
            or ((report_for_progress.get("research_task_package_paths") or {}).get("aspen_zero_build_spec_json"))
            or any(
                str((row or {}).get("step") or (row or {}).get("stage") or "").strip().lower()
                in {"molecular_evidence_ingestion", "candidate_selection", "aspen_validation", "nsga2_optimization", "process_evidence_ingestion"}
                for row in report_steps
                if isinstance(row, dict)
            )
        )
        use_full_flow_progress = (
            action_name in {"agent_full_flow_autopilot", "publication_one_system_trial_autopilot"}
            or (action_name == "agent_screening_autopilot" and status_stage not in {"relative_volatility_flash", "alpha_queue"})
            or (not action_name and has_full_flow_status)
            or (not action_name and report_path and has_downstream_trial_evidence)
        )
        if use_full_flow_progress and report_path:
            progress = live_full_flow_progress(report_for_progress, status_payload_for_progress, report_path=report_path)
            if progress:
                payload["live_progress"] = progress
                if not action_name:
                    status_text = str(status_payload_for_progress.get("status") or "").strip().lower()
                    stage_status_text = str(status_payload_for_progress.get("stage_status") or "").strip().lower()
                    progress_status_text = str(progress.get("status") or "").strip().lower()
                    recovered_running = (
                        progress_status_text == "running"
                        or status_text == "running"
                        or stage_status_text in {"running", "planning", "started", "delegating"}
                    )
                    payload.update({
                        "running": bool(recovered_running),
                        "action": status_mode or "agent_full_flow_autopilot",
                        "returncode": None if recovered_running else (0 if progress_status_text == "complete" else None),
                        "message": progress.get("state_note") or status_payload_for_progress.get("message") or "Recovered latest agent full-flow status for the selected report.",
                })
                return payload
        progress = live_relative_volatility_progress(payload)
        if not progress and report_path and (not action_name or action_name in alpha_actions or status_stage in {"relative_volatility_flash", "alpha_queue"}):
            probe = dict(payload)
            probe.update({
                "action": "run_relative_volatility_flash",
                "report_path": str(report_path),
            })
            progress = live_relative_volatility_progress(probe)
            if progress and not payload.get("action"):
                has_results = bool(progress.get("has_results"))
                status_text = str(status_payload_for_progress.get("status") or "").strip().lower()
                stage_status_text = str(status_payload_for_progress.get("stage_status") or "").strip().lower()
                progress_status_text = str(progress.get("status") or "").strip().lower()
                progress_execution_text = str(progress.get("execution_state") or "").strip().lower()
                recovered_running = (
                    status_text == "running"
                    or stage_status_text in {"running", "planning", "started", "delegating"}
                    or progress_status_text == "running"
                    or progress_execution_text == "running"
                )
                if recovered_running:
                    progress = dict(progress)
                    progress.update({
                        "status": "running",
                        "stage_status": "running",
                        "execution_state": "running",
                    })
                payload.update({
                    "running": bool(recovered_running),
                    "status": "running" if recovered_running else payload.get("status"),
                    "action": status_mode or "run_relative_volatility_flash",
                    "returncode": None if recovered_running else (0 if has_results else None),
                    "finished_at": "" if recovered_running else payload.get("finished_at"),
                    "message": (
                        status_payload_for_progress.get("message")
                        or (
                            "读取所选体系最近一次 Aspen α / Iα 预筛记录；该状态可在 dashboard 重启后从结果 CSV 恢复。"
                            if has_results else
                            "所选体系已有 Aspen α / Iα 快算队列，但还没有结果；启动后会显示正在计算的萃取剂和 S/F 点。"
                        )
                    ),
                })
        if progress:
            payload["live_progress"] = progress
    except Exception as exc:
        payload["live_progress_error"] = str(exc)
    return payload


def promote_live_progress_summary(payload):
    payload = dict(payload or {})
    progress = payload.get("live_progress") or {}
    if not isinstance(progress, dict) or not progress:
        return payload

    direct_keys = (
        "kind",
        "title",
        "task_label",
        "total_cases",
        "completed_cases",
        "pending_cases",
        "percent",
        "latest_status",
        "latest_error_message",
        "results_updated_at",
        "status_counts",
        "result_status_counts",
        "current_candidate",
        "last_completed",
        "next_candidate",
    )
    for key in direct_keys:
        if key in progress and payload.get(key) in (None, "", {}, []):
            payload[key] = progress.get(key)

    alias_pairs = (
        ("result_rows", "result_row_count"),
        ("candidate_rows", "candidate_result_row_count"),
        ("base_rows", "base_result_row_count"),
        ("request_rows", "request_row_count"),
    )
    for payload_key, progress_key in alias_pairs:
        if payload.get(payload_key) in (None, "", {}, []):
            payload[payload_key] = progress.get(progress_key)

    return payload


def screening_state_has_retryable_property_method_review(state):
    state = state or {}
    if str(state.get("next_action") or "").strip() != "retry_alpha_with_predictive_property_method":
        return False
    blocker = (
        state.get("blocker")
        or ((state.get("blockers") or {}).get("alpha_global_blocker") or {})
    )
    if not blocker:
        return False
    blocker_tokens = {
        str(blocker.get(key) or "").strip().lower()
        for key in ("status", "base_blocker")
    }
    if blocker_tokens & {
        "blocked_aspen_property_license",
        "blocked_aspen_property_engine_unavailable",
    }:
        return False
    if row_has_aspen_property_license_blocker(blocker):
        return False
    if blocker.get("retryable") is False:
        return False
    return bool(str(blocker.get("next_method") or "").strip())


def compact_autopilot_screening_state(state):
    state = state or {}
    counts = ((state.get("progress") or {}).get("alpha") or {})
    budget = state.get("budget") or {}
    external = state.get("external_candidate_library") or {}
    current = state.get("current_candidate") or {}
    blockers = state.get("blockers") or {}
    return {
        "stage": state.get("stage") or "",
        "stage_label": state.get("stage_label") or "",
        "next_action": state.get("next_action") or "",
        "next_action_label": state.get("next_action_label") or "",
        "current_candidate": current,
        "passed_candidates": (state.get("passed_candidates") or [])[:6],
        "alpha": counts,
        "budget": {
            "used": budget.get("used"),
            "max_candidate_total": budget.get("max_candidate_total"),
            "remaining_total": budget.get("remaining_total"),
            "pool_mode": budget.get("pool_mode"),
        },
        "external": {
            "ready": external.get("ready_for_aspen_alpha_count"),
            "new_ready": external.get("new_ready_for_aspen_alpha_count"),
            "already_in_pool": external.get("ready_already_in_pool_count"),
            "needs_mapping": external.get("needs_aspen_identity_mapping_count"),
            "needs_review": external.get("needs_boiling_point_or_process_gate_review_count"),
        },
        "blocker": blockers.get("alpha_global_blocker") or {},
    }


def normalize_autopilot_status_with_report(status_payload, report):
    if not status_payload:
        return {}
    status = dict(status_payload)
    try:
        state = build_screening_state(report)
    except Exception:
        state = report.get("screening_state") or {}
    if not state:
        return status
    status["screening_state"] = compact_autopilot_screening_state(state)
    stage = str(state.get("stage") or "").strip()
    action = str(state.get("next_action") or "").strip()
    alpha = ((state.get("progress") or {}).get("alpha") or {})
    alpha_pass = int(alpha.get("pass") or 0)
    process_import = report.get("process_result_import") or {}
    closed_loop_diag = process_import.get("closed_loop_recycle_diagnosis") or {}
    status_text = str(status.get("status") or "").strip().lower()
    stage_status = str(status.get("stage_status") or "").strip().lower()
    active = status_text == "running" or stage_status in {"running", "planning", "started", "delegating"}
    closed_loop_pass_count = int(process_import.get("closed_loop_optimization_pass_case_count") or 0)
    if (not active) and closed_loop_pass_count > 0:
        molecular_gate = molecular_validation_gate_summary(report, report.get("research_task_package_paths") or {})
        if not molecular_gate.get("gate_open"):
            status["status"] = "molecular_validation_required"
            status["stage_status"] = "waiting"
            status["current_stage"] = "molecular_queue"
            status["current_action"] = "continue_molecular_validation_before_aspen_optimization"
            status["process_import_after_optimization"] = process_import
            status["closed_loop_recycle_diagnosis"] = closed_loop_diag
            status["molecular_gate"] = molecular_gate
            status["message"] = (
                "Aspen 优化结果已存在，但当前体系分子验证尚未闭合；这些优化结果暂存为未解锁证据，"
                "不会把主流程判定为完成。{}".format(molecular_gate.get("message") or "")
            )
            return status
        multi_complete = bool(process_import.get("multi_objective_optimization_complete"))
        multi_converged = bool(process_import.get("multi_objective_converged"))
        publication_floor = bool(process_import.get("publication_optimization_budget_complete"))
        alignment = str(process_import.get("optimization_solvent_alignment_status") or "").strip().lower()
        mainline_required = bool(process_import.get("mainline_aspen_optimization_required"))
        status["process_import_after_optimization"] = process_import
        status["closed_loop_recycle_diagnosis"] = closed_loop_diag
        if alignment in {"mismatch", "unknown"} or mainline_required:
            status["status"] = "blocked_aspen_mainline_not_optimized"
            status["stage_status"] = "blocked"
            status["current_stage"] = "aspen_mainline_optimization"
            status["current_action"] = "run_current_locked_solvent_aspen_optimization"
            status["message"] = (
                "Existing Aspen Pareto/TOPSIS evidence belongs to a side or unverified solvent; "
                "the current locked solvent still needs mainline Aspen optimization."
            )
        elif multi_complete and multi_converged and publication_floor:
            status["status"] = "complete"
            status["stage_status"] = "done"
            status["current_stage"] = "full_flow_verified"
            status["current_action"] = ""
            status["message"] = "Trusted closed-loop Aspen PASS and multi-objective Pareto/TOPSIS evidence are complete."
        else:
            status["status"] = "blocked_aspen_multi_objective_not_converged"
            status["stage_status"] = "blocked"
            status["current_stage"] = "aspen_multi_objective_optimization"
            status["current_action"] = "continue_pareto_topsis_optimization"
            status["message"] = (
                "Trusted closed-loop Aspen PASS is imported ({} case); continue serial Aspen optimization "
                "until Pareto/TOPSIS convergence and publication evidence floor are met."
            ).format(closed_loop_pass_count)
        return status
    if closed_loop_diag.get("status") == "closed_loop_required_outputs_missing":
        untested_repair_strategies = closed_loop_diag.get("untested_repair_strategies") or []
        if isinstance(untested_repair_strategies, str):
            untested_repair_strategies = [untested_repair_strategies]
        untested_repair_strategies = [str(item or "").strip() for item in untested_repair_strategies if str(item or "").strip()]
        retryable = bool(untested_repair_strategies)
        status["status"] = "blocked_required_outputs_missing_retryable" if retryable else "blocked_required_outputs_missing"
        status["stage_status"] = "blocked"
        status["current_stage"] = "aspen_required_output_repair_probe" if retryable else "aspen_required_outputs_missing"
        status["current_action"] = (
            "continue_required_output_repair_probe"
            if retryable
            else "repair_aspen_model_outputs_before_more_optimization"
        )
        status["returncode"] = status.get("returncode", 0)
        status["process_import_after_optimization"] = process_import
        if retryable:
            status["missing_repair_mode_families"] = untested_repair_strategies
            status["message"] = (
                "Aspen required outputs are missing, but the repair probe has not covered all generic recycle-control families yet: {}. "
                "Continue the full-flow agent repair probe before declaring a final Aspen blocker."
            ).format(", ".join(untested_repair_strategies))
        else:
            status["message"] = (
                closed_loop_diag.get("blocker")
                or "Aspen cases are blocked because required duty/stream outputs are missing."
            )
        return status
    if active or not stage or alpha_pass > 0:
        return status
    if stage in {"strategy_review", "property_strategy_review"} and screening_state_has_retryable_property_method_review(state):
        status["status"] = "waiting_property_method_retry"
        status["stage_status"] = "waiting"
        status["current_stage"] = stage
        status["current_action"] = action
        blocker = ((state.get("blockers") or {}).get("alpha_global_blocker") or {})
        status["message"] = (
            "Aspen alpha is blocked by property-method trust checks, but a retry method is available: {}. "
            "The screening autopilot should continue with the retry action before declaring a final blocker."
        ).format(blocker.get("next_method") or "-")
        return status
    if stage in {"strategy_review", "property_strategy_review"} and not screening_state_has_retryable_property_method_review(state):
        status["status"] = "blocked_strategy_review"
        status["stage_status"] = "blocked"
        status["current_stage"] = stage
        status["current_action"] = action
        status["message"] = "智能体已停在策略复核：没有新的可自动进入 Aspen α 的候选，Gaussian/GROMACS 未启动。"
    elif not action:
        status["status"] = "blocked_no_next_action"
        status["stage_status"] = "blocked"
        status["current_stage"] = stage
        status["current_action"] = ""
        status["message"] = "智能体已停止：当前筛选状态没有可自动执行的下一步。"
    return status


def autopilot_status_payload_for_report(report_path=None):
    if not report_path:
        return {}
    try:
        report = read_json_default(report_path, {})
        paths = report.get("research_task_package_paths") or {}
        status_path = paths.get("full_flow_autopilot_status_json") or ""
        if status_path and Path(status_path).exists():
            return normalize_autopilot_status_with_report(read_json_default(status_path, {}), report)
        return normalize_autopilot_status_with_report(report.get("full_flow_autopilot_status") or {}, report)
    except Exception as exc:
        return {"status_error": "{}: {}".format(exc.__class__.__name__, exc)}


def merge_system_trial_run_state(payload, report_path=None):
    run_state = dict(RUN_STATE)
    if str(run_state.get("action") or "") != "system-trial":
        return payload
    active_report_path = run_state_report_path(run_state)
    if not active_report_path:
        return payload
    if report_path and not run_state_matches_report(run_state, report_path):
        return payload
    returncode = run_state.get("returncode")
    running = bool(run_state.get("running"))
    status_text = "running" if running else ("done" if int(returncode or 0) == 0 else "failed")
    merged = dict(payload or {})
    merged.update({
        "running": running,
        "status": status_text,
        "action": "system-trial",
        "task_id": ((run_state.get("task") or {}).get("task_id") or merged.get("task_id") or ""),
        "started_at": run_state.get("started_at"),
        "finished_at": run_state.get("finished_at"),
        "returncode": None if running else returncode,
        "pid": run_state.get("pid") or merged.get("pid"),
        "command": run_state.get("command") or merged.get("command") or [],
        "cwd": run_state.get("cwd") or merged.get("cwd") or "",
        "stdout_tail": run_state.get("stdout_tail") or merged.get("stdout_tail") or "",
        "stderr_tail": run_state.get("stderr_tail") or merged.get("stderr_tail") or "",
        "message": run_state.get("message") or ("System trial is running." if running else "System trial finished."),
        "report_path": active_report_path,
        "output_dir": run_state.get("output_dir") or "",
        "run_state": run_state,
    })
    return merged


def orchestrator_execution_status(report_path=None):
    global ORCH_EXEC_PROCESS
    with ORCH_EXEC_LOCK:
        if ORCH_EXEC_PROCESS is not None and ORCH_EXEC_STATE.get("running"):
            returncode = ORCH_EXEC_PROCESS.poll()
            if returncode is not None:
                ORCH_EXEC_STATE.update({
                    "running": False,
                    "finished_at": iso_from_timestamp(time.time()),
                    "returncode": returncode,
                    "stdout_tail": tail_text_file(ORCH_EXEC_STATE.get("stdout_log")),
                    "stderr_tail": tail_text_file(ORCH_EXEC_STATE.get("stderr_log")),
                    "message": "后台执行已结束，returncode={}".format(returncode),
                })
                ORCH_EXEC_PROCESS = None
        payload = dict(ORCH_EXEC_STATE)
    payload = merge_system_trial_run_state(payload, report_path=report_path)
    if (
        report_path
        and payload.get("action") in {"run_aspen_optimization_once", "approve_optimization_bounds_adjustment"}
        and payload.get("returncode") is not None
        and not payload.get("post_run_import_done")
    ):
        try:
            resolved_report_path = Path(report_path)
            if not resolved_report_path.is_absolute():
                resolved_report_path = (BASE_DIR / resolved_report_path).resolve()
            report_for_import = read_json_default(resolved_report_path, {})
            if report_for_import:
                _, process_summary = import_process_results(report_for_import, resolved_report_path)
                payload["process_result_import"] = process_summary
                payload["post_run_import_done"] = True
                payload["message"] = "{}；本轮 Aspen 结果已自动导入主报告".format(payload.get("message") or "后台任务已结束")
                with ORCH_EXEC_LOCK:
                    ORCH_EXEC_STATE.update({
                        "post_run_import_done": True,
                        "process_result_import": process_summary,
                        "message": payload["message"],
                    })
        except Exception as exc:
            payload["post_run_import_done"] = False
            payload["post_run_import_error"] = "{}: {}".format(exc.__class__.__name__, exc)
            with ORCH_EXEC_LOCK:
                ORCH_EXEC_STATE.update({
                    "post_run_import_error": payload["post_run_import_error"],
                })
    payload = promote_live_progress_summary(attach_orchestrator_live_progress(payload, report_path=report_path))
    if "compute_processes" not in payload:
        payload["compute_processes"] = active_compute_process_summary()
    compute = payload.get("compute_processes") or {}
    payload["process_safety"] = {
        "level": compute.get("safety_status") or "idle",
        "reason": "; ".join(compute.get("unsafe_reasons") or []),
        "active_total": compute.get("active_total") or 0,
        "aspen_count": compute.get("aspen_count") or 0,
        "aspen_limit": compute.get("aspen_limit") or ASPEN_MAX_PARALLEL_PROCESSES,
    }
    autopilot_status = autopilot_status_payload_for_report(report_path)
    if autopilot_status:
        payload["autopilot_status"] = autopilot_status
    if report_path:
        report_for_aspen = read_json_default(report_path, {})
        if report_for_aspen:
            aspen_progress = aspen_progress_summary(report_for_aspen)
            payload["aspen_progress"] = aspen_progress
            compute_for_stale_check = payload.get("compute_processes") or active_compute_process_summary()
            owned_for_stale_check = report_owned_runtime_processes(compute_for_stale_check, report_path)
            live_progress_for_stale_check = payload.get("live_progress") or {}
            live_stage_for_stale_check = (
                live_progress_for_stale_check.get("current_stage")
                or (autopilot_status_payload_for_report(report_path) or {}).get("current_stage")
                or ""
            )
            stage_for_stale_check_active = full_flow_stage_process_count(
                live_stage_for_stale_check,
                compute_for_stale_check,
            ) > 0
            if (
                aspen_progress.get("stale_running_state")
                and not owned_for_stale_check
                and not stage_for_stale_check_active
            ):
                payload["running"] = False
                payload["status"] = "stale_after_reboot"
                payload["returncode"] = 0
                payload["message"] = aspen_progress.get("headline") or "后台状态文件仍显示 running，但没有检测到 Agent、optimizer 或 Aspen 进程。"
                with ORCH_EXEC_LOCK:
                    ORCH_EXEC_STATE.update({
                        "running": False,
                        "status": "stale_after_reboot",
                        "returncode": 0,
                        "message": payload["message"],
                        "pid": None,
                        "finished_at": iso_from_timestamp(time.time()),
                    })
    autopilot_live = payload.get("autopilot_status") or autopilot_status
    autopilot_status_text = str((autopilot_live or {}).get("status") or "").strip().lower()
    autopilot_stage_status_text = str((autopilot_live or {}).get("stage_status") or "").strip().lower()
    live_progress = payload.get("live_progress") or {}
    live_stage = live_progress.get("current_stage") or (autopilot_live or {}).get("current_stage") or ""
    owned_runtime_rows = report_owned_runtime_processes(compute, report_path) if report_path else []
    owned_runtime_active = bool(live_progress.get("owned_runtime_processes") or owned_runtime_rows)
    stage_process_active = full_flow_stage_process_count(live_stage, compute) > 0
    authoritative_running = bool(
        (owned_runtime_active or stage_process_active)
        and (
            str(live_progress.get("status") or "").strip().lower() == "running"
            or autopilot_status_text == "running"
            or autopilot_stage_status_text in {"running", "planning", "started", "delegating"}
        )
    )
    if authoritative_running:
        payload["running"] = True
        payload["status"] = "running"
        payload["returncode"] = None
        payload["finished_at"] = ""
        payload["message"] = live_progress.get("state_note") or (autopilot_live or {}).get("message") or "智能体正在执行当前阶段。"
        if isinstance(payload.get("autopilot_status"), dict):
            live_autopilot_status = dict(payload.get("autopilot_status") or {})
            live_autopilot_status.setdefault("reported_status", live_autopilot_status.get("status") or "")
            live_autopilot_status.setdefault("reported_stage_status", live_autopilot_status.get("stage_status") or "")
            live_autopilot_status.setdefault("reported_current_stage", live_autopilot_status.get("current_stage") or "")
            live_autopilot_status.update({
                "status": "running",
                "stage_status": "running",
                "current_stage": live_stage or live_autopilot_status.get("current_stage") or "",
                "current_action": live_autopilot_status.get("current_action") or "agent_full_flow_autopilot",
                "message": payload["message"],
            })
            payload["autopilot_status"] = live_autopilot_status
        with ORCH_EXEC_LOCK:
            ORCH_EXEC_STATE.update({
                "running": True,
                "status": "running",
                "returncode": None,
                "message": payload["message"],
                "finished_at": "",
            })
    blocked_autopilot_state = bool(
        not authoritative_running
        and int((payload.get("compute_processes") or {}).get("active_total") or 0) <= 0
        and (
            autopilot_status_text.startswith("blocked")
            or autopilot_stage_status_text == "blocked"
        )
    )
    if blocked_autopilot_state:
        payload["running"] = False
        payload["status"] = autopilot_status_text or "blocked"
        payload["returncode"] = payload.get("returncode") if payload.get("returncode") is not None else 3
        payload["message"] = (autopilot_live or {}).get("message") or live_progress.get("state_note") or payload.get("message") or "Agent supervision is blocked."
        with ORCH_EXEC_LOCK:
            ORCH_EXEC_STATE.update({
                "running": False,
                "status": payload["status"],
                "returncode": payload["returncode"],
                "message": payload["message"],
                "finished_at": iso_from_timestamp(time.time()),
            })
    stale_live_state = bool(
        payload.get("running")
        and not authoritative_running
        and int((payload.get("compute_processes") or {}).get("active_total") or 0) <= 0
        and (
            autopilot_status_text == "running"
            or autopilot_stage_status_text in {"running", "planning", "started", "delegating"}
        )
    )
    if stale_live_state:
        payload["running"] = False
        payload["status"] = "stale_after_reboot"
        payload["returncode"] = 0
        payload["message"] = "后台状态文件仍显示 running，但没有检测到本任务的 Agent、Gaussian、Aspen Plus、NCI/VMD 或 GROMACS 进程；应视为上次运行已中断，下一步需要继续启动监督运行。"
        with ORCH_EXEC_LOCK:
            ORCH_EXEC_STATE.update({
                "running": False,
                "status": "stale_after_reboot",
                "returncode": 0,
                "message": payload["message"],
                "pid": None,
                "finished_at": iso_from_timestamp(time.time()),
            })
    if str(payload.get("status") or "").strip().lower() == "stale_after_reboot" and not payload.get("running"):
        stale_progress = dict(payload.get("aspen_progress") or {})
        stale_progress.update({
            "status": "stale_after_reboot",
            "stage_status": "stale",
            "headline": payload.get("message") or stale_progress.get("headline") or "",
            "aspen_process_active": False,
            "stale_running_state": True,
        })
        payload["aspen_progress"] = stale_progress
    return payload


