def dialogue_component_label(row):
    row = row or {}
    code = row.get("code") or row.get("solvent_code") or row.get("aspen_component_id") or ""
    name = row.get("name") or row.get("solvent_name") or ""
    return " / ".join([str(x) for x in [code, name] if str(x or "").strip()]) or "-"


def dialogue_alpha_value(row):
    row = row or {}
    for key in ("alpha_improvement_best", "i_alpha", "alpha_improvement", "candidate_best_i_alpha"):
        value = safe_float(row.get(key))
        if value is not None:
            return value
    return None


def dialogue_alpha_result_stats(report):
    paths = report.get("research_task_package_paths") or {}
    candidates = [
        paths.get("relative_volatility_kvalue_results_csv"),
        ((report.get("live_progress") or {}).get("results_csv")),
    ]
    rows = []
    for candidate in candidates:
        if not candidate:
            continue
        try:
            path = generated_path(candidate, "relative_volatility_kvalue_results_csv")
            rows = read_csv_rows(path)
            if rows:
                break
        except Exception:
            continue
    grouped = {}
    threshold = RELATIVE_VOLATILITY_I_ALPHA_PASS_THRESHOLD
    for row in rows:
        code = component_token(row.get("solvent_code") or row.get("code") or row.get("aspen_component_id"))
        if not code or str(row.get("status") or "").strip() != "imported":
            continue
        i_alpha = safe_float(row.get("alpha_improvement") or row.get("i_alpha") or row.get("Ialpha"))
        if i_alpha is None:
            continue
        item = grouped.setdefault(code, {
            "code": code,
            "name": row.get("solvent_name") or "",
            "rows": 0,
            "row_pass": 0,
            "best_i_alpha": None,
            "min_i_alpha": None,
            "key_values": [],
            "last_case": "",
        })
        item["rows"] += 1
        item["last_case"] = row.get("case_id") or item.get("last_case") or ""
        item["row_pass"] += 1 if i_alpha >= threshold else 0
        item["best_i_alpha"] = i_alpha if item["best_i_alpha"] is None else max(item["best_i_alpha"], i_alpha)
        item["min_i_alpha"] = i_alpha if item["min_i_alpha"] is None else min(item["min_i_alpha"], i_alpha)
        zone = str(row.get("composition_zone") or "")
        if any(token in zone for token in ("feed", "azeotrope", "alpha_hard")):
            item["key_values"].append(i_alpha)
    stats = {}
    for code, item in grouped.items():
        key_values = item.pop("key_values")
        key_pass = sum(1 for value in key_values if value >= threshold)
        item["key_count"] = len(key_values)
        item["key_pass"] = key_pass
        item["key_mean"] = round(sum(key_values) / len(key_values), 5) if key_values else ""
        item["key_min"] = round(min(key_values), 5) if key_values else ""
        item["key_pass_fraction"] = round(key_pass / len(key_values), 3) if key_values else ""
        if item["best_i_alpha"] is not None:
            item["best_i_alpha"] = round(item["best_i_alpha"], 5)
        if item["min_i_alpha"] is not None:
            item["min_i_alpha"] = round(item["min_i_alpha"], 5)
        stats[code] = item
    return stats


def dialogue_alpha_ranked_candidates(pool, result_stats):
    metadata = {}
    for row in pool or []:
        for key in (row.get("code"), row.get("solvent_code"), row.get("aspen_component_id")):
            token = component_token(key)
            if token:
                metadata[token] = row
    ranked = []
    for code, item in (result_stats or {}).items():
        meta = metadata.get(component_token(code)) or {}
        value = safe_float(item.get("best_i_alpha"))
        if value is None:
            continue
        label = dialogue_component_label({
            "code": code,
            "name": item.get("name") or meta.get("name") or meta.get("solvent_name") or "",
        })
        ranked.append({
            "label": label,
            "code": code,
            "name": item.get("name") or meta.get("name") or meta.get("solvent_name") or "",
            "i_alpha": value,
            "best_i_alpha": value,
            "rows": item.get("rows") or "",
            "row_pass": item.get("row_pass") or "",
            "key_mean": item.get("key_mean") or "",
            "key_min": item.get("key_min") or "",
            "key_pass_fraction": item.get("key_pass_fraction") or "",
            "relative_volatility_gate": meta.get("relative_volatility_gate") or "",
            "reason": meta.get("alpha_reason") or "",
        })
    return sorted(ranked, key=lambda row: row.get("i_alpha") or -999, reverse=True)


def dialogue_float_text(value, digits=3):
    number = safe_float(value)
    if number is None:
        return "-"
    return ("{:.%df}" % digits).format(number)


def dialogue_row_code(row):
    row = row or {}
    return str(row.get("code") or row.get("solvent_code") or row.get("aspen_component_id") or "").strip()


def dialogue_candidate_match_tokens(row):
    row = row or {}
    tokens = set()
    for value in (
        row.get("code"),
        row.get("solvent_code"),
        row.get("aspen_component_id"),
        row.get("name"),
        row.get("solvent_name"),
        row.get("label"),
    ):
        value = str(value or "").strip()
        if not value:
            continue
        tokens.add(value.lower())
        normalized = normalize_agent_token(value)
        if normalized:
            tokens.add(normalized.lower())
        code_head = re.split(r"[_\s/,-]+", value, maxsplit=1)[0].strip()
        if len(code_head) >= 2:
            tokens.add(code_head.lower())
            head_norm = normalize_agent_token(code_head)
            if head_norm:
                tokens.add(head_norm.lower())
    return {token for token in tokens if len(token) >= 2}


def dialogue_mentioned_candidate_rows(message, candidates, limit=5):
    text_lower = str(message or "").lower()
    normalized_message = normalize_agent_token(message).lower()
    mentioned = []
    seen = set()
    for row in candidates or []:
        code = dialogue_row_code(row) or dialogue_component_label(row)
        key = normalize_agent_token(code or dialogue_component_label(row))
        if key in seen:
            continue
        tokens = dialogue_candidate_match_tokens(row)
        if any(token and (token in text_lower or token in normalized_message) for token in tokens):
            mentioned.append(row)
            seen.add(key)
            if len(mentioned) >= limit:
                break
    return mentioned


def dialogue_candidate_selection_facts(pool, alpha_ranked, molecular, message):
    pool = [row for row in (pool or []) if isinstance(row, dict)]
    alpha_ranked = [row for row in (alpha_ranked or []) if isinstance(row, dict)]
    selected_code = (
        (molecular or {}).get("selected_solvent_code")
        or (molecular or {}).get("selected_solvent_label")
        or ""
    )
    selected_token = normalize_agent_token(selected_code)
    selected = {}
    selected_rank = None
    for index, row in enumerate(alpha_ranked, start=1):
        row_tokens = {
            normalize_agent_token(row.get("code")),
            normalize_agent_token(row.get("solvent_code")),
            normalize_agent_token(row.get("aspen_component_id")),
            normalize_agent_token(row.get("label")),
        }
        row_tokens.discard("")
        if selected_token and selected_token in row_tokens:
            selected = dict(row)
            selected_rank = index
            break
    if not selected:
        selected = dialogue_find_pool_candidate(pool, selected_code)
    if selected:
        selected.setdefault("label", dialogue_component_label(selected))
        selected.setdefault("code", dialogue_row_code(selected))
    all_candidates = []
    all_candidates.extend(alpha_ranked)
    all_candidates.extend(pool)
    mentioned = dialogue_mentioned_candidate_rows(message, all_candidates, limit=6)
    return {
        "selected": selected or {
            "label": (molecular or {}).get("selected_solvent_label") or "",
            "code": (molecular or {}).get("selected_solvent_code") or "",
        },
        "selected_rank_by_i_alpha": selected_rank,
        "top_alpha_candidates": alpha_ranked[:10],
        "mentioned_candidates": mentioned,
        "selection_rule": (
            "先用 Aspen α / K-value 对全候选池快筛；必须通过 Iα 阈值和关键组成区检查，"
            "再按排序锁定少量候选进入 Gaussian/NCI/GROMACS 分子证据；最终还要等 Aspen 优化闭合后才算最终方案。"
        ),
        "not_final_claim": "当前选中项是分子验证主线候选，不等同于最终工艺最优萃取剂。",
    }


def dialogue_find_pool_candidate(pool, token):
    target = normalize_agent_token(token)
    if not target:
        return {}
    for row in pool or []:
        if not isinstance(row, dict):
            continue
        row_tokens = {
            normalize_agent_token(row.get("code")),
            normalize_agent_token(row.get("solvent_code")),
            normalize_agent_token(row.get("aspen_component_id")),
            normalize_agent_token(row.get("name")),
            normalize_agent_token(row.get("solvent_name")),
        }
        row_tokens.discard("")
        if target in row_tokens:
            return row
    return {}


def dialogue_find_mentioned_candidate(message, candidates):
    message_token = normalize_agent_token(message)
    if not message_token:
        return -1, {}
    for index, row in enumerate(candidates or []):
        tokens = {
            normalize_agent_token(row.get("code")),
            normalize_agent_token(row.get("solvent_code")),
            normalize_agent_token(row.get("aspen_component_id")),
            normalize_agent_token(row.get("name")),
            normalize_agent_token(row.get("label")),
        }
        tokens.discard("")
        for token in tokens:
            if token and token in message_token:
                return index, row
    return -1, {}


def dialogue_molecular_facts(report, brief, pool, runtime_stage, alpha_pending):
    task = report.get("separation_task") or {}
    queue = brief.get("candidate_molecular_task_queue") or []
    active_rows = [
        row for row in queue
        if isinstance(row, dict)
        and str(row.get("execution_policy") or "") == "approved_current_recommendation"
    ]
    auto_code = "" if molecular_selection_is_manual(report) else post_alpha_top_candidate_code(pool)
    selected_code = clean_text_arg(
        auto_code
        or report.get("selected_molecular_solvent_code")
        or task.get("molecular_selected_solvent_code")
        or task.get("selected_solvent_code")
        or ((active_rows[0] or {}).get("solvent_code") if active_rows else ""),
        "",
        max_len=80,
    )
    selected_row = dialogue_find_pool_candidate(pool, selected_code)
    if not selected_row and active_rows:
        selected_row = {
            "code": active_rows[0].get("solvent_code") or selected_code,
            "name": active_rows[0].get("solvent_name") or "",
            "aspen_component_id": active_rows[0].get("aspen_component_id") or "",
            "relative_volatility_gate": active_rows[0].get("relative_volatility_gate") or "",
        }
    selected_label = dialogue_component_label({
        "code": selected_code or selected_row.get("code") or selected_row.get("solvent_code") or selected_row.get("aspen_component_id"),
        "name": selected_row.get("name") or selected_row.get("solvent_name") or "",
    })
    selected_token = normalize_agent_token(selected_code)
    selected_queue_rows = []
    for row in queue:
        if not isinstance(row, dict) or not selected_token:
            continue
        row_tokens = {
            normalize_agent_token(row.get("solvent_code")),
            normalize_agent_token(row.get("aspen_component_id")),
            normalize_agent_token(row.get("solvent_name")),
        }
        row_tokens.discard("")
        if selected_token in row_tokens:
            selected_queue_rows.append(row)
    approved_selected_queue_rows = [
        row for row in selected_queue_rows
        if str(row.get("execution_policy") or "") == "approved_current_recommendation"
    ]
    status_counts = {}
    for row in queue:
        if not isinstance(row, dict):
            continue
        status = str(row.get("status") or "unknown")
        status_counts[status] = status_counts.get(status, 0) + 1
    return {
        "stage_ready": str(runtime_stage or "") == "molecular_queue" or int(alpha_pending or 0) == 0,
        "selected_solvent_code": selected_code,
        "selected_solvent_name": selected_row.get("name") or selected_row.get("solvent_name") or "",
        "selected_solvent_label": selected_label,
        "selected_relative_volatility_gate": selected_row.get("relative_volatility_gate") or "",
        "queue_count": len(queue),
        "approved_queue_count": len(active_rows),
        "selected_queue_count": len(selected_queue_rows),
        "approved_selected_queue_count": len(approved_selected_queue_rows),
        "status_counts": status_counts,
    }


