def dialogue_user_consented(message):
    text_value = str(message or "").strip().lower()
    return bool(re.search(r"(同意|可以|确认|批准|执行|开始|按你|按建议|yes\b|ok\b|go\b)", text_value, re.I))


def dialogue_user_declined(message):
    text_value = str(message or "").strip().lower()
    return bool(re.search(r"(不同意|先不|暂不|不要|别|停止|取消|no\b|not now|do not)", text_value, re.I))


def dialogue_intent(message):
    text_value = str(message or "").strip().lower()
    if re.fullmatch(r"(还有多久|还要多久|多久|多长时间|什么时候结束|什么时候完成)[？?。!！\s]*", text_value, re.I):
        return "status"
    if re.search(r"(图|图片|画图|出图|figure|plot|chart|可视化|曲线|前沿图|收敛图|诊断图|变量图|排名图|误差图|nci|vmd)", text_value, re.I) and re.search(r"(图|图片|画|看|调出|显示|生成|打开|figure|plot|chart|可视化|nci|vmd)", text_value, re.I):
        return "figure_request"
    if re.search(r"((为什么|为啥|怎么).*(还没|没有|没|不).*(停|停止|结束|完|完成|收敛))|((什么时候|多久).*(停|停止|结束|完|完成|收敛))|((还要|还得).*(多久|几代|多少).*(停|停止|结束|完|完成|收敛))", text_value, re.I):
        return "aspen_status"
    if re.search(r"(sf|rr1|rr2|d1|d2|n1|n2|bounds?|range|范围|上下限|参数|变量)", text_value, re.I) and re.search(r"(aspen|topsis|optimization|多目标|优化)", text_value, re.I):
        return "bounds_or_optimization"
    if re.search(r"((现在|当前|这次|本次).*(什么|哪个|哪一个).*(体系|系统))|((体系|系统).*(是什么|是啥|哪个|哪一个))", text_value, re.I):
        return "system_identity"
    if re.search(r"(萃取剂|溶剂|候选)", text_value, re.I) and re.search(r"(有哪些|有哪|哪几|列表|全部|所有|筛选|候选池|候选|多少|排名)", text_value, re.I):
        return "explain_candidate_screening"
    if re.search(r"((现在|当前|这次|本次).*(什么|哪个|哪一个).*(萃取剂|溶剂))|((萃取剂|溶剂).*(是什么|是啥|选了什么|选的什么|哪个|哪一个))", text_value, re.I):
        return "current_solvent_identity"
    if re.search(r"((为什么|为啥|凭什么|理由|依据|怎么).*(没选|不选|没用|不用|不是|没进|不进).*(萃取剂|溶剂|候选|[a-z]{2,}))|((萃取剂|溶剂|候选|[a-z]{2,}).*(为什么|为啥).*(没选|不选|没用|不用|不是|没进|不进))", text_value, re.I):
        return "compare_candidate_choice"
    if re.search(r"((为什么|为啥|凭什么|理由|依据|怎么).*(选|选择|推荐|锁定|用).*(这个|该|当前|萃取剂|溶剂|候选))|((这个|该|当前).*(萃取剂|溶剂|候选).*(为什么|为啥|理由|依据))", text_value, re.I):
        return "explain_selected_solvent"
    if re.search(r"((候选|萃取剂|溶剂).*(从哪|来源|哪来|怎么来|怎么选|怎么筛|筛选逻辑|筛选标准|数量|多少))|(筛选逻辑|筛选标准|候选来源|候选池|候选数量)", text_value, re.I):
        return "explain_candidate_screening"
    if re.search(r"(哪个|哪一个|哪种|谁|萃取剂|溶剂).*(多目标|优化|topsis|case|案例)|((多目标|优化|topsis).*(哪个|哪一个|哪种|谁|萃取剂|溶剂))", text_value, re.I):
        return "optimization_solvent_lookup"
    if re.search(r"\bGENERIC_ASPEN_OPT_\d+\b", text_value, re.I):
        return "optimization_case_lookup"
    if re.search(r"((aspen|多目标|优化).*(跑|开始|启动|完成|完了|结束|收敛|了吗|没有|没|状态|进度|结果))|((跑|开始|启动|完成|完了|结束|收敛).*(aspen|多目标|优化))", text_value, re.I):
        return "aspen_status"
    if re.search(r"(失败|未通过|没过|筛掉|淘汰|fail|failed)|(why|为什么|为啥).*(失败|未通过|没过|筛掉|淘汰)", text_value, re.I):
        return "explain_alpha_failures"
    if re.search(r"(最好|最优|最高|最大|top|排名|排行|谁好|哪个好|相对挥发度|挥发度|iα|ialpha|i_alpha|best)", text_value, re.I):
        return "rank_current_candidates"
    if re.search(r"(卡住|卡死|不动|停了|stuck|hang)", text_value, re.I):
        return "check_stuck"
    if re.search(r"(还在|在干啥|干什么|做什么|进度|状态|跑到哪|算到哪|还有几个|剩几个|待算|没算|status|progress)|现在.*(干啥|干什么|做什么|进度|状态|跑到哪|算到哪)", text_value, re.I):
        return "status"
    if re.search(r"(gaussian|gromacs|分子|为什么还不|下一步|什么时候)", text_value, re.I):
        return "next_step"
    if re.search(r"(范围|参数|边界|重跑|优化|bounds?|profile|sf|rr|n1|n2)", text_value, re.I):
        return "bounds_or_optimization"
    if dialogue_user_consented(text_value):
        return "approval"
    if dialogue_user_declined(text_value):
        return "decline"
    return "general"


def dialogue_format_candidate(row, value_key="i_alpha"):
    if not row:
        return ""
    label = row.get("label") or dialogue_component_label(row)
    value = row.get(value_key)
    if value is None or value == "":
        value = row.get("best_i_alpha")
    if value is None or value == "":
        return label
    try:
        return "{}，Iα {:.3f}".format(label, float(value))
    except Exception:
        return "{}，Iα {}".format(label, value)


def dialogue_case_display(case):
    case = case or {}
    label = case.get("solvent_label") or " / ".join(
        str(part).strip()
        for part in (case.get("solvent_code") or case.get("aspen_component_id"), case.get("solvent_name"))
        if str(part or "").strip()
    )
    bits = []
    if case.get("case_id"):
        bits.append(str(case.get("case_id")))
    if label:
        bits.append(str(label))
    if case.get("TAC"):
        bits.append("TAC {}".format(case.get("TAC")))
    if case.get("topsis_score"):
        bits.append("TOPSIS {}".format(case.get("topsis_score")))
    if case.get("pass_or_fail"):
        bits.append(str(case.get("pass_or_fail")))
    return "，".join(bits)

