def dialogue_format_number(value, digits=4):
    try:
        number = float(value)
    except Exception:
        return str(value) if value not in (None, "") else "-"
    if abs(number - round(number)) < 1e-9:
        return str(int(round(number)))
    return ("{:.%df}" % digits).format(number).rstrip("0").rstrip(".") or "0"


def dialogue_format_range(value):
    if isinstance(value, (list, tuple)) and len(value) >= 2:
        return "{} - {}".format(dialogue_format_number(value[0]), dialogue_format_number(value[1]))
    if value not in (None, ""):
        return dialogue_format_number(value)
    return "-"


def dialogue_bound_pair(bounds, key):
    value = (bounds or {}).get(key)
    if isinstance(value, (list, tuple)) and len(value) >= 2:
        low = safe_float(value[0])
        high = safe_float(value[1])
        if low is not None and high is not None:
            return (min(low, high), max(low, high))
    return (None, None)


def dialogue_clamped_range(center, bounds, key, low_factor=0.7, high_factor=1.4, absolute=None, integer=False):
    center = safe_float(center)
    if center is None:
        return None
    bound_low, bound_high = dialogue_bound_pair(bounds, key)
    if absolute is not None:
        low = center - float(absolute)
        high = center + float(absolute)
    else:
        low = center * float(low_factor)
        high = center * float(high_factor)
    if bound_low is not None:
        low = max(low, bound_low)
    if bound_high is not None:
        high = min(high, bound_high)
    if integer:
        low = int(max(1, round(low)))
        high = int(max(low, round(high)))
    else:
        low = round(low, 6)
        high = round(max(low, high), 6)
    return [low, high]


def dialogue_local_ranges_from_case(case, current_bounds):
    case = case or {}
    current_bounds = current_bounds or {}
    ranges = {}
    range_specs = {
        "SF": {"low_factor": 0.6, "high_factor": 1.8},
        "RR1": {"low_factor": 0.45, "high_factor": 3.0},
        "RR2": {"low_factor": 0.35, "high_factor": 4.0},
        "D1": {"low_factor": 0.96, "high_factor": 1.06},
        "D2": {"low_factor": 0.65, "high_factor": 1.45},
    }
    for key, spec in range_specs.items():
        value = dialogue_clamped_range(case.get(key), current_bounds, key, spec["low_factor"], spec["high_factor"])
        if value is not None:
            ranges[key] = value
    for key, width in (("N1", 25), ("N2", 10)):
        value = dialogue_clamped_range(case.get(key), current_bounds, key, absolute=width, integer=True)
        if value is not None:
            ranges[key] = value
    n1 = safe_float(case.get("N1"))
    n2 = safe_float(case.get("N2"))
    nf1 = safe_float(case.get("NF1"))
    ns1 = safe_float(case.get("NS1"))
    nf2 = safe_float(case.get("NF2"))
    if nf1 is not None and n1 is not None:
        ranges["NF1"] = [max(2, int(round(nf1 - 15))), min(max(2, int(round(n1 - 1))), int(round(nf1 + 20)))]
    if ns1 is not None and n1 is not None:
        ranges["NS1"] = [max(2, int(round(ns1 - 12))), min(max(2, int(round(n1 - 1))), int(round(ns1 + 20)))]
    if nf2 is not None and n2 is not None:
        ranges["NF2"] = [max(2, int(round(nf2 - 3))), min(max(2, int(round(n2 - 1))), int(round(nf2 + 6)))]
    return ranges


def dialogue_expand_observed_range(pair, current_bounds, key, pad_fraction=0.35, min_pad=0.0, integer=False):
    if not isinstance(pair, (list, tuple)) or len(pair) < 2:
        return None
    low = safe_float(pair[0])
    high = safe_float(pair[1])
    if low is None or high is None:
        return None
    low, high = min(low, high), max(low, high)
    width = max(high - low, 0.0)
    pad = max(width * float(pad_fraction), float(min_pad or 0.0))
    expanded = [low - pad, high + pad]
    bound_low, bound_high = dialogue_bound_pair(current_bounds, key)
    if bound_low is not None:
        expanded[0] = max(expanded[0], bound_low)
    if bound_high is not None:
        expanded[1] = min(expanded[1], bound_high)
    if integer:
        integer_floor = 2 if key in {"NF1", "NS1", "NF2"} else 1
        expanded = [int(max(integer_floor, round(expanded[0]))), int(max(integer_floor, round(expanded[1])))]
        if expanded[0] > expanded[1]:
            expanded[0], expanded[1] = expanded[1], expanded[0]
    else:
        expanded = [round(expanded[0], 6), round(max(expanded[0], expanded[1]), 6)]
    return expanded


def dialogue_local_ranges_from_observed(observed_ranges, current_bounds):
    observed_ranges = observed_ranges or {}
    basis = (
        observed_ranges.get("recent_240_pareto")
        or observed_ranges.get("pareto")
        or observed_ranges.get("recent_240_formal")
        or observed_ranges.get("formal")
        or {}
    )
    min_pad = {
        "SF": 0.08,
        "RR1": 0.12,
        "RR2": 0.10,
        "D1": 0.08,
        "D2": 0.06,
        "N1": 3,
        "NF1": 2,
        "NS1": 2,
        "N2": 2,
        "NF2": 1,
    }
    ranges = {}
    for key in DIALOGUE_OPTIMIZATION_VARIABLES:
        value = dialogue_expand_observed_range(
            basis.get(key),
            current_bounds,
            key,
            pad_fraction=0.35,
            min_pad=min_pad.get(key, 0.0),
            integer=key in {"N1", "NF1", "NS1", "N2", "NF2"},
        )
        if value is not None:
            ranges[key] = value
    return ranges


def dialogue_ranges_include_seed(ranges, seed_case):
    ranges = dict(ranges or {})
    seed_case = seed_case or {}
    case_ranges = dialogue_local_ranges_from_case(seed_case, {})
    for key in DIALOGUE_OPTIMIZATION_VARIABLES:
        seed = safe_float(seed_case.get(key))
        if seed is None:
            continue
        pair = ranges.get(key)
        if not (isinstance(pair, (list, tuple)) and len(pair) >= 2):
            if key in case_ranges:
                ranges[key] = case_ranges[key]
            continue
        low = safe_float(pair[0])
        high = safe_float(pair[1])
        if low is None or high is None:
            if key in case_ranges:
                ranges[key] = case_ranges[key]
            continue
        low, high = min(low, high, seed), max(low, high, seed)
        if key in {"N1", "NF1", "NS1", "N2", "NF2"}:
            ranges[key] = [int(max(1, round(low))), int(max(1, round(high)))]
        else:
            ranges[key] = [round(low, 6), round(high, 6)]
    return ranges


def dialogue_optimization_seed_case(facts):
    opt = facts.get("optimization") or {}
    evidence = opt.get("evidence") or {}
    role_cases = evidence.get("role_cases") if isinstance(evidence.get("role_cases"), dict) else {}
    for role in ("repriced_economic_topsis_best", "current_run_topsis_best", "reported_topsis_best", "best_closed_loop", "latest_case"):
        case = role_cases.get(role)
        if isinstance(case, dict) and case.get("case_id"):
            return role, case
    case_lookup = evidence.get("case_lookup") if isinstance(evidence.get("case_lookup"), dict) else {}
    topsis_case = str(opt.get("topsis_best_case_id") or "").strip()
    if topsis_case and isinstance(case_lookup.get(topsis_case), dict):
        return "topsis_best", case_lookup[topsis_case]
    return "", {}


def dialogue_optimization_continuation_advice(facts):
    opt = facts.get("optimization") or {}
    role, seed_case = dialogue_optimization_seed_case(facts)
    historical_report_bounds = opt.get("current_bounds") or opt.get("variable_ranges") or {}
    engineering_start_bounds = opt.get("engineering_start_bounds") or {}
    engineering_purity_bounds = opt.get("engineering_purity_bounds") or {}
    current_bounds = engineering_start_bounds or historical_report_bounds
    observed_ranges = opt.get("observed_variable_ranges") or ((opt.get("evidence") or {}).get("variable_ranges") or {})
    local_ranges = dialogue_local_ranges_from_observed(observed_ranges, current_bounds) or dialogue_local_ranges_from_case(seed_case, current_bounds)
    local_ranges = dialogue_ranges_include_seed(local_ranges, seed_case)
    formal_count = int(safe_float(opt.get("formal_pass_count"), opt.get("current_feasible_count") or 0) or 0)
    purity_count = int(safe_float(opt.get("purity_pass_count"), 0) or 0)
    pareto_count = int(safe_float(opt.get("current_pareto_count") or opt.get("pareto_count"), 0) or 0)
    target_formal = 20
    target_pareto = 5
    count_gate_satisfied = bool(formal_count >= target_formal and pareto_count >= target_pareto)
    converged = bool(opt.get("mainline_multi_objective_converged") or opt.get("multi_objective_converged"))
    diagnostics = opt.get("convergence_diagnostics") or {}
    stagnant = int(safe_float(diagnostics.get("stagnant_generations"), 0) or 0)
    patience = int(safe_float(opt.get("convergence_patience") or (opt.get("campaign") or {}).get("convergence_patience"), 4) or 4)
    continue_recommended = bool((not count_gate_satisfied) or (not converged))
    if formal_count < target_formal:
        reason = "formal_feasible_points_insufficient"
    elif pareto_count < target_pareto:
        reason = "pareto_front_too_small"
    elif not converged:
        reason = "not_converged_patience_not_met"
    else:
        reason = "sufficient_feasible_pareto_and_converged"
    if not continue_recommended:
        reason = "sufficient_feasible_pareto_and_converged"
    stop_rule = {
        "minimum_formal_feasible_points": target_formal,
        "minimum_pareto_points": target_pareto,
        "minimum_generations": opt.get("minimum_generations") or (opt.get("campaign") or {}).get("minimum_generations") or 6,
        "patience": patience,
        "score_epsilon": ((opt.get("convergence_diagnostics") or {}).get("score_epsilon") or 0.002),
    }
    return {
        "continue_recommended": continue_recommended,
        "reason": reason,
        "target_purity": opt.get("target_purity") or "",
        "purity_pass_count": purity_count,
        "formal_feasible_count": formal_count,
        "pareto_front_count": pareto_count,
        "target_formal_feasible_count": target_formal,
        "target_pareto_front_count": target_pareto,
        "count_gate_satisfied": count_gate_satisfied,
        "stagnant_generations": stagnant,
        "convergence_patience": patience,
        "strategy": "seeded_local_nsga2_with_small_global_exploration",
        "seed_role": role,
        "seed_case": {
            key: seed_case.get(key)
            for key in (
                "case_id", "solvent_name", "aspen_component_id", "SF", "RR1", "D1", "RR2", "D2",
                "N1", "NF1", "NS1", "N2", "NF2", "target_purity_mole_frac", "target_recovery",
                "carbon_emission_ton_per_year", "TAC", "objective_recovery_loss",
                "energy_cost", "solvent_loss_total", "topsis_score", "topsis_rank",
            )
        },
        "current_bounds_profile": opt.get("bounds_profile") or "",
        "engineering_start_bounds_profile": opt.get("engineering_start_bounds_profile") or "",
        "engineering_purity_bounds_profile": opt.get("engineering_purity_bounds_profile") or "",
        "current_bounds": current_bounds,
        "historical_report_bounds": historical_report_bounds,
        "engineering_start_bounds": engineering_start_bounds,
        "engineering_purity_bounds": engineering_purity_bounds,
        "observed_variable_ranges": observed_ranges,
        "recommended_local_ranges": local_ranges,
        "global_exploration_fraction": 0.2,
        "local_exploitation_fraction": 0.8,
        "stop_rule": stop_rule,
    }


def dialogue_parameter_question(message):
    text_value = str(message or "")
    return bool(re.search(r"(范围|上下限|参数|变量|是多少|哪些|sf|rr1|rr2|d1|d2|n1|n2|bound|range)", text_value, re.I))


def dialogue_parameter_range_or_advice_question(message):
    text_value = str(message or "")
    return bool(re.search(
        r"(范围|上下限|边界|区间|下一轮|下轮|局部|继续|重跑|扩|收缩|调整|怎么调|怎么优化|该不该|是否还|bound|bounds|range|local|continue|rerun|expand|shrink)",
        text_value,
        re.I,
    ))


def dialogue_best_case_parameter_question(message):
    text_value = str(message or "")
    if dialogue_parameter_range_or_advice_question(text_value):
        return False
    has_parameter = bool(re.search(
        r"(操作参数|工况参数|参数|变量|sf|rr1|rr2|d1|d2|n1|nf1|ns1|n2|nf2|回流比|采出|塔板|级数|solvent[_ ]?flow|reflux|stage)",
        text_value,
        re.I,
    ))
    asks_value = bool(re.search(r"(是什么|是啥|多少|是多少|哪些|哪几个|列出来|给我|分别|what|value|values)", text_value, re.I))
    points_to_best = bool(re.search(r"(最佳|最优|最好|当前|现在|这次|本次|最终|推荐|TOPSIS|topsis|case|案例|方案|操作)", text_value, re.I))
    return bool(has_parameter and (asks_value or points_to_best))


def dialogue_case_first_value(case, *keys):
    case = case or {}
    for key in keys:
        if dialogue_nonempty(case.get(key)):
            return case.get(key)
    return ""


def dialogue_case_solvent_label(case, fallback=""):
    case = case or {}
    label = case.get("solvent_label")
    if label:
        return label
    parts = [
        str(case.get("solvent_code") or case.get("aspen_component_id") or "").strip(),
        str(case.get("solvent_name") or "").strip(),
    ]
    label = " / ".join(part for part in parts if part)
    return label or fallback or "-"


def dialogue_case_value_for_display(key, value):
    if key in {"target_purity_mole_frac", "purity", "target_recovery", "recovery"}:
        return dialogue_format_number(value, digits=9)
    if key in {"TAC", "energy_cost"}:
        return dialogue_format_number(value, digits=2)
    if key in {"carbon_emission_ton_per_year", "carbon_emission", "co2"}:
        return dialogue_format_number(value, digits=3)
    if key in {"topsis_score", "TOPSIS"}:
        return dialogue_format_number(value, digits=8)
    return dialogue_format_number(value, digits=6)


def dialogue_best_case_parameter_reply(facts):
    opt = facts.get("optimization") or {}
    role, best_case = dialogue_optimization_seed_case(facts)
    if not best_case:
        return "我现在没有在当前事实包里解析到 TOPSIS 最佳 case，所以不能编参数。需要先有 optimizer report 或 process_result_import 里的 case 行。"

    label = dialogue_case_solvent_label(best_case, opt.get("optimized_solvent_label") or opt.get("selected_solvent_label") or "")
    case_id = best_case.get("case_id") or opt.get("topsis_best_case_id") or "-"
    operation_items = [
        ("SF", "SF"),
        ("solvent_flow_kmol_hr", "solvent_flow_kmol_hr"),
        ("RR1", "RR1"),
        ("RR2", "RR2"),
        ("D1", "D1"),
        ("D2", "D2"),
        ("N1", "N1"),
        ("NF1", "NF1"),
        ("NS1", "NS1"),
        ("N2", "N2"),
        ("NF2", "NF2"),
        ("condenser_mode", "condenser_mode"),
        ("distillate_phase", "distillate_phase"),
        ("target_product_stream", "target_product_stream"),
    ]
    metric_items = [
        ("target_purity_mole_frac", "purity"),
        ("target_recovery", "recovery"),
        ("TAC", "TAC"),
        ("energy_cost", "energy_cost"),
        ("carbon_emission_ton_per_year", "carbon_emission_ton_per_year"),
        ("topsis_score", "TOPSIS score"),
    ]
    parameter_lines = []
    for key, label_text in operation_items:
        value = dialogue_case_first_value(best_case, key)
        if dialogue_nonempty(value):
            parameter_lines.append("{} = {}".format(label_text, dialogue_case_value_for_display(key, value)))
    metric_lines = []
    for key, label_text in metric_items:
        value = dialogue_case_first_value(best_case, key, "purity" if key == "target_purity_mole_frac" else "recovery" if key == "target_recovery" else key)
        if dialogue_nonempty(value):
            metric_lines.append("{} = {}".format(label_text, dialogue_case_value_for_display(key, value)))
    lines = [
        "当前最佳操作参数是 {}（{}）：".format(case_id, label),
        "\n".join(parameter_lines) if parameter_lines else "参数行尚未解析完整。",
    ]
    if metric_lines:
        lines.append("结果指标：{}。".format("；".join(metric_lines)))
    if opt.get("alignment_status") == "mismatch":
        lines.append("注意：这条结果和当前锁定萃取剂不一致，不能当作当前主线最终方案。")
    elif opt.get("alignment_status") == "unknown":
        lines.append("注意：这条结果还没有完成当前体系/萃取剂来源核对。")
    return "\n".join(lines)


def dialogue_case_parameter_line(case):
    case = case or {}
    parts = []
    for key in OPTIMIZATION_CASE_PARAMETER_ORDER:
        if dialogue_nonempty(case.get(key)):
            parts.append("{}={}".format(key, dialogue_format_number(case.get(key))))
    if dialogue_nonempty(case.get("TAC")):
        parts.append("TAC={}".format(dialogue_format_number(case.get("TAC"), digits=2)))
    if dialogue_nonempty(case.get("topsis_score")):
        parts.append("TOPSIS={}".format(dialogue_format_number(case.get("topsis_score"), digits=4)))
    return "；".join(parts)


def dialogue_optimization_parameters_reply(facts):
    opt = facts.get("optimization") or {}
    evidence = opt.get("evidence") or {}
    role_cases = evidence.get("role_cases") or {}
    selected = opt.get("selected_solvent_label") or opt.get("selected_solvent_code") or "-"
    optimized = opt.get("optimized_solvent_label") or selected
    profile = opt.get("bounds_profile") or opt.get("recommended_profile") or "-"
    ranges = opt.get("variable_ranges") or opt.get("current_bounds") or opt.get("recommended_bounds") or {}
    notes = opt.get("variable_notes") or {}
    campaign = opt.get("campaign") or {}

    range_lines = []
    for key in OPTIMIZATION_VARIABLE_ORDER:
        if key not in ranges:
            continue
        label = OPTIMIZATION_VARIABLE_LABELS.get(key, key)
        suffix = ""
        if key in {"D1", "D2"}:
            suffix = " kmol/h"
        elif key in {"N1", "N2", "NF1_BOTTOM_MARGIN", "NF1_NS1_MIN_GAP"}:
            suffix = " 级"
        line = "{}：{}{}".format(label, dialogue_format_range(ranges.get(key)), suffix)
        if notes.get(key) and key in {"D1", "D2"}:
            line += "（{}）".format(notes.get(key))
        range_lines.append(line)

    best_case = (
        role_cases.get("repriced_economic_topsis_best")
        or role_cases.get("current_run_topsis_best")
        or role_cases.get("reported_topsis_best")
        or role_cases.get("latest_case")
        or {}
    )
    case_label = best_case.get("solvent_label") or best_case.get("solvent_name") or best_case.get("aspen_component_id") or optimized
    case_line = dialogue_case_parameter_line(best_case)

    campaign_bits = []
    if campaign.get("population_size"):
        campaign_bits.append("种群 {}".format(campaign.get("population_size")))
    if campaign.get("minimum_case_count"):
        campaign_bits.append("最低案例 {}".format(campaign.get("minimum_case_count")))
    if campaign.get("minimum_feasible_case_count"):
        campaign_bits.append("最低可行点 {}".format(campaign.get("minimum_feasible_case_count")))
    if campaign.get("convergence_patience"):
        campaign_bits.append("连续无改进 {} 代才停".format(campaign.get("convergence_patience")))

    lines = [
        "可以看。当前这轮 Aspen 多目标优化属于 {}，当前锁定萃取剂是 {}。".format(optimized, selected),
        "使用的范围配置是 {}。优化变量范围：".format(profile),
    ]
    lines.extend(range_lines or ["当前事实包没有解析到变量范围，这属于后端状态缺字段。"])
    if campaign_bits:
        lines.append("运行规则：{}。".format("；".join(campaign_bits)))
    if best_case:
        lines.append("当前 TOPSIS 临时最优是 {}（{}）：{}。".format(
            best_case.get("case_id") or "-",
            case_label,
            case_line or "参数行尚未解析完整",
        ))
    advice = dialogue_optimization_continuation_advice(facts)
    if advice.get("recommended_local_ranges"):
        local_lines = dialogue_compact_mapping(advice.get("recommended_local_ranges"), limit=12)
        seed = advice.get("seed_case") or {}
        lines.append("继续优化建议：{}；当前纯度达标点 {} 个、正式可行点 {} 个、Pareto {} 个。".format(
            "应该继续" if advice.get("continue_recommended") else "暂时可停止",
            dialogue_value_text(advice.get("purity_pass_count"), "0"),
            dialogue_value_text(advice.get("formal_feasible_count"), "0"),
            dialogue_value_text(advice.get("pareto_front_count"), "0"),
        ))
        lines.append("建议围绕 {} 做局部搜索；推荐下一轮变量范围：{}。".format(
            seed.get("case_id") or "-",
            "；".join(local_lines),
        ))
    if opt.get("alignment_status") == "mismatch":
        lines.append("注意：这条优化结果和当前锁定萃取剂不一致，只能当旁证，不能算主线完成。")
    elif opt.get("alignment_status") == "matched":
        lines.append("来源判断：当前优化报告和锁定萃取剂匹配，是主线结果。")
    return "\n".join(lines)


def dialogue_primary_optimization_case(facts):
    evidence = (((facts.get("optimization") or {}).get("evidence") or {}))
    role_cases = evidence.get("role_cases") or {}
    for role in ("current_run_topsis_best", "reported_topsis_best", "best_closed_loop", "imported_baseline_topsis_best", "latest_case"):
        case = role_cases.get(role)
        if case and (case.get("solvent_label") or case.get("solvent_name") or case.get("aspen_component_id")):
            return role, case
    for case in (evidence.get("case_lookup") or {}).values():
        if case and (case.get("solvent_label") or case.get("solvent_name") or case.get("aspen_component_id")):
            return "case_lookup", case
    return "", {}


def dialogue_reply_has_solvent(reply, case):
    reply = str(reply or "")
    case = case or {}
    tokens = [
        case.get("solvent_label"),
        case.get("solvent_name"),
        case.get("solvent_code"),
        case.get("aspen_component_id"),
    ]
    return any(token and str(token) in reply for token in tokens)


def dialogue_clean_activity_name(value):
    value = str(value or "").strip().replace("\\", "/")
    if not value:
        return "-"
    name = value.split("/")[-1]
    for suffix in (".gjf", ".out", ".log", ".chk", ".fch", ".fchk"):
        if name.lower().endswith(suffix):
            name = name[: -len(suffix)]
            break
    return name or "-"


def dialogue_gaussian_job_purpose(job_name):
    job = str(job_name or "")
    if job.endswith("_cp"):
        parts = [part for part in job[:-3].split("_") if part]
        if len(parts) >= 2:
            return "{} + {} 的双分子/BSSE 计算".format(parts[0].upper(), parts[1].upper())
        return "双分子/BSSE 计算"
    if job.endswith("_monomer_opt"):
        return "{} 的单分子结构优化".format(job[: -len("_monomer_opt")].upper())
    return "量子化学任务"


def dialogue_runtime_stage_row(runtime, label):
    wanted = str(label or "").strip().lower()
    for row in (runtime or {}).get("stages") or []:
        if str(row.get("label") or "").strip().lower() == wanted:
            return row
    return {}


DIALOGUE_MOLECULAR_STAGE_ORDER = (
    ("Gaussian", "gaussian"),
    ("NCI/VMD", "nci_vmd"),
    ("GROMACS", "gromacs"),
)


def dialogue_molecular_gate_from_facts(facts):
    runtime = (facts or {}).get("runtime") or {}

    def _stage_int(value):
        try:
            return int(float(value or 0))
        except Exception:
            return 0

    rows = []
    for label, key in DIALOGUE_MOLECULAR_STAGE_ORDER:
        src = dialogue_runtime_stage_row(runtime, label)
        total = _stage_int(src.get("total"))
        completed = _stage_int(src.get("completed"))
        pending = _stage_int(src.get("pending"))
        if total > 0:
            pending = max(pending, total - completed, 0)
        rows.append({
            "label": label,
            "key": key,
            "total": total,
            "completed": completed,
            "pending": pending,
            "ready": _stage_int(src.get("ready")),
            "status": src.get("status") or ("missing" if total <= 0 else ""),
            "next": src.get("next") or "",
        })

    incomplete = []
    current_blocking_stage = ""
    for row in rows:
        if row["total"] <= 0:
            incomplete.append("{} 未生成".format(row["label"]))
        elif row["pending"] > 0 or row["completed"] < row["total"]:
            incomplete.append("{} {}/{}".format(row["label"], row["completed"], row["total"]))
        if not current_blocking_stage and (row["total"] <= 0 or row["pending"] > 0 or row["completed"] < row["total"]):
            current_blocking_stage = row["key"]

    summary = "，".join(
        "{} {}".format(row["label"], "{}/{}".format(row["completed"], row["total"]) if row["total"] > 0 else "未生成")
        for row in rows
    )
    gate_open = bool(rows and not incomplete)
    return {
        "gate_open": gate_open,
        "policy": "Gaussian + NCI/VMD + GROMACS must all be complete before current-system Aspen optimization",
        "summary": summary,
        "stage_rows": rows,
        "incomplete_stages": incomplete,
        "current_blocking_stage": current_blocking_stage,
        "pending_count": sum(row["pending"] for row in rows) + sum(1 for row in rows if row["total"] <= 0),
    }


def dialogue_molecular_gate_blocked_lines(facts, selected=""):
    gate = dialogue_molecular_gate_from_facts(facts)
    opt = (facts or {}).get("optimization") or {}
    runtime = (facts or {}).get("runtime") or {}
    selected = selected or opt.get("selected_solvent_label") or opt.get("selected_solvent_code") or "当前锁定萃取剂"
    stage_key = gate.get("current_blocking_stage") or "gaussian"
    rows = {row.get("key"): row for row in gate.get("stage_rows") or []}
    blocking_row = rows.get(stage_key) or {}
    stage_label = {
        "gaussian": "Gaussian 分子验证",
        "nci_vmd": "NCI/VMD 相互作用图",
        "gromacs": "GROMACS 分子动力学",
    }.get(stage_key, "分子证据")
    next_item = str(blocking_row.get("next") or "").strip()
    if next_item:
        next_item = next_item.replace("\\", "/").split("/")[-1]
        for suffix in (".gjf", ".out", ".log", ".chk", ".fch", ".fchk"):
            if next_item.lower().endswith(suffix):
                next_item = next_item[: -len(suffix)]
                break
    next_action = {
        "gaussian": "等待当前 Gaussian 跑完并生成 .fch，然后智能体进入 NCI/VMD。",
        "nci_vmd": "生成或导入当前体系当前溶剂的 NCI/VMD 相互作用图。",
        "gromacs": "完成或导入当前体系当前溶剂的 GROMACS MD/RDF/相互作用能证据。",
    }.get(stage_key, "先补齐当前体系当前溶剂的分子证据。")
    total_cases = runtime.get("total_cases")
    completed_cases = runtime.get("completed_cases")
    percent = runtime.get("percent")
    progress_bits = []
    if completed_cases not in ("", None) and total_cases not in ("", None):
        progress_bits.append("总进度 {}/{}".format(completed_cases, total_cases))
    if percent not in ("", None):
        progress_bits.append("{}%".format(percent))
    progress_text = "（{}）".format("，".join(progress_bits)) if progress_bits else ""
    first = "现在在{}阶段{}{}。".format(
        " " + stage_label,
        "，正在处理 {}".format(next_item) if next_item else "",
        progress_text,
    )
    remaining_bits = [
        "{} 还剩 {} 个".format(row.get("label"), row.get("pending"))
        for row in gate.get("stage_rows") or []
        if row.get("pending") not in (None, "", 0, "0")
    ]
    lines = [
        first,
        "当前分子证据进度：{}；锁定萃取剂是 {}。".format(gate.get("summary") or "分子阶段缺少实时统计", selected),
        "还剩：{}；Gaussian 长计算没有可靠的分钟级 ETA，当前文件仍在更新就说明还在正常推进。".format("，".join(remaining_bits)) if remaining_bits else "当前分子证据没有未完成队列项。",
        "后续：{}；Aspen 多目标优化会等这个分子闸门闭合后再开始。".format(next_action.rstrip("。")),
    ]
    gromacs_done = bool(rows.get("gromacs") and rows["gromacs"].get("total", 0) > 0 and rows["gromacs"].get("pending", 0) <= 0)
    if gromacs_done and not gate.get("gate_open"):
        lines.insert(2, "这里 GROMACS 2/2 只是说明 MD 证据已导入，整套分子证据还要等 Gaussian 和 NCI/VMD。")
    return lines


def dialogue_molecular_gate_direct_prefix(message):
    text_value = str(message or "").strip().lower()
    asks_molecular_ready = re.search(
        r"(分子|gaussian|nci|vmd|gromacs).*(就绪|好了|完成|完了|跑完|ready|done)",
        text_value,
        re.I,
    )
    asks_aspen_started = (
        re.search(r"(aspen|多目标|优化|topsis|pareto).*(开始|启动|跑了|跑吗|跑了吗|了吗|进了吗)", text_value, re.I)
        or re.search(r"(开始|启动|跑了|跑吗|跑了吗).*(aspen|多目标|优化|topsis|pareto)", text_value, re.I)
    )
    asks_aspen_converged = re.search(r"(aspen|多目标|优化|topsis|pareto|pass).*(收敛|结果|完成|完了)", text_value, re.I)
    if asks_molecular_ready:
        return "直接答案：分子证据还没就绪。"
    if asks_aspen_converged:
        return "直接答案：Aspen 多目标优化还没开始，所以还没有收敛/Pareto/TOPSIS 结果。"
    if asks_aspen_started:
        return "直接答案：Aspen 多目标优化还没开始；当前要先补齐分子证据。"
    return ""


def dialogue_stage_key(facts):
    runtime = facts.get("runtime") or {}
    alpha = facts.get("alpha") or {}
    optimization = facts.get("optimization") or {}
    raw = str(runtime.get("active_stage") or runtime.get("stage") or runtime.get("queue_stage") or "").strip().lower()
    if "report" in raw or "publication" in raw:
        return "report"
    if "candidate" in raw or "solvent_pool" in raw:
        return "candidates"
    if "component" in raw or "identity" in raw or "system_analysis" in raw:
        return "analysis"
    if "property_strategy" in raw or "strategy_review" in raw:
        return "alpha"
    if "alpha" in raw or "relative_volatility" in raw:
        return "alpha"
    if int(alpha.get("pending") or 0) > 0:
        return "alpha"
    molecular_gate = dialogue_molecular_gate_from_facts(facts)
    if (
        not molecular_gate.get("gate_open")
        and molecular_gate.get("current_blocking_stage")
        and ("aspen" in raw or "optimization" in raw or "topsis" in raw)
    ):
        return molecular_gate.get("current_blocking_stage")
    if "aspen" in raw or "optimization" in raw or "topsis" in raw:
        return "aspen"
    normalized = normalized_full_flow_stage(raw)
    if normalized in {"gaussian", "nci_vmd", "gromacs", "aspen", "complete"}:
        return normalized
    for label, key in (("Gaussian", "gaussian"), ("NCI/VMD", "nci_vmd"), ("GROMACS", "gromacs")):
        row = dialogue_runtime_stage_row(runtime, label)
        total = int(row.get("total") or 0)
        completed = int(row.get("completed") or 0)
        if row and (total <= 0 or completed < total or int(row.get("pending") or 0) > 0):
            return key
    if not molecular_gate.get("gate_open") and molecular_gate.get("current_blocking_stage"):
        return molecular_gate.get("current_blocking_stage")
    if optimization.get("alignment_status") in {"mismatch", "unknown"} or optimization.get("mainline_aspen_optimization_required"):
        return "aspen_pending"
    if optimization.get("mainline_multi_objective_converged"):
        return "complete"
    if str(runtime.get("status") or "").lower() in {"complete", "completed", "done"}:
        return "complete"
    return "generic"


def dialogue_stage_snapshot(facts):
    runtime = facts.get("runtime") or {}
    processes = facts.get("processes") or {}
    key = dialogue_stage_key(facts)
    stage_labels = {
        "analysis": "体系分析",
        "candidates": "候选萃取剂筛选",
        "alpha": "Aspen α 筛选",
        "gaussian": "Gaussian",
        "nci_vmd": "NCI/VMD",
        "gromacs": "GROMACS",
        "aspen_pending": "主线 Aspen 待启动",
        "aspen": "Aspen 优化",
        "report": "报告生成",
        "complete": "全流程完成",
        "generic": "当前任务",
    }
    row = {
        "gaussian": dialogue_runtime_stage_row(runtime, "Gaussian"),
        "nci_vmd": dialogue_runtime_stage_row(runtime, "NCI/VMD"),
        "gromacs": dialogue_runtime_stage_row(runtime, "GROMACS"),
    }.get(key, {})
    process_count = {
        "gaussian": int(processes.get("gaussian_driver") or processes.get("gaussian") or 0),
        "nci_vmd": int(processes.get("nci_vmd") or 0),
        "gromacs": int(processes.get("gromacs") or 0),
        "aspen_pending": int(processes.get("aspen") or 0),
        "aspen": int(processes.get("aspen") or 0),
    }.get(key, int(processes.get("agent_runtime") or 0))
    status_text = str(runtime.get("status") or runtime.get("live_status") or "").strip().lower()
    stage_status = str(runtime.get("stage_status") or "").strip().lower()
    interrupted = status_text == "stale_after_reboot" or stage_status == "interrupted"
    blocked = "blocked" in status_text or stage_status == "blocked"
    return {
        "key": key,
        "label": stage_labels.get(key, "当前任务"),
        "running": bool(runtime.get("running") or process_count > 0),
        "interrupted": interrupted,
        "blocked": blocked,
        "process_count": process_count,
        "completed": int(row.get("completed") or 0),
        "total": int(row.get("total") or 0),
        "pending": int(row.get("pending") or 0),
        "next_item": row.get("next") or "",
        "latest": runtime.get("latest_activity") or {},
        "runtime": runtime,
        "processes": processes,
    }


