def dialogue_stage_reply_alpha(facts, snap):
    alpha = facts.get("alpha") or {}
    current = facts.get("current_candidate") or {}
    blocker = alpha.get("global_blocker") or {}
    completed = int(alpha.get("completed") or 0)
    total = int(alpha.get("total") or 0)
    pending = int(alpha.get("pending") or 0)
    if blocker.get("blocked"):
        reason = str(blocker.get("reason") or blocker.get("status") or "base alpha0 不可信").rstrip("。.;； ")
        next_label = blocker.get("next_action_label") or alpha.get("next_action_label") or "复核 Aspen 物性"
        current_label = current.get("label") if current.get("label") and current.get("label") != "-" else "下一支候选"
        return [
            "当前没有卡在某个候选剂计算上，而是 Aspen α/K-value 入口被全局阻塞。",
            "已完成 {}/{}，通过 {}，待算 {}；下一支本来是 {}，但现在不能继续运行下一候选。".format(completed, total, int(alpha.get("pass") or 0), pending, current_label),
            "原因：{}。下一步：{}。".format(reason, next_label),
        ]
    lines = [
        "正在用 Aspen flash/K-value 筛选候选萃取剂{}。".format("，当前是 {}".format(current.get("label")) if current.get("label") and current.get("label") != "-" else ""),
        "候选池已完成 {}/{}，通过 {}，待计算 {}。".format(completed, total, int(alpha.get("pass") or 0), pending),
    ]
    lines.append(
        "全部筛完后会按 Iα 排名选择候选进入 Gaussian。"
        if pending else
        "α 全池已完成，下一步按 Iα 排名进入 Gaussian 分子验证。"
    )
    return lines


