def dialogue_stage_reply_gromacs(facts, snap):
    latest = snap.get("latest") or {}
    case_name = str(latest.get("case_dir") or "").strip()
    if not case_name:
        relative = str(latest.get("relative_path") or snap.get("next_item") or "").replace("\\", "/")
        parts = [part for part in relative.split("/") if part]
        case_name = parts[-2] if len(parts) >= 2 else (parts[-1] if parts else "当前算例")
    progress = latest.get("progress") or {}
    current_ps = safe_float(progress.get("current_time_ps"))
    total_ps = safe_float(progress.get("total_time_ps"))
    percent = safe_float(progress.get("percent"))
    if current_ps is not None and total_ps:
        internal = "已完成 {:.1f}/{:.1f} ps（{:.1f}%）".format(current_ps, total_ps, percent if percent is not None else current_ps * 100 / total_ps)
    elif percent is not None:
        internal = "当前完成 {:.1f}%".format(percent)
    else:
        internal = "正在运行"
    return [
        "正在进行 GROMACS 分子动力学，当前算例是 {}，{}。".format(case_name, internal),
        "本阶段需要形成 {} 个最终结果，目前完成 {} 个；内部百分比表示当前算例进度。".format(snap.get("total", 0), snap.get("completed", 0)),
        "当前算例结束后会继续队列；全部完成后自动导入证据并判断是否解锁 Aspen 优化。",
    ]


def dialogue_stage_reply_aspen_pending(facts, snap):
    opt = facts.get("optimization") or {}
    selected = opt.get("selected_solvent_label") or opt.get("selected_solvent_code") or "当前锁定萃取剂"
    molecular_gate = dialogue_molecular_gate_from_facts(facts)
    if not molecular_gate.get("gate_open"):
        return dialogue_molecular_gate_blocked_lines(facts, selected)
    optimized = opt.get("optimized_solvent_label") or "已有优化结果"
    alignment = opt.get("alignment_status") or ""
    if alignment == "mismatch":
        first = "结论：当前主线 Aspen 还没完成。已收敛记录属于 {}，不是当前锁定的 {}。".format(optimized, selected)
    elif alignment == "unknown":
        first = "结论：已有 Aspen 优化记录，但还不能确认它属于当前锁定的 {}，所以主线 Aspen 仍待核对。".format(selected)
    else:
        first = "结论：分子证据已就绪，当前主线 Aspen 优化还没有完成。"
    return [
        first,
        "旁支或未核对的优化结果只能作为参考证据，不能直接进入当前体系的报告结论。",
        "下一步应由智能体启动或导入 {} 的 Aspen 优化，并继续保持 AspenPlus 最多 1 个实例。".format(selected),
    ]


def dialogue_mainline_aspen_pending_reply(message, facts):
    opt = facts.get("optimization") or {}
    alignment = opt.get("alignment_status") or ""
    if alignment not in {"mismatch", "unknown"} and not opt.get("mainline_aspen_optimization_required"):
        return None

    intent = dialogue_intent(message)
    text_value = str(message or "").strip().lower()
    if intent in {
        "system_identity",
        "current_solvent_identity",
        "explain_selected_solvent",
        "compare_candidate_choice",
        "explain_candidate_screening",
        "rank_current_candidates",
        "explain_alpha_failures",
    }:
        return None
    asks_aspen_state = bool(
        re.search(r"(aspen|多目标|优化|收敛|topsis|报告|最终)", text_value, re.I)
        or re.search(r"(下一步|继续|进度|状态|跑|开始|启动)", text_value, re.I)
        or re.search(r"(现在|当前).*(干啥|干什么|做什么|到哪|进度|状态|跑|开始|启动)", text_value, re.I)
    )
    if intent not in {"aspen_status", "status", "next_step", "check_stuck", "bounds_or_optimization"} and not asks_aspen_state:
        return None

    selected = opt.get("selected_solvent_label") or opt.get("selected_solvent_code") or "当前锁定萃取剂"
    molecular_gate = dialogue_molecular_gate_from_facts(facts)
    if not molecular_gate.get("gate_open"):
        lines = dialogue_molecular_gate_blocked_lines(facts, selected)
        prefix = dialogue_molecular_gate_direct_prefix(message)
        if prefix and lines and not lines[0].startswith("直接答案："):
            lines.insert(0, prefix)
        return {
            "handled": True,
            "intent": intent,
            "reply": "\n".join(lines),
            "facts_used": ["molecular_gate.stage_rows", "optimization.selected_solvent_label", "runtime.stages"],
            "needs_user_approval": False,
            "mainline_aspen_guard": True,
            "molecular_gate_guard": True,
        }
    optimized = opt.get("optimized_solvent_label") or "已有优化结果"
    case_count = opt.get("current_case_count") or opt.get("case_count") or 0
    pass_count = opt.get("current_pass_count") or opt.get("pass_count") or 0
    pareto_count = opt.get("current_pareto_count") or opt.get("pareto_count") or 0
    topsis_case = opt.get("topsis_best_case_id") or "-"
    tac = opt.get("topsis_best_TAC") or "-"

    if alignment == "mismatch":
        first = "直接答案：当前主线 {} 的 Aspen 还没跑完，也没有主线收敛结果。".format(selected)
        second = "已有收敛/TOPSIS 记录属于 {}，不是当前锁定的 {}，所以只能当旁支证据，不能算当前体系 Aspen 完成。".format(optimized, selected)
    elif alignment == "unknown":
        first = "直接答案：当前主线 {} 的 Aspen 还不能判定已完成。".format(selected)
        second = "已有优化记录还没有和当前锁定萃取剂完成来源核对，所以不能直接当作主线收敛结果。"
    else:
        first = "直接答案：分子证据已经就绪，但当前主线 {} 的 Aspen 优化还没闭合。".format(selected)
        second = "下一步需要由智能体启动或导入当前主线 Aspen 优化。"

    details = []
    if case_count:
        details.append("旁支优化规模：{} cases，PASS {}，Pareto {}。".format(case_count, pass_count, pareto_count))
    if topsis_case and topsis_case != "-":
        details.append("旁支 TOPSIS：{}，TAC={}。".format(topsis_case, tac))
    details.append("下一步：让智能体只针对 {} 启动/导入 Aspen 优化，继续保持 AspenPlus 最多 1 个实例。".format(selected))
    return {
        "handled": True,
        "intent": intent,
        "reply": "\n".join([first, second] + details),
        "facts_used": ["optimization.alignment_status", "optimization.selected_solvent_label", "optimization.optimized_solvent_label"],
        "needs_user_approval": False,
        "mainline_aspen_guard": True,
    }


def dialogue_recent_count_from_message(message, default=4):
    text_value = str(message or "")
    match = re.search(r"(?:近|最近|最后|前)\s*(\d{1,2})\s*(?:个|代|次|轮)?", text_value, re.I)
    if match:
        return max(1, min(20, int(match.group(1))))
    chinese_digits = {
        "一": 1, "两": 2, "二": 2, "三": 3, "四": 4, "五": 5,
        "六": 6, "七": 7, "八": 8, "九": 9, "十": 10,
    }
    match = re.search(r"(?:近|最近|最后|前)\s*([一两二三四五六七八九十])\s*(?:个|代|次|轮)?", text_value)
    if match:
        return chinese_digits.get(match.group(1), default)
    if re.search(r"(几|多少)", text_value):
        return default
    return default


def dialogue_optimization_metric_reply(message, facts):
    text_value = str(message or "").strip()
    q = text_value.lower()
    asks_metric = bool(re.search(r"(误差|残差|差值|改进量|变化量|epsilon|阈值|delta|improvement|stagnant|停滞)", text_value, re.I))
    asks_stop = bool(re.search(r"((为什么|为啥|怎么).*(还没|没有|没|不).*(停|停止|结束|完|完成|收敛))|((什么时候|多久).*(停|停止|结束|完|完成|收敛))", text_value, re.I))
    asks_convergence = bool(re.search(r"(收敛|conver)", text_value, re.I) and re.search(r"(了吗|没有|没|多少|几|差|误差|残差|阈值|停滞|为什么|多久|什么时候)", text_value, re.I))
    if not (asks_metric or asks_stop or asks_convergence):
        return None
    opt = facts.get("optimization") or {}
    diag = opt.get("convergence_diagnostics") or {}
    rows = diag.get("recent_deltas") or diag.get("last_four_deltas") or diag.get("recent_history") or []
    if not rows:
        return None
    n = dialogue_recent_count_from_message(message, default=4)
    selected_rows = rows[-n:]
    epsilon = diag.get("score_epsilon")
    stagnant = diag.get("stagnant_generations")
    patience = diag.get("patience")
    min_generations = diag.get("min_generations")
    latest_generation = diag.get("latest_generation")
    status = diag.get("status") or opt.get("convergence_status") or ""
    converged = bool(diag.get("converged") or opt.get("mainline_multi_objective_converged"))
    solvent = opt.get("selected_solvent_label") or opt.get("selected_solvent_code") or "当前主线萃取剂"
    parts = []
    for row in selected_rows:
        generation = row.get("generation")
        delta = row.get("delta_topsis_score")
        score = row.get("topsis_best_score")
        case_id = row.get("topsis_best_case_id") or ""
        if delta in ("", None):
            continue
        parts.append("第{}代：ΔTOPSIS={}（score {}，{}）".format(
            generation,
            dialogue_float_text(delta, 8),
            dialogue_float_text(score, 8),
            case_id,
        ))
    if not parts:
        return None
    first = "这里的“误差/残差”不是 Aspen 求解残差，我按多目标优化的逐代 TOPSIS 变化量 ΔTOPSIS 来看。"
    if asks_stop:
        first = "还没停的原因是：当前 {} 的优化还没有满足连续停滞判据。".format(solvent)
    elif asks_convergence and not asks_metric:
        first = "当前 {} 的多目标优化{}。".format(solvent, "已经收敛" if converged else "还没有收敛")
    lines = [
        first,
        "最近{}个逐代变化量：{}。".format(len(parts), "；".join(parts)),
    ]
    if any((safe_float(row.get("delta_topsis_score")) or 0.0) < 0.0 for row in selected_rows):
        lines.append("其中负值表示这一代重排/归一化后的 TOPSIS 分数低于上一代快照，不代表 Aspen 算错，也不能叫“有效改进”。")
    if epsilon not in ("", None):
        lines.append("当前 score_epsilon={}；低于它只是“可能停滞”的一部分，还要同时看目标函数/Pareto 变化。".format(dialogue_float_text(epsilon, 8)))
    if patience not in ("", None):
        lines.append("停止规则：至少 {} 代后，连续 {} 代无有效改进才停；现在停滞计数是 {} / {}，最新代数 {}，状态 {}。".format(
            min_generations or "-",
            patience,
            stagnant if stagnant not in ("", None) else "-",
            patience,
            latest_generation or "-",
            status or "-",
        ))
    if selected_rows and selected_rows[-1].get("delta_topsis_score") not in ("", None) and epsilon not in ("", None):
        latest_delta = safe_float(selected_rows[-1].get("delta_topsis_score"))
        eps = safe_float(epsilon)
        if latest_delta is not None and eps is not None and latest_delta < eps:
            lines.append("注意：最后一个 ΔTOPSIS={} 已低于 score_epsilon，但前面几代仍有明显改进，且综合停滞计数还没到 patience，所以不会立刻停。".format(dialogue_float_text(latest_delta, 8)))
    return {
        "handled": True,
        "intent": "optimization_metric_query",
        "reply": "\n".join(lines),
        "facts_used": ["optimization.convergence_diagnostics"],
        "needs_user_approval": False,
    }


def dialogue_stage_reply_aspen(facts, snap):
    opt = facts.get("optimization") or {}
    if opt.get("alignment_status") in {"mismatch", "unknown"} or opt.get("mainline_aspen_optimization_required"):
        return dialogue_stage_reply_aspen_pending(facts, snap)
    cases = int(opt.get("current_case_count") or opt.get("case_count") or 0)
    passes = int(opt.get("current_pass_count") or opt.get("pass_count") or 0)
    pareto = int(opt.get("current_pareto_count") or opt.get("pareto_count") or 0)
    generation = opt.get("current_generation")
    converged = bool(opt.get("multi_objective_converged"))
    return [
        "正在进行当前体系的 Aspen 多目标优化{}。".format("，当前第 {} 代".format(generation) if generation not in (None, "", 0, "0") else ""),
        "已计算 {} 个案例，PASS {} 个，Pareto 前沿 {} 个。".format(cases, passes, pareto),
        "已满足收敛条件，下一步生成最终报告。" if converged else "智能体会继续串行计算，直到满足收敛规则后再选择 TOPSIS 方案。",
    ]


def dialogue_stage_reply_report(facts, snap):
    return [
        "正在汇总当前体系的最终报告。",
        "报告会整合候选筛选、Aspen α、分子证据、流程优化和 TOPSIS 结果。",
        "写入完成后会给出最终方案和证据文件位置。",
    ]


def dialogue_stage_reply_complete(facts, snap):
    return [
        "当前体系的自动流程已经完成。",
        "候选筛选、分子验证、Aspen 优化和结果汇总均已闭合。",
        "现在可以查看最终方案、TOPSIS 结果和报告证据。",
    ]


DIALOGUE_STAGE_PRESENTERS = {
    "analysis": dialogue_stage_reply_analysis,
    "candidates": dialogue_stage_reply_candidates,
    "alpha": dialogue_stage_reply_alpha,
    "gaussian": dialogue_stage_reply_gaussian,
    "nci_vmd": dialogue_stage_reply_nci,
    "gromacs": dialogue_stage_reply_gromacs,
    "aspen_pending": dialogue_stage_reply_aspen_pending,
    "aspen": dialogue_stage_reply_aspen,
    "report": dialogue_stage_reply_report,
    "complete": dialogue_stage_reply_complete,
}


def dialogue_stage_status_reply(message, facts, intent="status"):
    snap = dialogue_stage_snapshot(facts)
    presenter = DIALOGUE_STAGE_PRESENTERS.get(snap.get("key"))
    lines = presenter(facts, snap) if presenter else [
        "当前处于 {}。".format(snap.get("label") or "后台任务"),
        "智能体正在同步任务状态和最新文件证据。",
        "状态确认后会自动给出下一步。",
    ]
    if intent == "check_stuck":
        if snap.get("running") and snap.get("process_count") > 0:
            lines[0] = "没有卡住。" + lines[0]
        elif snap.get("interrupted"):
            lines[0] = "当前计算已中断。上次停在 {}。".format(snap.get("label"))
            lines[-1] = "需要从该阶段恢复，已完成的文件会继续复用。"
        elif not snap.get("running"):
            lines[0] = "当前没有活跃计算进程，停在 {}。".format(snap.get("label"))
    if snap.get("blocked"):
        blocker = str((snap.get("runtime") or {}).get("message") or "").strip()
        lines.append("阻塞原因：{}".format(blocker or "当前阶段的必需证据尚未满足。"))
    if snap.get("key") in {"gaussian", "nci_vmd", "gromacs"}:
        prefix = dialogue_molecular_gate_direct_prefix(message)
        if prefix and lines and not lines[0].startswith("直接答案："):
            lines.insert(0, prefix)
    if snap.get("key") == "alpha" and re.search(r"(aspen|多目标|优化|topsis|收敛|开始|启动)", str(message or ""), re.I):
        lines.append("注意：这里的 Aspen 指 α/K-value 预筛，不是后面的 Aspen 多目标优化；多目标优化要等 α 筛选和分子验证闭合后才会开始。")
    safety = str((snap.get("processes") or {}).get("safety_status") or "").strip().lower()
    if safety == "unsafe":
        lines.append("资源风险：检测到进程数量超过安全限制，智能体已停止继续扩容。")
    if re.search(r"(详细|具体|全部|完整|detail|full)", str(message or ""), re.I):
        runtime = snap.get("runtime") or {}
        completed = [
            "{} {}/{}".format(row.get("label"), int(row.get("completed") or 0), int(row.get("total") or 0))
            for row in runtime.get("stages") or []
            if int(row.get("total") or 0) > 0
        ]
        if completed:
            lines.append("阶段明细：{}。".format("；".join(completed)))
    return "\n".join(lines)


def dialogue_candidate_metrics_text(row):
    row = row or {}
    parts = []
    value = row.get("best_i_alpha")
    if value in (None, ""):
        value = row.get("i_alpha") or row.get("alpha_improvement_best")
    if value not in (None, ""):
        parts.append("best Iα {}".format(dialogue_float_text(value, 3)))
    if row.get("key_mean") not in (None, ""):
        parts.append("关键区均值 {}".format(dialogue_float_text(row.get("key_mean"), 3)))
    if row.get("key_min") not in (None, ""):
        parts.append("关键区最低 {}".format(dialogue_float_text(row.get("key_min"), 3)))
    if row.get("row_pass") not in (None, "") and row.get("rows") not in (None, ""):
        parts.append("通过点 {}/{}".format(row.get("row_pass"), row.get("rows")))
    if row.get("relative_volatility_gate"):
        parts.append("闸门 {}".format(row.get("relative_volatility_gate")))
    return "，".join(parts)


def dialogue_candidate_source_line(facts):
    strategy = facts.get("candidate_strategy") or {}
    seeds = strategy.get("seed_strategy") or []
    families = []
    for row in seeds[:3]:
        family = str(row.get("family") or "").strip()
        examples = str(row.get("examples") or "").strip()
        reason = str(row.get("reason") or "").strip()
        item = family
        if examples:
            item = "{}（{}）".format(item, examples) if item else examples
        if reason:
            item = "{}：{}".format(item, reason) if item else reason
        if item:
            families.append(item)
    if families:
        return "候选来源：{}。".format("；".join(families))
    pool_count = strategy.get("pool_count")
    return "候选来源：当前报告候选池{}，再经 Aspen α 闸门筛选。".format("共 {} 个".format(pool_count) if pool_count else "")


def dialogue_selected_solvent_explanation(message, facts, compare=False, screening_only=False):
    alpha = facts.get("alpha") or {}
    selection = facts.get("candidate_selection") or {}
    strategy = facts.get("candidate_strategy") or {}
    selected = selection.get("selected") or {}
    selected_label = selected.get("label") or dialogue_component_label(selected)
    top = selection.get("top_alpha_candidates") or facts.get("alpha_ranked_candidates") or []
    mentioned = selection.get("mentioned_candidates") or []
    threshold = strategy.get("alpha_threshold") or alpha.get("threshold") or RELATIVE_VOLATILITY_I_ALPHA_PASS_THRESHOLD
    rank = selection.get("selected_rank_by_i_alpha")

    if screening_only:
        top_line = "；".join(dialogue_format_candidate(row) for row in top[:6]) or "暂无可排序 Iα 结果"
        return "\n".join([
            "不是无休止地算。候选先来自体系诊断和候选库，再用 Aspen α 快筛收缩范围；当前候选池数量是 {}，Iα 闸门阈值是 {}。".format(
                strategy.get("pool_count") or alpha.get("total") or "-",
                threshold,
            ),
            dialogue_candidate_source_line(facts),
            "筛选规则：{}。".format(strategy.get("selection_rule") or "先 α 快筛，再进分子证据，最后才做 Aspen 优化。"),
            "当前 α 排名前列：{}。".format(top_line),
        ])

    lines = []
    if selected_label and selected_label != "-":
        lines.append("当前不是临时随便选；进入分子验证主线的是 {}。".format(selected_label))
    else:
        lines.append("当前还没有稳定锁定进入分子验证的萃取剂。")

    metric_line = dialogue_candidate_metrics_text(selected)
    if metric_line:
        rank_text = "，Iα 排名第 {}".format(rank) if rank else ""
        lines.append("选择依据：它通过 Aspen α 快筛{}，{}；闸门阈值是 Iα ≥ {}。".format(rank_text, metric_line, threshold))
    else:
        lines.append("选择依据：按当前候选池的 α 快筛、关键组成区检查和分子验证队列规则锁定；如果没有 Iα 数据，会继续等真实结果导入。")

    if compare and mentioned:
        compare_lines = []
        selected_token = normalize_agent_token(dialogue_row_code(selected) or selected_label)
        for row in mentioned[:4]:
            row_label = row.get("label") or dialogue_component_label(row)
            if selected_token and normalize_agent_token(dialogue_row_code(row) or row_label) == selected_token:
                continue
            metrics = dialogue_candidate_metrics_text(row)
            compare_lines.append("{}：{}".format(row_label, metrics or "当前事实包里没有可比较的 Iα/闸门结果"))
        if compare_lines:
            lines.append("你提到的候选对比：{}。".format("；".join(compare_lines)))

    top_line = "；".join(dialogue_format_candidate(row) for row in top[:5])
    if top_line:
        lines.append("当前 α 排名前列：{}。".format(top_line))
    lines.append(dialogue_candidate_source_line(facts))
    lines.append("注意：{} 后面还要等 Gaussian/NCI/GROMACS 和 Aspen 优化闭合，才是最终工艺结论。".format(
        strategy.get("not_final_claim") or "这个选择只是分子验证主线候选，不是最终萃取剂"
    ))
    return "\n".join(line for line in lines if line)


def fallback_agent_dialogue_reply(message, facts):
    intent = dialogue_intent(message)
    alpha = facts.get("alpha") or {}
    alpha_global_blocker = alpha.get("global_blocker") or {}
    runtime = facts.get("runtime") or {}
    current = facts.get("current_candidate") or {}
    processes = facts.get("processes") or {}
    ranked_alpha = facts.get("alpha_ranked_candidates") or []
    top = ranked_alpha or facts.get("top_candidates") or []
    failed = facts.get("screened_out_candidates") or []
    molecular = facts.get("molecular") or {}
    threshold = alpha.get("threshold") or RELATIVE_VOLATILITY_I_ALPHA_PASS_THRESHOLD
    alpha_pending = int(alpha.get("pending") or 0)
    alpha_completed = int(alpha.get("completed") or 0)
    alpha_total = int(alpha.get("total") or 0)
    alpha_complete = bool(alpha_total and alpha_completed >= alpha_total and alpha_pending <= 0)
    runtime_stage = str(runtime.get("stage") or "")
    active_stage = str(runtime.get("active_stage") or runtime_stage or "")
    queue_stage = str(runtime.get("queue_stage") or "")
    runtime_interrupted = (
        str(runtime.get("status") or runtime.get("live_status") or "").strip().lower() == "stale_after_reboot"
        or str(runtime.get("stage_status") or "").strip().lower() == "interrupted"
    )

    if intent in {"status", "next_step", "check_stuck"}:
        return {
            "handled": True,
            "intent": intent,
            "reply": dialogue_stage_status_reply(message, facts, intent),
            "facts_used": ["runtime", "current_stage", "stage_progress", "next_action"],
            "needs_user_approval": False,
        }

    if intent == "system_identity":
        task = facts.get("task") or {}
        system = task.get("system") or "当前报告未提供体系名称"
        target = task.get("target_product") or "-"
        solvent = (facts.get("molecular") or {}).get("selected_solvent_label") or "尚未锁定"
        return {
            "handled": True,
            "intent": intent,
            "reply": "当前体系是 {}，目标产物是 {}。当前分子验证锁定的萃取剂是 {}。".format(system, target, solvent),
            "facts_used": ["task.system", "task.target_product", "molecular.selected_solvent_label"],
            "needs_user_approval": False,
        }

    if intent == "current_solvent_identity":
        molecular_facts = facts.get("molecular") or {}
        solvent = molecular_facts.get("selected_solvent_label") or "尚未锁定"
        gate = molecular_facts.get("selected_relative_volatility_gate") or ""
        return {
            "handled": True,
            "intent": intent,
            "reply": "当前分子验证锁定的萃取剂是 {}{}。".format(solvent, "，α 闸门状态为 {}".format(gate) if gate else ""),
            "facts_used": ["molecular.selected_solvent_label", "molecular.selected_relative_volatility_gate"],
            "needs_user_approval": False,
        }

    if intent in {"explain_selected_solvent", "compare_candidate_choice", "explain_candidate_screening"}:
        return {
            "handled": True,
            "intent": intent,
            "reply": dialogue_selected_solvent_explanation(
                message,
                facts,
                compare=(intent == "compare_candidate_choice"),
                screening_only=(intent == "explain_candidate_screening"),
            ),
            "facts_used": ["candidate_strategy", "candidate_selection", "alpha_ranked_candidates", "molecular"],
            "needs_user_approval": False,
        }

    if intent == "aspen_status":
        if dialogue_stage_key(facts) in {"alpha", "gaussian", "nci_vmd", "gromacs", "aspen_pending"}:
            return {
                "handled": True,
                "intent": intent,
                "reply": dialogue_stage_status_reply(message, facts, intent),
                "facts_used": ["runtime", "current_stage", "stage_progress", "process_safety"],
                "needs_user_approval": False,
            }
        opt = facts.get("optimization") or {}
        forced = dialogue_mainline_aspen_pending_reply(message, facts)
        if forced:
            return forced
        selected = opt.get("selected_solvent_label") or opt.get("selected_solvent_code") or "当前锁定萃取剂"
        case_count = opt.get("current_case_count") or opt.get("case_count") or 0
        pass_count = opt.get("current_pass_count") or opt.get("pass_count") or 0
        pareto_count = opt.get("current_pareto_count") or opt.get("pareto_count") or 0
        topsis_case = opt.get("topsis_best_case_id") or "-"
        if opt.get("mainline_multi_objective_converged"):
            answer = "直接答案：当前主线 {} 的 Aspen 多目标优化已经收敛。".format(selected)
            detail = "证据：{} cases，PASS {}，Pareto {}，TOPSIS {}。".format(case_count, pass_count, pareto_count, topsis_case)
        elif case_count:
            answer = "直接答案：当前主线 {} 的 Aspen 已有优化记录，但还没有满足主线收敛判断。".format(selected)
            detail = "当前记录：{} cases，PASS {}，Pareto {}，TOPSIS {}。".format(case_count, pass_count, pareto_count, topsis_case)
        else:
            answer = "直接答案：当前主线 {} 的 Aspen 优化还没有开始或还没有导入有效结果。".format(selected)
            detail = "下一步需要启动或导入当前主线 Aspen 优化，并保持 AspenPlus 最多 1 个实例。"
        return {
            "handled": True,
            "intent": intent,
            "reply": "\n".join([answer, detail]),
            "facts_used": ["optimization.mainline_multi_objective_converged", "optimization.alignment_status", "optimization.case_count"],
            "needs_user_approval": False,
        }

    def stage_name(value):
        value = str(value or "")
        return {
            "gaussian": "Gaussian",
            "nci_vmd": "NCI/VMD",
            "gromacs": "GROMACS",
            "molecular_queue": "molecular_queue",
            "alpha_queue": "Aspen α",
            "relative_volatility_flash": "Aspen α",
        }.get(value, value or "-")

    def runtime_progress_line():
        if not runtime.get("running") and not runtime_interrupted:
            return ""
        bits = []
        if runtime.get("completed_cases") != "" and runtime.get("total_cases") != "":
            bits.append("实时进度：{}/{}，待做 {}".format(
                runtime.get("completed_cases"),
                runtime.get("total_cases"),
                runtime.get("pending_cases") if runtime.get("pending_cases") != "" else "-",
            ))
        latest = runtime.get("latest_activity") or {}
        if latest.get("relative_path"):
            bits.append("当前文件：{}".format(latest.get("relative_path")))
        return "；".join(bits)

    def runtime_stage_row(label):
        label_lower = str(label or "").strip().lower()
        for row in runtime.get("stages") or []:
            if str(row.get("label") or "").strip().lower() == label_lower:
                return row
        return {}

    def clean_runtime_job_name(value):
        value = str(value or "").strip()
        if not value:
            value = str((runtime.get("latest_activity") or {}).get("relative_path") or "").strip()
        if not value:
            return "-"
        value = value.replace("\\", "/").split("/")[-1]
        for suffix in (".gjf", ".out", ".log", ".chk", ".fch", ".fchk"):
            if value.lower().endswith(suffix):
                value = value[: -len(suffix)]
                break
        return value or "-"

    def explain_gaussian_job(job_name):
        job = str(job_name or "")
        if job.endswith("_cp"):
            parts = [part for part in job[:-3].split("_") if part]
            if len(parts) >= 2:
                return "{} + {} 的双分子/BSSE 优化".format(parts[0].upper(), parts[1].upper())
            return "双分子/BSSE 优化"
        if job.endswith("_monomer_opt"):
            return "{} 的单分子结构优化".format(job[: -len("_monomer_opt")].upper())
        return "Gaussian 任务"

    def human_status_reply():
        gaussian_row = runtime_stage_row("Gaussian")
        nci_row = runtime_stage_row("NCI/VMD")
        gromacs_row = runtime_stage_row("GROMACS")
        latest = runtime.get("latest_activity") or {}
        effective_stage = normalized_full_flow_stage(active_stage or runtime_stage)
        gaussian_driver = int(processes.get("gaussian_driver") or 0)
        gaussian_link = int(processes.get("gaussian_link") or 0)
        gaussian_active = gaussian_driver > 0
        nci_active = int(processes.get("nci_vmd") or 0) > 0
        gromacs_active = int(processes.get("gromacs") or 0) > 0
        aspen_active = int(processes.get("aspen") or 0) > 0
        molecular_gate = dialogue_molecular_gate_from_facts(facts)
        molecular_gate_open = bool(molecular_gate.get("gate_open"))
        if gromacs_active or (runtime.get("running") and effective_stage == "gromacs"):
            case_name = str(latest.get("case_dir") or "").strip()
            if not case_name:
                relative = str(latest.get("relative_path") or gromacs_row.get("next") or "").replace("\\", "/")
                parts = [part for part in relative.split("/") if part]
                case_name = parts[-2] if len(parts) >= 2 else (parts[-1] if parts else "当前 GROMACS 算例")
            md_progress = latest.get("progress") or {}
            current_ps = safe_float(md_progress.get("current_time_ps"))
            total_ps = safe_float(md_progress.get("total_time_ps"))
            percent = safe_float(md_progress.get("percent"))
            if current_ps is not None and total_ps:
                progress_text = "，MD {:.1f} / {:.1f} ps（{:.1f}%）".format(current_ps, total_ps, percent or current_ps * 100 / total_ps)
            elif percent is not None:
                progress_text = "，当前 {:.1f}%".format(percent)
            else:
                progress_text = ""
            conclusion = "结论：现在处于 GROMACS 阶段，正在运行分子动力学，不是在跑 Gaussian 或 Aspen。"
            current_line = "正在算：{}{}；两个目标结果当前完成 {}/{}。".format(
                case_name,
                progress_text,
                gromacs_row.get("completed", 0),
                gromacs_row.get("total", 0),
            )
            process_line = "进程：GROMACS {}，Gaussian {}，AspenPlus {}/{}；当前受单进程限流保护。".format(
                processes.get("gromacs", 0),
                processes.get("gaussian", 0),
                processes.get("aspen", 0),
                processes.get("aspen_limit", 1),
            )
        elif nci_active or (runtime.get("running") and effective_stage == "nci_vmd"):
            job_name = clean_runtime_job_name(nci_row.get("next") or latest.get("relative_path"))
            conclusion = "结论：现在处于 NCI/VMD 阶段，正在生成或导入分子相互作用图。"
            current_line = "正在处理：{}；当前完成 {}/{}。".format(job_name, nci_row.get("completed", 0), nci_row.get("total", 0))
            process_line = "进程：NCI/VMD {}，Gaussian {}，GROMACS {}。".format(
                processes.get("nci_vmd", 0), processes.get("gaussian", 0), processes.get("gromacs", 0)
            )
        elif gaussian_active or (runtime.get("running") and effective_stage == "gaussian"):
            job_name = clean_runtime_job_name(gaussian_row.get("next") or latest.get("relative_path"))
            conclusion = "结论：现在正在跑 Gaussian，不是在跑 Aspen 或 GROMACS。"
            current_line = "正在算：{}，也就是 {}。".format(job_name, explain_gaussian_job(job_name))
            process_line = "进程：1 个 Gaussian 主任务在跑；旁边的 link 进程 {} 个是 Gaussian 自己的子步骤，不代表同时跑了多个任务。".format(gaussian_link)
        elif (aspen_active or (runtime.get("running") and effective_stage == "aspen")) and not molecular_gate_open:
            conclusion = "结论：现在不能算 Aspen 优化阶段，分子证据还没闭合。"
            current_line = "闸门进度：{}。".format(molecular_gate.get("summary") or "缺少分子阶段统计")
            process_line = "进程：AspenPlus {}/{}，Gaussian {}，GROMACS {}；Aspen 即使有旁支记录，也要等分子闸门闭合后才进主线。".format(
                processes.get("aspen", 0), processes.get("aspen_limit", 1), processes.get("gaussian", 0), processes.get("gromacs", 0)
            )
        elif aspen_active or (runtime.get("running") and effective_stage == "aspen"):
            conclusion = "结论：分子证据已过闸门，现在处于 Aspen 优化阶段。"
            current_line = "正在执行当前体系的 Aspen 优化，分子任务不会并行重跑。"
            process_line = "进程：AspenPlus {}/{}，Gaussian {}，GROMACS {}。".format(
                processes.get("aspen", 0), processes.get("aspen_limit", 1), processes.get("gaussian", 0), processes.get("gromacs", 0)
            )
        elif runtime_interrupted:
            interrupted_label = stage_name(effective_stage or active_stage or runtime_stage)
            stage_row = {"gaussian": gaussian_row, "nci_vmd": nci_row, "gromacs": gromacs_row}.get(effective_stage, {})
            next_item = clean_runtime_job_name(stage_row.get("next") or latest.get("relative_path"))
            conclusion = "结论：现在没有长计算进程；上次停在 {} 阶段，需要从这里恢复。".format(interrupted_label)
            current_line = "下一步要继续：{}，当前阶段完成 {}/{}。".format(next_item, stage_row.get("completed", 0), stage_row.get("total", 0))
            process_line = "进程：AspenPlus 0，Gaussian 0，GROMACS 0。"
        else:
            waiting_label = stage_name(effective_stage or active_stage or runtime_stage)
            stage_row = {"gaussian": gaussian_row, "nci_vmd": nci_row, "gromacs": gromacs_row}.get(effective_stage, {})
            next_item = clean_runtime_job_name(stage_row.get("next") or latest.get("relative_path"))
            conclusion = "结论：当前没有长计算进程；{} 阶段已就绪，等待智能体恢复。".format(waiting_label)
            current_line = "下一步要做：{}，当前阶段完成 {}/{}。".format(next_item, stage_row.get("completed", 0), stage_row.get("total", 0))
            process_line = "进程：AspenPlus {}，Gaussian {}，GROMACS {}。".format(
                processes.get("aspen", 0),
                processes.get("gaussian_driver") or processes.get("gaussian", 0),
                processes.get("gromacs", 0),
            )
        selected = molecular.get("selected_solvent_label") or current.get("label") or "-"
        best = dialogue_format_candidate(top[0]) if top else selected
        gaussian_progress = "{} / {}".format(gaussian_row.get("completed", runtime.get("completed_cases") or 0), gaussian_row.get("total", "-"))
        nci_progress = "{} / {}".format(nci_row.get("completed", 0), nci_row.get("total", 0))
        gromacs_progress = "{} / {}".format(gromacs_row.get("completed", 0), gromacs_row.get("total", 0))
        remaining = []
        if gaussian_row:
            remaining.append("Gaussian 还剩 {} 个".format(gaussian_row.get("pending", 0)))
        if nci_row:
            remaining.append("NCI/VMD 还剩 {} 个".format(nci_row.get("pending", 0)))
        if gromacs_row:
            remaining.append("GROMACS 还剩 {} 个".format(gromacs_row.get("pending", 0)))
        resource_line = "资源限制：Gaussian 一次 1 个 job；GROMACS 一次 1 个任务；AspenPlus 最多 1 个实例。"
        lines = [
            conclusion,
            current_line,
            "为什么会到这里：α 相对挥发度预筛已经完成 {}/{}，当前选中 {}；Iα 最高的是 {}。".format(
                alpha_completed,
                alpha_total,
                selected,
                best,
            ),
            "进度：Gaussian {}；NCI/VMD {}；GROMACS {}。{}".format(
                gaussian_progress,
                nci_progress,
                gromacs_progress,
                "后面：" + "，".join(remaining) + "。" if remaining else "",
            ),
            process_line,
            resource_line,
        ]
        return "\n".join(lines)

    if intent in ("optimization_solvent_lookup", "optimization_case_lookup"):
        evidence = ((facts.get("optimization") or {}).get("evidence") or {})
        role, case = dialogue_primary_optimization_case(facts)
        if case:
            role_text = {
                "current_run_topsis_best": "当前本轮 TOPSIS 最优",
                "reported_topsis_best": "当前报告 TOPSIS 最优",
                "best_closed_loop": "当前闭环最低 TAC / 最优可行",
                "imported_baseline_topsis_best": "历史基线 TOPSIS 最优",
                "latest_case": "最近写入的优化 case",
                "case_lookup": "你问到的优化 case",
            }.get(role, "优化结果")
            solvent = case.get("solvent_label") or case.get("solvent_name") or case.get("aspen_component_id") or "-"
            lines = [
                "直接答案：{}对应的萃取剂是 {}。".format(role_text, solvent),
                "证据：{}。".format(dialogue_case_display(case)),
            ]
            opt = facts.get("optimization") or {}
            if opt.get("multi_objective_converged"):
                lines.append("多目标状态：已收敛。")
            if opt.get("alignment_status") == "mismatch":
                lines.append("主线判断：这条优化属于 {}，当前锁定的是 {}，所以它是旁支证据，不能说明当前主线 Aspen 已完成。".format(
                    opt.get("optimized_solvent_label") or solvent,
                    opt.get("selected_solvent_label") or opt.get("selected_solvent_code") or "-",
                ))
            elif opt.get("alignment_status") == "unknown":
                lines.append("主线判断：这条优化还没有和当前锁定萃取剂完成来源核对，不能直接当作主线收敛。")
            if (facts.get("alpha") or {}).get("pending", 0):
                lines.append("注意：这和当前监督运行的 α 全池预筛是两条状态线；当前 α 预筛还没结束，所以 Gaussian/GROMACS 仍不会启动。")
            return {
                "handled": True,
                "intent": intent,
                "reply": "\n".join(lines),
                "facts_used": ["optimization.evidence.case_lookup", "optimization.evidence.role_cases", "runtime/alpha distinction"],
                "needs_user_approval": False,
            }
        missing = "、".join(evidence.get("lookup_case_ids") or []) or "当前 TOPSIS / 优化 case_id"
        return {
            "handled": True,
            "intent": intent,
            "reply": "我知道要怎么查，但这次没有在当前 optimizer report 或 process_result_import.csv 里解析到 {} 对应的萃取剂。需要先导入或刷新优化结果表。".format(missing),
            "facts_used": ["optimization.evidence.sources", "optimization.evidence.lookup_case_ids"],
            "needs_user_approval": False,
        }

    if intent == "approval" and facts.get("pending_action"):
        action = facts["pending_action"]
        action_name = action.get("action") or action.get("type") or ""
        if action_name in DIALOGUE_REQUIRES_APPROVAL_ACTIONS:
            return {
                "handled": True,
                "intent": "approval",
                "reply": "收到你的同意。我不会让语言模型直接执行，接下来交给后端规则动作执行：{}。".format(action_name),
                "facts_used": ["pending_action", "safety_policy"],
                "execute_action": {"action": action_name, "params": action.get("params") or {}},
                "needs_user_approval": False,
            }
    if intent == "decline" and facts.get("pending_action"):
        return {
            "handled": True,
            "intent": "decline",
            "reply": "好的，这个建议先不执行。我会保留当前结果和诊断，只继续按已经允许的流程读取状态。",
            "facts_used": ["pending_action"],
            "pending_action": None,
            "needs_user_approval": False,
        }

    if intent == "explain_alpha_failures":
        if not failed:
            reply = "目前事实包里还没有候选被 α 闸门筛掉。当前仍在 {}，候选池完成 {}/{}。".format(
                runtime.get("stage") or "后台任务",
                alpha.get("completed", 0),
                alpha.get("total", 0),
            )
        else:
            details = []
            for row in failed[:4]:
                details.append("{}：最好 Iα {}，关键区均值 {}，关键区最低 {}。".format(
                    row.get("label") or row.get("code") or "-",
                    row.get("best_i_alpha") if row.get("best_i_alpha") != "" else "-",
                    row.get("key_mean") if row.get("key_mean") != "" else "-",
                    row.get("key_min") if row.get("key_min") != "" else "-",
                ))
            reply = (
                "这里的“未通过”不是 Aspen 崩了，而是 α 闸门没过。阈值是 Iα ≥ {}，而且要看关键组成区，不只看单个最好点。\n"
                "{}\n"
                "所以这些候选暂时不会进入 Gaussian/GROMACS。"
            ).format(threshold, "\n".join(details))
        return {"handled": True, "intent": intent, "reply": reply, "facts_used": ["alpha", "screened_out_candidates"], "needs_user_approval": False}

    if intent == "rank_current_candidates":
        rank_limit = len(top) if re.search(r"(所有|全部|完整|全量|all|full)", str(message or ""), re.I) else min(12, len(top))
        ranked = "；".join(
            "{}. {}".format(index + 1, dialogue_format_candidate(row))
            for index, row in enumerate(top[:rank_limit])
        ) or "还没有稳定 Top 候选"
        lines = []
        if top:
            mentioned_index, mentioned = dialogue_find_mentioned_candidate(message, top)
            if mentioned:
                if mentioned_index == 0:
                    lines.append("是，按当前已取得 Iα 的结果，{} 最高。".format(dialogue_format_candidate(top[0])))
                else:
                    lines.append("不是，按当前已取得 Iα 的结果，{} 最高；你问到的 {} 排第 {}。".format(
                        dialogue_format_candidate(top[0]),
                        dialogue_format_candidate(mentioned),
                        mentioned_index + 1,
                    ))
            else:
                lines.append("当前 Iα 最高的是 {}。".format(dialogue_format_candidate(top[0])))
        qualifier = "全池还没筛完，所以这是暂列排名，不是最终锁定。" if alpha_pending else "全池已筛完，可以作为进入分子验证的排序依据。"
        if alpha.get("unranked_completed_count", 0):
            qualifier += " 另有 {} 个已完成项没有可排序 Iα，通常是 blocked 或未形成有效 imported α 结果，不参与排名。".format(alpha.get("unranked_completed_count"))
        if molecular.get("selected_solvent_label"):
            qualifier += " 注意：Iα 排名第一不等于已经进入分子模拟；当前分子验证目标候选是 {}。".format(
                molecular.get("selected_solvent_label")
            )
        lines.append("当前按 Iα 排名：{}".format(ranked))
        lines.append("已取得 Iα 的候选 {} 个；候选池完成 {}/{}，待算 {}。".format(
            alpha.get("ranked_with_i_alpha_count", len(top)),
            alpha_completed,
            alpha_total,
            alpha_pending,
        ))
        lines.append(qualifier)
        reply = "\n".join(lines)
        return {"handled": True, "intent": intent, "reply": reply, "facts_used": ["alpha_ranked_candidates", "alpha.pending", "molecular"], "needs_user_approval": False}

    if intent == "bounds_or_optimization":
        opt = facts.get("optimization") or {}
        if dialogue_best_case_parameter_question(message):
            return {
                "handled": True,
                "intent": "optimization_best_case_parameters",
                "reply": dialogue_best_case_parameter_reply(facts),
                "facts_used": ["optimization.evidence.role_cases", "optimizer_report_rows", "topsis_best_case"],
                "needs_user_approval": False,
            }
        if dialogue_parameter_question(message):
            return {
                "handled": True,
                "intent": intent,
                "reply": dialogue_optimization_parameters_reply(facts),
                "facts_used": ["optimization.variable_ranges", "optimization.variable_notes", "optimization.evidence.role_cases"],
                "needs_user_approval": False,
            }
        if opt.get("should_adjust_bounds"):
            pending_action = {
                "action": "approve_optimization_bounds_adjustment",
                "params": {
                    "current_profile": opt.get("bounds_profile"),
                    "recommended_profile": opt.get("recommended_profile"),
                },
            }
            reply = "优化报告建议调整范围：{} -> {}。这属于会启动真实后端动作的操作，我需要你明确同意后才能执行。".format(
                opt.get("bounds_profile") or "-",
                opt.get("recommended_profile") or "-",
            )
            return {
                "handled": True,
                "intent": intent,
                "reply": reply,
                "facts_used": ["optimization"],
                "pending_action": pending_action,
                "needs_user_approval": True,
            }
        reply = "当前没有新的范围调整待审批。已有优化状态：profile={}，多目标收敛={}，TOPSIS={}。".format(
            opt.get("bounds_profile") or "-",
            opt.get("multi_objective_converged"),
            opt.get("topsis_best_case_id") or "-",
        )
        if opt.get("alignment_status") == "mismatch":
            reply = (
                "当前主线 Aspen 还不能判定完成：已有优化结果属于 {}，当前锁定萃取剂是 {}。"
                "这些结果可以保留为旁支证据，但不能直接进入当前体系报告。"
            ).format(
                opt.get("optimized_solvent_label") or "-",
                opt.get("selected_solvent_label") or opt.get("selected_solvent_code") or "-",
            )
        elif opt.get("alignment_status") == "unknown":
            reply = "当前有优化结果，但来源还没和当前锁定萃取剂核对，不能直接判定主线 Aspen 收敛。"
        return {"handled": True, "intent": intent, "reply": reply, "facts_used": ["optimization"], "needs_user_approval": False}

    if alpha_global_blocker.get("blocked") and (
        alpha_pending
        or "alpha" in runtime_stage.lower()
        or "relative_volatility" in runtime_stage.lower()
        or "property_strategy" in runtime_stage.lower()
        or "strategy_review" in runtime_stage.lower()
    ):
        blocker_reason = str(
            alpha_global_blocker.get("reason")
            or alpha_global_blocker.get("status")
            or "base alpha0 不可信"
        ).rstrip("。.;； ")
        reply = (
            "当前没有卡在某个候选剂计算上，而是 Aspen α/K-value 入口被全局阻塞。\n"
            "候选池完成 {}/{}，通过 {}，未通过 {}，待算 {}；下一支本来是 {}，但现在不应该继续运行下一候选。\n"
            "原因：{}。下一步：{}。"
        ).format(
            alpha_completed,
            alpha_total,
            alpha.get("pass", 0),
            alpha.get("fail", 0),
            alpha_pending,
            current.get("label") or "-",
            blocker_reason,
            alpha_global_blocker.get("next_action_label") or alpha.get("next_action_label") or "复核 Aspen 物性",
        )
    elif alpha_pending or "alpha" in runtime_stage.lower() or "relative_volatility" in runtime_stage.lower():
        reply = (
            "当前阶段：{}。当前候选是 {}；候选池完成 {}/{}，通过 {}，未通过 {}，待算 {}。\n"
            "我的判断：现在仍是 Aspen α 全池预筛；α 没筛完前不锁定分子模拟候选，Gaussian/GROMACS 不启动。"
        ).format(
            runtime_stage or "后台任务",
            current.get("label") or "-",
            alpha_completed,
            alpha_total,
            alpha.get("pass", 0),
            alpha.get("fail", 0),
            alpha_pending,
        )
    elif alpha_complete or runtime_stage == "molecular_queue":
        top_label = dialogue_format_candidate(top[0]) if top else "-"
        selected = molecular.get("selected_solvent_label") or "尚未锁定"
        if (runtime.get("running") or runtime_interrupted) and active_stage and queue_stage and active_stage != queue_stage:
            stage_line = "当前执行阶段：{}；队列阶段：{}。".format(stage_name(active_stage), stage_name(queue_stage))
        else:
            stage_line = "当前阶段：{}。".format(stage_name(runtime_stage or queue_stage or "molecular_queue"))
        progress_line = runtime_progress_line()
        reply = (
            "{}α 全池已完成 {}/{}，通过 {}，未通过 {}，待算 0。\n"
            "按 Iα 排名，当前最高是 {}；分子验证当前目标候选是 {}。\n"
            "进程：Aspen {}/{}，Gaussian {}，GROMACS {}。{}{}"
        ).format(
            stage_line,
            alpha_completed,
            alpha_total,
            alpha.get("pass", 0),
            alpha.get("fail", 0),
            top_label,
            selected,
            processes.get("aspen", 0),
            processes.get("aspen_limit", 1),
            processes.get("gaussian", 0),
            processes.get("gromacs", 0),
            (
                "上次运行已中断；当前没有长计算进程，需要重新启动监督运行后从当前队列继续。"
                if runtime_interrupted else
                ("当前没有长计算进程，属于队列就绪/等待显式启动。" if not runtime.get("running") else "后台任务仍在运行。")
            ),
            ("\n" + progress_line) if progress_line else "",
        )
    else:
        reply = (
            "当前阶段：{}。候选池完成 {}/{}，通过 {}，未通过 {}，待算 {}。\n"
            "我没有看到明确的当前候选；需要以实时监督面板和最新任务包为准。"
        ).format(
            runtime_stage or "后台任务",
            alpha_completed,
            alpha_total,
            alpha.get("pass", 0),
            alpha.get("fail", 0),
            alpha_pending,
        )
    return {"handled": True, "intent": intent, "reply": reply, "facts_used": ["runtime", "alpha", "current_candidate", "molecular", "processes"], "needs_user_approval": False}


def agent_dialogue_llm_settings():
    override = DIALOGUE_LLM_RUNTIME_OVERRIDE if isinstance(DIALOGUE_LLM_RUNTIME_OVERRIDE, dict) else {}
    override_provider = clean_text_arg(override.get("provider"), "", max_len=40).strip().lower()
    provider = clean_text_arg(os.environ.get("ED_AGENT_LLM_PROVIDER"), "", max_len=40).strip().lower()
    if override_provider and override_provider not in {"auto", "default"}:
        provider = override_provider
    elif override_provider in {"auto", "default"}:
        provider = ""
    openai_key = os.environ.get("ED_AGENT_OPENAI_API_KEY") or os.environ.get("OPENAI_API_KEY")
    deepseek_key = os.environ.get("ED_AGENT_DEEPSEEK_API_KEY") or os.environ.get("DEEPSEEK_API_KEY")
    codex_local_key = (
        os.environ.get("ED_AGENT_CODEX_LOCAL_API_KEY")
        or os.environ.get("ED_AGENT_CODEX_API_KEY")
        or os.environ.get("CODEX_LOCAL_API_KEY")
    )
    if not provider:
        if codex_local_key:
            provider = "codex_local"
        else:
            provider = "deepseek" if deepseek_key and not openai_key else "openai"
    if provider == "deepseek":
        api_key = deepseek_key
        model = (
            os.environ.get("ED_AGENT_DEEPSEEK_MODEL")
            or os.environ.get("ED_AGENT_LLM_MODEL")
            or os.environ.get("DEEPSEEK_MODEL")
            or "deepseek-v4-flash"
        )
        base_url = (
            os.environ.get("ED_AGENT_DEEPSEEK_BASE_URL")
            or os.environ.get("ED_AGENT_LLM_BASE_URL")
            or "https://api.deepseek.com"
        )
    elif provider in {"codex", "codex_local", "local_codex"}:
        provider = "codex_local"
        api_key = codex_local_key or os.environ.get("ED_AGENT_LLM_API_KEY") or "local"
        model = (
            os.environ.get("ED_AGENT_CODEX_LOCAL_MODEL")
            or os.environ.get("ED_AGENT_CODEX_MODEL")
            or os.environ.get("ED_AGENT_LLM_MODEL")
            or "gpt-5.5"
        )
        base_url = (
            os.environ.get("ED_AGENT_CODEX_LOCAL_BASE_URL")
            or os.environ.get("ED_AGENT_CODEX_BASE_URL")
            or os.environ.get("ED_AGENT_LLM_BASE_URL")
            or "http://127.0.0.1:49784/v1"
        )
    elif provider == "custom":
        api_key = os.environ.get("ED_AGENT_CUSTOM_API_KEY") or os.environ.get("ED_AGENT_LLM_API_KEY")
        model = os.environ.get("ED_AGENT_CUSTOM_MODEL") or os.environ.get("ED_AGENT_LLM_MODEL") or ""
        base_url = os.environ.get("ED_AGENT_CUSTOM_BASE_URL") or os.environ.get("ED_AGENT_LLM_BASE_URL") or ""
    else:
        provider = "openai"
        api_key = openai_key
        model = (
            os.environ.get("ED_AGENT_OPENAI_MODEL")
            or os.environ.get("ED_AGENT_LLM_MODEL")
            or os.environ.get("OPENAI_MODEL")
            or "gpt-4o-mini"
        )
        base_url = os.environ.get("ED_AGENT_OPENAI_BASE_URL") or os.environ.get("ED_AGENT_LLM_BASE_URL") or "https://api.openai.com/v1"
    override_model = clean_text_arg(override.get("model"), "", max_len=120).strip()
    override_base_url = clean_text_arg(override.get("base_url"), "", max_len=500).strip()
    if override_model:
        model = override_model
    if override_base_url:
        base_url = override_base_url
    base_url = str(base_url or "").rstrip("/")
    endpoint = os.environ.get("ED_AGENT_LLM_CHAT_COMPLETIONS_URL") or (base_url + "/chat/completions" if base_url else "")
    return {
        "provider": provider,
        "api_key": api_key,
        "model": model,
        "base_url": base_url,
        "endpoint": endpoint,
        "configured": bool(api_key and model and endpoint),
    }


def agent_dialogue_llm_public_settings():
    settings = agent_dialogue_llm_settings()
    override = DIALOGUE_LLM_RUNTIME_OVERRIDE if isinstance(DIALOGUE_LLM_RUNTIME_OVERRIDE, dict) else {}
    active_override = clean_text_arg(override.get("provider"), "", max_len=40).strip().lower() or "auto"
    codex_key = (
        os.environ.get("ED_AGENT_CODEX_LOCAL_API_KEY")
        or os.environ.get("ED_AGENT_CODEX_API_KEY")
        or os.environ.get("CODEX_LOCAL_API_KEY")
    )
    deepseek_key = os.environ.get("ED_AGENT_DEEPSEEK_API_KEY") or os.environ.get("DEEPSEEK_API_KEY")
    openai_key = os.environ.get("ED_AGENT_OPENAI_API_KEY") or os.environ.get("OPENAI_API_KEY")
    return {
        "provider": settings.get("provider") or "",
        "model": settings.get("model") or "",
        "base_url": settings.get("base_url") or "",
        "endpoint": settings.get("endpoint") or "",
        "configured": bool(settings.get("configured")),
        "selected_provider": active_override,
        "options": [
            {
                "id": "auto",
                "label": "自动",
                "description": "优先使用已配置的本地 Codex/GPT，否则回退到可用 provider。",
                "configured": bool(codex_key or deepseek_key or openai_key),
            },
            {
                "id": "codex_local",
                "label": "Codex/GPT",
                "description": "本地 Codex 反代，OpenAI-compatible /v1/chat/completions。",
                "configured": bool(codex_key),
                "default_model": "gpt-5.5",
            },
            {
                "id": "deepseek",
                "label": "DeepSeek",
                "description": "DeepSeek 官方兼容接口。",
                "configured": bool(deepseek_key),
                "default_model": "deepseek-v4-flash",
            },
        ],
    }


def update_agent_dialogue_llm_settings(payload):
    provider = clean_text_arg((payload or {}).get("provider"), "auto", max_len=40).strip().lower()
    model = clean_text_arg((payload or {}).get("model"), "", max_len=120).strip()
    base_url = clean_text_arg((payload or {}).get("base_url"), "", max_len=500).strip()
    allowed = {"auto", "default", "codex", "codex_local", "local_codex", "deepseek", "openai", "custom"}
    if provider not in allowed:
        return {"error": "unsupported provider", "provider": provider, "returncode": 2}
    if provider in {"default"}:
        provider = "auto"
    if provider in {"codex", "local_codex"}:
        provider = "codex_local"
    if provider == "codex_local" and not model:
        model = os.environ.get("ED_AGENT_CODEX_LOCAL_MODEL") or os.environ.get("ED_AGENT_CODEX_MODEL") or "gpt-5.5"
    if provider == "deepseek" and not model:
        model = os.environ.get("ED_AGENT_DEEPSEEK_MODEL") or os.environ.get("DEEPSEEK_MODEL") or "deepseek-v4-flash"
    DIALOGUE_LLM_RUNTIME_OVERRIDE.update({
        "provider": provider,
        "model": model,
        "base_url": base_url,
    })
    result = agent_dialogue_llm_public_settings()
    result["returncode"] = 0
    return result


def agent_dialogue_llm_timeout(settings, requested=None):
    try:
        timeout = float(requested if requested is not None else os.environ.get("ED_AGENT_LLM_TIMEOUT_SECONDS", "20"))
    except Exception:
        timeout = 20.0
    if (settings or {}).get("provider") == "codex_local":
        try:
            codex_timeout = float(os.environ.get("ED_AGENT_CODEX_LOCAL_TIMEOUT_SECONDS", "90"))
        except Exception:
            codex_timeout = 90.0
        timeout = max(timeout, codex_timeout)
    return timeout


def agent_dialogue_effective_mode(settings):
    raw_mode = clean_text_arg(os.environ.get("ED_AGENT_DIALOGUE_MODE"), "", max_len=40).strip().lower()
    force_fast = clean_bool_arg(os.environ.get("ED_AGENT_DIALOGUE_FORCE_FAST"), False)
    if raw_mode in {"agent_loop", "loop", "explore", "slow"}:
        return raw_mode
    if raw_mode in {"deterministic", "rules", "rule", "no_llm"}:
        return "fast"
    if raw_mode in {"fast", "", "hybrid", "auto"} and settings.get("configured") and not force_fast:
        return "agent_loop"
    return raw_mode or "fast"


def call_agent_dialogue_llm(message, facts):
    settings = agent_dialogue_llm_settings()
    if not settings.get("configured"):
        return None
    api_key = settings.get("api_key")
    model = settings.get("model")
    system_prompt = (
        "You are the dialogue layer for a chemical-engineering screening agent. "
        "Reply in Chinese. Use only the provided facts. Do not invent data. "
        "Behave like an agent, not a log summarizer: infer the user's intent, inspect the relevant dynamic evidence inside facts, answer directly first, then cite evidence. "
        "Answer the user's exact question instead of defaulting to progress. If the user asks which system is active, use facts.task.system and facts.task.target_product, and echo their exact labels in the reply. "
        "Respect the current workflow stage before mentioning downstream results. If facts.runtime.stage or active_stage contains relative_volatility or alpha, answer only about Aspen α/K-value screening, the current candidate, alpha counts, and process safety; do not discuss Aspen optimization generations, TOPSIS, convergence, or a final solvent except to say those stages are not reached yet. "
        "If Gaussian/NCI/GROMACS is current, answer only about molecular evidence progress unless the user explicitly asks for historical optimization evidence. "
        "If the user asks which extractant/solvent is selected, use facts.molecular.selected_solvent_label. Do not replace identity questions with a stage-progress answer. "
        "For candidate-selection questions such as why this extractant was selected, why another candidate was not selected, or where candidates came from, use facts.candidate_strategy, facts.candidate_selection, facts.alpha_ranked_candidates, and facts.screened_out_candidates. "
        "You must distinguish three things: (1) selected molecular-validation candidate, (2) alpha-screen ranking, and (3) final Aspen-optimized process solvent. "
        "If facts.optimization.alignment_status is mismatch or unknown, treat Aspen optimization as side or unverified evidence: do not say the current mainline Aspen is converged or the whole flow is complete. Say the mainline selected solvent still needs Aspen optimization or source verification. "
        "For 'why selected' answers, state the selected candidate first, then give Ialpha/key-region evidence, compare mentioned candidates if present, explain the source/screening rule, and say it is not final until molecular evidence and Aspen optimization close. "
        "For optimization-case questions, use facts.optimization.evidence.case_lookup and role_cases to resolve case_id -> solvent_code/solvent_name dynamically; never memorize or hard-code a solvent. "
        "For optimization parameter or bounds questions, use facts.optimization.variable_ranges, variable_notes, campaign, and role_cases; answer with the solvent identity, variable ranges, and current TOPSIS case parameters. "
        "For convergence, stopping, error/residual, recent improvement, and 'last N generations' questions, use facts.optimization.convergence_diagnostics. "
        "In that object, delta_topsis_score is the optimization improvement/residual between generations; compare it with score_epsilon and explain stagnant_generations/patience. "
        "When facts.optimization.alignment_status is matched or facts.optimization.evidence_scope is mainline, the current run is the mainline evidence. Do not call it side evidence, imported baseline, another solvent, or unverified unless the user explicitly asks about imported/baseline/history. "
        "If facts.agent_method gives a lookup recipe, follow it. If the lookup is missing, say which artifact or case id is missing. "
        "Do not execute or claim to execute actions. For any start/stop/rerun/bounds-change action, "
        "ask for explicit approval and return pending_action only. "
        "Return strict JSON with keys: reply, intent, facts_used, pending_action, needs_user_approval."
    )
    payload = {
        "model": model,
        "temperature": 0.2,
        "response_format": {"type": "json_object"},
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": json.dumps({"message": message, "facts": facts}, ensure_ascii=False, default=str)},
        ],
    }
    data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(
        settings.get("endpoint"),
        data=data,
        headers={
            "Content-Type": "application/json",
            "Authorization": "Bearer {}".format(api_key),
        },
        method="POST",
    )
    timeout = agent_dialogue_llm_timeout(settings)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            result = json.loads(resp.read().decode("utf-8"))
        content = (((result.get("choices") or [{}])[0].get("message") or {}).get("content") or "").strip()
        parsed = json.loads(content)
    except Exception as exc:
        return {"llm_error": "{}: {}".format(exc.__class__.__name__, exc)}
    if not isinstance(parsed, dict):
        return {"llm_error": "model did not return an object"}
    reply = str(parsed.get("reply") or "").strip()
    if not reply:
        return {"llm_error": "model reply is empty"}
    pending_action = parsed.get("pending_action")
    if isinstance(pending_action, dict):
        action_name = pending_action.get("action") or pending_action.get("type") or ""
        if action_name and action_name not in DIALOGUE_REQUIRES_APPROVAL_ACTIONS:
            pending_action = None
    else:
        pending_action = None
    return {
        "handled": True,
        "intent": str(parsed.get("intent") or dialogue_intent(message)),
        "reply": reply,
        "facts_used": parsed.get("facts_used") if isinstance(parsed.get("facts_used"), list) else [],
        "pending_action": pending_action,
        "needs_user_approval": bool(parsed.get("needs_user_approval") and pending_action),
        "llm_model": model,
        "llm_provider": settings.get("provider"),
        "llm_used": True,
    }


def dialogue_llm_json_request(system_prompt, payload, timeout_seconds=None):
    settings = agent_dialogue_llm_settings()
    if not settings.get("configured"):
        return {"llm_error": "llm is not configured"}
    request_payload = {
        "model": settings.get("model"),
        "temperature": 0.15,
        "response_format": {"type": "json_object"},
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": json.dumps(payload, ensure_ascii=False, default=str)},
        ],
    }
    data = json.dumps(request_payload, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(
        settings.get("endpoint"),
        data=data,
        headers={
            "Content-Type": "application/json",
            "Authorization": "Bearer {}".format(settings.get("api_key")),
        },
        method="POST",
    )
    timeout = agent_dialogue_llm_timeout(settings, requested=timeout_seconds)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            result = json.loads(resp.read().decode("utf-8"))
        content = (((result.get("choices") or [{}])[0].get("message") or {}).get("content") or "").strip()
        parsed = json.loads(content)
        if not isinstance(parsed, dict):
            return {"llm_error": "model did not return an object"}
        parsed.setdefault("llm_provider", settings.get("provider"))
        parsed.setdefault("llm_model", settings.get("model"))
        return parsed
    except Exception as exc:
        return {"llm_error": "{}: {}".format(exc.__class__.__name__, exc)}


def dialogue_reply_fails_answer_check(message, reply, facts):
    intent = dialogue_intent(message)
    reply_text = str((reply or {}).get("reply") or "")
    message_text = str(message or "")
    opt = facts.get("optimization") or {}
    selected_text = " ".join(
        str(item or "")
        for item in (
            opt.get("selected_solvent_label"),
            opt.get("selected_solvent_code"),
            opt.get("optimized_solvent_label"),
        )
    )
    user_asked_history = bool(re.search(r"(旁支|历史|导入|baseline|imported|以前|之前|PG|propylene|丙二醇)", message_text, re.I))
    stage_key = dialogue_stage_key(facts)
    status_like_intents = {"status", "aspen_status", "next_step", "check_stuck"}
    molecular_gate = (facts.get("molecular_gate") or dialogue_molecular_gate_from_facts(facts))
    if not molecular_gate.get("gate_open") and not user_asked_history:
        claims_molecular_complete = bool(re.search(
            r"(分子证据|分子验证|Gaussian/NCI/VMD/GROMACS|Gaussian.*NCI.*GROMACS).*(已|已经|均|全部|都).*(就绪|完成|闭合|过闸门|齐了)",
            reply_text,
            re.I,
        ))
        jumps_to_aspen = bool(re.search(
            r"(下一步|现在|当前|应当|需要|可以).*(启动|导入|进入|跑|开始).*(Aspen|多目标|优化)",
            reply_text,
            re.I,
        ))
        has_molecular_block = bool(re.search(r"(分子.*(未|没|待|不).*(闭合|完成|就绪)|Gaussian|NCI/VMD|GROMACS|挡在|闸门|不能提前)", reply_text, re.I))
        if claims_molecular_complete:
            return "molecular_gate_false_claimed_complete"
        if jumps_to_aspen and not has_molecular_block:
            return "molecular_gate_false_jumped_to_aspen"
    if stage_key == "alpha" and intent in status_like_intents and not user_asked_history:
        mentions_alpha = bool(re.search(r"(Aspen\s*α|alpha|Iα|Ialpha|K-value|相对挥发度|候选|筛选)", reply_text, re.I))
        jumps_to_optimization = bool(re.search(r"(TOPSIS|多目标|收敛|Pareto|第\s*[-\d]+\s*代|案例\s*[-\d]+|PASS\s*[-\d]+|TAC)", reply_text, re.I))
        if jumps_to_optimization and not re.search(r"(尚未|还没|未进入|没到|不能|不是|不会)", reply_text, re.I):
            return "stage_inappropriate_optimization_summary_during_alpha"
        if not mentions_alpha:
            return "missing_alpha_stage_status"
    if (
        (opt.get("alignment_status") == "matched" or opt.get("evidence_scope") == "mainline")
        and not user_asked_history
    ):
        wrongly_side_scoped = bool(re.search(r"(旁支|不匹配|未匹配|不计入|不能算当前|不是当前|另一种溶剂|另一个溶剂|历史结果|导入结果)", reply_text, re.I))
        if wrongly_side_scoped:
            return "incorrect_side_scope_for_matched_mainline"
        if selected_text and "PG" not in selected_text.upper() and re.search(r"\bPG\b|propylene\s+glycol|1,2-propanediol|丙二醇", reply_text, re.I):
            return "wrong_historical_solvent_for_current_mainline"
    if opt.get("alignment_status") in {"mismatch", "unknown"}:
        claims_mainline_done = bool(re.search(r"(全流程.*(完成|闭合)|当前体系.*(完成|闭合)|可以进入报告|已满足收敛|主线.*已收敛|Aspen.*已收敛)", reply_text, re.I))
        has_alignment_caution = bool(re.search(r"(主线|旁支|不匹配|未匹配|未核对|不能直接|不计入|还没|未完成|待启动|待核对)", reply_text, re.I))
        first_sentence = re.split(r"[。！？\n]", reply_text, maxsplit=1)[0]
        misleading_side_result_first = bool(
            re.search(r"(Aspen|多目标|优化).*(已完成|已收敛|收敛完成|已可排序)", first_sentence, re.I)
            and not re.search(r"(当前主线.*(未|没|待|不能)|旁支|不是当前|不匹配|未匹配|未核对)", first_sentence, re.I)
        )
        if misleading_side_result_first:
            return "misleading_side_aspen_first_sentence"
        if claims_mainline_done and not has_alignment_caution:
            return "missing_mainline_alignment_caution"
    if intent == "system_identity":
        system = str(((facts.get("task") or {}).get("system") or "")).strip()
        target = str(((facts.get("task") or {}).get("target_product") or "")).strip()
        if system and system not in reply_text:
            return "missing_current_system"
        if target and target not in reply_text:
            return "missing_target_product"
    if intent == "current_solvent_identity":
        solvent = str(((facts.get("molecular") or {}).get("selected_solvent_label") or "")).strip()
        if solvent and solvent not in reply_text:
            return "missing_selected_solvent"
    if intent in {"explain_selected_solvent", "compare_candidate_choice"}:
        selected = ((facts.get("candidate_selection") or {}).get("selected") or {})
        selected_label = str(selected.get("label") or ((facts.get("molecular") or {}).get("selected_solvent_label") or "")).strip()
        if selected_label and selected_label != "-" and selected_label not in reply_text:
            return "missing_selected_candidate_in_selection_answer"
        if not re.search(r"(Iα|Ialpha|i_alpha|alpha|相对挥发度|关键区|闸门)", reply_text, re.I):
            return "missing_alpha_selection_evidence"
        if not re.search(r"(最终|分子|Gaussian|GROMACS|NCI|Aspen)", reply_text, re.I):
            return "missing_downstream_validation_context"
    if intent == "explain_candidate_screening":
        if not re.search(r"(候选|萃取剂|溶剂|筛选|来源|闸门)", reply_text, re.I):
            return "missing_candidate_screening_context"
    if intent in ("optimization_solvent_lookup", "optimization_case_lookup"):
        _, case = dialogue_primary_optimization_case(facts)
        if case and not dialogue_reply_has_solvent(reply_text, case):
            return "missing_resolved_solvent"
        if case and case.get("case_id") and str(case.get("case_id")) not in reply_text:
            return "missing_case_evidence"
        if case and case.get("TAC") and "TAC" not in reply_text and "tac" not in reply_text.lower():
            return "missing_objective_evidence"
        if case and re.search(r"(未明确|不明确|无法确定|没有明确|事实.*不足|not clear|cannot determine)", reply_text, re.I):
            return "overcautious_despite_resolved_case"
    if intent == "bounds_or_optimization" and dialogue_parameter_question(message):
        variable_ranges = (opt.get("variable_ranges") or opt.get("current_bounds") or {})
        if variable_ranges and re.search(r"(没有.*范围|没有.*参数|未提供.*范围|查询.*日志|查.*日志|facts.*没有|not provided|missing)", reply_text, re.I):
            return "missing_available_optimization_variable_ranges"
        if variable_ranges and not re.search(r"(SF|RR1|RR2|D1|D2|N1|N2)", reply_text, re.I):
            return "missing_optimization_variable_names"
    return ""


def dialogue_safe_artifact_path(path_value, report_path=""):
    path_value = str(path_value or "").strip()
    if not path_value:
        raise ValueError("artifact path is missing")
    candidate = Path(path_value)
    if not candidate.is_absolute():
        candidate = (BASE_DIR / candidate).resolve()
    else:
        candidate = candidate.resolve()
    allowed_roots = [
        (BASE_DIR / "generated").resolve(),
        REPORT_PATH.resolve().parent,
    ]
    if report_path:
        try:
            allowed_roots.append(Path(report_path).resolve().parent)
        except Exception:
            pass
    if not any(str(candidate).lower().startswith(str(root).lower()) for root in allowed_roots):
        raise ValueError("artifact path is outside the generated workspace")
    if not candidate.exists() or not candidate.is_file():
        raise FileNotFoundError(str(candidate))
    return candidate


def dialogue_file_kind(path):
    suffix = path.suffix.lower()
    if suffix == ".csv":
        return "csv"
    if suffix in (".json", ".jsonl"):
        return suffix.lstrip(".")
    if suffix in (".log", ".out", ".err", ".txt", ".md"):
        return "text"
    return suffix.lstrip(".") or "file"


def dialogue_compact_path_label(path, root):
    try:
        return str(path.resolve().relative_to(root.resolve()))
    except Exception:
        return path.name


def dialogue_collect_path_strings(value, out, max_items=240):
    if len(out) >= max_items:
        return
    if isinstance(value, dict):
        for item in value.values():
            dialogue_collect_path_strings(item, out, max_items=max_items)
    elif isinstance(value, list):
        for item in value[:80]:
            dialogue_collect_path_strings(item, out, max_items=max_items)
    elif isinstance(value, str):
        text_value = value.strip()
        if not text_value or len(text_value) > 1000:
            return
        lower = text_value.lower()
        if any(token in lower for token in (".json", ".csv", ".log", ".txt", ".jsonl", ".out", ".err")):
            out.append(text_value)


def dialogue_artifact_schema(path, kind):
    try:
        if kind == "csv":
            with path.open("r", encoding="utf-8-sig", newline="") as handle:
                reader = csv.DictReader(handle)
                sample = []
                for _, row in zip(range(3), reader):
                    sample.append({k: row.get(k, "") for k in (reader.fieldnames or [])[:18]})
                return {
                    "columns": (reader.fieldnames or [])[:80],
                    "sample_rows": sample,
                }
        if kind == "json":
            data = read_json_default(path, {})
            if isinstance(data, dict):
                schema = {"top_keys": list(data.keys())[:80]}
                nested = {}
                for key, value in list(data.items())[:30]:
                    if isinstance(value, dict):
                        nested[key] = list(value.keys())[:40]
                    elif isinstance(value, list):
                        nested[key] = {"type": "list", "length": len(value)}
                schema["nested"] = nested
                return schema
            if isinstance(data, list):
                return {"type": "list", "length": len(data), "sample_type": type(data[0]).__name__ if data else ""}
        if kind == "jsonl":
            rows = []
            with path.open("r", encoding="utf-8", errors="replace") as handle:
                for _, line in zip(range(3), handle):
                    parsed = json_loads_repaired(line, default=None)
                    if parsed is None:
                        rows.append(line.strip()[:300])
                    else:
                        rows.append(parsed)
            return {"sample_rows": rows}
        text = path.read_text(encoding="utf-8", errors="replace")[:1200]
        return {"preview": text}
    except Exception as exc:
        return {"error": "{}: {}".format(exc.__class__.__name__, exc)}


def dialogue_build_artifact_index(facts):
    report_path = facts.get("report_path") or ""
    report, path = load_action_report(report_path)
    candidates = [str(path)]
    dialogue_collect_path_strings(report, candidates)
    dialogue_collect_path_strings(facts, candidates)
    roots = [path.parent]
    package_dir = ((report.get("research_task_package_paths") or {}).get("research_task_package_dir") or "")
    if package_dir:
        try:
            roots.append(dialogue_safe_artifact_path(Path(package_dir) / "__missing__", report_path).parent)
        except Exception:
            try:
                p = Path(package_dir).resolve()
                if p.exists() and p.is_dir():
                    roots.append(p)
            except Exception:
                pass
    for root in list(dict.fromkeys([str(r) for r in roots])):
        try:
            root_path = Path(root).resolve()
            if not root_path.exists() or not root_path.is_dir():
                continue
            for file_path in root_path.rglob("*"):
                if len(candidates) >= 260:
                    break
                if file_path.is_file() and file_path.suffix.lower() in (".json", ".csv", ".jsonl", ".log", ".txt", ".out", ".err"):
                    candidates.append(str(file_path.resolve()))
        except Exception:
            continue
    artifacts = []
    seen = set()
    generated_root = (BASE_DIR / "generated").resolve()
    for raw in candidates:
        try:
            artifact_path = dialogue_safe_artifact_path(raw, report_path=report_path)
        except Exception:
            continue
        key = str(artifact_path).lower()
        if key in seen:
            continue
        seen.add(key)
        kind = dialogue_file_kind(artifact_path)
        try:
            stat = artifact_path.stat()
        except Exception:
            continue
        artifact = {
            "id": "a{}".format(len(artifacts)),
            "name": artifact_path.name,
            "kind": kind,
            "path": str(artifact_path),
            "label": dialogue_compact_path_label(artifact_path, generated_root),
            "size_bytes": stat.st_size,
            "mtime": iso_from_timestamp(stat.st_mtime),
        }
        if kind in ("csv", "json"):
            artifact["schema"] = dialogue_artifact_schema(artifact_path, kind)
        artifacts.append(artifact)
        if len(artifacts) >= 120:
            break
    return {
        "report_path": str(path),
        "artifacts": artifacts,
        "tool_names": [
            "get_current_system",
            "get_current_stage",
            "get_candidate_screening_summary",
            "get_aspen_optimization_status",
            "get_convergence_diagnostics",
            "get_topsis_best_case",
            "get_variable_ranges",
            "get_optimization_continuation_advice",
            "get_process_safety",
            "get_available_figures",
            "list_artifacts",
            "inspect_schema",
            "search_artifacts",
            "query_table",
            "query_json",
        ],
    }


def dialogue_artifact_by_id(index, artifact_id):
    artifact_id = str(artifact_id or "").strip()
    for artifact in index.get("artifacts") or []:
        if artifact.get("id") == artifact_id or artifact.get("name") == artifact_id or artifact.get("label") == artifact_id:
            return artifact
    return {}


def dialogue_tool_list_artifacts(index, args):
    kinds = set(str(x).lower() for x in (args.get("kinds") or []) if str(x).strip())
    keyword = str(args.get("keyword") or "").strip().lower()
    items = []
    for artifact in index.get("artifacts") or []:
        if kinds and artifact.get("kind") not in kinds:
            continue
        hay = " ".join([artifact.get("name", ""), artifact.get("label", ""), json.dumps(artifact.get("schema", {}), ensure_ascii=False)])[:4000].lower()
        if keyword and keyword not in hay:
            continue
        items.append({k: artifact.get(k) for k in ("id", "name", "kind", "label", "size_bytes", "mtime", "schema")})
        if len(items) >= int(args.get("limit") or 30):
            break
    return {"artifacts": items, "count": len(items)}


def dialogue_tool_inspect_schema(index, args):
    artifact = dialogue_artifact_by_id(index, args.get("artifact_id"))
    if not artifact:
        return {"error": "artifact not found"}
    path = dialogue_safe_artifact_path(artifact.get("path"), index.get("report_path"))
    return {
        "artifact": {k: artifact.get(k) for k in ("id", "name", "kind", "label")},
        "schema": dialogue_artifact_schema(path, artifact.get("kind")),
    }


def dialogue_read_text_for_search(path, kind, limit=1200000):
    if kind == "json":
        data = read_json_default(path, {})
        return json.dumps(data, ensure_ascii=False, default=str)[:limit]
    if kind == "csv":
        rows = read_csv_rows(path)
        return json.dumps(rows[:2000], ensure_ascii=False, default=str)[:limit]
    return path.read_text(encoding="utf-8", errors="replace")[:limit]


def dialogue_tool_search_artifacts(index, args):
    keywords = args.get("keywords")
    if isinstance(keywords, str):
        keywords = [keywords]
    keywords = [str(k).strip() for k in (keywords or []) if str(k).strip()]
    if not keywords:
        return {"error": "keywords missing"}
    results = []
    for artifact in index.get("artifacts") or []:
        try:
            path = dialogue_safe_artifact_path(artifact.get("path"), index.get("report_path"))
            text_blob = dialogue_read_text_for_search(path, artifact.get("kind"))
        except Exception:
            continue
        lower_blob = text_blob.lower()
        hits = []
        for keyword in keywords:
            pos = lower_blob.find(keyword.lower())
            if pos >= 0:
                start = max(0, pos - 160)
                end = min(len(text_blob), pos + 360)
                hits.append({"keyword": keyword, "excerpt": text_blob[start:end]})
        if hits:
            results.append({
                "artifact": {k: artifact.get(k) for k in ("id", "name", "kind", "label")},
                "hits": hits[:5],
            })
        if len(results) >= int(args.get("limit") or 10):
            break
    return {"results": results, "count": len(results)}


def dialogue_filter_row(row, filter_spec):
    column = str(filter_spec.get("column") or "").strip()
    op = str(filter_spec.get("op") or "contains").strip().lower()
    expected = str(filter_spec.get("value") or "")
    value = str(row.get(column) or "")
    if op == "eq":
        return value.lower() == expected.lower()
    if op == "neq":
        return value.lower() != expected.lower()
    if op == "regex":
        try:
            return bool(re.search(expected, value, re.I))
        except Exception:
            return False
    if op == "truthy":
        return truthy_cell(value)
    if op in ("gt", "gte", "lt", "lte"):
        left = safe_float(value)
        right = safe_float(expected)
        if left is None or right is None:
            return False
        return {"gt": left > right, "gte": left >= right, "lt": left < right, "lte": left <= right}[op]
    return expected.lower() in value.lower()


def dialogue_tool_query_table(index, args):
    artifact = dialogue_artifact_by_id(index, args.get("artifact_id"))
    if not artifact:
        return {"error": "artifact not found"}
    if artifact.get("kind") != "csv":
        return {"error": "artifact is not a csv"}
    path = dialogue_safe_artifact_path(artifact.get("path"), index.get("report_path"))
    rows = read_csv_rows(path)
    filters = args.get("filters") or []
    if isinstance(filters, dict):
        filters = [filters]
    for filter_spec in filters:
        rows = [row for row in rows if dialogue_filter_row(row, filter_spec)]
    sort_by = str(args.get("sort_by") or "").strip()
    if sort_by:
        reverse = bool(args.get("descending"))
        def sort_key(row):
            number = safe_float(row.get(sort_by))
            return number if number is not None else str(row.get(sort_by) or "")
        rows = sorted(rows, key=sort_key, reverse=reverse)
    columns = args.get("columns") or []
    columns = [str(c) for c in columns if str(c).strip()]
    limit = max(1, min(80, int(args.get("limit") or 12)))
    output_rows = []
    for row in rows[:limit]:
        if columns:
            output_rows.append({column: row.get(column, "") for column in columns})
        else:
            output_rows.append({k: v for k, v in row.items() if dialogue_nonempty(v)})
    return {
        "artifact": {k: artifact.get(k) for k in ("id", "name", "kind", "label")},
        "matched_count": len(rows),
        "rows": output_rows,
    }


def dialogue_json_path_get(data, path_expr):
    current = data
    if not path_expr:
        return current
    for part in str(path_expr).replace("/", ".").split("."):
        part = part.strip()
        if not part:
            continue
        if isinstance(current, dict):
            current = current.get(part)
        elif isinstance(current, list):
            try:
                current = current[int(part)]
            except Exception:
                return None
        else:
            return None
    return current


def dialogue_tool_query_json(index, args):
    artifact = dialogue_artifact_by_id(index, args.get("artifact_id"))
    if not artifact:
        return {"error": "artifact not found"}
    if artifact.get("kind") not in ("json", "jsonl"):
        return {"error": "artifact is not json/jsonl"}
    path = dialogue_safe_artifact_path(artifact.get("path"), index.get("report_path"))
    if artifact.get("kind") == "jsonl":
        rows = []
        with path.open("r", encoding="utf-8", errors="replace") as handle:
            for _, line in zip(range(int(args.get("limit") or 20)), handle):
                parsed = json_loads_repaired(line, default=None)
                if parsed is None:
                    rows.append(line.strip())
                else:
                    rows.append(parsed)
        return {"artifact": {k: artifact.get(k) for k in ("id", "name", "kind", "label")}, "rows": rows}
    data = read_json_default(path, {})
    search = str(args.get("search") or "").strip()
    path_expr = str(args.get("path") or args.get("json_path") or "").strip()
    if search:
        blob = json.dumps(data, ensure_ascii=False, default=str)
        pos = blob.lower().find(search.lower())
        excerpt = ""
        if pos >= 0:
            excerpt = blob[max(0, pos - 240): min(len(blob), pos + 700)]
        return {"artifact": {k: artifact.get(k) for k in ("id", "name", "kind", "label")}, "search": search, "excerpt": excerpt}
    value = dialogue_json_path_get(data, path_expr)
    return {
        "artifact": {k: artifact.get(k) for k in ("id", "name", "kind", "label")},
        "path": path_expr,
        "value": value,
    }


