def dialogue_message_topics(message):
    topics = set()
    for topic, terms in DIALOGUE_TOPIC_TERMS.items():
        if dialogue_contains_any(message, terms):
            topics.add(topic)
    return topics


def dialogue_deep_reasoning_requested(message):
    text_value = str(message or "")
    if dialogue_contains_any(text_value, DIALOGUE_DEEP_REASONING_TERMS):
        return True
    # "为什么还没停/为什么没收敛" is a factual convergence question, not a deep-model question.
    if re.search(r"(为什么|为啥|原因|why)", text_value, re.I):
        if re.search(r"(还没停|没停|未停|停止|收敛|误差|残差|stagnant|epsilon|conver)", text_value, re.I):
            return False
        if re.search(r"(合理|好不好|对不对|怎么|方案|策略|架构|选择|取舍|评价)", text_value, re.I):
            return True
    return False


def dialogue_fast_fact_route(message, facts):
    if dialogue_user_consented(message) or dialogue_user_declined(message):
        return False, ""
    if dialogue_deep_reasoning_requested(message):
        return False, "deep_reasoning_requested"
    topics = dialogue_message_topics(message)
    intent = dialogue_intent(message)
    fast_intents = {
        "status",
        "check_stuck",
        "next_step",
        "rank_current_candidates",
        "explain_alpha_failures",
        "aspen_status",
        "optimization_solvent_lookup",
        "optimization_case_lookup",
        "bounds_or_optimization",
        "system_identity",
        "current_solvent_identity",
    }
    if topics & DIALOGUE_FAST_FACT_TOPICS:
        return True, "fast_fact_topics:{}".format(",".join(sorted(topics & DIALOGUE_FAST_FACT_TOPICS)))
    if intent in fast_intents:
        return True, "fast_fact_intent:{}".format(intent)
    text_value = str(message or "").strip()
    if re.fullmatch(r"(现在呢|还在吗|开始了吗|跑了吗|跑完了吗|收敛了吗|到哪了|什么程度了|现在在干啥|还在运行吗|还有多久|还要多久|多久|多长时间)[？?。!！\s]*", text_value, re.I):
        return True, "short_status_question"
    return False, ""


def dialogue_fast_fact_tool_calls(message):
    topics = dialogue_message_topics(message)
    lower = str(message or "").lower()
    calls = [
        {"tool": "get_current_system", "args": {}},
        {"tool": "get_current_stage", "args": {}},
    ]
    needs_aspen = bool(
        topics & {"optimization", "convergence", "bounds"}
        or "aspen" in lower
        or "topsis" in lower
        or re.search(r"(多目标|优化|收敛|TAC|塔|回流|变量|参数)", str(message or ""), re.I)
    )
    if needs_aspen:
        calls.append({"tool": "get_aspen_optimization_status", "args": {}})
    if "convergence" in topics or re.search(r"(收敛|误差|残差|停|epsilon|delta|stagnant|conver)", str(message or ""), re.I):
        calls.append({"tool": "get_convergence_diagnostics", "args": {}})
    if "optimization" in topics or "identity" in topics or re.search(r"(topsis|case|TAC|最优|萃取剂|溶剂)", str(message or ""), re.I):
        calls.append({"tool": "get_topsis_best_case", "args": {}})
    if "bounds" in topics:
        calls.append({"tool": "get_variable_ranges", "args": {}})
        calls.append({"tool": "get_optimization_continuation_advice", "args": {}})
    if ("optimization" in topics and re.search(r"(继续|还得|建议|意见|范围|参数|continue|recommend|advice|range|bound)", str(message or ""), re.I)):
        calls.append({"tool": "get_optimization_continuation_advice", "args": {}})
    if "process" in topics or "status" in topics:
        calls.append({"tool": "get_process_safety", "args": {}})
    if "candidate" in topics:
        calls.append({"tool": "get_candidate_screening_summary", "args": {}})
    if "figure" in topics:
        calls.append({"tool": "get_available_figures", "args": {}})
    deduped = []
    seen = set()
    for call in calls:
        key = call.get("tool")
        if key in seen:
            continue
        seen.add(key)
        deduped.append(call)
    return deduped[:9]


