def optimizer_report_path_from_progress(report):
    progress = aspen_progress_summary(report)
    path = str(progress.get("optimizer_report_json") or "").strip()
    if path and Path(path).exists():
        return Path(path)
    output_dir = str(progress.get("optimization_output_dir") or "").strip()
    if output_dir:
        candidate = Path(output_dir) / "generic_aspen_once_optimizer.report.json"
        if candidate.exists():
            return candidate
    base = Path(report.get("output_dir") or REPORT_PATH.parent)
    candidates = sorted(base.glob("aspen_optimization_once*/generic_aspen_once_optimizer.report.json"))
    candidates.extend(sorted(base.glob("aspen_optimization_bounds_adjustment*/generic_aspen_once_optimizer.report.json")))
    if candidates:
        return max(candidates, key=lambda item: item.stat().st_mtime)
    return None


def optimizer_existing_path(value):
    if not value:
        return None
    try:
        path = Path(str(value))
    except Exception:
        return None
    return path if path.exists() else None


def optimizer_report_rows_with_events(optimizer_report, report_path=None):
    optimizer_report = optimizer_report if isinstance(optimizer_report, dict) else {}
    rows = optimizer_report.get("rows") or []
    if isinstance(rows, list) and rows:
        return [row for row in rows if isinstance(row, dict)]
    candidates = []
    event_path = str(optimizer_report.get("case_events_jsonl") or "").strip()
    if event_path:
        candidates.append(Path(event_path))
    if report_path:
        try:
            candidates.extend((Path(report_path).parent / "optimization").glob("*.case_events.jsonl"))
        except Exception:
            pass
    restored = []
    seen = set()
    for candidate in candidates:
        try:
            candidate = Path(candidate)
        except Exception:
            continue
        key = str(candidate)
        if key in seen or not candidate.exists():
            continue
        seen.add(key)
        try:
            with candidate.open("r", encoding="utf-8", errors="replace") as handle:
                for line in handle:
                    if '"case_completed"' not in line and '"case_backfilled"' not in line:
                        continue
                    event = json_loads_repaired(line, default=None)
                    if not isinstance(event, dict):
                        continue
                    row = event.get("row") if isinstance(event, dict) else None
                    if isinstance(row, dict):
                        restored.append(row)
        except Exception:
            continue
    return restored


def optimizer_report_has_solvent_price_mismatch(optimizer_report, current_price, tolerance=1e-9):
    current = safe_float(current_price)
    if current is None:
        return False
    rows = optimizer_report_rows_with_events(optimizer_report)
    checked = 0
    for row in rows:
        if not isinstance(row, dict):
            continue
        case_id = str(row.get("case_id") or "")
        if not case_id.startswith("GENERIC_ASPEN_OPT_"):
            continue
        checked += 1
        recorded = safe_float(row.get("solvent_price_usd_per_kg"))
        if recorded is None:
            return True
        if abs(recorded - current) > tolerance:
            return True
        if checked >= 25:
            break
    return False


def optimizer_fast_template_bkp(optimizer_report):
    rows = optimizer_report_rows_with_events(optimizer_report)
    preferred_ids = []
    boundary = optimizer_report.get("boundary_diagnosis") or {}
    for key in ("topsis_best_case_id", "best_tac_case_id"):
        token = str(boundary.get(key) or "").strip()
        if token and token not in preferred_ids:
            preferred_ids.append(token)
    for key in ("topsis_best_case_id", "best_pass_case_id"):
        token = str(optimizer_report.get(key) or "").strip()
        if token and token not in preferred_ids:
            preferred_ids.append(token)
    ordered = []
    for case_id in preferred_ids:
        ordered.extend(row for row in rows if str(row.get("case_id") or "") == case_id)
    ordered.extend(reversed(rows))
    for row in ordered:
        for key in ("validated_bkp", "generated_bkp", "fast_template_bkp"):
            path = optimizer_existing_path(row.get(key))
            if path and path.suffix.lower() == ".bkp":
                return path
    return None


def optimizer_spec_path_for_bounds_adjustment(report, optimizer_report):
    rows = optimizer_report_rows_with_events(optimizer_report)
    for row in reversed(rows):
        path = optimizer_existing_path(row.get("spec"))
        if path:
            return path
    paths = report.get("research_task_package_paths") or {}
    for key in ("aspen_zero_build_spec_json", "aspen_flowsheet_spec_json"):
        path = optimizer_existing_path(paths.get(key))
        if path:
            return path
    return None


def solvent_price_evidence_summary(evidence):
    evidence = evidence or {}
    solvent = evidence.get("solvent") or {}
    fetched = [
        source for source in (evidence.get("sources") or [])
        if source.get("status") == "fetched"
    ]
    return {
        "status": evidence.get("status") or "",
        "generated_at": evidence.get("generated_at") or "",
        "solvent": " / ".join(
            str(part).strip()
            for part in (
                solvent.get("aspen_component_id") or solvent.get("code"),
                solvent.get("name"),
            )
            if str(part or "").strip()
        ),
        "solvent_price_usd_per_kg": evidence.get("selected_price_usd_per_kg"),
        "price_range_usd_per_kg": evidence.get("price_range_usd_per_kg", ""),
        "basis": evidence.get("basis") or "",
        "confidence": evidence.get("confidence") or "",
        "source_note": evidence.get("source_note") or "",
        "fetched_source_count": len(fetched),
        "price_mention_count": len(evidence.get("mentions") or []),
        "source_urls": [
            source.get("url") or ""
            for source in fetched
            if source.get("url")
        ][:5],
    }


def ensure_current_solvent_price_evidence(report, report_path, selected_solvent_code=""):
    task = (report or {}).get("separation_task") or {}
    if task.get("compatible_verified_case"):
        return report, (report.get("research_task_package_paths") or {}), {}
    paths = dict((report or {}).get("research_task_package_paths") or {})
    plan_path = generated_path(paths.get("aspen_build_plan_json"), "aspen_build_plan_json")
    spec_path = generated_path(
        paths.get("aspen_zero_build_spec_json") or ((plan_path.parent / "aspen_zero_build_spec.json") if plan_path else ""),
        "aspen_zero_build_spec_json",
    )
    if not spec_path.exists():
        return report, paths, {}
    locked_code = locked_molecular_solvent_code(report)
    if locked_code:
        selected_solvent_code = locked_code
    selected = primary_validation_solvent_identity(report, selected_solvent_code)
    if selected.get("selection_error"):
        return report, paths, {"status": "blocked_selected_solvent_unresolved", "selected_solvent": selected}
    package_dir = spec_path.parent
    evidence = solvent_price_research.ensure_solvent_price_evidence(
        spec_path,
        package_dir,
        {
            "code": selected.get("code") or selected.get("solvent_code") or selected_solvent_code,
            "name": selected.get("name") or selected.get("solvent_name") or "",
            "aspen_component_id": selected.get("aspen_component_id") or selected.get("code") or selected_solvent_code,
        },
    )
    evidence_path = package_dir / "solvent_price_evidence.json"
    paths["solvent_price_evidence_json"] = str(evidence_path.resolve())
    report["research_task_package_paths"] = paths
    report["solvent_price_evidence"] = solvent_price_evidence_summary(evidence)
    brief = dict(report.get("system_research_brief") or {})
    brief["solvent_price_evidence"] = solvent_price_evidence_summary(evidence)
    report["system_research_brief"] = brief
    write_json_file(report_path, report)
    return report, paths, evidence


def approve_optimization_bounds_adjustment(report, report_path):
    task = report.get("separation_task") or {}
    task_id = task.get("task_id") or ""
    existing_approval = (report.get("agent_approvals") or {}).get("optimization_bounds_adjustment") or {}
    existing_output_dir = optimizer_existing_path(existing_approval.get("new_output_dir"))
    if existing_output_dir:
        return {
            "returncode": 0,
            "status": "already_approved",
            "action": "approve_optimization_bounds_adjustment",
            "task_id": task_id,
            "report_path": str(report_path),
            "message": "Bounds adjustment was already approved; continuing to monitor {}.".format(existing_output_dir),
            "approval": existing_approval,
        }
    report, summary = import_process_results(report, report_path)
    if not truthy_cell(summary.get("optimization_agent_should_adjust_bounds")):
        return set_orchestrator_blocked(
            "approve_optimization_bounds_adjustment",
            task_id,
            "No optimizer bounds adjustment is pending; import results or run the boundary diagnosis first.",
            {"process_result_import": summary},
        )
    recommended_profile = str(summary.get("optimization_boundary_recommended_bounds_profile") or "").strip()
    if not recommended_profile:
        recommended_profile = "publication_safe"
    optimizer_report_path = optimizer_report_path_from_progress(report)
    if not optimizer_report_path or not optimizer_report_path.exists():
        return set_orchestrator_blocked(
            "approve_optimization_bounds_adjustment",
            task_id,
            "Optimizer report not found; cannot prepare the approved bounds rerun.",
        )
    optimizer_report = read_json_default(optimizer_report_path, {})
    spec_path = optimizer_spec_path_for_bounds_adjustment(report, optimizer_report)
    if not spec_path:
        return set_orchestrator_blocked(
            "approve_optimization_bounds_adjustment",
            task_id,
            "Aspen optimizer spec not found; cannot prepare the approved bounds rerun.",
            {"optimizer_report": str(optimizer_report_path.resolve())},
        )
    template_bkp = optimizer_fast_template_bkp(optimizer_report)
    if not template_bkp:
        return set_orchestrator_blocked(
            "approve_optimization_bounds_adjustment",
            task_id,
            "Fast in-place Aspen rerun is blocked because no validated/template BKP is available. Generate or import the current-system BKP first.",
            {"optimizer_report": str(optimizer_report_path.resolve())},
        )
    output_dir = Path(report.get("output_dir") or Path(report_path).parent) / "aspen_optimization_bounds_adjustment_{}".format(
        dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    )
    campaign = optimization_campaign_defaults(dict(task, optimization_bounds_profile=recommended_profile))
    population_size = max(4, min(12, int(campaign.get("population_size") or PUBLICATION_OPTIMIZATION_POPULATION_SIZE)))
    min_generations = int(campaign.get("minimum_generations") or PUBLICATION_OPTIMIZATION_MIN_GENERATIONS)
    convergence_patience = int(campaign.get("convergence_patience") or PUBLICATION_OPTIMIZATION_CONVERGENCE_PATIENCE)
    command = [
        sys.executable,
        str(BASE_DIR / "generic_aspen_once_optimizer.py"),
        "--spec",
        str(spec_path),
        "--output-dir",
        str(output_dir),
        "--population-size",
        str(population_size),
        "--generations",
        "0",
        "--run-until-converged",
        "--case-timeout-seconds",
        "180",
        "--aspen-cleanup-batch-size",
        "0",
        "--aspen-process-limit",
        str(ASPEN_MAX_PARALLEL_PROCESSES),
        "--min-generations",
        str(min_generations),
        "--convergence-patience",
        str(convergence_patience),
        "--bounds-profile",
        recommended_profile,
    ]
    command.extend([
        "--fast-inplace",
        "--fast-template-bkp",
        str(template_bkp),
        "--fast-session-restart-interval",
        "10",
    ])
    approval = {
        "approved_at": iso_from_timestamp(time.time()),
        "recommended_bounds_profile": recommended_profile,
        "source_optimizer_report": str(optimizer_report_path.resolve()),
        "source_boundary_status": summary.get("optimization_boundary_status", ""),
        "source_recommended_action": summary.get("optimization_boundary_recommended_action", ""),
        "new_output_dir": str(output_dir.resolve()),
        "fast_template_bkp": str(template_bkp.resolve()) if template_bkp else "",
        "spec": str(spec_path.resolve()),
    }
    report.setdefault("agent_approvals", {})["optimization_bounds_adjustment"] = approval
    task = dict(task)
    task["optimization_bounds_profile"] = recommended_profile
    report["separation_task"] = task
    write_json_file(report_path, report)
    return start_orchestrator_process(
        "approve_optimization_bounds_adjustment",
        task_id,
        command,
        BASE_DIR,
        output_dir / "logs",
        "Bounds adjustment approved; optimizer rerun started with profile {}{}.".format(
            recommended_profile,
            " using fast in-place Aspen" if template_bkp else "",
        ),
    )


def import_generated_topology_assets_action(report, report_path):
    task = report.get("separation_task") or {}
    report, summary = import_generated_gromacs_assets(report, report_path)
    return {
        "returncode": 0,
        "status": summary.get("status"),
        "action": "import_generated_topology_assets",
        "task_id": task.get("task_id"),
        "message": "拓扑资产导入完成：{} 个 Sobtop 生成资产进入智能体资产库。".format(
            summary.get("imported_asset_count", 0)
        ),
        "generated_topology_import": summary,
        "report_path": str(report_path),
    }


def full_flow_self_check_action(report, report_path):
    task = report.get("separation_task") or {}
    paths = report.get("research_task_package_paths") or {}
    molecular_summary = {"status": "no_molecular_package"}
    process_summary = {"status": "no_aspen_plan"}
    topology_summary = {"status": "not_checked", "imported_asset_count": 0}
    gromacs_readiness = {"status": "not_checked"}
    aspen_plan = {"status": "missing", "can_generate_bkp_now": False}

    if paths.get("molecular_inputs_dir") and (paths.get("gaussian_jobs_csv") or paths.get("gromacs_jobs_csv")):
        report, molecular_summary = import_molecular_results(report, report_path)
        paths = report.get("research_task_package_paths") or {}

    if paths.get("aspen_build_plan_json"):
        report, process_summary = import_process_results(report, report_path)
        paths = report.get("research_task_package_paths") or {}
        try:
            plan = read_json(paths.get("aspen_build_plan_json"))
            aspen_plan = {
                "status": plan.get("status") or "available",
                "can_generate_bkp_now": bool(plan.get("can_generate_bkp_now")),
                "boundary": friendly_aspen_boundary(plan, task),
                "selected_property_method": plan.get("selected_property_method"),
            }
        except Exception as exc:
            aspen_plan = {"status": "read_failed", "can_generate_bkp_now": False, "boundary": str(exc)}

    if paths.get("molecular_inputs_dir"):
        report, topology_summary = import_generated_gromacs_assets(report, report_path)
        paths = report.get("research_task_package_paths") or {}

    if paths.get("run_gromacs_queue_ps1") and paths.get("molecular_inputs_dir"):
        try:
            gromacs_readiness = inspect_gromacs_queue_readiness(paths)
        except Exception as exc:
            gromacs_readiness = {"status": "read_failed", "error": str(exc)}

    report = enrich_trial_report_payload(report)
    old_paths = report.get("research_task_package_paths") or {}
    output_dir = Path(report.get("output_dir") or Path(report_path).parent)
    paths = export_research_task_package(report, output_dir)
    paths = attach_existing_molecular_import_paths(paths)
    if old_paths.get("full_flow_autopilot_status_json"):
        paths["full_flow_autopilot_status_json"] = old_paths["full_flow_autopilot_status_json"]
    report["research_task_package_paths"] = paths
    report = enrich_trial_report_payload(report)
    refresh_system_frontend_artifacts(report, report_path)
    write_json_file(report_path, report)
    stages = report.get("agent_stage_trace") or []
    unfinished = [
        row for row in stages
        if row.get("status") in {"blocked", "queued", "missing", "partial"}
    ]
    closed_loop = task_is_full_flow_verified(report)
    screening_state = build_screening_state(report)
    external_state = screening_state.get("external_candidate_library") or {}
    alpha_state = (screening_state.get("progress") or {}).get("alpha") or {}
    if not closed_loop and screening_state.get("stage") in {
        "candidate_generation",
        "alpha_queue",
        "external_candidate_discovery",
        "external_candidate_triage",
        "property_strategy_review",
        "strategy_review",
    }:
        message = (
            "全流程自检完成：当前停在【{}】。{}；Aspen α 已完成 {}/{}，通过 {}；外部候选 {} 个，可直接进 α {} 个，待 Aspen ID/物性映射 {} 个。本轮未启动真实长计算。".format(
                screening_state.get("stage_label") or screening_state.get("stage") or "筛选阶段",
                screening_state.get("stage_title") or screening_state.get("stage_copy") or "等待下一步",
                alpha_state.get("completed", 0),
                alpha_state.get("total", 0),
                alpha_state.get("pass", 0),
                external_state.get("total_count", 0),
                external_state.get("ready_for_aspen_alpha_count", 0),
                (
                    int(external_state.get("needs_aspen_identity_mapping_count") or 0)
                    + int(external_state.get("needs_boiling_point_or_process_gate_review_count") or 0)
                ),
            )
        )
    else:
        message = (
            "全流程自检完成：已识别当前报告的分子证据 {} / {} 行、流程结果 {} / {} 行；{}。".format(
                molecular_summary.get("evidence_record_count", 0),
                molecular_summary.get("row_count", 0),
                process_summary.get("process_result_count", 0),
                process_summary.get("row_count", 0),
                "当前任务已形成导入闭环" if closed_loop else "仍需继续执行或导入外部计算结果",
            )
        )
    return {
        "returncode": 0,
        "status": "closed_loop_outputs_imported" if closed_loop else (screening_state.get("stage") or "waiting_external_results"),
        "action": "full_flow_self_check",
        "task_id": task.get("task_id"),
        "message": message,
        "screening_state": screening_state,
        "molecular_evidence_import": molecular_summary,
        "process_result_import": process_summary,
        "generated_topology_import": topology_summary,
        "gromacs_readiness": gromacs_readiness,
        "aspen_plan": aspen_plan,
        "unfinished_stage_count": len(unfinished),
        "unfinished_stages": unfinished,
        "report_path": str(report_path),
    }


def launch_aspen_optimization_once(report, report_path):
    task = report.get("separation_task") or {}
    task_id = task.get("task_id") or ""
    safety_blocker = aspen_launch_safety_blocker("run_aspen_optimization_once", task_id)
    if safety_blocker:
        return safety_blocker
    if not task.get("compatible_verified_case"):
        paths = report.get("research_task_package_paths") or {}
        molecular_gate = molecular_validation_gate_summary(report, paths)
        if not molecular_gate.get("gate_open"):
            return set_orchestrator_blocked(
                "run_aspen_optimization_once",
                task_id,
                "Aspen 多目标优化被分子门控拦截：{} 先补齐当前体系/当前萃取剂的 Gaussian、NCI/VMD、GROMACS 证据，再解锁优化。".format(
                    molecular_gate.get("message") or "分子验证未完成。"
                ),
                {"report_path": str(report_path), "molecular_gate": molecular_gate},
            )
        plan_path = generated_path(paths.get("aspen_build_plan_json"), "aspen_build_plan_json")
        if not plan_path.exists():
            return set_orchestrator_blocked("run_aspen_optimization_once", task_id, "Aspen 建模计划不存在：{}".format(plan_path))
        plan = read_json(plan_path)
        if not plan.get("can_generate_bkp_now"):
            return set_orchestrator_blocked(
                "run_aspen_optimization_once",
                task_id,
                "当前体系还不能进入通用 Aspen 优化：{}".format(friendly_aspen_boundary(plan, task)),
                {"report_path": str(report_path), "aspen_build_plan_json": str(plan_path)},
            )
        spec_path = generated_path(paths.get("aspen_zero_build_spec_json") or (plan_path.parent / "aspen_zero_build_spec.json"), "aspen_zero_build_spec_json")
        if not spec_path.exists():
            return set_orchestrator_blocked("run_aspen_optimization_once", task_id, "Aspen zero-build spec 不存在：{}".format(spec_path))
        report, paths, price_evidence = ensure_current_solvent_price_evidence(report, report_path)
        process_summary = report.get("process_result_import") or {}
        closed_loop_diag = (process_summary or {}).get("closed_loop_recycle_diagnosis") or {}
        if not closed_loop_diag:
            try:
                progress_summary = aspen_progress_summary(report, report_path)
                closed_loop_diag = progress_summary.get("closed_loop_recycle_diagnosis") or {}
            except Exception:
                closed_loop_diag = {}
        if closed_loop_diag.get("agent_should_stop_before_more_optimization"):
            untested_repair_strategies = closed_loop_diag.get("untested_repair_strategies") or []
            if isinstance(untested_repair_strategies, str):
                untested_repair_strategies = [untested_repair_strategies]
            untested_repair_strategies = [
                str(item or "").strip()
                for item in untested_repair_strategies
                if str(item or "").strip()
            ]
            if (
                closed_loop_diag.get("status") == "closed_loop_required_outputs_missing"
                and untested_repair_strategies
            ):
                return set_orchestrator_blocked(
                    "run_aspen_optimization_once",
                    task_id,
                    "Aspen required outputs are missing, and the repair probe has not covered all generic recycle-control families yet: {}. Continue the full-flow agent repair probe first.".format(
                        ", ".join(untested_repair_strategies)
                    ),
                    {
                        "report_path": str(report_path),
                        "aspen_zero_build_spec_json": str(spec_path),
                        "closed_loop_recycle_diagnosis": closed_loop_diag,
                        "recommended_agent_action": "continue_required_output_repair_probe",
                        "missing_repair_mode_families": untested_repair_strategies,
                    },
                )
            return set_orchestrator_blocked(
                "run_aspen_optimization_once",
                task_id,
                "Agent stopped before another Aspen campaign: closed-loop recycle repair is required ({})".format(
                    closed_loop_diag.get("dominant_failure") or "no closed-loop pass"
                ),
                {
                    "report_path": str(report_path),
                    "aspen_zero_build_spec_json": str(spec_path),
                    "closed_loop_recycle_diagnosis": closed_loop_diag,
                },
            )
        output_dir = Path(report.get("output_dir") or Path(report_path).parent) / "aspen_optimization_once_{}".format(
            dt.datetime.now().strftime("%Y%m%d_%H%M%S")
        )
        aspen_dir = plan_path.parent / "aspen_generated"
        seed_report = aspen_dir / "{}_zero_agent.autoverify.json".format(safe_file_token(task_id or "binary_task"))
        zero_bkp = aspen_dir / "{}_zero_agent.bkp".format(safe_file_token(task_id or "binary_task"))
        if not zero_bkp.exists():
            return set_orchestrator_blocked(
                "run_aspen_optimization_once",
                task_id,
                "Fast in-place Aspen optimization needs the current-system zero-build BKP first. Run Aspen generation, then start optimization.",
                {
                    "report_path": str(report_path),
                    "required_bkp": str(zero_bkp.resolve()),
                    "aspen_zero_build_spec_json": str(spec_path),
                },
            )
        resume_report_path = None
        reset_resume_convergence = False
        try:
            latest_optimizer_path = optimizer_report_path_from_progress(report)
            latest_optimizer_payload = read_json_default(latest_optimizer_path, {}) if latest_optimizer_path else {}
            latest_convergence = latest_optimizer_payload.get("convergence") or {}
            latest_rows = optimizer_report_rows_with_events(latest_optimizer_payload, latest_optimizer_path)
            current_price = (price_evidence or {}).get("selected_price_usd_per_kg")
            price_mismatch = optimizer_report_has_solvent_price_mismatch(latest_optimizer_payload, current_price)
            if (
                latest_optimizer_path
                and latest_optimizer_path.exists()
                and latest_rows
                and (not truthy_cell(latest_convergence.get("converged")) or price_mismatch)
            ):
                resume_report_path = latest_optimizer_path
                reset_resume_convergence = bool(price_mismatch)
        except Exception:
            resume_report_path = None
            reset_resume_convergence = False
        campaign = optimization_campaign_defaults(task)
        population_size = int(campaign.get("population_size") or FAST_OPTIMIZATION_POPULATION_SIZE)
        max_generations = int(campaign.get("max_generations") or campaign.get("generations") or FAST_OPTIMIZATION_GENERATIONS)
        min_generations = int(campaign.get("minimum_generations") or FAST_OPTIMIZATION_GENERATIONS)
        convergence_patience = int(campaign.get("convergence_patience") or FAST_OPTIMIZATION_CONVERGENCE_PATIENCE)
        run_until_converged = bool(campaign.get("run_until_converged"))
        generation_limit = int(campaign.get("safety_max_generations") or (0 if run_until_converged else max_generations))
        bounds_profile = str(campaign.get("bounds_profile") or "exploratory")
        search_mode = str(campaign.get("search_mode") or "nsga2_hybrid")
        random_seed = int(campaign.get("random_seed") or 20260630)
        crossover_rate = float(campaign.get("crossover_rate") or 0.85)
        mutation_rate = float(campaign.get("mutation_rate") or 0.18)
        command = [
            sys.executable,
            str(BASE_DIR / "generic_aspen_once_optimizer.py"),
            "--spec",
            str(spec_path),
            "--output-dir",
            str(output_dir),
            "--population-size",
            str(population_size),
            "--search-mode",
            search_mode,
            "--random-seed",
            str(random_seed),
            "--crossover-rate",
            str(crossover_rate),
            "--mutation-rate",
            str(mutation_rate),
            "--generations",
            str(generation_limit),
            "--case-timeout-seconds",
            "240",
            "--aspen-cleanup-batch-size",
            "1",
            "--aspen-cleanup-settle-seconds",
            "18",
            "--aspen-cleanup-cooldown-seconds",
            "10",
            "--aspen-process-limit",
            str(ASPEN_MAX_PARALLEL_PROCESSES),
            "--min-generations",
            str(min_generations),
            "--convergence-patience",
            str(convergence_patience),
            "--bounds-profile",
            bounds_profile,
        ]
        if resume_report_path:
            command.extend(["--resume-report", str(resume_report_path)])
        if reset_resume_convergence:
            command.append("--reset-resume-convergence")
        if run_until_converged:
            command.append("--run-until-converged")
        if seed_report.exists():
            command.extend(["--seed-report", str(seed_report)])
        command.extend([
            "--fast-inplace",
            "--fast-template-bkp",
            str(zero_bkp),
            "--fast-session-id",
            "{}_optimization".format(safe_file_token(task_id or "binary_task")),
            "--fast-session-restart-interval",
            "10",
            "--fast-run-timeout-seconds",
            "240",
        ])
        return start_orchestrator_process(
            "run_aspen_optimization_once",
            task_id,
            command,
            BASE_DIR,
            output_dir / "logs",
            "通用 Aspen 收敛型多目标优化已由智能体启动：population={}, max_generations={}, min_generations={}, patience={}, solvent_price={} USD/kg, output={}".format(
                population_size,
                max_generations,
                min_generations,
                convergence_patience,
                (price_evidence or {}).get("selected_price_usd_per_kg", ""),
                output_dir,
            ),
        )
    if not task.get("compatible_verified_case"):
        return set_orchestrator_blocked(
            "run_aspen_optimization_once",
            task_id,
            "当前体系还不能直接进入 Aspen 优化：智能体尚未形成可复用 BKP/变量映射/流程证据边界。请先完成 Gaussian/Sobtop/GROMACS 导入和 Aspen 组分/物性确认。",
            {
                "required_before_optimization": [
                    "imported molecular evidence",
                    "Aspen component mapping",
                    "property-method/BIP provenance",
                    "BKP or compatible template",
                    "variable/unit map",
                ],
                "report_path": str(report_path),
            },
        )
    output_dir = Path(report.get("output_dir") or Path(report_path).parent) / "aspen_optimization_once_{}".format(
        dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    )
    command = [
        sys.executable,
        str(BASE_DIR / "full_screening_agent.py"),
        "--component-a", str(task.get("component_a") or "C3F8"),
        "--component-b", str(task.get("component_b") or "C3F6"),
        "--target-product", str(task.get("target_product") or "C3F8"),
        "--target-purity", str(task.get("target_purity") or 0.999),
        "--separation-class", str(task.get("separation_class") or "near-boiling fluorocarbon binary"),
        "--process-boundary", str(task.get("process_boundary") or "closed-loop extractive distillation"),
        "--property-method", str(task.get("property_method") or "PRWS"),
        "--feed-temperature-c", str(task.get("feed_temperature_c") or 50.0),
        "--feed-pressure-mpa", str(task.get("feed_pressure_mpa") or 0.1),
        "--feed-molar-ratio", str(task.get("feed_molar_ratio") or "90/10 mol%"),
        "--flow-validation-count", "1",
        "--run-optimization",
        "--optimization-population-size", "4",
        "--optimization-generations", "2",
        "--output-dir", str(output_dir),
    ]
    target_recovery = clean_optional_unit_interval(task.get("target_recovery"))
    if target_recovery is not None:
        command.extend(["--target-recovery", str(target_recovery)])
    return start_orchestrator_process(
        "run_aspen_optimization_once",
        task_id,
        command,
        BASE_DIR,
        output_dir / "logs",
        "Aspen 多目标优化已由智能体启动：population=4, generations=2, output={}".format(output_dir),
    )


def preflight_aspen_optimization_once(report, report_path):
    task = report.get("separation_task") or {}
    task_id = task.get("task_id") or ""
    compatible = bool(task.get("compatible_verified_case"))
    template = Path(vm.TEMPLATE_BKP).resolve()
    script = BASE_DIR / "optimize_nmp_nsga2.py"
    win32com_status = "unknown"
    try:
        import win32com.client  # noqa: F401
        win32com_status = "available"
    except Exception as exc:
        win32com_status = "{}: {}".format(exc.__class__.__name__, exc)
    command_preview = [
        sys.executable,
        str(BASE_DIR / "full_screening_agent.py"),
        "--component-a", str(task.get("component_a") or "C3F8"),
        "--component-b", str(task.get("component_b") or "C3F6"),
        "--target-product", str(task.get("target_product") or "C3F8"),
        "--flow-validation-count", "1",
        "--run-optimization",
        "--optimization-population-size", "4",
        "--optimization-generations", "2",
    ]
    blockers = []
    if not compatible:
        blockers.append("current binary system is not inside verified Aspen optimization boundary")
    if not template.exists():
        blockers.append("Aspen template BKP not found: {}".format(template))
    if not script.exists():
        blockers.append("optimizer script not found: {}".format(script))
    if win32com_status != "available":
        blockers.append("win32com unavailable: {}".format(win32com_status))
    status = "ready" if not blockers else "blocked"
    return {
        "returncode": 0,
        "status": status,
        "action": "preflight_aspen_optimization_once",
        "task_id": task_id,
        "message": (
            "Aspen 一次优化预检通过；可由智能体启动真实优化。"
            if status == "ready"
            else "Aspen 一次优化预检被闸门阻塞：{}".format("；".join(blockers))
        ),
        "compatible_verified_case": compatible,
        "template_bkp": str(template),
        "template_exists": template.exists(),
        "optimizer_script": str(script),
        "optimizer_script_exists": script.exists(),
        "win32com_status": win32com_status,
        "command_preview": command_preview,
        "blockers": blockers,
        "report_path": str(report_path),
    }


def expand_candidate_library_action(report, report_path):
    task = dict(report.get("separation_task") or {})
    task_id = task.get("task_id") or ""
    if not task:
        return set_orchestrator_blocked("expand_candidate_library", task_id, "当前报告缺少 separation_task，不能扩展候选库。")
    policy = screening_policy(report)
    current_pool = (((report.get("system_research_brief") or {}).get("candidate_solvent_pool") or {}).get("items") or [])
    expanded_report = report_with_candidate_pool_mode(report, "expanded_pubchem_material_library")
    expanded_capacity = min(candidate_pool_limit(expanded_report), len(candidate_base_rows_for_task(expanded_report)))
    if candidate_pool_mode(report).startswith("expanded") and len(current_pool) >= expanded_capacity:
        return set_orchestrator_blocked(
            "expand_candidate_library",
            task_id,
            "当前本地扩展候选库已到容量上限（{} 个），不能无休止重复扩展；请先复核体系策略或接入新的外部材料库。".format(expanded_capacity),
            {"candidate_pool_count": len(current_pool), "expanded_local_capacity": expanded_capacity},
        )
    if len(current_pool) >= policy["max_candidate_total"]:
        return set_orchestrator_blocked(
            "expand_candidate_library",
            task_id,
            "候选总预算已达到 {} 个，停止继续扩展；请先复核萃取剂家族、物性方法或分离路线。".format(policy["max_candidate_total"]),
            {"candidate_pool_count": len(current_pool), "max_candidate_total": policy["max_candidate_total"]},
        )
    old_paths = dict(report.get("research_task_package_paths") or {})
    task["candidate_pool_mode"] = "expanded_pubchem_material_library"
    task["candidate_pool_expanded_at"] = iso_from_timestamp(time.time())
    task["candidate_pool_policy"] = (
        "Expand from the seed entrainer set to the local extractive-solvent material library; "
        "each candidate still needs PubChem identity lookup and Aspen alpha screening before Gaussian."
    )
    report["separation_task"] = task
    report.pop("system_research_brief", None)
    report = enrich_trial_report_payload(report)
    output_dir = Path(report.get("output_dir") or Path(report_path).parent)
    paths = export_research_task_package(report, output_dir)
    if old_paths.get("full_flow_autopilot_status_json"):
        paths["full_flow_autopilot_status_json"] = old_paths["full_flow_autopilot_status_json"]
    report["research_task_package_paths"] = paths
    report = enrich_trial_report_payload(report)
    refresh_system_frontend_artifacts(report, report_path)
    write_json_file(report_path, report)
    pool = (((report.get("system_research_brief") or {}).get("candidate_solvent_pool") or {}).get("items") or [])
    request_rows = read_csv_rows(generated_path(paths.get("relative_volatility_kvalue_request_csv"), "relative_volatility_kvalue_request_csv"))
    return {
        "returncode": 0,
        "status": "done",
        "action": "expand_candidate_library",
        "report_path": str(Path(report_path).resolve()),
        "candidate_pool_count": len(pool),
        "relative_volatility_request_rows": len(request_rows),
        "message": "候选库已扩展为 {} 个萃取剂，并生成 {} 条 Aspen α 请求；下一步可运行下一支未完成候选。".format(len(pool), len(request_rows)),
    }


def import_external_candidate_library_action(report, report_path):
    task = dict(report.get("separation_task") or {})
    task_id = task.get("task_id") or ""
    if not external_candidate_sources_available():
        return set_orchestrator_blocked(
            "import_external_candidate_library",
            task_id,
            "没有找到外部候选库文件；当前不会伪造 PubChem 候选。请先生成 online_recommendations.json 或 active_learning_recommendations.json。",
        )
    library = load_external_candidate_library(report)
    report["external_candidate_library"] = library
    output_dir = Path(report.get("output_dir") or Path(report_path).parent)
    package_dir = output_dir / "research_task_package"
    package_dir.mkdir(parents=True, exist_ok=True)
    paths = dict(report.get("research_task_package_paths") or {})
    paths["external_candidate_library_csv"] = str((package_dir / "external_candidate_library.csv").resolve())
    paths["external_candidate_identity_queue_csv"] = str((package_dir / "external_candidate_identity_queue.csv").resolve())
    write_csv_file(paths["external_candidate_library_csv"], library.get("items") or [])
    write_csv_file(paths["external_candidate_identity_queue_csv"], library.get("identity_mapping_queue") or [])
    report["research_task_package_paths"] = paths
    report = enrich_trial_report_payload(report)
    refresh_system_frontend_artifacts(report, report_path)
    write_json_file(report_path, report)
    return {
        "returncode": 0,
        "status": "done",
        "action": "import_external_candidate_library",
        "report_path": str(Path(report_path).resolve()),
        "external_candidate_count": library.get("total_count") or 0,
        "ready_for_aspen_alpha_count": library.get("ready_for_aspen_alpha_count") or 0,
        "needs_aspen_identity_mapping_count": library.get("needs_aspen_identity_mapping_count") or 0,
        "message": (
            "外部候选库已导入 {} 个候选；其中 {} 个可直接进入 Aspen α，{} 个需要先做 Aspen ID/物性映射。本动作没有启动真实计算。"
        ).format(
            library.get("total_count") or 0,
            library.get("ready_for_aspen_alpha_count") or 0,
            library.get("needs_aspen_identity_mapping_count") or 0,
        ),
    }


def preflight_external_candidate_identity_action(report, report_path):
    task = dict(report.get("separation_task") or {})
    task_id = task.get("task_id") or ""
    library = report.get("external_candidate_library") or load_external_candidate_library(report)
    library = refresh_external_candidate_library_counts(library)
    if not library.get("items"):
        return set_orchestrator_blocked(
            "preflight_external_candidate_identity",
            task_id,
            "外部候选库为空；请先导入 PubChem/主动学习候选库。",
        )
    new_ready = external_ready_candidates_new_to_local_pool(report, library)
    if new_ready:
        return {
            "returncode": 0,
            "status": "ready_for_aspen_alpha",
            "action": "preflight_external_candidate_identity",
            "report_path": str(Path(report_path).resolve()),
            "ready_for_aspen_alpha_count": len(new_ready),
            "message": "已有 {} 个外部候选满足 Aspen ID/物性预检；下一步可加入 Aspen α 队列，本动作未启动长计算。".format(
                len(new_ready)
            ),
        }

    policy = screening_policy(report)
    batch_size = clean_int_arg(
        policy.get("external_identity_batch_size"),
        EXTERNAL_IDENTITY_PREFLIGHT_BATCH_SIZE,
        min_value=1,
        max_value=12,
    )
    rows = [dict(row) for row in (library.get("items") or [])]
    queue = [
        row for row in rows
        if row.get("external_candidate_status") == "needs_aspen_identity_mapping"
        and not external_candidate_formula(row)
    ]
    if not queue:
        return set_orchestrator_blocked(
            "preflight_external_candidate_identity",
            task_id,
            "外部候选没有剩余可自动预检的 PubChem 身份项；当前仍需人工补可靠沸点、Aspen ID 或物性参数来源。",
            {
                "needs_mapping_count": library.get("needs_aspen_identity_mapping_count") or 0,
                "needs_review_count": library.get("needs_boiling_point_or_process_gate_review_count") or 0,
            },
        )

    existing_aspen_ids = {
        component_token(row.get("aspen_component_id"))
        for row in rows
        if row.get("aspen_component_id")
    }
    checked_rows = []
    checked_keys = set()
    for index, candidate in enumerate(queue[:batch_size], start=1):
        updated = dict(candidate)
        lookup = pubchem_lookup_candidate_identity(updated)
        updated["pubchem_identity_status"] = lookup.get("status") or "not_checked"
        updated["pubchem_identity_query"] = lookup.get("query") or ""
        updated["pubchem_source_url"] = lookup.get("source_url") or ""
        updated["pubchem_title"] = lookup.get("title") or ""
        updated["pubchem_cas"] = "; ".join(lookup.get("cas") or [])
        if lookup.get("status") == "found":
            if lookup.get("cid"):
                updated["cid"] = lookup.get("cid")
            if lookup.get("molecular_formula"):
                updated["molecular_formula"] = lookup.get("molecular_formula")
                updated["formula"] = lookup.get("molecular_formula")
            if lookup.get("molecular_weight"):
                updated["molecular_weight"] = safe_float(lookup.get("molecular_weight"))
            if lookup.get("iupac_name"):
                updated["iupac_name"] = lookup.get("iupac_name")
            if not updated.get("aspen_component_id") and external_candidate_formula(updated):
                local_id = external_candidate_local_aspen_id(updated, updated.get("rank") or index)
                base_id = local_id
                suffix = 2
                while component_token(local_id) in existing_aspen_ids:
                    local_id = "{}{}".format(base_id[:max(1, 8 - len(str(suffix)))], suffix)
                    suffix += 1
                updated["aspen_component_id"] = local_id
                existing_aspen_ids.add(component_token(local_id))
                updated["aspen_alias_confidence"] = "pubchem_formula_preflight_needs_aspen_probe"
                updated["aspen_databank_query"] = external_candidate_formula(updated)
        updated = refresh_external_candidate_status(updated)
        updated["identity_preflight_checked_at"] = iso_from_timestamp(time.time())
        checked_rows.append(updated)
        checked_keys.add(component_token(updated.get("cid")) or component_token(updated.get("name")) or component_token(updated.get("code")))

    by_key = {}
    for row in rows:
        key = component_token(row.get("cid")) or component_token(row.get("name")) or component_token(row.get("code"))
        by_key[key] = row
    for row in checked_rows:
        key = component_token(row.get("cid")) or component_token(row.get("name")) or component_token(row.get("code"))
        by_key[key] = row
    updated_rows = []
    seen_keys = set()
    for row in rows:
        key = component_token(row.get("cid")) or component_token(row.get("name")) or component_token(row.get("code"))
        if key in seen_keys:
            continue
        seen_keys.add(key)
        updated_rows.append(by_key.get(key, row))
    library["items"] = updated_rows
    library = refresh_external_candidate_library_counts(library)
    library["identity_preflight_updated_at"] = iso_from_timestamp(time.time())
    report["external_candidate_library"] = library

    previous_preflight = report.get("external_candidate_identity_preflight") or {}
    history = list(previous_preflight.get("checked_items") or [])
    history_by_key = {}
    for row in history:
        key = component_token(row.get("cid")) or component_token(row.get("name")) or component_token(row.get("code"))
        history_by_key[key] = row
    for row in checked_rows:
        key = component_token(row.get("cid")) or component_token(row.get("name")) or component_token(row.get("code"))
        history_by_key[key] = row
    history_rows = list(history_by_key.values())
    report["external_candidate_identity_preflight"] = {
        "status": "done",
        "generated_at": iso_from_timestamp(time.time()),
        "batch_size": batch_size,
        "checked_this_batch_count": len(checked_rows),
        "checked_total_count": len(history_rows),
        "ready_for_aspen_alpha_count": library.get("ready_for_aspen_alpha_count") or 0,
        "needs_aspen_identity_mapping_count": library.get("needs_aspen_identity_mapping_count") or 0,
        "needs_boiling_point_or_process_gate_review_count": library.get("needs_boiling_point_or_process_gate_review_count") or 0,
        "policy": "Small-batch PubChem CID/formula preflight only; Aspen alpha remains a separate explicit one-candidate action.",
        "latest_batch": checked_rows,
        "checked_items": history_rows,
    }

    output_dir = Path(report.get("output_dir") or Path(report_path).parent)
    package_dir = output_dir / "research_task_package"
    package_dir.mkdir(parents=True, exist_ok=True)
    paths = dict(report.get("research_task_package_paths") or {})
    paths["external_candidate_library_csv"] = str((package_dir / "external_candidate_library.csv").resolve())
    paths["external_candidate_identity_queue_csv"] = str((package_dir / "external_candidate_identity_queue.csv").resolve())
    paths["external_candidate_identity_preflight_csv"] = str((package_dir / "external_candidate_identity_preflight.csv").resolve())
    write_csv_file(paths["external_candidate_library_csv"], library.get("items") or [])
    write_csv_file(paths["external_candidate_identity_queue_csv"], library.get("identity_mapping_queue") or [])
    write_csv_file(paths["external_candidate_identity_preflight_csv"], history_rows)
    report["research_task_package_paths"] = paths
    report = enrich_trial_report_payload(report)
    refresh_system_frontend_artifacts(report, report_path)
    write_json_file(report_path, report)
    return {
        "returncode": 0,
        "status": "done",
        "action": "preflight_external_candidate_identity",
        "report_path": str(Path(report_path).resolve()),
        "checked_this_batch_count": len(checked_rows),
        "ready_for_aspen_alpha_count": library.get("ready_for_aspen_alpha_count") or 0,
        "needs_aspen_identity_mapping_count": library.get("needs_aspen_identity_mapping_count") or 0,
        "needs_boiling_point_or_process_gate_review_count": library.get("needs_boiling_point_or_process_gate_review_count") or 0,
        "message": (
            "外部候选身份预检完成：本批检查 {} 个，当前可进 Aspen α {} 个，仍待 Aspen ID {} 个，待物性复核 {} 个。本动作未启动 Aspen/Gaussian/GROMACS。"
        ).format(
            len(checked_rows),
            library.get("ready_for_aspen_alpha_count") or 0,
            library.get("needs_aspen_identity_mapping_count") or 0,
            library.get("needs_boiling_point_or_process_gate_review_count") or 0,
        ),
    }


def activate_external_aspen_candidates_action(report, report_path):
    task = dict(report.get("separation_task") or {})
    task_id = task.get("task_id") or ""
    library = report.get("external_candidate_library") or load_external_candidate_library(report)
    library = refresh_external_candidate_library_counts(library)
    all_ready = library.get("ready_for_aspen_alpha_items") or []
    ready = external_ready_candidates_new_to_local_pool(report, library)
    if not ready and all_ready:
        task["candidate_pool_mode"] = "external_material_library"
        task["external_candidate_activated_at"] = iso_from_timestamp(time.time())
        report["separation_task"] = task
        report["external_candidate_library"] = library
        report.pop("system_research_brief", None)
        report = enrich_trial_report_payload(report)
        refresh_system_frontend_artifacts(report, report_path)
        write_json_file(report_path, report)
        return {
            "returncode": 0,
            "status": "no_new_external_candidates",
            "action": "activate_external_aspen_candidates",
            "report_path": str(Path(report_path).resolve()),
            "ready_external_candidates": len(all_ready),
            "activated_external_candidates": 0,
            "message": "External ready candidates are already present in the current Aspen alpha pool; no new Aspen request rows were added.",
        }
    if not ready:
        return set_orchestrator_blocked(
            "activate_external_aspen_candidates",
            task_id,
            "外部候选库没有 Aspen ID 与萃取精馏物性预检同时通过的候选，不能生成 α 队列。",
            {
                "external_candidate_count": library.get("total_count") or 0,
                "needs_aspen_identity_mapping_count": library.get("needs_aspen_identity_mapping_count") or 0,
            },
        )
    task["candidate_pool_mode"] = "external_material_library"
    task["external_candidate_activated_at"] = iso_from_timestamp(time.time())
    report["separation_task"] = task
    report["external_candidate_library"] = library
    report.pop("system_research_brief", None)
    report = enrich_trial_report_payload(report)
    output_dir = Path(report.get("output_dir") or Path(report_path).parent)
    old_paths = dict(report.get("research_task_package_paths") or {})
    paths = export_research_task_package(report, output_dir)
    for key in ("external_candidate_library_csv", "external_candidate_identity_queue_csv", "full_flow_autopilot_status_json"):
        if old_paths.get(key):
            paths[key] = old_paths[key]
    report["research_task_package_paths"] = paths
    report = enrich_trial_report_payload(report)
    refresh_system_frontend_artifacts(report, report_path)
    write_json_file(report_path, report)
    request_rows = read_csv_rows(generated_path(paths.get("relative_volatility_kvalue_request_csv"), "relative_volatility_kvalue_request_csv"))
    return {
        "returncode": 0,
        "status": "done",
        "action": "activate_external_aspen_candidates",
        "report_path": str(Path(report_path).resolve()),
        "activated_external_candidates": len(ready),
        "relative_volatility_request_rows": len(request_rows),
        "message": "已把 {} 个外部可算候选加入 Aspen α 队列，生成 {} 条请求；仍未启动真实 Aspen 计算。".format(len(ready), len(request_rows)),
    }


def launch_property_method_retry_alpha(report, report_path):
    report = enrich_trial_report_payload(report)
    task = dict(report.get("separation_task") or {})
    task_id = task.get("task_id") or ""
    method = normalize_aspen_property_method(next_property_retry_method(report))
    if not method:
        return set_orchestrator_blocked(
            "retry_alpha_with_predictive_property_method",
            task_id,
            "没有可继续尝试的 Aspen 物性方法；请先补 VLE/BIP 来源或人工指定方法。",
            {"attempted_methods": (report.get("property_strategy_retry") or {}).get("attempted_methods") or []},
        )
    candidate = select_property_retry_candidate(report)
    code = candidate.get("code") or candidate.get("aspen_component_id") or ""
    if not code:
        return set_orchestrator_blocked(
            "retry_alpha_with_predictive_property_method",
            task_id,
            "没有找到可用于物性方法重试的候选萃取剂；请先补候选身份或扩展候选库。",
        )
    script = BASE_DIR / "aspen_relative_volatility_flash.py"
    if not script.exists():
        return set_orchestrator_blocked(
            "retry_alpha_with_predictive_property_method",
            task_id,
            "Aspen α 脚本不存在：{}".format(script),
        )
    output_dir = Path(report.get("output_dir") or Path(report_path).parent)
    package_dir = output_dir / "research_task_package"
    package_dir.mkdir(parents=True, exist_ok=True)
    method_token = safe_file_token(method.lower())
    output_csv = package_dir / "relative_volatility_kvalue_results_{}.csv".format(method_token)
    work_dir = package_dir / "relative_volatility_flash_{}".format(method_token)
    paths = dict(report.get("research_task_package_paths") or {})
    previous_results = paths.get("relative_volatility_kvalue_results_csv") or ""
    if previous_results and previous_results != str(output_csv.resolve()):
        paths.setdefault("relative_volatility_kvalue_results_previous_csv", previous_results)
    paths["relative_volatility_kvalue_results_csv"] = str(output_csv.resolve())
    paths["relative_volatility_flash_work_dir"] = str(work_dir.resolve())
    report["research_task_package_paths"] = paths

    brief = dict(report.get("system_research_brief") or {})
    thermo = dict(brief.get("thermo_method_confirmation") or {})
    thermo["execution_method_candidate"] = method
    thermo["property_strategy_retry_basis"] = (
        "NRTL BIP audit blocked the first alpha campaign; this retry uses a separate Aspen method campaign."
    )
    brief["thermo_method_confirmation"] = thermo
    report["system_research_brief"] = brief
    task["property_method"] = method
    report["separation_task"] = task

    retry = dict(report.get("property_strategy_retry") or {})
    attempted = [
        str(item or "").strip().upper()
        for item in (retry.get("attempted_methods") or [])
        if str(item or "").strip()
    ]
    if method not in attempted:
        attempted.append(method)
    retry.update({
        "status": "running",
        "property_method": method,
        "candidate_code": code,
        "candidate_name": candidate.get("name") or "",
        "attempted_methods": attempted,
        "previous_results_csv": previous_results,
        "output_csv": str(output_csv.resolve()),
        "work_dir": str(work_dir.resolve()),
        "started_at": iso_from_timestamp(time.time()),
        "policy": "one Aspen candidate at a time; Gaussian/GROMACS remain blocked until trusted pass_alpha_gate or integrated_screening_selected.",
    })
    report["property_strategy_retry"] = retry
    write_json_file(report_path, report)

    command = [
        sys.executable,
        str(script),
        "--report",
        str(Path(report_path).resolve()),
        "--max-candidates",
        "1",
        "--candidate-code",
        str(code),
        "--property-method",
        str(method),
        "--output-csv",
        str(output_csv.resolve()),
        "--work-dir",
        str(work_dir.resolve()),
        "--force",
    ]
    message = (
        "物性策略重试已启动：用 {} 对 {} / {} 真实重算 Aspen α；本轮仍只跑 1 个候选，"
        "通过可信 Iα 后才允许进入 Gaussian/GROMACS。"
    ).format(method, code, candidate.get("name") or "")
    return start_orchestrator_process(
        "retry_alpha_with_predictive_property_method",
        task_id,
        command,
        BASE_DIR,
        output_dir / "relative_volatility_flash_logs",
        message,
    )


def launch_relative_volatility_flash(report, report_path, max_candidates=8, skip_completed=False, candidate_code=""):
    task = report.get("separation_task") or {}
    task_id = task.get("task_id") or ""
    script = BASE_DIR / "aspen_relative_volatility_flash.py"
    if not script.exists():
        return set_orchestrator_blocked(
            "run_relative_volatility_flash",
            task_id,
            "Aspen 相对挥发度快算脚本不存在：{}".format(script),
        )
    output_dir = Path(report.get("output_dir") or Path(report_path).parent)
    paths = report.get("research_task_package_paths") or {}
    if not paths.get("relative_volatility_kvalue_request_csv"):
        report = enrich_trial_report_payload(report)
        old_paths = dict(report.get("research_task_package_paths") or {})
        paths = export_research_task_package(report, output_dir)
        if old_paths.get("full_flow_autopilot_status_json"):
            paths["full_flow_autopilot_status_json"] = old_paths["full_flow_autopilot_status_json"]
        report["research_task_package_paths"] = paths
        report = enrich_trial_report_payload(report)
        refresh_system_frontend_artifacts(report, report_path)
        write_json_file(report_path, report)
    request_csv = generated_path(paths.get("relative_volatility_kvalue_request_csv"), "relative_volatility_kvalue_request_csv")
    if not request_csv.exists():
        return set_orchestrator_blocked(
            "run_relative_volatility_flash",
            task_id,
            "还没有 Aspen α 快算请求表；请先重新生成任务包，确认组分/Aspen ID/物性方法后再启动。",
            {"expected_request_csv": str(request_csv)},
        )
    request_rows = read_csv_rows(request_csv)
    if not request_rows:
        return set_orchestrator_blocked(
            "run_relative_volatility_flash",
            task_id,
            "Aspen α 快算请求表为空；候选萃取剂或组分身份还没有准备好。",
            {"request_csv": str(request_csv)},
        )
    command = [
        sys.executable,
        str(script),
        "--report",
        str(Path(report_path).resolve()),
        "--max-candidates",
        str(int(max_candidates or 8)),
    ]
    if skip_completed:
        command.append("--skip-completed")
    if candidate_code:
        command.extend(["--candidate-code", str(candidate_code)])
    output_csv = paths.get("relative_volatility_kvalue_results_csv") or ""
    work_dir = paths.get("relative_volatility_flash_work_dir") or ""
    if output_csv:
        command.extend(["--output-csv", str(generated_path(output_csv, "relative_volatility_kvalue_results_csv"))])
    if work_dir:
        command.extend(["--work-dir", str(generated_path(work_dir, "relative_volatility_flash_work_dir"))])
    retry = report.get("property_strategy_retry") or {}
    retry_method = str(retry.get("property_method") or "").strip()
    retry_method_active = bool(
        retry_method
        and retry.get("status") in {"completed_by_aspen_script", "done", "running", "queued"}
        and retry.get("output_csv")
    )
    thermo = ((report.get("system_research_brief") or {}).get("thermo_method_confirmation") or {})
    property_method = (
        (retry_method if retry_method_active else "")
        or (report.get("separation_task") or {}).get("property_method")
        or thermo.get("execution_method_candidate")
        or (report.get("separation_task") or {}).get("property_method")
        or ""
    )
    if str(property_method or "").strip().lower() not in {"", "to_be_selected", "none"}:
        command.extend(["--property-method", str(property_method)])
    if retry_method_active:
        command.extend(["--output-csv", str(generated_path(retry.get("output_csv"), "relative_volatility_kvalue_results_csv"))])
        if retry.get("work_dir"):
            command.extend(["--work-dir", str(generated_path(retry.get("work_dir"), "relative_volatility_flash_work_dir"))])
    message = (
        "Aspen α 快算已启动；这次只取下一个未完成候选剂，写入 relative_volatility_kvalue_results.csv。"
        if skip_completed and int(max_candidates or 8) == 1
        else "Aspen α 快算已启动；智能体会先计算 base binary 的 alpha0，再按候选萃取剂/S-F 网格写入 relative_volatility_kvalue_results.csv。只有 Iα 过关后才进入 Gaussian/GROMACS。"
    )
    return start_orchestrator_process(
        "run_relative_volatility_flash",
        task_id,
        command,
        BASE_DIR,
        output_dir / "relative_volatility_flash_logs",
        message,
    )


def restart_relative_volatility_flash_from_scratch(report, report_path):
    report = enrich_trial_report_payload(report)
    task = report.get("separation_task") or {}
    task_id = task.get("task_id") or ""
    script = BASE_DIR / "aspen_relative_volatility_flash.py"
    if not script.exists():
        return set_orchestrator_blocked(
            "restart_relative_volatility_flash",
            task_id,
            "Aspen alpha script does not exist: {}".format(script),
        )
    output_dir = Path(report.get("output_dir") or Path(report_path).parent)
    package_dir = output_dir / "research_task_package"
    package_dir.mkdir(parents=True, exist_ok=True)
    paths = dict(report.get("research_task_package_paths") or {})
    if not paths.get("relative_volatility_kvalue_request_csv"):
        old_paths = dict(paths)
        paths = export_research_task_package(report, output_dir)
        if old_paths.get("full_flow_autopilot_status_json"):
            paths["full_flow_autopilot_status_json"] = old_paths["full_flow_autopilot_status_json"]
    request_csv = generated_path(paths.get("relative_volatility_kvalue_request_csv"), "relative_volatility_kvalue_request_csv")
    if not request_csv.exists():
        return set_orchestrator_blocked(
            "restart_relative_volatility_flash",
            task_id,
            "Aspen alpha request CSV is missing; regenerate the task package before restarting alpha.",
            {"expected_request_csv": str(request_csv)},
        )
    request_rows = read_csv_rows(request_csv)
    if not request_rows:
        return set_orchestrator_blocked(
            "restart_relative_volatility_flash",
            task_id,
            "Aspen alpha request CSV is empty; no candidate can be restarted.",
            {"request_csv": str(request_csv)},
        )

    token = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    output_csv = package_dir / "relative_volatility_kvalue_results_from_scratch_{}.csv".format(token)
    work_dir = package_dir / "relative_volatility_flash_from_scratch_{}".format(token)
    previous_results = paths.get("relative_volatility_kvalue_results_csv") or ""
    if previous_results:
        paths["relative_volatility_kvalue_results_previous_csv"] = previous_results
    paths["relative_volatility_kvalue_results_csv"] = str(output_csv.resolve())
    paths["relative_volatility_flash_work_dir"] = str(work_dir.resolve())
    report["research_task_package_paths"] = paths
    report["alpha_recalculation_campaign"] = {
        "status": "running_from_scratch",
        "started_at": iso_from_timestamp(time.time()),
        "policy": "new results CSV; recompute base VLE; run one candidate at a time under the Aspen process guard",
        "output_csv": str(output_csv.resolve()),
        "work_dir": str(work_dir.resolve()),
        "previous_results_csv": previous_results,
    }
    report.pop("property_strategy_retry", None)
    write_json_file(report_path, report)

    property_method = (
        task.get("property_method")
        or (((report.get("system_research_brief") or {}).get("thermo_method_confirmation") or {}).get("execution_method_candidate"))
        or ""
    )
    command = [
        sys.executable,
        str(script),
        "--report",
        str(Path(report_path).resolve()),
        "--max-candidates",
        str(int(screening_policy(report).get("alpha_batch_size", 1) or 1)),
        "--output-csv",
        str(output_csv.resolve()),
        "--work-dir",
        str(work_dir.resolve()),
        "--force",
    ]
    if str(property_method or "").strip().lower() not in {"", "to_be_selected", "none"}:
        command.extend(["--property-method", str(property_method)])
    message = (
        "Aspen alpha restart from scratch started: new CSV, recompute base VLE, "
        "then run one candidate only. Gaussian/GROMACS remain blocked until the corrected gate passes."
    )
    return start_orchestrator_process(
        "restart_relative_volatility_flash",
        task_id,
        command,
        BASE_DIR,
        output_dir / "relative_volatility_flash_logs",
        message,
    )


def launch_next_relative_volatility_candidate(report, report_path):
    report = enrich_trial_report_payload(report)
    task = report.get("separation_task") or {}
    state = build_screening_state(report)
    global_blocker = ((state.get("blockers") or {}).get("alpha_global_blocker") or {})
    if global_blocker.get("blocked") and global_blocker.get("next_action") != "run_next_relative_volatility_candidate":
        blocker_reason = str(
            global_blocker.get("reason") or global_blocker.get("status") or "alpha0 不可信"
        ).rstrip("。.;； ")
        return set_orchestrator_blocked(
            "run_next_relative_volatility_candidate",
            task.get("task_id") or "",
            "Aspen α 入口被全局阻塞，不能继续运行下一支候选。下一步应为：{}；原因：{}。".format(
                global_blocker.get("next_action_label") or state.get("next_action_label") or "复核 Aspen 物性",
                blocker_reason,
            ),
            {"screening_state": state, "alpha_global_blocker": global_blocker},
        )
    candidate = state.get("current_candidate") or {}
    code = candidate.get("code") or candidate.get("aspen_component_id") or ""
    if state.get("next_action") != "run_next_relative_volatility_candidate" or not code:
        return set_orchestrator_blocked(
            "run_next_relative_volatility_candidate",
            task.get("task_id") or "",
            "当前没有可继续运行的 Aspen α 候选；请先刷新体系状态、扩展候选库，或进入下一阶段。",
            {"screening_state": state},
        )
    return launch_relative_volatility_flash(
        report,
        report_path,
        max_candidates=screening_policy(report).get("alpha_batch_size", 1),
        skip_completed=True,
        candidate_code=code,
    )


def launch_agent_full_flow_autopilot(report, report_path, selected_solvent_code=""):
    task = report.get("separation_task") or {}
    task_id = task.get("task_id") or ""
    runner = BASE_DIR / "agent_full_flow_runner.py"
    if not runner.exists():
        return set_orchestrator_blocked("agent_full_flow_autopilot", task_id, "全流程 runner 不存在：{}".format(runner))
    if not task.get("compatible_verified_case"):
        screen = build_screening_state(report)
        alpha = ((screen.get("progress") or {}).get("alpha") or {})
        screen_stage = str(screen.get("stage") or "").strip()
        screen_next_action = str(screen.get("next_action") or "").strip()
        # Full-flow autopilot is stage-aware: finish screening/property gates before locking a solvent.
        if screen_stage in {
            "candidate_generation",
            "alpha_queue",
            "property_strategy_review",
            "strategy_review",
            "external_candidate_discovery",
            "external_candidate_triage",
            "component_identity",
        }:
            if screen_next_action == "restart_relative_volatility_flash":
                return restart_relative_volatility_flash_from_scratch(report, report_path)
            if screen_next_action == "retry_alpha_with_predictive_property_method":
                return launch_property_method_retry_alpha(report, report_path)
            if screen_next_action == "expand_candidate_library":
                return expand_candidate_library_action(report, report_path)
            if screen_next_action == "import_external_candidate_library":
                return import_external_candidate_library_action(report, report_path)
            if screen_next_action == "preflight_external_candidate_identity":
                return preflight_external_candidate_identity_action(report, report_path)
            if screen_next_action == "activate_external_aspen_candidates":
                return activate_external_aspen_candidates_action(report, report_path)
            if screen_next_action == "full_flow_self_check":
                return full_flow_self_check_action(report, report_path)
        if int(alpha.get("pending") or 0) > 0:
            return launch_next_relative_volatility_candidate(report, report_path)
    locked_code = locked_molecular_solvent_code(report)
    if locked_code and selected_solvent_code and normalize_agent_token(locked_code) != normalize_agent_token(selected_solvent_code):
        return set_orchestrator_blocked(
            "agent_full_flow_autopilot",
            task_id,
            "当前报告已锁定萃取剂 {}；收到前端旧选择 {}，为避免误跑其他候选，智能体已阻止本次启动。请刷新页面后再操作，或先显式切换本次计算对象。".format(
                locked_code,
                selected_solvent_code,
            ),
            {"locked_solvent_code": locked_code, "requested_solvent_code": selected_solvent_code},
        )
    if locked_code:
        selected_solvent_code = locked_code
    selected_solvent = {} if task.get("compatible_verified_case") else primary_validation_solvent_identity(report, selected_solvent_code)
    if selected_solvent.get("selection_error"):
        return selected_solvent_blocker("agent_full_flow_autopilot", task_id, selected_solvent)
    selected_solvent_code = selected_solvent.get("code") or selected_solvent.get("aspen_component_id") or selected_solvent_code or ""
    output_dir = Path(report.get("output_dir") or Path(report_path).parent)
    command = [
        sys.executable,
        str(runner),
        "--report",
        str(Path(report_path).resolve()),
        "--max-gaussian-jobs",
        "1",
    ]
    if selected_solvent_code:
        command.extend(["--solvent-code", selected_solvent_code])
    return start_orchestrator_process(
        "agent_full_flow_autopilot",
        task_id,
        command,
        BASE_DIR,
        output_dir / "autopilot_logs",
        "全流程自动驾驶已启动；智能体会先跑 Aspen α 快算/导入 Iα，通过后才锁定萃取剂 {} 并继续 Gaussian -> Multiwfn/VMD NCI -> Sobtop/Multiwfn -> GROMACS -> Aspen/优化。".format(selected_solvent_code or "当前推荐项"),
    )


