def launch_publication_one_system_trial_autopilot():
    cohort = build_publication_validation_cohort(instantiate_missing=True)
    candidates = [
        row for row in cohort.get("systems") or []
        if row.get("publication_eligible") and row.get("stage") != "full_flow_validated" and row.get("report_path")
    ]
    if not candidates:
        return set_orchestrator_blocked(
            "publication_one_system_trial_autopilot",
            "",
            "没有可试跑的发表验证新体系；cohort 为空或都已完成。",
            {"cohort": cohort},
        )
    selected = candidates[0]
    report_path = Path(selected["report_path"]).resolve()
    report, path = load_action_report(report_path)
